insert into public.fitness_goal_modes (catalog_version, id, name, prescription)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"strength","name":{"en":"Strength","ru":"Сила"},"prescription":{"name":{"en":"Strength","ru":"Сила"},"summary":{"en":"Heavy and low-rep: 3–6 reps on the main lifts with 2 reps in reserve, 3 min rests, fewer sets. Builds maximal strength on the machines you actually train on.","ru":"Тяжело и мало повторений: 3–6 повторений в основных упражнениях с запасом 2 повторения, отдых 3 минуты, меньше подходов. Развивает максимальную силу именно на тех тренажёрах, на которых вы тренируетесь."},"repRange":[3,6],"rir":2,"setsPerMuscleWeek":{"start":4,"target":8,"max":12,"unit":"direct sets per main lift (accessories 6–10 per muscle)"},"restSec":{"compound":180,"isolation":90},"frequency":[2,3],"blockWeeks":5,"deloadRule":{"en":"Every 5 weeks a lighter week: 40 % fewer sets at the same weights, 2 fewer reps and 2 more reps in reserve. After 3 failed sessions in a row on an exercise, its weight drops 10 %.","ru":"Каждые 5 недель — облегчённая неделя: на 40 % меньше подходов с теми же весами, на 2 повторения меньше и на 2 больше в запасе. После 3 неудачных тренировок подряд вес в упражнении снижается на 10 %."},"progression":{"rule":"double","repRange":[3,6],"rir":2,"stepPct":2.5,"failsBeforeDeload":3,"deloadPct":10,"overshootReps":2},"roles":{"primary":{"sets":4,"repRange":[3,6],"rir":2,"restSec":180},"secondary":{"sets":3,"repRange":[6,10],"rir":2,"restSec":150},"isolation":{"sets":2,"repRange":[8,12],"rir":2,"restSec":90},"small":{"sets":2,"repRange":[10,15],"rir":2,"restSec":75},"trunk":{"sets":3,"repRange":[6,10],"rir":2,"restSec":90},"hold":{"sets":2,"repRange":[6,10],"rir":2,"restSec":60,"unit":"reps","byUnit":{"seconds":[20,40],"meters":[20,30]}},"carry":{"sets":2,"repRange":[20,30],"rir":2,"restSec":120,"unit":"meters","byUnit":{"seconds":[20,30],"reps":[6,10]}}},"sources":["research/01 Table 1 (a), Table 5, Table 10; research/02 §B2, §C","Currier BS, Mcleod JC, Banfield L, et al. Resistance training prescription for muscle strength and hypertrophy in healthy adults: a systematic review and Bayesian network meta-analysis. Br J Sports Med 2023;57(18):1211–1220. https://doi.org/10.1136/bjsports-2023-106807","Pelland JC, Remmert JF, Robinson ZP, Hinson SR, Zourdos MC. The resistance training dose response: meta-regressions exploring the effects of weekly volume and frequency on muscle hypertrophy and strength gain. Sports Med 2026;56(2):481–505. https://doi.org/10.1007/s40279-025-02344-w","Robinson ZP, Pelland JC, Remmert JF, et al. Exploring the dose–response relationship between estimated resistance training proximity to failure, strength gain, and muscle hypertrophy: a series of meta-regressions. Sports Med 2024;54(9):2209–2231. https://doi.org/10.1007/s40279-024-02069-2","Ralston GW, Kilgore L, Wyatt FB, Baker JS. The effect of weekly set volume on strength gain: a meta-analysis. Sports Med 2017;47(12):2585–2601. https://doi.org/10.1007/s40279-017-0762-7","Androulakis-Korakakis P, Fisher JP, Steele J. The minimum effective training dose required to increase 1RM strength in resistance-trained men: a systematic review and meta-analysis. Sports Med 2020;50(4):751–765. https://doi.org/10.1007/s40279-019-01236-0","Moesgaard L, Beck MM, Christiansen L, Aagaard P, Lundbye-Jensen J. Effects of periodization on strength and muscle hypertrophy in volume-equated resistance training programs: a systematic review and meta-analysis. Sports Med 2022;52(7):1647–1666. https://doi.org/10.1007/s40279-021-01636-1","StrongLifts. StrongLifts 5×5: how to overcome failure (repeat after a miss, −10 % after three). https://stronglifts.com/stronglifts-5x5/failure/","American College of Sports Medicine. Position stand: progression models in resistance training for healthy adults. Med Sci Sports Exerc 2009;41(3):687–708. https://doi.org/10.1249/MSS.0b013e3181915670"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"hypertrophy","name":{"en":"Muscle growth","ru":"Рост мышц"},"prescription":{"name":{"en":"Muscle growth","ru":"Рост мышц"},"summary":{"en":"More sets per muscle (10 → 16, up to 22 a week), 8–12 reps on presses and rows, 12–20 on isolation work, close to failure (1–2 reps in reserve) on machines. Works best at maintenance calories or a small surplus.","ru":"Больше подходов на мышцу (10 → 16, до 22 в неделю), 8–12 повторений в жимах и тягах, 12–20 в изолирующих упражнениях, близко к отказу (запас 1–2 повторения) на тренажёрах. Лучше всего работает при питании на поддержание или с небольшим профицитом."},"repRange":[8,12],"rir":2,"setsPerMuscleWeek":{"start":10,"target":16,"max":22,"unit":"fractional sets per muscle (direct 1, synergist 0.5)"},"restSec":{"compound":150,"isolation":75},"frequency":[2,3],"blockWeeks":5,"deloadRule":{"en":"Every 5 weeks a lighter week: 40 % fewer sets at the same weights, 2 fewer reps and 2 more reps in reserve. After 2 failed sessions in a row on an exercise, its weight drops 10 %.","ru":"Каждые 5 недель — облегчённая неделя: на 40 % меньше подходов с теми же весами, на 2 повторения меньше и на 2 больше в запасе. После 2 неудачных тренировок подряд вес в упражнении снижается на 10 %."},"progression":{"rule":"double","repRange":[8,12],"rir":2,"stepPct":2.5,"failsBeforeDeload":2,"deloadPct":10,"overshootReps":2},"roles":{"primary":{"sets":3,"repRange":[8,12],"rir":2,"restSec":150},"secondary":{"sets":3,"repRange":[10,15],"rir":1,"restSec":120},"isolation":{"sets":3,"repRange":[12,20],"rir":1,"restSec":75},"small":{"sets":3,"repRange":[15,25],"rir":1,"restSec":60},"trunk":{"sets":3,"repRange":[10,15],"rir":1,"restSec":75},"hold":{"sets":2,"repRange":[10,15],"rir":1,"restSec":60,"unit":"reps","byUnit":{"seconds":[30,45],"meters":[30,40]}},"carry":{"sets":2,"repRange":[30,40],"rir":1,"restSec":90,"unit":"meters","byUnit":{"seconds":[30,45],"reps":[10,15]}}},"sources":["research/01 Table 1 (b), Table 2, Table 4, Table 5; research/02 §L","Schoenfeld BJ, Ogborn D, Krieger JW. Dose-response relationship between weekly resistance training volume and increases in muscle mass: a systematic review and meta-analysis. J Sports Sci 2017;35(11):1073–1082. https://doi.org/10.1080/02640414.2016.1210197","Pelland JC, Remmert JF, Robinson ZP, Hinson SR, Zourdos MC. The resistance training dose response: meta-regressions exploring the effects of weekly volume and frequency on muscle hypertrophy and strength gain. Sports Med 2026;56(2):481–505. https://doi.org/10.1007/s40279-025-02344-w","Baz-Valle E, Balsalobre-Fernández C, Alix-Fages C, Santos-Concejero J. A systematic review of the effects of different resistance training volumes on muscle hypertrophy. J Hum Kinet 2022;81:199–210. https://doi.org/10.2478/hukin-2022-0017","Refalo MC, Helms ER, Trexler ET, Hamilton DL, Fyfe JJ. Influence of resistance training proximity-to-failure on skeletal muscle hypertrophy: a systematic review with meta-analysis. Sports Med 2023;53(3):649–665. https://doi.org/10.1007/s40279-022-01784-y","Schoenfeld BJ, Grgic J, Van Every DW, Plotkin DL. Loading recommendations for muscle strength, hypertrophy, and local endurance: a re-examination of the repetition continuum. Sports (Basel) 2021;9(2):32. https://doi.org/10.3390/sports9020032","Singer A, Wolf M, Generoso L, et al. Give it a rest: a systematic review with Bayesian meta-analysis on the effect of inter-set rest interval duration on muscle hypertrophy. Front Sports Act Living 2024;6:1429789. https://doi.org/10.3389/fspor.2024.1429789","Schoenfeld BJ, Grgic J, Krieger J. How many times per week should a muscle be trained to maximize muscle hypertrophy? A systematic review and meta-analysis. J Sports Sci 2019;37(11):1286–1295. https://doi.org/10.1080/02640414.2018.1555906","Coleman M, Burke R, Augustin F, et al. Gaining more from doing less? The effects of a one-week deload period during supervised resistance training on muscular adaptations. PeerJ 2024;12:e16777. https://doi.org/10.7717/peerj.16777"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"recomp","name":{"en":"Fat loss & recomposition","ru":"Похудение и рекомпозиция"},"prescription":{"name":{"en":"Fat loss & recomposition","ru":"Похудение и рекомпозиция"},"summary":{"en":"The default for a calorie deficit: keep the weights heavy (6–10 reps on the main lifts with 2 in reserve), moderate volume (10–16 sets per muscle a week), progress reps before weight, and count holding your strength as a win. Eat no more than 500 kcal/day below maintenance, with about 2.2 g of protein per kg of body weight.","ru":"Режим для дефицита калорий: веса остаются тяжёлыми (6–10 повторений в основных упражнениях с запасом 2), умеренный объём (10–16 подходов на мышцу в неделю), сначала растут повторения, потом вес, а сохранённая сила — уже успех. Дефицит не больше 500 ккал в день и около 2,2 г белка на кг массы тела."},"repRange":[6,10],"rir":2,"setsPerMuscleWeek":{"start":10,"target":13,"max":16,"unit":"fractional sets per muscle (direct 1, synergist 0.5)"},"restSec":{"compound":150,"isolation":75},"frequency":[2,3],"blockWeeks":5,"deloadRule":{"en":"Every 5 weeks (or at a diet break) a lighter week: 40 % fewer sets at the same weights, 2 fewer reps and 2 more reps in reserve. After 2 failed sessions in a row on an exercise, its weight drops 10 %.","ru":"Каждые 5 недель (или в перерыв от диеты) — облегчённая неделя: на 40 % меньше подходов с теми же весами, на 2 повторения меньше и на 2 больше в запасе. После 2 неудачных тренировок подряд вес в упражнении снижается на 10 %."},"progression":{"rule":"double","repRange":[6,10],"rir":2,"stepPct":2.5,"failsBeforeDeload":2,"deloadPct":10,"overshootReps":2},"roles":{"primary":{"sets":3,"repRange":[6,10],"rir":2,"restSec":150},"secondary":{"sets":3,"repRange":[8,12],"rir":2,"restSec":120},"isolation":{"sets":2,"repRange":[10,15],"rir":1,"restSec":75},"small":{"sets":2,"repRange":[12,20],"rir":1,"restSec":60},"trunk":{"sets":3,"repRange":[8,12],"rir":2,"restSec":90},"hold":{"sets":2,"repRange":[8,12],"rir":2,"restSec":60,"unit":"reps","byUnit":{"seconds":[20,40],"meters":[20,40]}},"carry":{"sets":2,"repRange":[20,40],"rir":2,"restSec":90,"unit":"meters","byUnit":{"seconds":[30,45],"reps":[8,12]}}},"sources":["research/01 Table 1 (c), Table 10 and the owner profile section; research/02 §K, §L (DP-RIR-4)","Murphy C, Koehler K. Energy deficiency impairs resistance training gains in lean mass but not strength: a meta-analysis and meta-regression. Scand J Med Sci Sports 2022;32(1):125–137. https://doi.org/10.1111/sms.14075","Roth C, Schwiete C, Happ K, Rettenmaier L, Schoenfeld BJ, Behringer M. Resistance training volume does not influence lean mass preservation during energy restriction in trained males. Scand J Med Sci Sports 2023;33(1):20–35. https://doi.org/10.1111/sms.14237","Helms ER, Zinn C, Rowlands DS, Brown SR. A systematic review of dietary protein during caloric restriction in resistance trained lean athletes: a case for higher intakes. Int J Sport Nutr Exerc Metab 2014;24(2):127–138. https://doi.org/10.1123/ijsnem.2013-0054","Garthe I, Raastad T, Refsnes PE, Koivisto A, Sundgot-Borgen J. Effect of two different weight-loss rates on body composition and strength and power-related performance in elite athletes. Int J Sport Nutr Exerc Metab 2011;21(2):97–104. https://doi.org/10.1123/ijsnem.21.2.97","Plotkin D, Coleman M, Van Every D, et al. Progressive overload without progressing load? The effects of load or repetition progression on muscular adaptations. PeerJ 2022;10:e14142. https://doi.org/10.7717/peerj.14142","Schumann M, Feuerbacher JF, Sünkeler M, et al. Compatibility of concurrent aerobic and strength training for skeletal muscle size and function: an updated systematic review and meta-analysis. Sports Med 2022;52(3):601–612. https://doi.org/10.1007/s40279-021-01587-7","Robinson ZP, Pelland JC, Remmert JF, et al. Exploring the dose–response relationship between estimated resistance training proximity to failure, strength gain, and muscle hypertrophy: a series of meta-regressions. Sports Med 2024;54(9):2209–2231. https://doi.org/10.1007/s40279-024-02069-2"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"endurance","name":{"en":"Muscular endurance","ru":"Силовая выносливость"},"prescription":{"name":{"en":"Muscular endurance","ru":"Силовая выносливость"},"summary":{"en":"Light loads for 15–25 reps taken close to failure, short rests (45–75 s) and 8–15 sets per muscle a week. Expect maximal strength to drift down a few per cent.","ru":"Лёгкие веса на 15–25 повторений близко к отказу, короткий отдых (45–75 секунд) и 8–15 подходов на мышцу в неделю. Максимальная сила может немного снизиться."},"repRange":[15,20],"rir":2,"setsPerMuscleWeek":{"start":8,"target":12,"max":15,"unit":"fractional sets per muscle (direct 1, synergist 0.5)"},"restSec":{"compound":75,"isolation":45},"frequency":[2,3],"blockWeeks":5,"deloadRule":{"en":"Every 5 weeks a lighter week: 40 % fewer sets at the same weights, 2 fewer reps and 2 more reps in reserve. After 2 failed sessions in a row on an exercise, its weight drops 10 %.","ru":"Каждые 5 недель — облегчённая неделя: на 40 % меньше подходов с теми же весами, на 2 повторения меньше и на 2 больше в запасе. После 2 неудачных тренировок подряд вес в упражнении снижается на 10 %."},"progression":{"rule":"double","repRange":[15,20],"rir":2,"stepPct":5,"failsBeforeDeload":2,"deloadPct":10,"overshootReps":3},"roles":{"primary":{"sets":2,"repRange":[15,20],"rir":2,"restSec":75},"secondary":{"sets":2,"repRange":[15,20],"rir":1,"restSec":60},"isolation":{"sets":2,"repRange":[15,25],"rir":1,"restSec":45},"small":{"sets":2,"repRange":[20,30],"rir":1,"restSec":45},"trunk":{"sets":2,"repRange":[15,20],"rir":1,"restSec":45},"hold":{"sets":2,"repRange":[12,20],"rir":1,"restSec":45,"unit":"reps","byUnit":{"seconds":[40,60],"meters":[40,60]}},"carry":{"sets":2,"repRange":[40,60],"rir":1,"restSec":60,"unit":"meters","byUnit":{"seconds":[45,60],"reps":[12,20]}}},"sources":["research/01 Table 1 (d), Table 5 (endurance evidence is equivocal; ACSM numbers are the default)","Schoenfeld BJ, Grgic J, Van Every DW, Plotkin DL. Loading recommendations for muscle strength, hypertrophy, and local endurance: a re-examination of the repetition continuum. Sports (Basel) 2021;9(2):32. https://doi.org/10.3390/sports9020032","Lopez P, Radaelli R, Taaffe DR, et al. Resistance training load effects on muscle hypertrophy and strength gain: systematic review and network meta-analysis. Med Sci Sports Exerc 2021;53(6):1206–1216. https://doi.org/10.1249/MSS.0000000000002585","American College of Sports Medicine. Position stand: progression models in resistance training for healthy adults. Med Sci Sports Exerc 2009;41(3):687–708. https://doi.org/10.1249/MSS.0b013e3181915670"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"maintenance","name":{"en":"Health & maintenance","ru":"Здоровье и поддержание"},"prescription":{"name":{"en":"Health & maintenance","ru":"Здоровье и поддержание"},"summary":{"en":"The minimum that keeps strength and muscle: 2 sets per exercise, 5–8 reps on the main lifts and 8–20 elsewhere with 2 in reserve — about 30–60 min of lifting a week — plus 2–3 cardio sessions, one of them intervals.","ru":"Минимум, который сохраняет силу и мышцы: 2 подхода на упражнение, 5–8 повторений в основных упражнениях и 8–20 в остальных с запасом 2 — около 30–60 минут силовой работы в неделю — плюс 2–3 кардиотренировки, одна из них интервальная."},"repRange":[5,8],"rir":2,"setsPerMuscleWeek":{"start":6,"target":9,"max":12,"unit":"fractional sets per muscle (direct 1, synergist 0.5)"},"restSec":{"compound":150,"isolation":75},"frequency":[2,2],"blockWeeks":8,"deloadRule":{"en":"Every 8 weeks a lighter week: 40 % fewer sets at the same weights, 2 fewer reps and 2 more reps in reserve. After 2 failed sessions in a row on an exercise, its weight drops 10 %.","ru":"Каждые 8 недель — облегчённая неделя: на 40 % меньше подходов с теми же весами, на 2 повторения меньше и на 2 больше в запасе. После 2 неудачных тренировок подряд вес в упражнении снижается на 10 %."},"progression":{"rule":"double","repRange":[5,8],"rir":2,"stepPct":2.5,"failsBeforeDeload":2,"deloadPct":10,"overshootReps":2},"roles":{"primary":{"sets":2,"repRange":[5,8],"rir":2,"restSec":150},"secondary":{"sets":2,"repRange":[8,12],"rir":2,"restSec":120},"isolation":{"sets":2,"repRange":[10,15],"rir":2,"restSec":75},"small":{"sets":2,"repRange":[12,20],"rir":2,"restSec":60},"trunk":{"sets":2,"repRange":[8,12],"rir":2,"restSec":90},"hold":{"sets":2,"repRange":[8,12],"rir":2,"restSec":60,"unit":"reps","byUnit":{"seconds":[20,40],"meters":[20,40]}},"carry":{"sets":2,"repRange":[20,40],"rir":2,"restSec":90,"unit":"meters","byUnit":{"seconds":[30,45],"reps":[8,12]}}},"sources":["research/01 Table 1 (e), Table 10 (any → health/longevity maintenance)","Momma H, Kawakami R, Honda T, Sawada SS. Muscle-strengthening activities are associated with lower risk and mortality in major non-communicable diseases: a systematic review and meta-analysis of cohort studies. Br J Sports Med 2022;56(13):755–763. https://doi.org/10.1136/bjsports-2021-105061","Shailendra P, Baldock KL, Li LSK, Bennie JA, Boyle T. Resistance training and mortality risk: a systematic review and meta-analysis. Am J Prev Med 2022;63(2):277–285. https://doi.org/10.1016/j.amepre.2022.03.020","Androulakis-Korakakis P, Fisher JP, Steele J. The minimum effective training dose required to increase 1RM strength in resistance-trained men: a systematic review and meta-analysis. Sports Med 2020;50(4):751–765. https://doi.org/10.1007/s40279-019-01236-0","Watson SL, Weeks BK, Weis LJ, et al. High-intensity resistance and impact training improves bone mineral density and physical function in postmenopausal women with osteopenia and osteoporosis: the LIFTMOR randomized controlled trial. J Bone Miner Res 2018;33(2):211–220. https://doi.org/10.1002/jbmr.3284","Bull FC, Al-Ansari SS, Biddle S, et al. World Health Organization 2020 guidelines on physical activity and sedentary behaviour. Br J Sports Med 2020;54(24):1451–1462. https://doi.org/10.1136/bjsports-2020-102955","Helgerud J, Høydal K, Wang E, et al. Aerobic high-intensity intervals improve VO2max more than moderate training. Med Sci Sports Exerc 2007;39(4):665–671. https://doi.org/10.1249/mss.0b013e3180304570"]}}]'::jsonb) as x(catalog_version text, id text, name jsonb, prescription jsonb)
on conflict do nothing;

insert into public.fitness_machines (catalog_version, id, equipment_id, name, geometry, generic_variant)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"assisted-dip-chin-station","equipment_id":"assisted","name":{"en":"Assisted dip and pull-up station","ru":"Гравитрон для подтягиваний и отжиманий"},"geometry":"One tall assisted dip/chin station with fixed upper pull-up handles, lower parallel dip handles, a padded knee platform moving vertically on a guide, access steps and a guarded assistance stack. Keep both sets of handles visible in all configurations.","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"back-extension-45","equipment_id":"bodyweight","name":{"en":"45° back extension","ru":"Гиперэкстензия 45°"},"geometry":"a 45-degree back extension bench (hyperextension): an angled frame with a padded thigh support and two ankle rollers on a foot plate, no weights","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"single-cable-tower","equipment_id":"cable","name":{"en":"Adjustable cable tower","ru":"Регулируемая блочная стойка"},"geometry":"One upright cable tower with a guarded stack, vertical adjustment rail, one height-adjustable locked pulley carriage, cable and interchangeable attachment; stable floor base. Carriage height and attachment vary by the exercise; chassis and cable route remain identical.","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"belt-squat","equipment_id":"plate-loaded","name":{"en":"Belt squat","ru":"Приседания с поясом (белт-сквот)"},"geometry":"a plate-loaded belt squat machine: a raised standing platform, a hip belt hanging from a chain on a lever arm loaded with plates, handrails in front","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dual-cable-crossover","equipment_id":"cable","name":{"en":"Dual cable crossover","ru":"Двойной кроссовер"},"geometry":"Two matching cable columns connected by a fixed overhead crossbar, each with its own guarded stack, adjustment rail and lockable pulley carriage. One cable exits each carriage. Same columns, bases and crossbar across the family; carriage heights and attachments follow the exercise.","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"captains-chair-knee-raise","equipment_id":"bodyweight","name":{"en":"Captain''s chair knee raise","ru":"Подъём коленей в упоре на локтях"},"geometry":"a captain''s chair (vertical knee raise station): a tall upright frame with a vertical back pad, two horizontal padded forearm rests with grip handles at elbow height, and a step at the bottom, no weights","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"converging-chest-press","equipment_id":"selectorized","name":{"en":"Converging chest press machine","ru":"Конвергентный жим от груди в тренажёре"},"geometry":"a seated pin-loaded converging chest press: an upright back pad, an adjustable seat, two independent handle arms that swing forward and inward on angled pivots so the hands meet in front of the chest, a weight stack beside the seat","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"decline-chest-press-machine","equipment_id":"plate-loaded","name":{"en":"Decline chest press machine","ru":"Жим под отрицательным углом в тренажёре"},"geometry":"A plate-loaded seated decline press with adjustable upright seat/back pad, two independent lever arms carrying low handles that move forward and downward, plate horns on the arms and a stable base. No selector stack.","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"four-way-neck-machine","equipment_id":"plate-loaded","name":{"en":"4-way neck machine","ru":"Тренажёр для шеи на 4 направления"},"geometry":"A generic plate-loaded four-way neck station with adjustable seat, torso support, side handles and one padded head-contact plate on a lever at head height, loaded by a plate horn. No selector stack or forced neck rotation.","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"glute-kickback-machine","equipment_id":"selectorized","name":{"en":"Glute kickback machine","ru":"Отведение ноги назад в тренажёре"},"geometry":"a glute kickback machine: a standing frame with a chest pad and handles, a padded foot plate on a lever behind the working leg, a weight stack","generic_variant":true}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, geometry text, generic_variant boolean)
on conflict do nothing;

insert into public.fitness_machines (catalog_version, id, equipment_id, name, geometry, generic_variant)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"hack-squat","equipment_id":"plate-loaded","name":{"en":"Hack squat","ru":"Гакк-приседания в тренажёре"},"geometry":"a plate-loaded hack squat: an angled sled with shoulder pads and a back pad running on rails at about 45 degrees, a large angled foot platform at the bottom, weight plates on horns on the sled","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"high-row-machine","equipment_id":"plate-loaded","name":{"en":"High row machine","ru":"Тяга под углом сверху в рычажном тренажёре"},"geometry":"a plate-loaded high row: a seat with a thigh pad and a chest pad, two independent lever arms with handles high in front that pull down and back in an arc, weight plates on horns on the levers","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"hip-abduction-machine","equipment_id":"selectorized","name":{"en":"Hip abduction machine","ru":"Разведение ног сидя в тренажёре"},"geometry":"a seated pin-loaded hip abduction machine: a reclined seat with a back pad, two padded leg pads on levers on the outside of the knees, foot rests, a weight stack","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"hip-adduction-machine","equipment_id":"selectorized","name":{"en":"Hip adduction machine","ru":"Сведение ног сидя в тренажёре"},"geometry":"a seated pin-loaded hip adduction machine: a reclined seat with a back pad, two padded leg pads on levers on the inside of the knees, foot rests, a weight stack","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"seated-lat-pulldown","equipment_id":"selectorized","name":{"en":"Lat pulldown station","ru":"Станция вертикальной тяги"},"geometry":"One tall lat-pulldown station with a guarded stack in front of the seated actor, fixed overhead pulley, low seat and adjustable thigh hold-down rollers on a short post above the knees. One cable descends to the selected handle. No load stack above the knees.","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"leg-extension","equipment_id":"selectorized","name":{"en":"Leg extension","ru":"Разгибание ног сидя в тренажёре"},"geometry":"a seated pin-loaded leg extension machine: a seat with an adjustable back pad, a padded roller on a lever arm in front of the shins with the pivot level with the knees, side handles, a weight stack","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"sled-leg-press-45","equipment_id":"plate-loaded","name":{"en":"45-degree sled leg press","ru":"Жим ногами под 45 градусов"},"geometry":"One 45-degree sled leg press with reclined seat/back pad, paired inclined rails, a sled with large foot platform, plate horns on the moving sled and reachable safety handles/stops. Same machine for leg press and calf raise; no separate calf apparatus.","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"lower-back-machine","equipment_id":"selectorized","name":{"en":"Lower back machine (lumbar extension)","ru":"Разгибание спины сидя в тренажёре"},"geometry":"a seated pin-loaded lower back machine: a seat with a foot platform, thigh and hip pads that lock the pelvis, a padded roller across the upper back on a lever arm pivoting at the level of the lower back, a weight stack","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"lying-leg-curl","equipment_id":"selectorized","name":{"en":"Lying leg curl","ru":"Сгибание ног лёжа в тренажёре"},"geometry":"a lying (prone) pin-loaded leg curl: an angled bench to lie face down on, handles at the front, a padded roller on a lever behind the ankles with the pivot level with the knees, a weight stack","generic_variant":true},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-chest-press","equipment_id":"selectorized","name":{"en":"Chest press machine","ru":"Жим от груди в тренажёре"},"geometry":"a seated pin-loaded chest press: an upright padded back rest, an adjustable seat, two lever arms (one on each side of the seat, pivoting high on the frame behind the shoulders) that each end in a horizontal handle beside the chest and swing forward with the hands, and a weight stack with a selector pin standing behind the seat; nothing crosses in front of the chest","generic_variant":true}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, geometry text, generic_variant boolean)
on conflict do nothing;

