insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-chest-press","equipment_id":"selectorized","name":{"en":"Chest press machine","ru":"Жим от груди в тренажёре"},"pattern":"horizontal-push","details":{"id":"machine-chest-press","class":"horizontal-press","pattern":"horizontal-push","name":{"en":"Chest press machine","ru":"Жим от груди в тренажёре"},"aka":["Technogym Selection / Element Chest Press","Life Fitness Insignia Chest Press","Cybex Eagle NX Chest Press","Nautilus Inspiration Chest Press","Precor Vitality Chest Press","Seated chest press"],"equipment":"selectorized","primary":["pec-sternal"],"secondary":["pec-clavicular","delt-front","triceps-lateral"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"alternatives":["converging-chest-press","plate-loaded-chest-press","dumbbell-bench-press","smith-bench-press","push-up"],"setup":{"en":"Set the seat so the handles sit at mid-chest (nipple line) and start no further back than the front of your chest — use the handle-depth lever or foot bar if there is one. Sit with head, upper back and hips on the pads and feet flat.","ru":"Отрегулируйте сиденье так, чтобы рукоятки были на уровне середины груди (линия сосков) и в старте не уходили назад дальше передней поверхности груди — для этого есть регулировка глубины рукояток или педаль. Голова, лопатки и таз прижаты к спинке и сиденью, стопы на полу."},"cues":{"en":["Pull your shoulder blades back and down into the pad before the first rep, and keep them there.","Grip with straight wrists in line with the forearms; take the vertical (neutral) handles if the machine has them.","Keep the elbows about 45–60° from your sides, a little below shoulder height.","Breathe out and press smoothly until the arms are almost straight — stop just short of locking out.","At the end of the press your shoulders stay on the pad: push the handles away, not your shoulders.","Lower for 2–3 s until the hands are level with the front of your chest, then press again without clanking the plates.","Keep the natural curve in your lower back; don''t lift your hips off the seat."],"ru":["Перед первым повтором сведите и опустите лопатки, прижав их к спинке, — и держите так весь подход.","Запястья прямые, на одной линии с предплечьями; если есть вертикальные (нейтральные) рукоятки — берите их.","Локти — примерно под 45–60° к корпусу, чуть ниже линии плеч.","На выдохе плавно выжимайте почти до прямых рук, не выпрямляя локти до упора.","В конце жима плечи остаются на спинке: отталкивайте рукоятки, а не плечи вперёд.","Опускайте 2–3 секунды, пока кисти не окажутся на уровне передней поверхности груди, и жмите снова, не стуча плитами.","Сохраняйте естественный прогиб в пояснице; не отрывайте таз от сиденья."]},"mistakes":{"en":["Seat too low: the elbows drift up toward the ears and the front of the shoulder takes the load.","Handles set too deep, so every rep starts behind the chest and overstretches the front of the shoulder.","Shrugging or rolling the shoulders forward off the pad to finish the press.","Elbows flared out past ~75°, straight out from the shoulders.","Arching the lower back or lifting the hips to grind out a rep.","Ego loading: dropping the weight fast so the plates bang together."],"ru":["Сиденье слишком низко: локти уходят вверх к ушам, и нагрузку забирает передняя часть плеча.","Рукоятки выставлены слишком глубоко: каждый повтор начинается позади линии груди и перерастягивает переднюю часть плечевого сустава.","Плечи поднимаются к ушам или уходят вперёд со спинки, чтобы дожать.","Локти разведены шире ~75°, прямо в стороны от плеч.","Прогиб в пояснице или отрыв таза от сиденья, чтобы дожать повтор.","Эго-лифтинг: вес бросают вниз, и плиты грузоблока бьются друг о друга."]},"startLoad":{"kg":25,"source":"≈0.6 × Strength Level Beginner chest-press 1RM (39 kg at 80 kg body weight), research 04 §3.9"},"tags":["owner-primary"],"images":[],"sources":["Seated Chest Press — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/188/seated-chest-press/","Chest Press Machine — NASM Exercise Library, accessed 2026. https://www.nasm.org/resource-center/exercise-library/chest-press-machine","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Chest Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/chest-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"converging-chest-press","equipment_id":"selectorized","name":{"en":"Converging chest press machine","ru":"Конвергентный жим от груди в тренажёре"},"pattern":"horizontal-push","details":{"id":"converging-chest-press","class":"horizontal-press","pattern":"horizontal-push","name":{"en":"Converging chest press machine","ru":"Конвергентный жим от груди в тренажёре"},"aka":["Matrix Versa Converging Chest Press","Life Fitness Insignia Dual Axis Chest Press","Hammer Strength MTS Iso-Lateral Chest Press","Iso-lateral chest press"],"equipment":"selectorized","primary":["pec-sternal"],"secondary":["pec-clavicular","delt-front","triceps-lateral"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"alternatives":["machine-chest-press","plate-loaded-chest-press","dumbbell-bench-press","smith-bench-press","push-up"],"setup":{"en":"Set the seat so the handles start at mid-chest with the elbows just behind the line of your torso; back and head on the pad, feet flat. The arms move independently and converge as you press, so start with both handles level.","ru":"Установите сиденье так, чтобы рукоятки в старте были на уровне середины груди, а локти — чуть позади линии корпуса; спина и голова на спинке, стопы на полу. Рычаги независимые и сходятся к центру по ходу жима — начинайте с обеими рукоятками на одном уровне."},"cues":{"en":["Set the shoulder blades back and down before you push the handles off their stops.","Press both handles at the same speed; the arcs meet in front of your lower chest.","Elbows 45–60° from your sides; let them follow the converging path instead of flaring.","Breathe out through the press and stop just short of lockout.","Return for 2–3 s until the hands are level with your chest — no deeper.","If one arm is weaker, keep both handles level and don''t twist the torso to help it."],"ru":["Сведите и опустите лопатки до того, как сдвинете рукоятки с упоров.","Жмите обе рукоятки синхронно — дуги сходятся перед нижней частью груди.","Локти под 45–60° к корпусу; пусть они идут по сходящейся траектории, а не разъезжаются в стороны.","Выдох на жиме; остановитесь чуть раньше полного выпрямления локтей.","Возвращайте рукоятки 2–3 секунды до уровня груди — не глубже.","Если одна рука слабее, держите рукоятки на одном уровне и не скручивайте корпус, помогая ей."]},"mistakes":{"en":["Seat too low, so the press starts near the shoulders and the elbows ride up.","Letting the handles drift behind the chest at the bottom — a stretch the shoulder capsule pays for.","Shoulders rolling forward off the pad as the handles meet.","Uneven arms: one handle racing ahead while the torso twists.","Ego loading, with the plates banging between reps."],"ru":["Сиденье слишком низко: жим начинается у плеч, локти уходят вверх.","Рукоятки внизу уходят за линию груди — за такое растяжение платит капсула плечевого сустава.","Плечи уходят вперёд со спинки, когда рукоятки сходятся.","Руки работают несинхронно: одна рукоятка опережает, корпус скручивается.","Эго-лифтинг: плиты грузоблока бьются между повторами."]},"startLoad":{"kg":20,"source":"One 5 kg step under the chest-press seed (0.6 × Strength Level Beginner 39 kg ≈ 23 kg): converging stacks differ by brand"},"tags":["owner-alt"],"images":[],"sources":["Seated Chest Press — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/188/seated-chest-press/","Muyor et al., Bench press vs seated chest press muscle activity with several grips — J Hum Kinet, 2023. https://doi.org/10.5114/jhk/161468","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Chest Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/chest-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"plate-loaded-chest-press","equipment_id":"plate-loaded","name":{"en":"Plate-loaded chest press","ru":"Жим от груди в рычажном тренажёре"},"pattern":"horizontal-push","details":{"id":"plate-loaded-chest-press","class":"horizontal-press","pattern":"horizontal-push","name":{"en":"Plate-loaded chest press","ru":"Жим от груди в рычажном тренажёре"},"aka":["Hammer Strength Iso-Lateral Bench Press","Hammer Strength Iso-Lateral Horizontal Bench Press","Hammer Strength Iso-Lateral Wide Chest","Technogym Pure Strength Chest Press","Lever chest press"],"equipment":"plate-loaded","primary":["pec-sternal"],"secondary":["pec-clavicular","delt-front","triceps-lateral"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["machine-chest-press","converging-chest-press","dumbbell-bench-press","smith-bench-press","push-up"],"setup":{"en":"Seated models: set the seat so the handles line up with mid-chest; bench models: lie with the handles over mid-chest. Load the same plates on both arms and log the total of both sides (the lever''s own weight is not counted).","ru":"Модели сидя: сиденье так, чтобы рукоятки были на уровне середины груди; модели лёжа: лягте так, чтобы рукоятки были над серединой груди. Вешайте одинаковые диски на оба рычага и записывайте их общий вес с двух сторон (вес самого рычага не считается)."},"cues":{"en":["Back and head on the pad, shoulder blades pulled back and down.","Straight wrists; elbows 45–60° from your sides.","Press both arms in the same rhythm — the independent levers will show a weaker side.","Breathe out and press to just short of lockout.","Lower for 2–3 s to chest level; don''t let the plates'' momentum pull your hands deeper.","Feet planted, hips on the seat — no bridging."],"ru":["Спина и голова на спинке, лопатки сведены и опущены.","Запястья прямые; локти под 45–60° к корпусу.","Жмите обеими руками в одном ритме — независимые рычаги сразу покажут слабую сторону.","На выдохе выжимайте почти до прямых рук, без блокировки локтей.","Опускайте 2–3 секунды до уровня груди; не позволяйте инерции дисков утянуть руки глубже.","Стопы упираются в пол, таз на сиденье — без «моста»."]},"mistakes":{"en":["Different plates on each side, or not knowing what was loaded last time — log the total.","Letting the heavy levers drop into a deep stretch behind the chest.","Shrugging and rolling the shoulders off the pad at the top.","Elbows flared out past ~75°.","Bouncing out of the bottom and arching to finish reps."],"ru":["Разный вес на двух рычагах или забытый прошлый вес — записывайте общий вес дисков.","Тяжёлые рычаги проваливаются в глубокое растяжение за линию груди.","Плечи поднимаются и уходят вперёд со спинки вверху.","Локти разведены шире ~75°.","Отбив внизу и прогиб, чтобы дожать повтор."]},"startLoad":{"kg":20,"source":"Total plates (10 kg per arm): ≈0.6 × the barbell-bench seed (Strength Level Beginner 56 kg × 0.6 ≈ 34 kg), research 04 §3.8; lever ratios vary"},"tags":["owner-alt"],"images":[],"sources":["NSCA, Exercise Technique Manual for Resistance Training, 3rd ed. — Human Kinetics, 2016. https://canada.humankinetics.com/products/exercise-technique-manual-for-resistance-training-3rd-edition-with-online-video","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Noteboom et al., Bench press technique variations and musculoskeletal shoulder loads — Front Physiol, 2024. https://doi.org/10.3389/fphys.2024.1393235","Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/bench-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"smith-bench-press","equipment_id":"smith","name":{"en":"Smith machine bench press","ru":"Жим лёжа в машине Смита"},"pattern":"horizontal-push","details":{"id":"smith-bench-press","class":"horizontal-press","pattern":"horizontal-push","name":{"en":"Smith machine bench press","ru":"Жим лёжа в машине Смита"},"aka":["Smith bench press","Technogym Multipower bench press","Guided-bar bench press"],"equipment":"smith","primary":["pec-sternal"],"secondary":["pec-clavicular","delt-front","triceps-lateral"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["machine-chest-press","converging-chest-press","plate-loaded-chest-press","dumbbell-bench-press","barbell-bench-press","push-up"],"setup":{"en":"Place a flat bench so the bar lands on your lower chest (just below the nipples) and set the safety stops just below that touch point. Grip about 1.5× shoulder width and note the bar''s own weight once — Smith bars weigh 7–25 kg.","ru":"Поставьте горизонтальную скамью так, чтобы гриф опускался на нижнюю часть груди (чуть ниже сосков), а страховочные упоры — чуть ниже точки касания. Хват примерно в 1,5 ширины плеч; один раз узнайте вес самого грифа — в разных машинах Смита он от 7 до 25 кг."},"cues":{"en":["Shoulder blades squeezed together and down, feet flat, small natural arch.","Unrack by rotating the hooks off with straight arms over your shoulders.","Lower for 2–3 s to the lower chest with forearms vertical and elbows 45–70° from your sides.","Touch lightly — no bounce — then breathe out and press straight up.","Stop just short of lockout; after the last rep rotate the hooks back onto a pin.","Head, shoulders and hips stay on the bench for the whole set."],"ru":["Лопатки сведены и опущены, стопы на полу, небольшой естественный прогиб.","Снимайте гриф поворотом крюков на прямых руках над плечами.","Опускайте 2–3 секунды к нижней части груди: предплечья вертикальны, локти под 45–70° к корпусу.","Легко коснитесь груди — без отбива — и на выдохе жмите вверх.","Не блокируйте локти до упора; после последнего повтора поверните крюки на ближайший упор.","Голова, лопатки и таз весь подход на скамье."]},"mistakes":{"en":["Bench in the wrong spot, so the fixed bar lands on the neck or belly instead of the lower chest.","No safety stops set — the guided bar still pins you if you fail.","Elbows flared out to 90°, straight out from the shoulders.","Bouncing the bar off the chest or lifting the hips.","Forgetting the bar weight, so loads don''t match between gyms."],"ru":["Скамья стоит не там: фиксированный гриф опускается на шею или живот вместо нижней части груди.","Не выставлены страховочные упоры — направляющий гриф всё равно придавит, если не дожмёте.","Локти разведены на 90°, прямо в стороны от плеч.","Отбив грифа от груди или отрыв таза от скамьи.","Не учтён вес грифа — нагрузки в разных залах несопоставимы."]},"startLoad":{"kg":32.5,"source":"Bar + plates: 0.6 × Strength Level Beginner Smith bench 1RM (53 kg at 80 kg) ≈ 32 kg"},"tags":["owner-alt"],"images":[],"sources":["Saeterbakken et al., Muscle activity and 1-RM of three chest presses with different stability — J Sports Sci, 2011. https://doi.org/10.1080/02640414.2010.543916","Noteboom et al., Bench press technique variations and musculoskeletal shoulder loads — Front Physiol, 2024. https://doi.org/10.3389/fphys.2024.1393235","Nuckols, How to Bench Press: The Definitive Guide — Stronger by Science, accessed 2026. https://www.strongerbyscience.com/how-to-bench/","Smith Machine Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/smith-machine-bench-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dumbbell-bench-press","equipment_id":"dumbbell","name":{"en":"Dumbbell bench press","ru":"Жим гантелей лёжа"},"pattern":"horizontal-push","details":{"id":"dumbbell-bench-press","class":"horizontal-press","pattern":"horizontal-push","name":{"en":"Dumbbell bench press","ru":"Жим гантелей лёжа"},"aka":["Flat dumbbell press","DB bench press","Dumbbell chest press"],"equipment":"dumbbell","primary":["pec-sternal"],"secondary":["pec-clavicular","delt-front","triceps-lateral"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2,"repRange":[6,12],"alternatives":["machine-chest-press","converging-chest-press","plate-loaded-chest-press","smith-bench-press","barbell-bench-press","push-up"],"setup":{"en":"Sit on the end of a flat bench with the dumbbells on your thighs, lie back and kick them up with your knees to the start. Arms straight above the lower chest, palms forward or angled slightly in.","ru":"Сядьте на край горизонтальной скамьи, гантели на бёдрах, лягте и толчком коленей подайте их в исходное положение. Руки прямые над нижней частью груди, ладони вперёд или слегка развёрнуты друг к другу."},"cues":{"en":["Shoulder blades back and down, feet flat; head, shoulders and hips stay on the bench.","Lower for 2–3 s to the sides of the chest, elbows 45–70° from your torso, forearms vertical.","Stop at chest level — a little deeper than a bar allows, not as deep as you can go.","Breathe out and press up and slightly in until the dumbbells nearly touch over the chest.","Keep the wrists straight and stacked over the elbows.","Finish by pulling the dumbbells to your chest and rocking up with them onto your thighs."],"ru":["Лопатки сведены и опущены, стопы на полу; голова, лопатки и таз остаются на скамье.","Опускайте 2–3 секунды к бокам груди: локти под 45–70° к корпусу, предплечья вертикальны.","Остановитесь на уровне груди: чуть глубже, чем позволяет штанга, но не до предела.","На выдохе выжимайте вверх и немного внутрь, пока гантели почти не соприкоснутся над грудью.","Запястья прямые, точно над локтями.","Закончив, подтяните гантели к груди и вместе с ними перекатитесь в положение сидя, опустив их на бёдра."]},"mistakes":{"en":["Dropping the dumbbells far below the chest for a “stretch” — strains the front of the shoulder.","Elbows flared out to 90° at the bottom.","Clanging the dumbbells together and losing tension at the top.","Lifting the hips off the bench to finish a rep.","Dumping the dumbbells out to the sides after the set."],"ru":["Гантели опускают намного ниже груди «для растяжки» — это перегружает переднюю часть плеча.","Локти внизу разведены на 90°.","Гантели бьются друг о друга вверху, и мышцы теряют напряжение.","Отрыв таза от скамьи, чтобы дожать.","Гантели бросают в стороны после подхода."]},"startLoad":{"kg":12,"source":"Per hand: 0.6 × Strength Level Beginner dumbbell bench 1RM (19 kg per hand at 80 kg) ≈ 11 kg"},"tags":["owner-alt"],"images":[],"sources":["Chest Press (dumbbells) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/19/chest-press/","Saeterbakken et al., Muscle activity and 1-RM of three chest presses with different stability — J Sports Sci, 2011. https://doi.org/10.1080/02640414.2010.543916","Welsch et al., Pectoralis and anterior deltoid EMG in three upper-body lifts — J Strength Cond Res, 2005. https://doi.org/10.1519/14513.1","Dumbbell Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-bench-press/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"barbell-bench-press","equipment_id":"barbell","name":{"en":"Barbell bench press","ru":"Жим штанги лёжа"},"pattern":"horizontal-push","details":{"id":"barbell-bench-press","class":"horizontal-press","pattern":"horizontal-push","name":{"en":"Barbell bench press","ru":"Жим штанги лёжа"},"aka":["Bench press","Flat bench press","BB bench"],"equipment":"barbell","primary":["pec-sternal"],"secondary":["pec-clavicular","delt-front","triceps-lateral"],"difficulty":3,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[4,8],"alternatives":["machine-chest-press","converging-chest-press","plate-loaded-chest-press","dumbbell-bench-press","smith-bench-press","push-up"],"setup":{"en":"Lie with your eyes under the bar and grip about 1.5× shoulder width, bar low in the palm over the forearm. You train alone, so set the rack''s safety arms just below chest height first.","ru":"Лягте так, чтобы глаза были под грифом; хват примерно в 1,5 ширины плеч, гриф лежит в основании ладони над предплечьем. Вы тренируетесь без страхующего, поэтому сначала выставьте страховочные упоры стойки чуть ниже уровня груди."},"cues":{"en":["Pinch the shoulder blades together and down, keep a small arch, feet pressing into the floor.","Take a big breath and brace before each rep; breathe out near the top.","Lower for 2–3 s to the lower chest, between the nipples and the bottom of the sternum.","Forearms vertical, elbows 45–70° from the torso.","Touch without bouncing, then drive the bar up and slightly back over the shoulders.","Butt, upper back and head stay on the bench.","Stop each set with 1–2 reps in reserve — there is no spotter."],"ru":["Сведите и опустите лопатки, сохраните небольшой прогиб, стопы упираются в пол.","Перед каждым повтором — глубокий вдох и напряжённый пресс; выдох ближе к верху.","Опускайте 2–3 секунды к нижней части груди — между сосками и низом грудины.","Предплечья вертикальны, локти под 45–70° к корпусу.","Коснитесь груди без отбива и выжимайте вверх и немного назад, к линии плеч.","Ягодицы, верх спины и голова остаются на скамье.","Заканчивайте подход с запасом 1–2 повтора — страхующего нет."]},"mistakes":{"en":["Benching heavy alone without the safety arms set.","Grip much wider than 1.5× shoulder width — more load on the AC joint.","Elbows flared out to 90°.","Bouncing the bar off the chest.","Hips lifting off the bench.","Shoulders shrugging toward the ears at lockout."],"ru":["Тяжёлый жим в одиночку без выставленных страховочных упоров.","Хват намного шире 1,5 ширины плеч — больше нагрузки на акромиально-ключичный сустав.","Локти разведены на 90°.","Отбив грифа от груди.","Таз отрывается от скамьи.","Плечи поднимаются к ушам в верхней точке."]},"startLoad":{"kg":32.5,"source":"Bar + plates: 0.6 × Strength Level Beginner bench 1RM (56 kg at 80 kg) ≈ 34 kg, rounded down"},"tags":["owner-alt"],"images":[],"sources":["Nuckols, How to Bench Press: The Definitive Guide — Stronger by Science, accessed 2026. https://www.strongerbyscience.com/how-to-bench/","Noteboom et al., Bench press technique variations and musculoskeletal shoulder loads — Front Physiol, 2024. https://doi.org/10.3389/fphys.2024.1393235","NSCA, Exercise Technique Manual for Resistance Training, 3rd ed. — Human Kinetics, 2016. https://canada.humankinetics.com/products/exercise-technique-manual-for-resistance-training-3rd-edition-with-online-video","Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/bench-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"push-up","equipment_id":"bodyweight","name":{"en":"Push-up","ru":"Отжимания от пола"},"pattern":"horizontal-push","details":{"id":"push-up","class":"horizontal-press","pattern":"horizontal-push","name":{"en":"Push-up","ru":"Отжимания от пола"},"aka":["Press-up","Floor push-up"],"equipment":"bodyweight","primary":["pec-sternal"],"secondary":["delt-front","triceps-lateral","serratus-anterior","rectus-abdominis"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[6,20],"alternatives":["machine-chest-press","converging-chest-press","plate-loaded-chest-press","dumbbell-bench-press","smith-bench-press","barbell-bench-press"],"setup":{"en":"Hands slightly wider than the shoulders and under them, body straight from head to heels with glutes and abs tight. Too hard: hands on a bench; too easy: feet raised or a plate on the upper back.","ru":"Ладони чуть шире плеч, под плечевыми суставами; тело — прямая линия от головы до пяток, ягодицы и пресс напряжены. Тяжело — упритесь руками в скамью; легко — поставьте ноги на возвышение или положите блин на верх спины."},"cues":{"en":["Brace like a plank: hips neither sag nor pike.","Lower for 2 s with the elbows about 45° from your body until the chest is a fist from the floor.","Head in line with the spine — the chest leads, not the chin.","Breathe out and push the floor away until the arms are straight.","At the top, push a little further to spread the shoulder blades (push-up plus).","Progress with reps first, then a harder lever (feet up) or added load."],"ru":["Держите тело как в планке: таз не провисает и не задирается.","Опускайтесь 2 секунды, локти примерно под 45° к корпусу, пока до пола не останется кулак.","Голова на одной линии с позвоночником — к полу идёт грудь, а не подбородок.","На выдохе отталкивайте пол, пока руки не выпрямятся.","Вверху дотолкните чуть дальше, разводя лопатки (push-up plus).","Прогрессируйте сначала повторами, потом более тяжёлым вариантом (ноги выше) или отягощением."]},"mistakes":{"en":["Hips sagging, so the lower back hangs into an arch.","Elbows flared straight out to 90°.","Half reps that stop well above the floor.","Head dropping and the neck craning toward the floor."],"ru":["Таз провисает, поясница прогибается.","Локти разведены прямо в стороны, на 90°.","Половинчатые повторы высоко над полом.","Голова опущена, шея тянется к полу."]},"startLoad":{"kg":0,"source":"Body weight; Strength Level Beginner = 6 push-ups for an 80 kg man"},"tags":["owner-alt"],"images":[],"sources":["Push-Ups — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/41/push-up/","Calatayud et al., Bench press and push-up at matched muscle activity give similar strength gains — J Strength Cond Res, 2015. https://doi.org/10.1519/JSC.0000000000000589","Kotarsky et al., Progressive push-up training: muscle strength and thickness — J Strength Cond Res, 2018. https://doi.org/10.1519/JSC.0000000000002345","Push Ups Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/push-ups/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-incline-press","equipment_id":"selectorized","name":{"en":"Incline chest press machine","ru":"Наклонный жим от груди в тренажёре"},"pattern":"incline-push","details":{"id":"machine-incline-press","class":"incline-press","pattern":"incline-push","name":{"en":"Incline chest press machine","ru":"Наклонный жим от груди в тренажёре"},"aka":["Hammer Strength MTS Iso-Lateral Incline Press","Incline press machine","Seated incline chest press","Incline lever press"],"equipment":"selectorized","primary":["pec-clavicular"],"secondary":["delt-front","pec-sternal","triceps-lateral"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"alternatives":["plate-loaded-incline-press","incline-dumbbell-press","smith-incline-press","low-to-high-cable-fly"],"setup":{"en":"Set the seat so the handles start at upper-chest height, just below the collarbones. Sit with hips all the way back, back and head on the pad, feet flat.","ru":"Отрегулируйте сиденье так, чтобы рукоятки в старте были на уровне верха груди, чуть ниже ключиц. Таз до упора назад, спина и голова на спинке, стопы на полу."},"cues":{"en":["Shoulder blades back and down, chest lifted toward the handles.","Straight wrists; elbows about 45–60° from your sides, under the handles.","Breathe out and press along the machine''s path until the arms are nearly straight.","Shoulders stay on the pad at the top — reach with the arms, not with a shrug.","Lower for 2–3 s until the hands are back at the upper chest, no deeper.","Keep the low back''s natural curve; don''t slide the hips forward.","The upper chest should do the work: if the shoulders take over, raise the seat one notch."],"ru":["Лопатки сведены и опущены, грудь подана к рукояткам.","Запястья прямые; локти примерно под 45–60° к корпусу, под рукоятками.","На выдохе выжимайте по траектории тренажёра до почти прямых рук.","Вверху плечи остаются на спинке — тянитесь руками, а не плечами к ушам.","Опускайте 2–3 секунды, пока кисти не вернутся к верху груди, — не глубже.","Сохраняйте естественный прогиб в пояснице; не сползайте тазом вперёд.","Работать должен верх груди: если тянут плечи, поднимите сиденье на одну позицию."]},"mistakes":{"en":["Seat too low, so the handles start near the ears and it turns into a shoulder press that pinches the front of the shoulder.","Shrugging toward the ears at the top.","Elbows flared out past ~75°.","Arching hard or sliding the hips forward to finish reps.","Ego loading, with the plates banging between reps."],"ru":["Сиденье слишком низко: рукоятки стартуют у ушей, и упражнение превращается в жим на плечи, который защемляет переднюю часть плеча.","Плечи поднимаются к ушам вверху.","Локти разведены шире ~75°.","Сильный прогиб или сползание таза вперёд, чтобы дожать.","Эго-лифтинг: плиты грузоблока бьются между повторами."]},"startLoad":{"kg":20,"source":"≈0.6 × Strength Level chest-press Beginner 39 kg × 0.89 (incline vs flat bench, 50 vs 56 kg) ≈ 21 kg"},"tags":["owner-primary"],"images":[],"sources":["Rodríguez-Ridao et al., Five bench inclinations and pectoralis, deltoid and triceps EMG — Int J Environ Res Public Health, 2020. https://doi.org/10.3390/ijerph17197339","Seated Chest Press — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/188/seated-chest-press/","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Incline Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/incline-bench-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"plate-loaded-incline-press","equipment_id":"plate-loaded","name":{"en":"Plate-loaded incline press","ru":"Наклонный жим в рычажном тренажёре"},"pattern":"incline-push","details":{"id":"plate-loaded-incline-press","class":"incline-press","pattern":"incline-push","name":{"en":"Plate-loaded incline press","ru":"Наклонный жим в рычажном тренажёре"},"aka":["Hammer Strength Iso-Lateral Incline Press","Hammer Strength Iso-Lateral Super Incline Press","Technogym Pure Strength Incline Chest Press","Lever incline chest press","Iso-lateral incline press"],"equipment":"plate-loaded","primary":["pec-clavicular"],"secondary":["delt-front","pec-sternal","triceps-lateral"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["machine-incline-press","incline-dumbbell-press","smith-incline-press","low-to-high-cable-fly"],"setup":{"en":"Set the seat so the handles start at upper-chest height, just below the collarbones. Load equal plates on both arms and log their total.","ru":"Сиденье так, чтобы рукоятки в старте были на уровне верха груди, чуть ниже ключиц. Вешайте на оба рычага одинаковые диски и записывайте их общий вес."},"cues":{"en":["Back and head on the pad, shoulder blades pulled back and down.","Elbows 45–60° from your sides with the wrists stacked over them.","Breathe out and press both arms evenly up and slightly together.","Stop just short of lockout with the shoulders down.","Lower for 2–3 s to the upper chest without letting the levers drop.","On a “super incline” model the angle is steep: expect more front-delt work and a lighter load."],"ru":["Спина и голова на спинке, лопатки сведены и опущены.","Локти под 45–60° к корпусу, запястья точно над локтями.","На выдохе выжимайте обе руки равномерно вверх и чуть к центру.","Не блокируйте локти до упора; плечи опущены.","Опускайте 2–3 секунды к верху груди, не роняя рычаги.","В модели «super incline» угол крутой: больше работают передние дельты, вес будет меньше."]},"mistakes":{"en":["Seat too low, so it becomes a shoulder press.","Levers dropping into a deep stretch behind the chest.","Shrugging at lockout.","Uneven plates, or one arm racing ahead of the other."],"ru":["Сиденье слишком низко — получается жим на плечи.","Рычаги проваливаются в глубокое растяжение за линию груди.","Подъём плеч к ушам в верхней точке.","Разный вес на рычагах или одна рука опережает другую."]},"startLoad":{"kg":17.5,"source":"Total plates (8.75 kg per arm): ≈0.6 × the incline-bench seed (Strength Level Beginner 50 kg × 0.6 = 30 kg), research 04 §3.8"},"tags":["owner-alt"],"images":[],"sources":["Rodríguez-Ridao et al., Five bench inclinations and pectoralis, deltoid and triceps EMG — Int J Environ Res Public Health, 2020. https://doi.org/10.3390/ijerph17197339","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Incline Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/incline-bench-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"smith-incline-press","equipment_id":"smith","name":{"en":"Smith machine incline press","ru":"Жим на наклонной скамье в машине Смита"},"pattern":"incline-push","details":{"id":"smith-incline-press","class":"incline-press","pattern":"incline-push","name":{"en":"Smith machine incline press","ru":"Жим на наклонной скамье в машине Смита"},"aka":["Incline Smith press","Technogym Multipower incline press","Smith incline bench press"],"equipment":"smith","primary":["pec-clavicular"],"secondary":["delt-front","pec-sternal","triceps-lateral"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["machine-incline-press","plate-loaded-incline-press","incline-dumbbell-press","incline-barbell-press","low-to-high-cable-fly"],"setup":{"en":"Set an adjustable bench to about 30° and place it so the bar comes down just below your collarbones; set the safety stops just below that touch point. Grip about 1.5× shoulder width.","ru":"Установите регулируемую скамью примерно на 30° так, чтобы гриф опускался чуть ниже ключиц, а страховочные упоры — чуть ниже точки касания. Хват около 1,5 ширины плеч."},"cues":{"en":["Shoulder blades back and down, feet flat, hips on the seat.","Unrack by rotating the hooks with straight arms.","Lower for 2–3 s to the upper chest, forearms vertical, elbows 45–70° from your sides.","Touch lightly, breathe out and press straight up.","Keep the bench near 30°: steeper turns it into a shoulder press.","Hook the bar onto a pin after the last rep before you sit up."],"ru":["Лопатки сведены и опущены, стопы на полу, таз на сиденье.","Снимайте гриф поворотом крюков на прямых руках.","Опускайте 2–3 секунды к верху груди: предплечья вертикальны, локти под 45–70° к корпусу.","Легко коснитесь груди и на выдохе выжмите вверх.","Держите наклон около 30°: круче — и это уже жим на плечи.","После последнего повтора зацепите гриф за упор и только потом вставайте."]},"mistakes":{"en":["Bench at 45–60°: the front delts take over.","Bench in the wrong spot, so the bar lands on the neck or mid-chest.","No safety stops set.","Elbows flared out past ~75° with the shoulders shrugging."],"ru":["Наклон скамьи 45–60°: работу забирают передние дельты.","Скамья стоит не там: гриф опускается на шею или середину груди.","Не выставлены страховочные упоры.","Локти разведены шире ~75°, плечи поднимаются к ушам."]},"startLoad":{"kg":30,"source":"Bar + plates: 0.6 × Strength Level Beginner incline bench 1RM (50 kg at 80 kg) = 30 kg; Smith ≈ 0.97 × barbell"},"tags":["owner-alt"],"images":[],"sources":["Rodríguez-Ridao et al., Five bench inclinations and pectoralis, deltoid and triceps EMG — Int J Environ Res Public Health, 2020. https://doi.org/10.3390/ijerph17197339","Saeterbakken et al., Muscle activity and 1-RM of three chest presses with different stability — J Sports Sci, 2011. https://doi.org/10.1080/02640414.2010.543916","Incline Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/incline-bench-press/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"incline-dumbbell-press","equipment_id":"dumbbell","name":{"en":"Incline dumbbell press","ru":"Жим гантелей на наклонной скамье"},"pattern":"incline-push","details":{"id":"incline-dumbbell-press","class":"incline-press","pattern":"incline-push","name":{"en":"Incline dumbbell press","ru":"Жим гантелей на наклонной скамье"},"aka":["Incline DB press","Incline dumbbell bench press","Incline dumbbell chest press"],"equipment":"dumbbell","primary":["pec-clavicular"],"secondary":["delt-front","pec-sternal","triceps-lateral"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2,"repRange":[6,12],"alternatives":["machine-incline-press","plate-loaded-incline-press","smith-incline-press","incline-barbell-press","low-to-high-cable-fly"],"setup":{"en":"Set the bench to about 30°. Sit with the dumbbells on your thighs, lie back and kick them up one knee at a time to arms'' length over the upper chest.","ru":"Установите скамью примерно на 30°. Сядьте с гантелями на бёдрах, лягте и толчком коленей по очереди подайте их на прямые руки над верхом груди."},"cues":{"en":["Shoulder blades back and down; head, shoulders and hips stay on the bench.","Lower for 2–3 s to the sides of the upper chest, elbows 45–70° from your torso.","Stop at chest level; don''t sink the dumbbells far below it.","Breathe out and press up and slightly in, finishing over the upper chest.","Keep the wrists straight over the elbows.","End the set by bringing the dumbbells to your chest and sitting up with them on your thighs."],"ru":["Лопатки сведены и опущены; голова, лопатки и таз остаются на скамье.","Опускайте 2–3 секунды к бокам верхней части груди, локти под 45–70° к корпусу.","Остановитесь на уровне груди; не опускайте гантели намного ниже.","На выдохе выжимайте вверх и немного внутрь, до положения над верхом груди.","Запястья прямые, точно над локтями.","Закончив подход, подтяните гантели к груди и сядьте, опустив их на бёдра."]},"mistakes":{"en":["Bench at 45° or steeper: the front delts take the work.","Sinking the dumbbells deep below the chest.","Elbows flared out to 90°.","Hips lifting or the back arching hard to finish reps."],"ru":["Скамья под 45° и круче: работу забирают передние дельты.","Гантели опускают глубоко ниже груди.","Локти разведены на 90°.","Отрыв таза или сильный прогиб спины, чтобы дожать."]},"startLoad":{"kg":12,"source":"Per hand: 0.6 × Strength Level Beginner incline dumbbell press 1RM (22 kg per hand at 80 kg) ≈ 13 kg, rounded down"},"tags":["owner-alt"],"images":[],"sources":["Rodríguez-Ridao et al., Five bench inclinations and pectoralis, deltoid and triceps EMG — Int J Environ Res Public Health, 2020. https://doi.org/10.3390/ijerph17197339","Incline Chest Press (dumbbells) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/25/incline-chest-press/","Incline Dumbbell Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/incline-dumbbell-bench-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"incline-barbell-press","equipment_id":"barbell","name":{"en":"Incline barbell bench press","ru":"Жим штанги на наклонной скамье"},"pattern":"incline-push","details":{"id":"incline-barbell-press","class":"incline-press","pattern":"incline-push","name":{"en":"Incline barbell bench press","ru":"Жим штанги на наклонной скамье"},"aka":["Incline bench press","Incline BB press"],"equipment":"barbell","primary":["pec-clavicular"],"secondary":["delt-front","pec-sternal","triceps-lateral"],"difficulty":3,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[4,8],"alternatives":["machine-incline-press","plate-loaded-incline-press","incline-dumbbell-press","smith-incline-press","low-to-high-cable-fly"],"setup":{"en":"Use an incline bench near 30° inside a rack with the safety arms just below the bar''s lowest point. Grip about 1.5× shoulder width, bar low in the palm.","ru":"Работайте на наклонной скамье под углом около 30° в силовой раме, страховочные упоры — чуть ниже нижней точки грифа. Хват около 1,5 ширины плеч, гриф в основании ладони."},"cues":{"en":["Pinch the shoulder blades back and down; feet flat.","Unrack with straight arms and bring the bar over the upper chest.","Big breath, brace, then lower for 2–3 s to just below the collarbones.","Forearms vertical, elbows 45–70° from your torso.","Touch without bouncing and press straight up, breathing out near the top.","Leave 1–2 reps in reserve — there is no spotter."],"ru":["Сведите и опустите лопатки; стопы на полу.","Снимите гриф на прямых руках и выведите его над верхом груди.","Глубокий вдох, напрягите пресс и опускайте 2–3 секунды чуть ниже ключиц.","Предплечья вертикальны, локти под 45–70° к корпусу.","Коснитесь без отбива и жмите вверх, выдыхая ближе к верху.","Оставляйте запас 1–2 повтора — страхующего нет."]},"mistakes":{"en":["Training heavy alone without safety arms.","Using a fixed 45° bench as a chest exercise: the work shifts to the front delts.","Bouncing the bar off the chest.","Elbows flared out to 90°.","Hips lifting off the seat."],"ru":["Тяжёлые подходы в одиночку без страховочных упоров.","Фиксированная скамья на 45° вместо «грудного» угла: нагрузка уходит в передние дельты.","Отбив грифа от груди.","Локти разведены на 90°.","Таз отрывается от сиденья."]},"startLoad":{"kg":30,"source":"Bar + plates: 0.6 × Strength Level Beginner incline bench 1RM (50 kg at 80 kg) = 30 kg"},"tags":["owner-alt"],"images":[],"sources":["Rodríguez-Ridao et al., Five bench inclinations and pectoralis, deltoid and triceps EMG — Int J Environ Res Public Health, 2020. https://doi.org/10.3390/ijerph17197339","Noteboom et al., Bench press technique variations and musculoskeletal shoulder loads — Front Physiol, 2024. https://doi.org/10.3389/fphys.2024.1393235","Nuckols, How to Bench Press: The Definitive Guide — Stronger by Science, accessed 2026. https://www.strongerbyscience.com/how-to-bench/","Incline Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/incline-bench-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"low-to-high-cable-fly","equipment_id":"cable","name":{"en":"Low-to-high cable fly","ru":"Сведение рук в кроссовере снизу вверх"},"pattern":"chest-fly","details":{"id":"low-to-high-cable-fly","class":"incline-press","pattern":"chest-fly","name":{"en":"Low-to-high cable fly","ru":"Сведение рук в кроссовере снизу вверх"},"aka":["Low cable fly","Incline cable fly","Low-to-high cable crossover","Upward cable fly"],"equipment":"cable","primary":["pec-clavicular"],"secondary":["delt-front","pec-sternal"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[8,15],"alternatives":["cable-fly","pec-deck","machine-incline-press","incline-dumbbell-press","dumbbell-fly","high-to-low-cable-fly"],"setup":{"en":"Set both pulleys between knee and hip height with single handles. Step forward into a staggered stance until the cables pull your arms slightly back and down, palms forward, elbows softly bent.","ru":"Установите оба блока между уровнем коленей и бёдер, одиночные рукоятки. Шагните вперёд в разножку, чтобы тросы слегка тянули руки назад-вниз; ладони вперёд, локти слегка согнуты."},"cues":{"en":["Brace the abs and keep the torso upright — no leaning back.","Lock a soft bend in the elbows; it doesn''t change during the rep.","Sweep the hands up and in along an arc, finishing level with the chin.","Squeeze for 1 s with the hands together, breathing out.","Lower for 2–3 s and stop when the hands reach the line of your armpits — not behind you.","Keep the shoulders down: the upper chest lifts the arms, not a shrug."],"ru":["Напрягите пресс и держите корпус вертикально — без отклонения назад.","Зафиксируйте лёгкий сгиб в локтях; он не меняется по ходу повтора.","Ведите руки по дуге вверх и к центру, заканчивая на уровне подбородка.","Задержитесь на 1 секунду, кисти вместе, — на выдохе.","Опускайте 2–3 секунды и остановитесь, когда кисти дошли до линии подмышек, — не за спину.","Плечи опущены: руки поднимает верх груди, а не трапеции."]},"mistakes":{"en":["Bending the elbows so it becomes a front raise or a press.","Letting the cables pull the hands behind the body at the bottom.","Shrugging and leaning back to lift the handles.","Too much weight, so the reps get short and jerky."],"ru":["Сгибание локтей — получается подъём перед собой или жим.","Тросы утягивают руки за корпус в нижней точке.","Подъём плеч к ушам и отклонение назад, чтобы поднять рукоятки.","Слишком большой вес: повторы короткие и рывковые."]},"startLoad":{"kg":5,"source":"Per handle: ≈0.6 × Strength Level Beginner cable fly 1RM (8 kg at 80 kg)"},"tags":["owner-alt"],"images":[],"sources":["Incline Cable Flyes — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/163/standing-incline-cable-flyes/","Rodríguez-Ridao et al., Five bench inclinations and pectoralis, deltoid and triceps EMG — Int J Environ Res Public Health, 2020. https://doi.org/10.3390/ijerph17197339","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Cable Fly Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-fly/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"triceps-press-machine","equipment_id":"selectorized","name":{"en":"Triceps press machine (seated dip)","ru":"Отжимания сидя в тренажёре (на трицепс)"},"pattern":"decline-push","details":{"id":"triceps-press-machine","class":"decline-press","pattern":"decline-push","name":{"en":"Triceps press machine (seated dip)","ru":"Отжимания сидя в тренажёре (на трицепс)"},"aka":["Seated dip machine","Life Fitness Insignia Triceps Press","Nautilus Inspiration Tricep Dip","Matrix Ultra Triceps Press","Hammer Strength Plate-Loaded Seated Dip","Nautilus One Triceps Press"],"equipment":"selectorized","primary":["triceps-lateral","pec-costal"],"secondary":["triceps-long","delt-front","pec-sternal"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"alternatives":["assisted-dip","decline-chest-press-machine","dip","diamond-push-up","machine-triceps-extension"],"setup":{"en":"Set the seat so that, holding the handles at your sides, your elbows are bent about 90° with the hands just below chest height. Fasten the thigh pad snugly and sit tall with your back on the pad.","ru":"Отрегулируйте сиденье так, чтобы, держа рукоятки по бокам, локти были согнуты примерно на 90°, а кисти — чуть ниже уровня груди. Плотно зафиксируйте валик на бёдрах, сядьте ровно, спина на спинке."},"cues":{"en":["Sit tall with the chest up and the shoulders pulled down away from the ears.","Keep the elbows close to your sides and pointing back, not out.","Breathe out and press the handles down until the arms are straight.","Squeeze the triceps for a second at the bottom without shrugging.","Return for 2–3 s until the elbows are bent about 90° — no higher.","Stay upright for the triceps; leaning forward shifts the work to the chest.","Move only at the elbows and shoulders — no rocking off the seat."],"ru":["Сядьте ровно, грудь вперёд, плечи опущены — подальше от ушей.","Локти близко к корпусу и направлены назад, а не в стороны.","На выдохе выжимайте рукоятки вниз до прямых рук.","Внизу секунду напрягите трицепс, не поднимая плечи.","Возвращайте рукоятки 2–3 секунды, пока локти не согнутся примерно на 90°, — не выше.","Для трицепса держите корпус вертикально; наклон вперёд переносит работу на грудь.","Движение только в локтях и плечах — без раскачки на сиденье."]},"mistakes":{"en":["Letting the handles ride up past 90° so the shoulders roll forward — strains the front of the shoulder.","Elbows flaring wide.","Shrugging the shoulders up at the top of each rep.","Rocking or lifting off the seat to move the stack.","Ego loading with half reps near the bottom."],"ru":["Рукоятки уходят вверх выше 90°, плечи заваливаются вперёд — перегрузка передней части плеча.","Локти разводятся в стороны.","Плечи поднимаются к ушам в верхней точке каждого повтора.","Раскачка или отрыв от сиденья, чтобы сдвинуть вес.","Эго-лифтинг с половинчатыми повторами внизу."]},"startLoad":{"kg":35,"source":"≈0.6 × Strength Level Beginner seated dip machine 1RM (56 kg at 80 kg) ≈ 34 kg"},"tags":["owner-primary"],"images":[],"sources":["McKenzie et al., Bench, bar and ring dips: kinematics and muscle activity — Int J Environ Res Public Health, 2022. https://doi.org/10.3390/ijerph192013211","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Seated Dip Machine Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/seated-dip-machine/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"decline-chest-press-machine","equipment_id":"plate-loaded","name":{"en":"Decline chest press machine","ru":"Жим под отрицательным углом в тренажёре"},"pattern":"decline-push","details":{"id":"decline-chest-press-machine","class":"decline-press","pattern":"decline-push","name":{"en":"Decline chest press machine","ru":"Жим под отрицательным углом в тренажёре"},"aka":["Hammer Strength Iso-Lateral Decline Press","Hammer Strength MTS Iso-Lateral Decline Press","Lower chest press","Decline press machine"],"equipment":"plate-loaded","primary":["pec-costal","pec-sternal"],"secondary":["triceps-lateral","delt-front"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["assisted-dip","triceps-press-machine","dip","high-to-low-cable-fly","machine-chest-press"],"setup":{"en":"Set the seat so the handles start at lower-chest height with your back on the pad; the arms press forward and down toward the waist. On plate-loaded models load both arms equally and log the total.","ru":"Отрегулируйте сиденье так, чтобы рукоятки в старте были на уровне нижней части груди, спина на спинке; рычаги идут вперёд-вниз, к поясу. В моделях с дисками вешайте поровну на оба рычага и записывайте общий вес."},"cues":{"en":["Shoulder blades back and down before the first rep.","Elbows about 45° from your sides, wrists straight.","Breathe out and press forward and down until the arms are almost straight.","Keep the shoulders on the pad; don''t let them roll forward at the end.","Return for 2–3 s until the hands are back at the lower chest.","Press both arms evenly — the levers are independent."],"ru":["Перед первым повтором сведите и опустите лопатки.","Локти примерно под 45° к корпусу, запястья прямые.","На выдохе выжимайте вперёд-вниз почти до прямых рук.","Плечи остаются на спинке, не заваливайте их вперёд в конце.","Возвращайте 2–3 секунды, пока кисти не вернутся к нижней части груди.","Жмите обеими руками равномерно — рычаги независимые."]},"mistakes":{"en":["Seat set so the handles start at mid-chest or higher — it becomes a flat press.","Letting the levers pull the hands behind the chest line.","Shoulders rolling forward and shrugging at lockout.","Ego loading with bounced reps."],"ru":["Сиденье выставлено так, что рукоятки стартуют на середине груди или выше, — получается обычный жим.","Рычаги утягивают кисти за линию груди.","Плечи заваливаются вперёд и поднимаются в конце жима.","Эго-лифтинг с отбитыми повторами."]},"startLoad":{"kg":20,"source":"Total plates (10 kg per arm): ≈0.6 × the decline-bench seed (Strength Level Beginner 58 kg × 0.6 ≈ 35 kg), research 04 §3.8"},"tags":["owner-alt"],"images":[],"sources":["Seated Decline Cable Press — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/166/seated-decline-cable-press/","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Decline Bench Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/decline-bench-press/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"assisted-dip","equipment_id":"assisted","name":{"en":"Assisted dip machine","ru":"Отжимания на брусьях в гравитроне"},"pattern":"decline-push","details":{"id":"assisted-dip","class":"decline-press","pattern":"decline-push","name":{"en":"Assisted dip machine","ru":"Отжимания на брусьях в гравитроне"},"aka":["Gravitron dip","Life Fitness Insignia Assist Dip Chin","Assisted dip/chin machine","Machine-assisted dip"],"equipment":"assisted","primary":["pec-costal","triceps-lateral"],"secondary":["delt-front","pec-sternal","triceps-long"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"assistance":true,"alternatives":["triceps-press-machine","decline-chest-press-machine","dip","diamond-push-up","high-to-low-cable-fly"],"setup":{"en":"Choose the assistance first (more kg = easier), take the dip handles, then kneel or stand on the platform with straight arms and the shoulders pulled down. Log the assistance, not your body weight.","ru":"Сначала выберите противовес (больше кг — легче), возьмитесь за брусья, затем встаньте коленями или стопами на платформу на прямых руках, плечи опущены. Записывайте вес противовеса, а не свой вес."},"cues":{"en":["Start tall: arms straight, shoulders pushed down away from the ears.","Lean the torso slightly forward and keep the elbows pointing back.","Lower for 2–3 s until the upper arms are about parallel to the floor — no deeper.","Breathe out and press up until the arms are straight.","Keep tension at the top; don''t let the platform bounce you.","Once you pass 12 reps, take 5 kg of assistance off."],"ru":["Старт в верхней точке: руки прямые, плечи опущены, подальше от ушей.","Слегка наклоните корпус вперёд, локти направлены назад.","Опускайтесь 2–3 секунды, пока плечи не станут примерно параллельны полу, — не глубже.","На выдохе выжимайте себя вверх до прямых рук.","Держите напряжение вверху — не давайте платформе подбрасывать вас.","Когда получается больше 12 повторов, уменьшите противовес на 5 кг."]},"mistakes":{"en":["Sinking far below parallel: the deepest part of the dip strains the front of the shoulder.","Shoulders shrugging up to the ears at the bottom.","Elbows flaring wide.","Dropping fast and bouncing off the counterweight.","Logging it backwards: less assistance means harder."],"ru":["Опускание намного ниже параллели: самая глубокая часть движения перегружает переднюю часть плеча.","Плечи поднимаются к ушам в нижней точке.","Локти разводятся в стороны.","Быстрое падение вниз и отбив от противовеса.","Путаница в записи: меньше противовес — значит тяжелее."]},"startLoad":{"kg":40,"source":"Assistance, not load: about half of an 80 kg body weight, since Strength Level Beginner = 3 bodyweight dips; take 5 kg off after 12 reps"},"tags":["owner-alt"],"images":[],"sources":["McKenzie et al., Bench, bar and ring dips: kinematics and muscle activity — Int J Environ Res Public Health, 2022. https://doi.org/10.3390/ijerph192013211","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Dips Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/dips/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dip","equipment_id":"bodyweight","name":{"en":"Parallel bar dip","ru":"Отжимания на брусьях"},"pattern":"decline-push","details":{"id":"dip","class":"decline-press","pattern":"decline-push","name":{"en":"Parallel bar dip","ru":"Отжимания на брусьях"},"aka":["Dip","Bar dip","Chest dip","Triceps dip"],"equipment":"bodyweight","primary":["pec-costal","triceps-lateral"],"secondary":["delt-front","pec-sternal","triceps-long"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[5,12],"alternatives":["assisted-dip","triceps-press-machine","decline-chest-press-machine","diamond-push-up","close-grip-bench-press","high-to-low-cable-fly"],"setup":{"en":"Grip the bars about shoulder width, jump to straight arms with the shoulders pushed down and cross your ankles behind you. Below 5 clean reps use the assisted dip; extra load later goes on a dip belt.","ru":"Возьмитесь за брусья примерно на ширине плеч, выпрыгните на прямые руки, опустив плечи, и скрестите голени позади. Пока не выходит 5 чистых повторов — используйте гравитрон; отягощение позже — на пояс для отягощений."},"cues":{"en":["Shoulders down and back at the top — long neck.","Lean slightly forward for more chest; stay upright for more triceps.","Lower for 2–3 s until the upper arms are about parallel to the floor.","Keep the elbows tracking back, not out.","Breathe out and press up to straight arms.","End the set when depth or speed starts to drop."],"ru":["Вверху плечи опущены и отведены назад — шея длинная.","Небольшой наклон вперёд — больше грудь; вертикальный корпус — больше трицепс.","Опускайтесь 2–3 секунды, пока плечи не станут примерно параллельны полу.","Локти идут назад, а не в стороны.","На выдохе выжимайте себя до прямых рук.","Заканчивайте подход, когда начинают проседать глубина или скорость."]},"mistakes":{"en":["Going far below parallel: the end-range stretch overloads the front of the shoulder.","Shoulders shrugging up to the ears at the bottom.","Swinging the legs or kipping.","Elbows flaring wide.","Adding weight before 12 clean bodyweight reps."],"ru":["Опускание сильно ниже параллели: растяжение в крайней точке перегружает переднюю часть плеча.","Плечи поднимаются к ушам в нижней точке.","Раскачка ногами или рывки.","Локти разводятся в стороны.","Отягощение раньше, чем получится 12 чистых повторов со своим весом."]},"startLoad":{"kg":0,"source":"Body weight; Strength Level Beginner = 3 dips for an 80 kg man — use the assisted dip below 5 reps"},"tags":["owner-alt"],"images":[],"sources":["McKenzie et al., Bench, bar and ring dips: kinematics and muscle activity — Int J Environ Res Public Health, 2022. https://doi.org/10.3390/ijerph192013211","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Dips Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/dips/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"high-to-low-cable-fly","equipment_id":"cable","name":{"en":"High-to-low cable fly","ru":"Сведение рук в кроссовере сверху вниз"},"pattern":"chest-fly","details":{"id":"high-to-low-cable-fly","class":"decline-press","pattern":"chest-fly","name":{"en":"High-to-low cable fly","ru":"Сведение рук в кроссовере сверху вниз"},"aka":["Cable crossover","High cable fly","Decline cable fly","Standing cable crossover"],"equipment":"cable","primary":["pec-costal"],"secondary":["pec-sternal","delt-front"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[8,15],"alternatives":["cable-fly","pec-deck","decline-chest-press-machine","assisted-dip","dumbbell-fly","low-to-high-cable-fly"],"setup":{"en":"Set both pulleys at or just above head height with single handles. Step forward into a staggered stance with a slight forward lean until the cables pull your arms up and back, elbows softly bent.","ru":"Установите оба блока на уровне головы или чуть выше, одиночные рукоятки. Шагните вперёд в разножку с лёгким наклоном корпуса, чтобы тросы тянули руки вверх-назад; локти слегка согнуты."},"cues":{"en":["Brace and hold the torso still; only the arms move.","Keep a fixed soft bend in the elbows.","Sweep the hands down and in to meet in front of the lower chest or belt line.","Squeeze for 1 s, breathing out.","Return for 2–3 s and stop when the hands reach the line of your armpits.","Keep the shoulders down and back as the hands meet."],"ru":["Напрягите пресс и держите корпус неподвижным — двигаются только руки.","Сохраняйте постоянный лёгкий сгиб в локтях.","Ведите руки по дуге вниз и к центру, сводя их перед низом груди или на уровне пояса.","Задержитесь на 1 секунду на выдохе.","Возвращайте 2–3 секунды и остановитесь, когда кисти дошли до линии подмышек.","Плечи опущены и отведены назад, когда кисти сходятся."]},"mistakes":{"en":["Letting the cables pull the arms behind the body.","Bending and straightening the elbows, so it becomes a pressdown.","Bobbing the torso to swing the weight.","Rounding the shoulders forward at the finish."],"ru":["Тросы утягивают руки за корпус.","Сгибание и разгибание локтей — получается жим вниз.","Раскачка корпусом, чтобы закинуть вес.","Плечи заваливаются вперёд в конце движения."]},"startLoad":{"kg":5,"source":"Per handle: ≈0.6 × Strength Level Beginner cable fly 1RM (8 kg at 80 kg)"},"tags":["owner-alt"],"images":[],"sources":["Standing Decline Cable Flyes — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/161/standing-decline-cable-flyes/","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Cable Fly Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-fly/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"pec-deck","equipment_id":"selectorized","name":{"en":"Pec deck (machine fly)","ru":"Бабочка (пек-дек)"},"pattern":"chest-fly","details":{"id":"pec-deck","class":"chest-fly","pattern":"chest-fly","name":{"en":"Pec deck (machine fly)","ru":"Бабочка (пек-дек)"},"aka":["Technogym Selection / Element Pectoral","Technogym Selection 700 Dual Pectoral/Reverse Fly","Life Fitness Insignia Pectoral Fly/Rear Deltoid","Nautilus Inspiration Pec Fly/Rear Deltoid","Machine chest fly","Butterfly"],"equipment":"selectorized","primary":["pec-sternal"],"secondary":["pec-clavicular","pec-costal","delt-front"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["cable-fly","dumbbell-fly","high-to-low-cable-fly","low-to-high-cable-fly"],"setup":{"en":"Set the seat so the handles (or arm pads) are at chest height with the upper arms about parallel to the floor. Set the start position so that at the widest point your hands are level with your body, never behind it.","ru":"Отрегулируйте сиденье так, чтобы рукоятки (или упоры для рук) были на высоте груди, а плечи — примерно параллельны полу. Выставьте стартовую позицию так, чтобы в самой широкой точке кисти были на линии корпуса, но не позади него."},"cues":{"en":["Head and back on the pad, shoulder blades pulled back and down.","Soft, fixed bend in the elbows — the movement happens at the shoulder.","Bring the handles together in a wide arc, as if hugging a big tree.","Squeeze for 1 s with the hands in front of your chest, breathing out.","Open for 2–3 s until you feel a stretch across the chest with the elbows still in line with your torso.","Keep the shoulders down and the neck relaxed through the whole rep.","Don''t let the plates touch between reps — keep the tension on."],"ru":["Голова и спина на спинке, лопатки сведены и опущены.","Лёгкий постоянный сгиб в локтях — движение идёт в плечевом суставе.","Сводите рукоятки по широкой дуге, будто обнимаете толстое дерево.","Задержитесь на 1 секунду, кисти перед грудью, — на выдохе.","Разводите 2–3 секунды до ощущения растяжения в груди, пока локти ещё на линии корпуса.","Плечи опущены, шея расслаблена весь повтор.","Не опускайте плиты до касания между повторами — держите напряжение."]},"mistakes":{"en":["Start position set too wide, so the arms are pulled behind the body — the “high-five” position that loads the front of the shoulder capsule.","Bending and straightening the elbows, turning it into a press.","Seat too low or too high: the handles end up above the shoulders or far below the chest.","Shoulders rolling forward or shrugging as the hands meet.","Letting the weight yank the arms open so the plates bang down.","Ego loading with short, jerky reps."],"ru":["Стартовая позиция слишком широкая: руки уходят за корпус — положение «дай пять», которое нагружает переднюю капсулу плечевого сустава.","Сгибание и разгибание локтей — получается жим.","Сиденье слишком низко или высоко: рукоятки оказываются выше плеч или намного ниже груди.","Плечи заваливаются вперёд или поднимаются, когда кисти сходятся.","Вес резко растаскивает руки, и плиты грузоблока бьются друг о друга.","Эго-лифтинг с короткими рывковыми повторами."]},"startLoad":{"kg":25,"source":"≈0.6 × Strength Level Beginner machine fly 1RM (42 kg at 80 kg), research 04 §3.9"},"tags":["owner-primary"],"images":[],"sources":["Machine Chest Fly: muscles worked and proper form — StrengthLog, 2026. https://www.strengthlog.com/machine-chest-fly/","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Pinto et al., Pectoralis thickness after one vs three sets of pec deck in untrained men — J Strength Cond Res, 2025. https://doi.org/10.1519/JSC.0000000000005045","Machine Chest Fly Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-chest-fly/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"cable-fly","equipment_id":"cable","name":{"en":"Cable fly","ru":"Сведение рук в кроссовере"},"pattern":"chest-fly","details":{"id":"cable-fly","class":"chest-fly","pattern":"chest-fly","name":{"en":"Cable fly","ru":"Сведение рук в кроссовере"},"aka":["Cable crossover fly","Standing cable fly","Cable chest fly","Mid-pulley cable fly"],"equipment":"cable","primary":["pec-sternal"],"secondary":["pec-clavicular","pec-costal","delt-front"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[8,15],"alternatives":["pec-deck","dumbbell-fly","high-to-low-cable-fly","low-to-high-cable-fly"],"setup":{"en":"Set both pulleys at or slightly above shoulder height with single handles. Take one handle in each hand, step forward into a staggered stance and lean slightly forward until the cables hold your arms open at chest height, elbows softly bent.","ru":"Установите оба блока на уровне плеч или чуть выше, одиночные рукоятки. Возьмите по рукоятке в каждую руку, шагните вперёд в разножку и слегка наклоните корпус, чтобы тросы удерживали разведённые руки на высоте груди; локти слегка согнуты."},"cues":{"en":["Staggered stance, abs braced, a slight forward lean that doesn''t change.","Fix a soft bend in the elbows for the whole set.","Sweep the hands forward and together at chest height, as if hugging a barrel.","Squeeze for 1 s with the hands meeting in front of your lower chest; breathe out.","Return for 2–3 s and stop when the hands are in line with your torso — never behind it.","Keep the shoulders down and back; don''t let them roll forward at the finish.","Pick a weight you control in the stretch: the cable loads the chest hardest there."],"ru":["Разножка, пресс напряжён, небольшой наклон вперёд, который не меняется.","Зафиксируйте лёгкий сгиб в локтях на весь подход.","Сводите руки вперёд на уровне груди, будто обнимаете бочку.","Задержитесь на 1 секунду, кисти сходятся перед нижней частью груди; выдох.","Возвращайте руки 2–3 секунды и остановитесь, когда кисти окажутся на линии корпуса, — не заводите их за спину.","Плечи опущены и отведены назад; не заваливайте их вперёд в конце.","Берите вес, который контролируете в растяжении: именно там трос нагружает грудь сильнее всего."]},"mistakes":{"en":["Letting the cables drag the arms far behind the body — strains the front of the shoulder.","Bending and straightening the elbows, turning it into a press.","Rocking the torso to swing the handles.","Shrugging or rounding the shoulders as the hands meet.","Ego loading — the stack slamming between reps."],"ru":["Тросы утягивают руки далеко за корпус — это перегружает переднюю часть плеча.","Сгибание и разгибание локтей — получается жим.","Раскачка корпусом, чтобы закинуть рукоятки.","Плечи поднимаются или заваливаются вперёд, когда кисти сходятся.","Эго-лифтинг — плиты грохочут между повторами."]},"startLoad":{"kg":5,"source":"Per handle: ≈0.6 × Strength Level Beginner cable fly 1RM (8 kg at 80 kg)"},"tags":["owner-primary"],"images":[],"sources":["Standing Chest Fly (cables) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/160/standing-chest-fly/","Standing Decline Cable Flyes — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/161/standing-decline-cable-flyes/","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Cable Fly Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-fly/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dumbbell-fly","equipment_id":"dumbbell","name":{"en":"Dumbbell fly","ru":"Разводка гантелей лёжа"},"pattern":"chest-fly","details":{"id":"dumbbell-fly","class":"chest-fly","pattern":"chest-fly","name":{"en":"Dumbbell fly","ru":"Разводка гантелей лёжа"},"aka":["Flat dumbbell fly","DB fly","Lying chest fly"],"equipment":"dumbbell","primary":["pec-sternal"],"secondary":["pec-clavicular","delt-front"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":2,"repRange":[10,15],"alternatives":["pec-deck","cable-fly","high-to-low-cable-fly","low-to-high-cable-fly"],"setup":{"en":"Lie on a flat bench, press the dumbbells up over your chest with the palms facing each other, then unlock the elbows into a slight bend.","ru":"Лягте на горизонтальную скамью, выжмите гантели над грудью ладонями друг к другу и слегка согните локти."},"cues":{"en":["Shoulder blades back and down; head, shoulders and hips on the bench.","Keep the slight elbow bend fixed from the first rep to the last.","Lower in a wide arc for 2–3 s until the dumbbells are level with your chest — no lower.","Breathe out and bring them back up along the same arc, as if hugging a barrel.","Stop with the dumbbells a hand''s width apart above the chest to keep the tension.","Go light: the stretch at the bottom is where the shoulder is most exposed."],"ru":["Лопатки сведены и опущены; голова, лопатки и таз на скамье.","Лёгкий сгиб в локтях одинаковый от первого повтора до последнего.","Опускайте по широкой дуге 2–3 секунды, пока гантели не окажутся на уровне груди, — не ниже.","На выдохе возвращайте их по той же дуге, будто обнимаете бочку.","Остановитесь, когда между гантелями останется ладонь, — так сохраняется напряжение.","Берите лёгкий вес: в растяжении внизу плечевой сустав наиболее уязвим."]},"mistakes":{"en":["Dropping the dumbbells below chest level for a deep stretch — the classic way to strain a shoulder or a pec.","Bending the elbows more as you lower, turning it into a press.","Going heavy for low reps.","Clanging the dumbbells together at the top.","Arching the back or lifting the hips."],"ru":["Гантели опускают ниже уровня груди ради глубокой растяжки — классический способ травмировать плечо или грудную мышцу.","Локти сгибаются всё сильнее по ходу опускания — получается жим.","Тяжёлый вес на малое число повторов.","Гантели бьются друг о друга вверху.","Прогиб в спине или отрыв таза."]},"startLoad":{"kg":4,"source":"Per hand: ≈0.6 × Strength Level Beginner dumbbell fly 1RM (8 kg per hand at 80 kg) ≈ 5 kg, rounded down"},"tags":["owner-alt"],"images":[],"sources":["Lying Chest Fly — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/21/lying-chest-fly/","Welsch et al., Pectoralis and anterior deltoid EMG in three upper-body lifts — J Strength Cond Res, 2005. https://doi.org/10.1519/14513.1","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Dumbbell Fly Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-fly/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-shoulder-press","equipment_id":"selectorized","name":{"en":"Shoulder press machine","ru":"Жим над головой в тренажёре"},"pattern":"vertical-push","details":{"id":"machine-shoulder-press","class":"vertical-press","pattern":"vertical-push","name":{"en":"Shoulder press machine","ru":"Жим над головой в тренажёре"},"aka":["Technogym Selection / Element Shoulder Press","Life Fitness Insignia Shoulder Press","Cybex Eagle NX Overhead Press","Matrix Versa Converging Shoulder Press","Hammer Strength MTS Iso-Lateral Shoulder Press","Nautilus Inspiration Shoulder Press"],"equipment":"selectorized","primary":["delt-front"],"secondary":["delt-side","triceps-lateral","pec-clavicular","traps-upper"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["plate-loaded-shoulder-press","seated-dumbbell-shoulder-press","smith-shoulder-press","landmine-press"],"setup":{"en":"Set the seat so the handles start level with your shoulders or slightly above, with your back flat on the pad and feet planted. Use the neutral (palms-in) handles if the machine has them.","ru":"Отрегулируйте сиденье так, чтобы рукоятки в старте были на уровне плеч или чуть выше; спина плотно на спинке, стопы на полу. Если есть нейтральные рукоятки (ладони друг к другу) — берите их."},"cues":{"en":["Back and head on the pad, ribs down — brace without arching.","Keep the elbows slightly in front of your body — angled about 30° forward rather than flared straight out to the sides.","Start with the shoulders down, away from the ears; as you press, let the shoulder blades rotate up with the arms instead of pinning them down or hunching.","Breathe out and press up until the arms are almost straight, hands over or just in front of your head.","Lower for 2–3 s until the hands are back at shoulder height — no deeper.","Keep the wrists straight over the elbows.","If your lower back leaves the pad, the weight is too heavy."],"ru":["Спина и голова на спинке, рёбра опущены — напрягите пресс, не прогибаясь.","Держите локти немного впереди корпуса — примерно на 30° вперёд, а не прямо в стороны.","В старте плечи опущены, подальше от ушей; по ходу жима дайте лопаткам поворачиваться вверх вместе с руками — не прижимайте их вниз и не втягивайте голову в плечи.","На выдохе выжимайте вверх почти до прямых рук, кисти над головой или чуть впереди.","Опускайте 2–3 секунды, пока кисти не вернутся на уровень плеч, — не ниже.","Запястья прямые, точно над локтями.","Если поясница отрывается от спинки — вес слишком большой."]},"mistakes":{"en":["Seat too high: each rep starts with the hands below the shoulders, overloading the front of the shoulder.","Arching the lower back off the pad to press more.","Shrugging into the press, so the neck and upper traps take over.","Pressing behind the head on the wide handles: it needs end-range shoulder mobility most people lack.","Elbows flared straight out to the sides.","Half reps with too much weight."],"ru":["Сиденье слишком высоко: каждый повтор начинается с кистями ниже плеч, и передняя часть плеча перегружается.","Поясница отрывается от спинки и прогибается, чтобы выжать больше.","Плечи поднимаются к ушам во время жима — работу забирают шея и верх трапеций.","Жим из-за головы на широких рукоятках: он требует подвижности плеча, которой у большинства нет.","Локти разведены прямо в стороны.","Половинчатые повторы с чрезмерным весом."]},"startLoad":{"kg":17.5,"source":"≈0.6 × Strength Level Beginner machine shoulder press 1RM (29 kg at 80 kg), research 04 §3.9"},"tags":["owner-primary"],"images":[],"sources":["Seated Shoulder Press (machine) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/186/seated-shoulder-press/","Coratella et al., Front vs back and barbell vs machine overhead press: EMG — Front Physiol, 2022. https://doi.org/10.3389/fphys.2022.825880","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Machine Shoulder Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-shoulder-press/kg","Ludewig et al., Motion of the shoulder complex during multiplanar humeral elevation — J Bone Joint Surg Am, 2009. https://doi.org/10.2106/JBJS.G.01483"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"plate-loaded-shoulder-press","equipment_id":"plate-loaded","name":{"en":"Plate-loaded shoulder press","ru":"Жим над головой в рычажном тренажёре"},"pattern":"vertical-push","details":{"id":"plate-loaded-shoulder-press","class":"vertical-press","pattern":"vertical-push","name":{"en":"Plate-loaded shoulder press","ru":"Жим над головой в рычажном тренажёре"},"aka":["Hammer Strength Iso-Lateral Shoulder Press","Technogym Pure Strength Shoulder Press","Lever shoulder press","Iso-lateral shoulder press"],"equipment":"plate-loaded","primary":["delt-front"],"secondary":["delt-side","triceps-lateral","pec-clavicular","traps-upper"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["machine-shoulder-press","seated-dumbbell-shoulder-press","smith-shoulder-press","landmine-press"],"setup":{"en":"Set the seat so the handles start at shoulder height with your back flat on the pad. Load equal plates on both arms and log their total.","ru":"Сиденье так, чтобы рукоятки в старте были на уровне плеч, спина плотно на спинке. Вешайте на оба рычага одинаковые диски и записывайте их общий вес."},"cues":{"en":["Back on the pad, ribs down, feet planted.","Elbows slightly in front of the body, wrists over the elbows.","Pull the shoulders down before the first rep.","Breathe out and press both arms up evenly until almost straight.","Lower for 2–3 s back to shoulder height without letting the levers drop.","Watch for a weaker side — the arms move independently."],"ru":["Спина на спинке, рёбра опущены, стопы упираются в пол.","Локти немного впереди корпуса, запястья над локтями.","Опустите плечи перед первым повтором.","На выдохе выжимайте обе руки вверх равномерно почти до прямых.","Опускайте 2–3 секунды до уровня плеч, не роняя рычаги.","Следите за слабой стороной — рычаги работают независимо."]},"mistakes":{"en":["Seat too low, so each rep starts deep below the shoulders.","Arching off the pad.","Shrugging at the top.","Uneven plates, or one arm racing ahead."],"ru":["Сиденье слишком низко: каждый повтор начинается глубоко ниже плеч.","Прогиб с отрывом спины от спинки.","Подъём плеч к ушам вверху.","Разный вес на рычагах или одна рука опережает другую."]},"startLoad":{"kg":12.5,"source":"Total plates (6.25 kg per arm): ≈0.6 × the overhead-press seed (Strength Level Beginner 33 kg × 0.6 ≈ 20 kg), research 04 §3.8"},"tags":["owner-alt"],"images":[],"sources":["Seated Shoulder Press (machine) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/186/seated-shoulder-press/","Coratella et al., Front vs back and barbell vs machine overhead press: EMG — Front Physiol, 2022. https://doi.org/10.3389/fphys.2022.825880","Shoulder Press (barbell) Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/shoulder-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"smith-shoulder-press","equipment_id":"smith","name":{"en":"Smith machine shoulder press","ru":"Жим над головой сидя в машине Смита"},"pattern":"vertical-push","details":{"id":"smith-shoulder-press","class":"vertical-press","pattern":"vertical-push","name":{"en":"Smith machine shoulder press","ru":"Жим над головой сидя в машине Смита"},"aka":["Seated Smith press","Smith overhead press","Technogym Multipower shoulder press"],"equipment":"smith","primary":["delt-front"],"secondary":["delt-side","triceps-lateral","pec-clavicular","traps-upper"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["machine-shoulder-press","plate-loaded-shoulder-press","seated-dumbbell-shoulder-press","landmine-press","standing-barbell-overhead-press"],"setup":{"en":"Set a bench upright (80–90°) under the bar so it travels just in front of your face, with the safety stops at about chin height. Grip slightly wider than the shoulders.","ru":"Поставьте скамью почти вертикально (80–90°) под гриф так, чтобы он ходил прямо перед лицом, а страховочные упоры — примерно на уровне подбородка. Хват чуть шире плеч."},"cues":{"en":["Back and head on the pad, ribs down.","Unrack with the bar at about chin height and forearms vertical under it.","Breathe out and press up until the arms are almost straight.","Shoulders stay down — no shrug at the top.","Lower for 2–3 s to chin or upper-chest level, bar in front of the face.","Hook the bar onto a pin after the last rep."],"ru":["Спина и голова на спинке, рёбра опущены.","Снимайте гриф примерно на уровне подбородка, предплечья вертикально под ним.","На выдохе выжимайте вверх почти до прямых рук.","Плечи опущены — не поднимайте их к ушам вверху.","Опускайте 2–3 секунды до уровня подбородка или верха груди, гриф перед лицом.","После последнего повтора зацепите гриф за упор."]},"mistakes":{"en":["Bench placed so the bar comes down behind the head.","Arching hard off the backrest.","No safety stops set.","Shrugging and flaring the elbows straight out."],"ru":["Скамья стоит так, что гриф опускается за голову.","Сильный прогиб с отрывом от спинки.","Не выставлены страховочные упоры.","Подъём плеч к ушам и локти, разведённые прямо в стороны."]},"startLoad":{"kg":20,"source":"Bar + plates: 0.6 × Strength Level Beginner overhead press 1RM (33 kg at 80 kg) ≈ 20 kg; Smith bars weigh 7–25 kg"},"tags":["owner-alt"],"images":[],"sources":["Coratella et al., Front vs back and barbell vs machine overhead press: EMG — Front Physiol, 2022. https://doi.org/10.3389/fphys.2022.825880","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Shoulder Press (barbell) Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/shoulder-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"seated-dumbbell-shoulder-press","equipment_id":"dumbbell","name":{"en":"Seated dumbbell shoulder press","ru":"Жим гантелей сидя"},"pattern":"vertical-push","details":{"id":"seated-dumbbell-shoulder-press","class":"vertical-press","pattern":"vertical-push","name":{"en":"Seated dumbbell shoulder press","ru":"Жим гантелей сидя"},"aka":["Seated DB press","Dumbbell overhead press","Seated dumbbell overhead press"],"equipment":"dumbbell","primary":["delt-front"],"secondary":["delt-side","triceps-lateral","pec-clavicular","traps-upper"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2,"repRange":[6,12],"alternatives":["machine-shoulder-press","plate-loaded-shoulder-press","smith-shoulder-press","landmine-press","standing-barbell-overhead-press"],"setup":{"en":"Set the bench back upright (80–90°). Sit with the dumbbells on your thighs and kick them up one at a time to shoulder height, palms forward or turned in.","ru":"Поставьте спинку скамьи почти вертикально (80–90°). Сядьте, гантели на бёдрах, и толчком колена по одной подайте их к плечам, ладони вперёд или друг к другу."},"cues":{"en":["Head, shoulders and hips on the bench; ribs down.","Elbows slightly in front of the body, forearms vertical.","Breathe out and press up and slightly in until the arms are almost straight.","Keep the shoulders down at the top.","Lower for 2–3 s until the dumbbells are at ear or chin level.","Bring the dumbbells back to your thighs to finish — don''t drop them from overhead."],"ru":["Голова, лопатки и таз на скамье; рёбра опущены.","Локти немного впереди корпуса, предплечья вертикальны.","На выдохе выжимайте вверх и немного к центру почти до прямых рук.","Вверху плечи опущены.","Опускайте 2–3 секунды, пока гантели не окажутся на уровне ушей или подбородка.","Закончив подход, опустите гантели на бёдра — не бросайте их сверху."]},"mistakes":{"en":["Arching the lower back off the bench.","Lowering the dumbbells far below the shoulders with the elbows behind the body.","Shrugging into the press.","Clanging the dumbbells together overhead."],"ru":["Поясница отрывается от спинки и прогибается.","Гантели опускаются намного ниже плеч, локти уходят за корпус.","Плечи поднимаются к ушам во время жима.","Гантели бьются друг о друга над головой."]},"startLoad":{"kg":8,"source":"Per hand: 0.6 × Strength Level Beginner dumbbell shoulder press 1RM (15 kg per hand at 80 kg) = 9 kg, rounded down"},"tags":["owner-alt"],"images":[],"sources":["Seated Overhead Press (dumbbells) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/45/seated-overhead-press/","Saeterbakken & Fimland, Body position and loading modality in shoulder presses — J Strength Cond Res, 2013. https://doi.org/10.1519/JSC.0b013e318276b873","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Dumbbell Shoulder Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-shoulder-press/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"landmine-press","equipment_id":"barbell","name":{"en":"Landmine press","ru":"Жим штанги в ландмайне"},"pattern":"vertical-push","details":{"id":"landmine-press","class":"vertical-press","pattern":"vertical-push","name":{"en":"Landmine press","ru":"Жим штанги в ландмайне"},"aka":["Angled barbell press","Two-hand landmine press","Single-arm landmine press","Barbell corner press"],"equipment":"barbell","primary":["delt-front","pec-clavicular"],"secondary":["triceps-lateral","serratus-anterior","transverse-abdominis"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["machine-shoulder-press","plate-loaded-shoulder-press","seated-dumbbell-shoulder-press","smith-shoulder-press","standing-barbell-overhead-press"],"setup":{"en":"Put one end of a barbell in a landmine sleeve (or a padded corner), load the other end and stand in a staggered stance holding it with both hands at your upper chest. Log bar plus plates; an empty Olympic bar counts as 20 kg.","ru":"Вставьте один конец штанги в ландмайн (или уприте в угол через полотенце), на другой наденьте диски и встаньте в разножку, держа его обеими руками у верха груди. Записывайте гриф вместе с дисками; пустой олимпийский гриф — 20 кг."},"cues":{"en":["Brace the abs and squeeze the glutes; the torso stays still.","Press up and forward along the bar''s arc until the arms are straight.","Let the shoulder blades glide forward a little at the top; the angled path is easy on the shoulders.","Breathe out on the press.","Lower for 2–3 s back to the upper chest.","For the single-arm version, kneel on the knee on the pressing side and keep the hips square."],"ru":["Напрягите пресс и ягодицы; корпус неподвижен.","Выжимайте вверх и вперёд по дуге грифа до прямых рук.","Вверху дайте лопаткам немного уйти вперёд; наклонная траектория бережёт плечи.","Выдох на жиме.","Опускайте 2–3 секунды обратно к верху груди.","В варианте одной рукой встаньте на колено со стороны рабочей руки и держите таз ровно."]},"mistakes":{"en":["Leaning back with the lower back arched to turn it into an incline press.","Shrugging toward the ears at the top.","Driving with the legs (a push press) instead of the shoulders.","An unsecured bar end that slides on the floor."],"ru":["Отклонение назад с прогибом в пояснице — жим превращается в наклонный.","Плечи поднимаются к ушам вверху.","Толчок ногами вместо работы плеч.","Незакреплённый конец грифа скользит по полу."]},"startLoad":{"kg":20,"source":"Empty 20 kg bar (≈11 kg felt at the hands); Strength Level Beginner landmine press = 20 kg"},"tags":["owner-alt"],"images":[],"sources":["Landmine Press: muscles worked and proper form — StrengthLog, 2025. https://www.strengthlog.com/landmine-press/","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Landmine Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/landmine-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"standing-barbell-overhead-press","equipment_id":"barbell","name":{"en":"Standing barbell overhead press","ru":"Жим штанги стоя (армейский жим)"},"pattern":"vertical-push","details":{"id":"standing-barbell-overhead-press","class":"vertical-press","pattern":"vertical-push","name":{"en":"Standing barbell overhead press","ru":"Жим штанги стоя (армейский жим)"},"aka":["Overhead press (OHP)","Military press","Standing press","Strict press"],"equipment":"barbell","primary":["delt-front"],"secondary":["delt-side","triceps-lateral","pec-clavicular","traps-upper","serratus-anterior"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"high","lengthenedBias":false,"increment":2.5,"repRange":[4,8],"alternatives":["landmine-press","machine-shoulder-press","plate-loaded-shoulder-press","seated-dumbbell-shoulder-press","smith-shoulder-press"],"setup":{"en":"Set the bar in a rack at upper-chest height and grip just outside the shoulders, bar low in the palms with forearms vertical. Step back with feet hip-width and the bar resting on the front delts.","ru":"Установите гриф в стойке на уровне верха груди; хват чуть шире плеч, гриф в основании ладоней, предплечья вертикальны. Отойдите на шаг, стопы на ширине таза, гриф лежит на передних дельтах."},"cues":{"en":["Squeeze the glutes and brace the abs hard before every rep.","Breathe in, then press the bar straight up, tipping the head back just enough to clear the chin.","As the bar passes the forehead, move your head forward under it.","Finish with straight arms, biceps by the ears and the bar over mid-foot.","Lower for 2 s back to the front delts, elbows slightly in front of the bar.","Keep the ribs down and the torso vertical — no lean-back.","Stop each set with 1–2 reps in reserve."],"ru":["Перед каждым повтором сильно напрягите ягодицы и пресс.","Вдохните и выжимайте гриф строго вверх, отведя голову назад ровно настолько, чтобы гриф прошёл мимо подбородка.","Когда гриф минует лоб, подайте голову вперёд, под гриф.","Вверху руки прямые, бицепсы у ушей, гриф над серединой стопы.","Опускайте 2 секунды обратно на передние дельты, локти чуть впереди грифа.","Рёбра опущены, корпус вертикален — без отклонения назад.","Заканчивайте подход с запасом 1–2 повтора."]},"mistakes":{"en":["Leaning back into a standing incline press, so the lower back takes the load.","Pressing the bar around the face instead of moving the head.","Loose glutes and abs, so the hips drift forward.","Elbows flared out wide at the start.","Pressing behind the neck.","Pushing with the legs to finish reps."],"ru":["Отклонение назад — жим превращается в наклонный, нагрузку берёт поясница.","Гриф ведут по дуге вокруг лица вместо того, чтобы убрать голову.","Расслабленные ягодицы и пресс — таз уезжает вперёд.","Локти широко разведены в старте.","Жим из-за головы.","Подталкивание ногами, чтобы дожать повтор."]},"startLoad":{"kg":20,"source":"Empty 20 kg bar: 0.6 × Strength Level Beginner overhead press 1RM (33 kg at 80 kg) ≈ 20 kg"},"tags":["owner-alt","longevity"],"images":[],"sources":["NSCA, Exercise Technique Manual for Resistance Training, 3rd ed. — Human Kinetics, 2016. https://canada.humankinetics.com/products/exercise-technique-manual-for-resistance-training-3rd-edition-with-online-video","Saeterbakken & Fimland, Body position and loading modality in shoulder presses — J Strength Cond Res, 2013. https://doi.org/10.1519/JSC.0b013e318276b873","Coratella et al., Front vs back and barbell vs machine overhead press: EMG — Front Physiol, 2022. https://doi.org/10.3389/fphys.2022.825880","Shoulder Press (barbell) Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/shoulder-press/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-lateral-raise","equipment_id":"selectorized","name":{"en":"Lateral raise machine","ru":"Махи в стороны в тренажёре"},"pattern":"lateral-raise","details":{"id":"machine-lateral-raise","class":"lateral-raise","pattern":"lateral-raise","name":{"en":"Lateral raise machine","ru":"Махи в стороны в тренажёре"},"aka":["Technogym Selection Delts Machine","Life Fitness Insignia Lateral Raise","Nautilus Inspiration Deltoid Raise","Hammer Strength Plate-Loaded Lateral Raise","Deltoid raise machine"],"equipment":"selectorized","primary":["delt-side"],"secondary":["traps-upper","rotator-cuff","delt-front"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[10,20],"alternatives":["cable-lateral-raise","dumbbell-lateral-raise","band-lateral-raise"],"setup":{"en":"Adjust the seat so your shoulder joints line up with the machine''s pivot points (often marked). Rest the pads on the outside of your arms just above the elbows and hold the handles lightly.","ru":"Отрегулируйте сиденье так, чтобы плечевые суставы совпали с осями вращения тренажёра (их часто отмечают). Упоры — на внешней стороне рук чуть выше локтей, рукоятки держите без напряжения."},"cues":{"en":["Line up the shoulders with the pivots before the first rep.","Sit tall with the chest against the pad (or the back flat on the backrest).","Lead with the elbows: push the pads out and up, not with the hands.","Raise until the upper arms are level with the shoulders — no higher.","Keep the shoulders down: think “arms out wide”, not “shoulders up”.","Pause for 1 s at the top, then lower for 2–3 s.","Breathe out on the way up, in on the way down."],"ru":["Перед первым повтором совместите плечевые суставы с осями тренажёра.","Сидите ровно, грудью к упору (или спиной к спинке).","Ведите локтями: толкайте упоры в стороны и вверх, а не кистями.","Поднимайте до горизонтали плеч — не выше.","Плечи опущены: думайте «руки широко в стороны», а не «плечи вверх».","Задержитесь вверху на 1 секунду, затем опускайте 2–3 секунды.","Выдох на подъёме, вдох на опускании."]},"mistakes":{"en":["Pivots not lined up with the shoulders, so the path grinds or pinches.","Shrugging to lift the pads, so the upper traps do the work.","Raising above shoulder height.","Swinging the weight up and dropping it.","Leaning the torso to start the rep."],"ru":["Оси тренажёра не совпадают с плечевыми суставами — движение идёт рывками или защемляет.","Подъём плеч к ушам, чтобы поднять упоры, — работают трапеции.","Подъём выше уровня плеч.","Вес забрасывают рывком и бросают вниз.","Отклонение корпуса, чтобы стронуть вес."]},"startLoad":{"kg":15,"source":"0.6 × Strength Level Beginner machine lateral raise 1RM (25 kg at 80 kg) = 15 kg"},"tags":["owner-primary"],"images":[],"sources":["Lateral Shoulder Raise (machine) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/295/lateral-shoulder-raise/","Machine Lateral Raise — StrengthLog, 2023. https://www.strengthlog.com/machine-lateral-raise/","Lateral Raise (dumbbells) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/26/lateral-raise/","Machine Lateral Raise Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-lateral-raise/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"cable-lateral-raise","equipment_id":"cable","name":{"en":"Cable lateral raise","ru":"Махи в сторону на нижнем блоке"},"pattern":"lateral-raise","details":{"id":"cable-lateral-raise","class":"lateral-raise","pattern":"lateral-raise","name":{"en":"Cable lateral raise","ru":"Махи в сторону на нижнем блоке"},"aka":["Single-arm cable lateral raise","Cable side raise","Low-pulley lateral raise"],"equipment":"cable","primary":["delt-side"],"secondary":["traps-upper","rotator-cuff"],"difficulty":2,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":1.25,"repRange":[10,20],"alternatives":["machine-lateral-raise","dumbbell-lateral-raise","band-lateral-raise"],"setup":{"en":"Set a pulley low (or about hand height for a flatter resistance curve) with a single handle. Stand side-on, hold the handle in the far hand so the cable runs in front of your body, and steady yourself on the machine with the other hand.","ru":"Установите блок внизу (или примерно на уровне кисти, чтобы нагрузка была ровнее), одиночная рукоятка. Встаньте боком, возьмите рукоятку дальней рукой так, чтобы трос проходил перед корпусом, другой рукой держитесь за тренажёр."},"cues":{"en":["Soft bend in the elbow, with the elbow leading the hand.","Raise the arm out to the side until it is level with the shoulder.","Keep the shoulder down and the torso still — no leaning.","Pause briefly, then lower for 2–3 s until the hand is by your hip.","Breathe out on the way up.","Do the weaker arm first and match its reps with the other."],"ru":["Локоть слегка согнут и идёт впереди кисти.","Поднимайте руку в сторону до уровня плеча.","Плечо опущено, корпус неподвижен — без наклона.","Короткая пауза, затем опускайте 2–3 секунды до уровня бедра.","Выдох на подъёме.","Начинайте со слабой руки и повторите её число повторов другой."]},"mistakes":{"en":["Shrugging the shoulder up to start the rep.","Leaning away from the stack to swing the weight.","Raising above shoulder height with the thumb turned down.","Bending and straightening the elbow."],"ru":["Подъём плеча к уху в начале повтора.","Отклонение от тренажёра, чтобы закинуть вес.","Подъём выше плеча с большим пальцем, развёрнутым вниз.","Сгибание и разгибание локтя."]},"startLoad":{"kg":2.5,"source":"The lightest plate on most stacks; Strength Level Beginner cable lateral raise 1RM = 3 kg at 80 kg"},"tags":["owner-alt"],"images":[],"sources":["Larsen et al., Dumbbell versus cable lateral raises for lateral deltoid hypertrophy — Front Physiol, 2025. https://doi.org/10.3389/fphys.2025.1611468","Cable Lateral Raise — StrengthLog, 2026. https://www.strengthlog.com/cable-lateral-raise/","Lateral Raise (dumbbells) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/26/lateral-raise/","Cable Lateral Raise Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-lateral-raise/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dumbbell-lateral-raise","equipment_id":"dumbbell","name":{"en":"Dumbbell lateral raise","ru":"Махи гантелями в стороны"},"pattern":"lateral-raise","details":{"id":"dumbbell-lateral-raise","class":"lateral-raise","pattern":"lateral-raise","name":{"en":"Dumbbell lateral raise","ru":"Махи гантелями в стороны"},"aka":["Side raise","Lateral raise","DB side lateral"],"equipment":"dumbbell","primary":["delt-side"],"secondary":["traps-upper","rotator-cuff","delt-front"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":1,"repRange":[10,20],"alternatives":["machine-lateral-raise","cable-lateral-raise","band-lateral-raise"],"setup":{"en":"Stand with feet hip-width or in a split stance, dumbbells at your sides, palms facing in and elbows slightly bent. Brace and stand tall.","ru":"Встаньте, стопы на ширине таза или в разножке, гантели по бокам, ладони к корпусу, локти слегка согнуты. Напрягите пресс и выпрямитесь."},"cues":{"en":["Raise the arms out to the sides with the elbows and upper arms leading the dumbbells.","Stop when the arms are level with the shoulders.","Near the top, tip the front of the dumbbells slightly up — never pour them thumb-down.","Shoulders down and back, torso still.","Lower for 2–3 s.","Breathe out on the way up."],"ru":["Поднимайте руки в стороны: локти и плечи идут впереди гантелей.","Остановитесь, когда руки на уровне плеч.","Вверху слегка разверните передний край гантелей вверх — никогда не «выливайте» их большим пальцем вниз.","Плечи опущены и отведены назад, корпус неподвижен.","Опускайте 2–3 секунды.","Выдох на подъёме."]},"mistakes":{"en":["Swinging the torso to throw the weights up.","Shrugging, so the upper traps do the work.","Thumb-down “pouring” above shoulder height, which pinches the shoulder.","Dumbbells too heavy for the full range."],"ru":["Раскачка корпусом, чтобы забросить гантели.","Подъём плеч — работу забирают трапеции.","«Выливание» гантелей большим пальцем вниз выше уровня плеч — защемляет плечо.","Гантели слишком тяжёлые для полной амплитуды."]},"startLoad":{"kg":3,"source":"Per hand: 0.6 × Strength Level Beginner dumbbell lateral raise 1RM (5 kg per hand at 80 kg) = 3 kg"},"tags":["owner-alt"],"images":[],"sources":["Lateral Raise (dumbbells) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/26/lateral-raise/","Larsen et al., Dumbbell versus cable lateral raises for lateral deltoid hypertrophy — Front Physiol, 2025. https://doi.org/10.3389/fphys.2025.1611468","Dynamite Delts: ACE research identifies top shoulder exercises — ACE ProSource, 2015. https://www.acefitness.org/continuing-education/prosource/research-special-issue-2015/5320/dynamite-delts-ace-research-identifies-top-shoulder-exercises/","Dumbbell Lateral Raise Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-lateral-raise/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"band-lateral-raise","equipment_id":"band","name":{"en":"Band lateral raise","ru":"Махи в стороны с резиновой лентой"},"pattern":"lateral-raise","details":{"id":"band-lateral-raise","class":"lateral-raise","pattern":"lateral-raise","name":{"en":"Band lateral raise","ru":"Махи в стороны с резиновой лентой"},"aka":["Resistance band lateral raise","Band side raise"],"equipment":"band","primary":["delt-side"],"secondary":["traps-upper","rotator-cuff"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[10,20],"alternatives":["machine-lateral-raise","cable-lateral-raise","dumbbell-lateral-raise"],"setup":{"en":"Stand on the middle of a band with feet hip-width and hold one end in each hand at your sides. For less tension, stand on it with one foot or hold the ends longer.","ru":"Встаньте на середину ленты, стопы на ширине таза, концы в руках по бокам. Чтобы уменьшить натяжение, наступите на неё одной ногой или возьмите концы длиннее."},"cues":{"en":["Elbows slightly bent and leading the hands.","Raise the arms out to the sides to shoulder height.","Shoulders down, torso still.","Pause at the top, where the band is hardest, then lower for 2 s.","Progress with reps, then a stronger band or a shorter grip."],"ru":["Локти слегка согнуты и идут впереди кистей.","Поднимайте руки в стороны до уровня плеч.","Плечи опущены, корпус неподвижен.","Задержитесь вверху, где лента тянет сильнее всего, и опускайте 2 секунды.","Прогрессируйте повторами, затем более тугой лентой или более коротким хватом."]},"mistakes":{"en":["Shrugging as the band tension rises.","Letting the band snap the arms down.","Leaning or swinging."],"ru":["Подъём плеч к ушам по мере роста натяжения.","Лента резко бросает руки вниз.","Наклон корпуса или раскачка."]},"tags":["owner-alt"],"images":[],"sources":["Lateral Raise (dumbbells) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/26/lateral-raise/","Dynamite Delts: ACE research identifies top shoulder exercises — ACE ProSource, 2015. https://www.acefitness.org/continuing-education/prosource/research-special-issue-2015/5320/dynamite-delts-ace-research-identifies-top-shoulder-exercises/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"reverse-pec-deck","equipment_id":"selectorized","name":{"en":"Reverse pec deck (rear-delt machine)","ru":"Обратная бабочка (задние дельты)"},"pattern":"rear-delt","details":{"id":"reverse-pec-deck","class":"rear-delt","pattern":"rear-delt","name":{"en":"Reverse pec deck (rear-delt machine)","ru":"Обратная бабочка (задние дельты)"},"aka":["Technogym Selection Reverse Fly","Technogym Selection 700 Dual Pectoral/Reverse Fly","Life Fitness Insignia Pectoral Fly/Rear Deltoid","Nautilus Inspiration Pec Fly/Rear Deltoid","Rear delt machine","Reverse fly machine"],"equipment":"selectorized","primary":["delt-rear"],"secondary":["traps-mid","rhomboids","rotator-cuff"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[10,20],"alternatives":["cable-rear-delt-fly","face-pull","rear-delt-dumbbell-fly","band-pull-apart"],"setup":{"en":"Sit facing the pad with your chest against it, the seat set so the handles are at shoulder height and the arms in their rear-delt start position. Use the vertical (neutral) handles.","ru":"Сядьте лицом к спинке, грудью к упору; сиденье — так, чтобы рукоятки были на уровне плеч, рычаги — в стартовой позиции для задних дельт. Берите вертикальные (нейтральные) рукоятки."},"cues":{"en":["Chest on the pad, shoulders down; arms long with a soft elbow.","Sweep the arms out and back in a wide arc to about the line of your body.","Move at the shoulders; don''t bend the elbows to row the weight back.","Pause for 1 s, breathing out.","Return for 2–3 s until the hands nearly meet in front.","Keep the neck long — don''t poke the chin forward."],"ru":["Грудь на упоре, плечи опущены; руки длинные, локти чуть согнуты.","Разводите руки по широкой дуге назад примерно до линии корпуса.","Движение — в плечевых суставах; не сгибайте локти, превращая упражнение в тягу.","Задержитесь на 1 секунду на выдохе.","Возвращайте 2–3 секунды, пока кисти почти не сойдутся впереди.","Шея длинная — не вытягивайте подбородок вперёд."]},"mistakes":{"en":["Shrugging, so the upper traps take over.","Bending the elbows into a row.","Swinging the arms far past the body line with momentum.","Too heavy, so the chest lifts off the pad."],"ru":["Подъём плеч — работу забирает верх трапеций.","Локти сгибаются — получается тяга.","Руки с инерцией улетают далеко за линию корпуса.","Слишком тяжело: грудь отрывается от упора."]},"startLoad":{"kg":17.5,"source":"0.6 × Strength Level Beginner machine reverse fly 1RM (29 kg at 80 kg) ≈ 17 kg"},"tags":["owner-alt"],"images":[],"sources":["Franke et al., Deltoid activation in single- and multi-joint exercises — J Sports Med Phys Fitness, 2015. https://pubmed.ncbi.nlm.nih.gov/24947920/","Schoenfeld et al., Hand position and posterior shoulder EMG on the reverse fly machine — J Strength Cond Res, 2013. https://doi.org/10.1519/JSC.0b013e318281e1e9","Reverse Machine Fly — StrengthLog, 2025. https://www.strengthlog.com/reverse-machine-fly/","Machine Reverse Fly Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-reverse-fly/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"rear-delt-dumbbell-fly","equipment_id":"dumbbell","name":{"en":"Chest-supported rear-delt dumbbell fly","ru":"Обратные разведения гантелей с упором грудью"},"pattern":"rear-delt","details":{"id":"rear-delt-dumbbell-fly","class":"rear-delt","pattern":"rear-delt","name":{"en":"Chest-supported rear-delt dumbbell fly","ru":"Обратные разведения гантелей с упором грудью"},"aka":["Incline reverse fly","Seated rear lateral raise","Rear delt raise","Reverse dumbbell fly"],"equipment":"dumbbell","primary":["delt-rear"],"secondary":["traps-mid","rhomboids","rotator-cuff"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":1,"repRange":[10,20],"alternatives":["reverse-pec-deck","cable-rear-delt-fly","face-pull","band-pull-apart"],"setup":{"en":"Set an incline bench to about 45° and lie chest-down on it with the dumbbells hanging under your shoulders, palms facing each other and elbows slightly bent.","ru":"Установите наклонную скамью примерно на 45° и лягте на неё грудью; гантели висят под плечами, ладони друг к другу, локти слегка согнуты."},"cues":{"en":["Chest stays on the pad; neck long.","Raise the dumbbells out to the sides until the arms are level with the shoulders.","Finish with the dumbbells in line with, or slightly in front of, your ears — not behind the head.","Pause for 1 s, breathing out, then lower for 2–3 s.","Keep the slight elbow bend fixed."],"ru":["Грудь остаётся на скамье; шея длинная.","Поднимайте гантели в стороны до уровня плеч.","В верхней точке гантели на линии ушей или чуть впереди — не за головой.","Задержитесь на 1 секунду на выдохе, затем опускайте 2–3 секунды.","Лёгкий сгиб в локтях не меняется."]},"mistakes":{"en":["Raising the dumbbells behind the head, which shifts the work from the rear delts to the lats.","Shrugging the shoulders up.","Lifting the chest off the bench to swing.","Too heavy, so the elbows bend into a row."],"ru":["Гантели уходят за голову — работа смещается с задних дельт на широчайшие.","Подъём плеч к ушам.","Отрыв груди от скамьи для раскачки.","Слишком тяжело: локти сгибаются, получается тяга."]},"startLoad":{"kg":2,"source":"Per hand: ≈0.6 × Strength Level Beginner dumbbell reverse fly 1RM (3 kg per hand at 80 kg)"},"tags":["owner-alt"],"images":[],"sources":["Incline Reverse Fly — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/34/incline-reverse-fly/","Dynamite Delts: ACE research identifies top shoulder exercises — ACE ProSource, 2015. https://www.acefitness.org/continuing-education/prosource/research-special-issue-2015/5320/dynamite-delts-ace-research-identifies-top-shoulder-exercises/","Dumbbell Reverse Fly Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-reverse-fly/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"cable-rear-delt-fly","equipment_id":"cable","name":{"en":"Cable rear-delt fly","ru":"Обратные разведения в кроссовере"},"pattern":"rear-delt","details":{"id":"cable-rear-delt-fly","class":"rear-delt","pattern":"rear-delt","name":{"en":"Cable rear-delt fly","ru":"Обратные разведения в кроссовере"},"aka":["Cable reverse fly","Standing cable rear-delt crossover","Cable rear lateral raise"],"equipment":"cable","primary":["delt-rear"],"secondary":["traps-mid","rhomboids","rotator-cuff"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":1.25,"repRange":[10,20],"alternatives":["face-pull","reverse-pec-deck","rear-delt-dumbbell-fly","band-pull-apart"],"setup":{"en":"Set both pulleys at about shoulder height or slightly below. Stand centred and take the left cable in the right hand and the right cable in the left hand, so the arms start crossed in front of you.","ru":"Установите оба блока примерно на уровне плеч или чуть ниже. Встаньте по центру, левый трос возьмите правой рукой, правый — левой, чтобы в старте руки были скрещены перед собой."},"cues":{"en":["Stand tall, abs braced, knees soft.","With a soft elbow, sweep the arms apart until they form a straight line with the shoulders.","Pause for 1 s, breathing out.","Return for 2–3 s to the crossed start, keeping tension.","Shoulders stay down; the movement is at the shoulder joint."],"ru":["Стойте ровно, пресс напряжён, колени слегка согнуты.","С чуть согнутыми локтями разводите руки, пока они не образуют прямую линию с плечами.","Задержитесь на 1 секунду на выдохе.","Возвращайтесь 2–3 секунды в скрещённое положение, не теряя натяжения.","Плечи опущены; движение — в плечевых суставах."]},"mistakes":{"en":["Leaning back to pull with the body.","Shrugging the shoulders up.","Bending the elbows into a row.","Letting the stack slam between reps."],"ru":["Отклонение назад, чтобы тянуть корпусом.","Подъём плеч к ушам.","Сгибание локтей — получается тяга.","Плиты грохочут между повторами."]},"startLoad":{"kg":2.5,"source":"Per side: the lightest plate on most stacks; Strength Level Beginner cable reverse fly 1RM = 3 kg at 80 kg"},"tags":["owner-alt"],"images":[],"sources":["Reverse Fly (cables) — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/353/reverse-fly/","Franke et al., Deltoid activation in single- and multi-joint exercises — J Sports Med Phys Fitness, 2015. https://pubmed.ncbi.nlm.nih.gov/24947920/","Cable Reverse Fly Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-reverse-fly/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"face-pull","equipment_id":"cable","name":{"en":"Face pull","ru":"Тяга каната к лицу (фейс-пулл)"},"pattern":"rear-delt","details":{"id":"face-pull","class":"rear-delt","pattern":"rear-delt","name":{"en":"Face pull","ru":"Тяга каната к лицу (фейс-пулл)"},"aka":["Rope face pull","Cable face pull","High rope pull","Rear-delt rope pull"],"equipment":"cable","primary":["delt-rear","rotator-cuff"],"secondary":["traps-mid","traps-lower","rhomboids","delt-side"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[10,20],"alternatives":["cable-rear-delt-fly","reverse-pec-deck","rear-delt-dumbbell-fly","band-pull-apart","cable-external-rotation","side-lying-external-rotation","band-external-rotation"],"setup":{"en":"Set the pulley at about forehead height with a rope, grip both ends overhand (palms down) and step back until your arms are straight and the plates lift. Stand tall in a slight split stance.","ru":"Установите блок примерно на уровне лба с канатной рукояткой, возьмитесь за оба конца хватом сверху (ладони вниз) и отойдите, пока руки не выпрямятся, а плиты не поднимутся. Стойте ровно, в небольшой разножке."},"cues":{"en":["Brace the abs and keep the ribs down; the torso doesn''t move.","Pull the rope toward your forehead, spreading the ends apart.","Keep the elbows high, at shoulder height, as they travel out to the sides.","Rotate the forearms up as you pull, finishing with the hands beside your ears like a double-biceps pose.","Squeeze the shoulder blades back and down for 1 s, breathing out.","Return for 2–3 s until the arms are straight and the shoulder blades open.","Keep it light enough that every rep reaches your ears."],"ru":["Напрягите пресс, рёбра опущены; корпус неподвижен.","Тяните канат ко лбу, разводя концы в стороны.","Локти высоко, на уровне плеч, — они расходятся в стороны.","По ходу тяги поворачивайте предплечья вверх: в конце кисти у ушей, как в позе «двойной бицепс».","Сведите и опустите лопатки на 1 секунду — на выдохе.","Возвращайтесь 2–3 секунды до прямых рук, лопатки расходятся.","Вес такой, чтобы каждый повтор доходил до ушей."]},"mistakes":{"en":["Too heavy: it turns into a row, with the elbows dropping and the torso leaning back.","Shrugging toward the ears instead of drawing the shoulder blades back and down.","Pulling to the chin or neck with low elbows — no external rotation at the end.","Arching the lower back to finish the rep.","Yanking the rope and letting the stack snap back."],"ru":["Слишком тяжело: получается тяга к груди — локти опускаются, корпус отклоняется назад.","Плечи поднимаются к ушам вместо того, чтобы лопатки шли назад-вниз.","Тяга к подбородку или шее с низкими локтями — нет наружной ротации в конце.","Прогиб в пояснице, чтобы дотянуть.","Рывок каната и резкий возврат плит."]},"startLoad":{"kg":10,"source":"0.6 × Strength Level Beginner face pull 1RM (15 kg at 80 kg) = 9 kg"},"tags":["owner-primary"],"images":[],"sources":["Face Pull: muscles worked and proper form — StrengthLog, 2025. https://www.strengthlog.com/face-pull/","Reinold et al., Rotator cuff and deltoid EMG during shoulder external rotation exercises — J Orthop Sports Phys Ther, 2004. https://doi.org/10.2519/jospt.2004.34.7.385","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Face Pull Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/face-pull/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"band-pull-apart","equipment_id":"band","name":{"en":"Band pull-apart","ru":"Разведение резиновой ленты перед собой"},"pattern":"rear-delt","details":{"id":"band-pull-apart","class":"rear-delt","pattern":"rear-delt","name":{"en":"Band pull-apart","ru":"Разведение резиновой ленты перед собой"},"aka":["Resistance band pull-apart","Band reverse fly"],"equipment":"band","primary":["delt-rear"],"secondary":["traps-mid","rhomboids","rotator-cuff"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[10,20],"alternatives":["reverse-pec-deck","cable-rear-delt-fly","face-pull","rear-delt-dumbbell-fly"],"setup":{"en":"Hold a light band at shoulder height on straight arms with an overhand grip, hands about shoulder-width apart, and stand tall.","ru":"Держите лёгкую ленту на уровне плеч на прямых руках хватом сверху, кисти примерно на ширине плеч; стойте ровно."},"cues":{"en":["Ribs down, shoulders down.","Pull the band apart by moving the arms out to the sides until it touches your chest.","Keep the arms straight with a soft elbow.","Pause for 1 s, then return for 2 s without letting the band snap.","Narrow your grip on the band to make it harder."],"ru":["Рёбра опущены, плечи опущены.","Растягивайте ленту, разводя руки в стороны, пока она не коснётся груди.","Руки прямые, локти чуть согнуты.","Задержитесь на 1 секунду и возвращайтесь 2 секунды, не давая ленте дёрнуть руки.","Чтобы стало тяжелее, возьмите ленту уже."]},"mistakes":{"en":["Shrugging toward the ears.","Bending the elbows and rowing.","Arching the lower back to finish the rep."],"ru":["Подъём плеч к ушам.","Сгибание локтей и тяга.","Прогиб в пояснице, чтобы дотянуть."]},"tags":["owner-alt"],"images":[],"sources":["Band Pull-Apart — StrengthLog, 2023. https://www.strengthlog.com/band-pull-apart/","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"cable-external-rotation","equipment_id":"cable","name":{"en":"Cable external rotation","ru":"Наружная ротация плеча на блоке"},"pattern":"external-rotation","details":{"id":"cable-external-rotation","class":"external-rotation","pattern":"external-rotation","name":{"en":"Cable external rotation","ru":"Наружная ротация плеча на блоке"},"aka":["Standing cable external rotation","Cable ER at the side","Cable rotator-cuff external rotation"],"equipment":"cable","primary":["rotator-cuff"],"secondary":["delt-rear"],"difficulty":1,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":1.25,"repRange":[10,20],"alternatives":["side-lying-external-rotation","band-external-rotation","face-pull"],"setup":{"en":"Set a pulley at elbow height with a single handle and stand side-on with the working arm farther from the stack. Bend the elbow to 90° and tuck it against your side (a rolled towel between elbow and ribs helps), forearm across your belly.","ru":"Установите блок на уровне локтя, одиночная рукоятка; встаньте боком так, чтобы рабочая рука была дальше от тренажёра. Согните локоть под 90° и прижмите его к боку (поможет свёрнутое полотенце между локтем и рёбрами), предплечье перед животом."},"cues":{"en":["Keep the elbow pinned to your side for the whole set.","Rotate the forearm out like a door on a hinge, as far as is comfortable.","Keep the wrist straight and the forearm level.","Pause for 1 s, then return for 2–3 s.","Shoulder down and back; don''t twist the torso.","Light weight, slow reps: this is joint-health work, not a max-effort lift."],"ru":["Локоть прижат к боку весь подход.","Разворачивайте предплечье наружу, как дверь на петле, — насколько комфортно.","Запястье прямое, предплечье горизонтально.","Задержитесь на 1 секунду и возвращайтесь 2–3 секунды.","Плечо опущено и отведено назад; не скручивайте корпус.","Лёгкий вес, медленные повторы: это работа на здоровье сустава, а не на максимум."]},"mistakes":{"en":["The elbow drifting away from your side.","Twisting the torso to move the handle.","Shrugging the shoulder.","Too heavy, so the range shrinks to a few centimetres."],"ru":["Локоть отходит от корпуса.","Скручивание корпуса, чтобы сдвинуть рукоятку.","Подъём плеча к уху.","Слишком тяжело — амплитуда сжимается до нескольких сантиметров."]},"startLoad":{"kg":2.5,"source":"The lightest plate on most stacks; Strength Level cable external rotation 1RM at 80 kg: Beginner 1 kg, Novice 7 kg"},"tags":["owner-alt"],"images":[],"sources":["Rotator Cuff External Rotation — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/352/rotator-cuff-external-rotation/","Reinold et al., Rotator cuff and deltoid EMG during shoulder external rotation exercises — J Orthop Sports Phys Ther, 2004. https://doi.org/10.2519/jospt.2004.34.7.385","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330","Cable External Rotation Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-external-rotation/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"side-lying-external-rotation","equipment_id":"dumbbell","name":{"en":"Side-lying dumbbell external rotation","ru":"Наружная ротация плеча с гантелью лёжа на боку"},"pattern":"external-rotation","details":{"id":"side-lying-external-rotation","class":"external-rotation","pattern":"external-rotation","name":{"en":"Side-lying dumbbell external rotation","ru":"Наружная ротация плеча с гантелью лёжа на боку"},"aka":["Side-lying external rotation","Lying dumbbell external rotation","Side-lying ER"],"equipment":"dumbbell","primary":["rotator-cuff"],"secondary":["delt-rear"],"difficulty":1,"unilateral":true,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":1,"repRange":[10,20],"alternatives":["cable-external-rotation","band-external-rotation","face-pull"],"setup":{"en":"Lie on your side on a bench or mat with the working arm on top, elbow bent 90° and resting on a folded towel against your side, forearm across your belly holding a light dumbbell.","ru":"Лягте на бок на скамью или коврик, рабочая рука сверху: локоть согнут под 90° и лежит на сложенном полотенце у бока, предплечье перед животом, в руке лёгкая гантель."},"cues":{"en":["Keep the elbow on the towel against your side.","Rotate the forearm up until it points at the ceiling, or as far as is comfortable.","Pause for 1 s, then lower for 2–3 s.","Keep the wrist straight and the shoulder blade drawn back.","Don''t roll the body back to lift the weight."],"ru":["Локоть на полотенце, прижат к боку.","Поворачивайте предплечье вверх, пока оно не будет смотреть в потолок или пока комфортно.","Задержитесь на 1 секунду и опускайте 2–3 секунды.","Запястье прямое, лопатка отведена назад.","Не перекатывайтесь корпусом назад, чтобы поднять гантель."]},"mistakes":{"en":["The elbow lifting off your side.","Rolling the torso back.","Going heavy — these small muscles need light loads and full control."],"ru":["Локоть отрывается от бока.","Перекат корпуса назад.","Тяжёлая гантель — этим небольшим мышцам нужны малый вес и полный контроль."]},"startLoad":{"kg":2,"source":"Light by design: no Strength Level standard; cuff work starts with the lightest dumbbell that allows 15 slow reps"},"tags":["owner-alt"],"images":[],"sources":["Reinold et al., Rotator cuff and deltoid EMG during shoulder external rotation exercises — J Orthop Sports Phys Ther, 2004. https://doi.org/10.2519/jospt.2004.34.7.385","Lying Dumbbell External Shoulder Rotation — StrengthLog, 2023. https://www.strengthlog.com/lying-dumbbell-external-shoulder-rotation/","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"band-external-rotation","equipment_id":"band","name":{"en":"Band external rotation","ru":"Наружная ротация плеча с резиновой лентой"},"pattern":"external-rotation","details":{"id":"band-external-rotation","class":"external-rotation","pattern":"external-rotation","name":{"en":"Band external rotation","ru":"Наружная ротация плеча с резиновой лентой"},"aka":["Resistance band external rotation","Band ER at the side"],"equipment":"band","primary":["rotator-cuff"],"secondary":["delt-rear"],"difficulty":1,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[10,20],"alternatives":["cable-external-rotation","side-lying-external-rotation","face-pull"],"setup":{"en":"Anchor a light band at elbow height (door anchor or rack) and stand side-on with the working arm farther from the anchor. Bend the elbow to 90° and tuck it against your side, forearm across the belly.","ru":"Закрепите лёгкую ленту на уровне локтя (дверной анкер или стойка) и встаньте боком, рабочая рука дальше от точки крепления. Согните локоть под 90° и прижмите к боку, предплечье перед животом."},"cues":{"en":["Elbow pinned to your side — a rolled towel helps.","Rotate the forearm out like a door on a hinge.","Pause at the end, where the band is hardest, then return slowly.","Shoulder down, torso square.","Step farther from the anchor to add tension."],"ru":["Локоть прижат к боку — поможет свёрнутое полотенце.","Разворачивайте предплечье наружу, как дверь на петле.","Задержитесь в конце, где лента тянет сильнее, и медленно возвращайтесь.","Плечо опущено, корпус развёрнут прямо.","Чтобы добавить натяжение, отойдите дальше от точки крепления."]},"mistakes":{"en":["The elbow drifting away from the body.","Twisting the torso instead of rotating the shoulder.","Letting the band snap the arm back."],"ru":["Локоть отходит от корпуса.","Поворот корпуса вместо вращения в плече.","Лента резко возвращает руку."]},"tags":["owner-alt"],"images":[],"sources":["Band External Shoulder Rotation — StrengthLog, 2023. https://www.strengthlog.com/band-external-shoulder-rotation/","Reinold et al., Rotator cuff and deltoid EMG during shoulder external rotation exercises — J Orthop Sports Phys Ther, 2004. https://doi.org/10.2519/jospt.2004.34.7.385","Kolber et al., Shoulder injuries attributed to resistance training: a brief review — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181dc4330"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-shrug","equipment_id":"plate-loaded","name":{"en":"Machine shrug","ru":"Шраги в тренажёре"},"pattern":"shrug","details":{"id":"machine-shrug","class":"shrug","pattern":"shrug","name":{"en":"Machine shrug","ru":"Шраги в тренажёре"},"aka":["Hammer Strength Plate-Loaded Seated/Standing Shrug","Shrug machine","Plate-loaded shrug"],"equipment":"plate-loaded","primary":["traps-upper"],"secondary":["forearm-flexors","traps-mid"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["dumbbell-shrug","farmers-carry","suitcase-carry"],"setup":{"en":"Stand (or sit) between the handles with feet hip-width and arms straight at your sides. Load equal plates on both sides and log their total.","ru":"Встаньте (или сядьте) между рукоятками, стопы на ширине таза, руки прямые по бокам. Вешайте одинаковые диски с двух сторон и записывайте их общий вес."},"cues":{"en":["Stand tall with the abs braced and the chin level.","Lift the shoulders straight up toward the ears as high as they go.","Hold for 1 s at the top, breathing out.","Lower for 2 s to a full stretch.","Arms stay straight; the elbows don''t bend."],"ru":["Стойте ровно, пресс напряжён, подбородок прямо.","Поднимайте плечи строго вверх к ушам, насколько получается.","Задержитесь вверху на 1 секунду на выдохе.","Опускайте 2 секунды до полного растяжения.","Руки прямые; локти не сгибаются."]},"mistakes":{"en":["Rolling the shoulders in circles instead of lifting straight up and down.","Bending the elbows to pull the weight.","Jutting the head forward.","Heavy half-reps with a rounded back."],"ru":["Вращение плечами по кругу вместо подъёма строго вверх-вниз.","Сгибание локтей, чтобы подтянуть вес.","Голова выдвигается вперёд.","Тяжёлые полуповторы с круглой спиной."]},"startLoad":{"kg":35,"source":"Total plates: 0.6 × Strength Level Beginner machine shrug 1RM (60 kg at 80 kg) = 36 kg"},"tags":[],"images":[],"sources":["Standing Shrug — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/75/standing-shrug/","Pizzari et al., Modifying a shrug exercise to facilitate the scapular upward rotators — Clin Biomech, 2014. https://doi.org/10.1016/j.clinbiomech.2013.11.011","Machine Shrug Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-shrug/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dumbbell-shrug","equipment_id":"dumbbell","name":{"en":"Dumbbell shrug","ru":"Шраги с гантелями"},"pattern":"shrug","details":{"id":"dumbbell-shrug","class":"shrug","pattern":"shrug","name":{"en":"Dumbbell shrug","ru":"Шраги с гантелями"},"aka":["DB shrug","Standing dumbbell shrug"],"equipment":"dumbbell","primary":["traps-upper"],"secondary":["forearm-flexors","traps-mid"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2,"repRange":[8,15],"alternatives":["machine-shrug","farmers-carry","suitcase-carry"],"setup":{"en":"Stand tall holding the dumbbells at your sides, palms facing in, feet hip-width or in a slight split stance, abs braced.","ru":"Встаньте ровно с гантелями по бокам, ладони к корпусу, стопы на ширине таза или в небольшой разножке, пресс напряжён."},"cues":{"en":["Lift the shoulders straight up toward the ears.","Hold for 1 s at the top, then lower for 2 s to a full stretch.","Arms stay straight; the hands just hold on.","Keep the chin level and the neck long.","Holding the dumbbells slightly away from the thighs (arms about 30° out) also works the lower traps."],"ru":["Поднимайте плечи строго вверх, к ушам.","Задержитесь вверху на 1 секунду, затем опускайте 2 секунды до полного растяжения.","Руки прямые, кисти только держат вес.","Подбородок прямо, шея длинная.","Если держать гантели чуть в стороне от бёдер (руки отведены примерно на 30°), работает и нижняя часть трапеций."]},"mistakes":{"en":["Rolling the shoulders in circles instead of lifting straight up and down.","Bending the elbows to help.","Jutting the head forward.","Grip failing first — use a lighter pair or straps rather than half-reps."],"ru":["Вращение плечами по кругу вместо подъёма строго вверх-вниз.","Сгибание локтей, чтобы помочь.","Голова выдвигается вперёд.","Хват сдаётся раньше трапеций — возьмите гантели легче или лямки, а не делайте полуповторы."]},"startLoad":{"kg":10,"source":"Per hand: 0.6 × Strength Level Beginner dumbbell shrug 1RM (17 kg per hand at 80 kg) ≈ 10 kg"},"tags":[],"images":[],"sources":["Standing Shrug — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/75/standing-shrug/","Pizzari et al., Modifying a shrug exercise to facilitate the scapular upward rotators — Clin Biomech, 2014. https://doi.org/10.1016/j.clinbiomech.2013.11.011","Dumbbell Shrug Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-shrug/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"vertical-traction","equipment_id":"selectorized","name":{"en":"Machine lat pulldown (lever)","ru":"Вертикальная тяга в рычажном тренажёре"},"pattern":"vertical-pull","details":{"id":"vertical-traction","name":{"en":"Machine lat pulldown (lever)","ru":"Вертикальная тяга в рычажном тренажёре"},"aka":["Vertical Traction (Technogym Selection)","Life Fitness Insignia Pulldown","Life Fitness Signature Series Lat Pulldown","Life Fitness Insignia Dual Axis Pulldown","Lever lat pulldown","Iso-lateral pulldown machine"],"equipment":"selectorized","pattern":"vertical-pull","class":"vertical-pull","primary":["lats","teres-major"],"secondary":["traps-lower","rhomboids","rotator-cuff","delt-rear","biceps","brachialis"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"alternatives":["lat-pulldown","plate-loaded-pulldown","neutral-grip-pulldown","assisted-pull-up","single-arm-cable-pulldown","band-assisted-pull-up"],"setup":{"en":"Set the seat so you can just reach the handles with your arms fully straight; if the machine has thigh pads, lock them snugly over your thighs. Sit tall against the back pad with your feet flat.","ru":"Отрегулируйте сиденье так, чтобы доставать до рукоятей полностью прямыми руками; если есть валики для бёдер, плотно зафиксируйте их. Сядьте ровно, прижавшись спиной к спинке, стопы на полу."},"cues":{"en":["Start every rep by drawing the shoulder blades down, then drive the elbows down toward your ribs.","Pull until the handles reach upper-chest level, elbows close to your sides.","Keep the chest up and the torso still; only the arms and shoulder blades move.","Exhale as you pull, inhale as the handles rise.","Return over 2–3 s to straight arms and a lat stretch without letting the plates touch.","The arms move independently: keep both handles level and let the weaker side set the pace."],"ru":["Каждый повтор начинайте с опускания лопаток, затем ведите локти вниз к рёбрам.","Тяните, пока рукояти не окажутся на уровне верха груди; локти близко к корпусу.","Грудь вперёд, корпус неподвижен: двигаются только руки и лопатки.","Выдох на тяге, вдох, когда рукояти уходят вверх.","Возвращайте 2–3 секунды до прямых рук и растяжения широчайших так, чтобы плитки стека не касались друг друга.","Рычаги независимы: держите рукояти на одной высоте, темп задаёт более слабая сторона."]},"mistakes":{"en":["Shrugging the shoulders toward the ears at the bottom of the pull.","Leaning far back and turning the pulldown into a row.","Yanking the handles with momentum or letting the stack slam.","Stopping short at the top, so the lats never lengthen.","Ego loading: a weight so heavy that the biceps finish every rep."],"ru":["Поднимать плечи к ушам в нижней точке тяги.","Сильно отклоняться назад, превращая тягу сверху в горизонтальную.","Дёргать рукояти рывком или бросать вес на стек.","Не выпрямлять руки вверху — широчайшие так и не растягиваются.","Гнаться за весом: такой вес, что каждый повтор дожимают бицепсы."]},"startLoad":{"kg":25,"source":"Strength Level lat pulldown, 80 kg man: Beginner 1RM 47 kg; × 0.6 ≈ 28 kg, rounded down to 25 kg because lever machines differ by brand (research 04 §3.9)."},"tags":["owner-alt"],"images":[],"sources":["Selection 700 Vertical Traction — Technogym, 2026. https://www.technogym.com/en-SG/product/selection-700-vertical-traction_MNGC.html","Effects of grip width on muscle strength and activation in the lat pull-down — J Strength Cond Res, 2014. https://doi.org/10.1097/JSC.0000000000000232","Voluntary increase in latissimus dorsi muscle activity during the lat pull-down following expert instruction — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181bb7213","Lat Pulldown Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/lat-pulldown/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"lat-pulldown","equipment_id":"selectorized","name":{"en":"Lat pulldown","ru":"Тяга верхнего блока к груди"},"pattern":"vertical-pull","details":{"id":"lat-pulldown","name":{"en":"Lat pulldown","ru":"Тяга верхнего блока к груди"},"aka":["Wide-grip pulldown","Cable lat pulldown","Front pulldown","Lat Machine (Technogym Selection / Element)","Pulldown/Seated Row (Precor Vitality)"],"equipment":"selectorized","pattern":"vertical-pull","class":"vertical-pull","primary":["lats","teres-major"],"secondary":["traps-lower","rhomboids","rotator-cuff","delt-rear","biceps","brachialis","forearm-flexors"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"alternatives":["vertical-traction","plate-loaded-pulldown","neutral-grip-pulldown","assisted-pull-up","single-arm-cable-pulldown","band-assisted-pull-up"],"setup":{"en":"Set the thigh pad so your thighs are locked in with feet flat on the floor. Stand, take an overhand grip about 1.5 times shoulder width, then sit down with the arms straight.","ru":"Отрегулируйте валики так, чтобы бёдра были плотно зафиксированы, а стопы стояли на полу. Встаньте, возьмитесь за гриф хватом сверху примерно в 1,5 ширины плеч и сядьте с прямыми руками."},"cues":{"en":["Sit tall with the chest up and a slight backward lean; keep that torso angle for the whole set.","Start each rep by pulling the shoulder blades down, then drive the elbows down to your sides.","Pull the bar in front of your face to the top of your chest; the elbows finish under or slightly behind the bar.","Think ''elbows down'', not ''hands down'': the hands are hooks, wrists straight.","Exhale on the pull and pause briefly with the bar at the chest.","Return over 2–3 s to straight arms and a full lat stretch without letting the plates touch.","Keep the neck neutral: look ahead and don''t push the head forward to meet the bar."],"ru":["Сядьте ровно, грудь вперёд, корпус слегка отклонён назад; сохраняйте этот угол весь подход.","Каждый повтор начинайте с опускания лопаток, затем ведите локти вниз к бокам.","Тяните гриф перед лицом к верху груди; в нижней точке локти под грифом или чуть позади.","Думайте «локти вниз», а не «кисти вниз»: кисти — крюки, запястья прямые.","Выдох на тяге, короткая пауза, когда гриф у груди.","Возвращайте гриф 2–3 секунды до прямых рук и полного растяжения широчайших так, чтобы плитки стека не касались друг друга.","Шея нейтрально: смотрите вперёд и не тянитесь головой навстречу грифу."]},"mistakes":{"en":["Pulling the bar behind the neck: it forces the shoulder into an extreme position and works the lats no better than the front pulldown.","Shrugging the shoulders toward the ears instead of pulling them down.","Swinging the torso back to move the weight (momentum and lower-back strain).","Ego loading: a weight you cannot control even at the bottom of the rep range.","Letting the bar yank the arms up and the plates slam at the top.","Cutting the range: stopping at chin level or never straightening the arms."],"ru":["Тянуть гриф за голову: плечевой сустав уходит в крайнее положение, а широчайшие работают не лучше, чем при тяге к груди.","Поднимать плечи к ушам вместо того, чтобы опускать их.","Раскачиваться корпусом назад, чтобы сдвинуть вес (инерция и нагрузка на поясницу).","Гнаться за весом: вес, который не удаётся контролировать даже на нижней границе повторов.","Позволять грифу дёргать руки вверх, а плиткам — с грохотом падать на стек.","Неполная амплитуда: остановка у подбородка или недовыпрямленные руки."]},"startLoad":{"kg":30,"source":"Strength Level lat pulldown, 80 kg man: Beginner 1RM 47 kg; first working load ≈ 0.6 × 47 ≈ 28 → 30 kg at about 3 reps in reserve (research 04 §3.9)."},"tags":["owner-primary"],"images":[],"sources":["Electromyographic analysis of three different types of lat pull-down — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181b8d30a","Effects of grip width on muscle strength and activation in the lat pull-down — J Strength Cond Res, 2014. https://doi.org/10.1097/JSC.0000000000000232","Voluntary increase in latissimus dorsi muscle activity during the lat pull-down following expert instruction — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181bb7213","Lat Pulldown Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/lat-pulldown/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"plate-loaded-pulldown","equipment_id":"plate-loaded","name":{"en":"Plate-loaded lat pulldown","ru":"Тяга сверху в рычажном тренажёре с дисками"},"pattern":"vertical-pull","details":{"id":"plate-loaded-pulldown","name":{"en":"Plate-loaded lat pulldown","ru":"Тяга сверху в рычажном тренажёре с дисками"},"aka":["Hammer Strength Iso-Lateral Front Lat Pulldown","Hammer Strength Iso-Lateral Wide Pulldown","Plate-loaded lever pulldown","Iso-lateral pulldown"],"equipment":"plate-loaded","pattern":"vertical-pull","class":"vertical-pull","primary":["lats","teres-major"],"secondary":["traps-lower","rhomboids","rotator-cuff","delt-rear","biceps","brachialis"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["vertical-traction","lat-pulldown","neutral-grip-pulldown","assisted-pull-up","single-arm-cable-pulldown","band-assisted-pull-up"],"setup":{"en":"Set the seat so the handles are just within reach with the arms fully straight and lower the thigh pad onto your thighs. Load the same plates on both arms and log the total plate weight.","ru":"Отрегулируйте сиденье так, чтобы рукояти были в зоне досягаемости на полностью прямых руках, и опустите валик на бёдра. Навесьте одинаковые диски на оба рычага и записывайте общий вес дисков."},"cues":{"en":["Grip the handles, sit tall with the chest up and feet braced on the floor.","Pull the shoulder blades down first, then drive the elbows down and back toward your hips.","Bring the handles to shoulder or upper-chest level, following the arc of the levers.","Pull both arms at the same speed; they move independently, so keep them level.","Exhale on the pull, then lower for 2–3 s to a full stretch.","Progress in small plates (1.25 kg per side) and compare loads only on this machine."],"ru":["Возьмитесь за рукояти, сядьте ровно, грудь вперёд, стопы упираются в пол.","Сначала опустите лопатки, затем ведите локти вниз и назад к тазу.","Доводите рукояти до уровня плеч или верха груди, следуя дуге рычагов.","Тяните обеими руками с одной скоростью: рычаги независимы, держите их на одном уровне.","Выдох на тяге, затем опускайте 2–3 секунды до полного растяжения.","Прибавляйте маленькими дисками (по 1,25 кг на сторону) и сравнивайте веса только на этом тренажёре."]},"mistakes":{"en":["Loading different plates on the two arms.","Shrugging up at the bottom of the pull.","Leaning back and using body weight to start the levers moving.","Letting the levers fly up and bang at the top.","Comparing the plate weight with a cable pulldown: the lever changes the resistance."],"ru":["Навешивать разный вес на два рычага.","Поднимать плечи к ушам в нижней точке тяги.","Отклоняться назад и сдёргивать рычаги весом тела.","Отпускать рычаги так, что они взлетают и ударяются вверху.","Сравнивать вес дисков с весом в блочной тяге: рычаг меняет сопротивление."]},"startLoad":{"kg":20,"source":"Estimate: no crowd standard for lever pulldowns; ≈ 0.6–0.7 × the 30 kg cable-pulldown start, i.e. 10 kg of plates per side (research 04 §3.8: lever ratios vary, start low and adjust)."},"tags":["owner-alt"],"images":[],"sources":["Plate Loaded Iso-Lateral Front Lat Pulldown — Hammer Strength (Life Fitness), 2026. https://www.lifefitness.com/en-eu/catalog/strength-training/plate-loaded/plate-loaded-iso-lateral-front-lat-pulldown","Effects of grip width on muscle strength and activation in the lat pull-down — J Strength Cond Res, 2014. https://doi.org/10.1097/JSC.0000000000000232","Lat Pulldown Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/lat-pulldown/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"neutral-grip-pulldown","equipment_id":"selectorized","name":{"en":"Neutral-grip lat pulldown","ru":"Тяга верхнего блока узким параллельным хватом"},"pattern":"vertical-pull","details":{"id":"neutral-grip-pulldown","name":{"en":"Neutral-grip lat pulldown","ru":"Тяга верхнего блока узким параллельным хватом"},"aka":["Close-grip V-bar pulldown","Parallel-grip pulldown","MAG-grip pulldown","Close neutral-grip lat pulldown"],"equipment":"selectorized","pattern":"vertical-pull","class":"vertical-pull","primary":["lats","teres-major"],"secondary":["biceps","brachialis","brachioradialis","traps-lower","rhomboids","delt-rear"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"alternatives":["lat-pulldown","vertical-traction","plate-loaded-pulldown","assisted-pull-up","single-arm-cable-pulldown","band-assisted-pull-up"],"setup":{"en":"Clip a close neutral-grip (V) handle or a parallel-grip bar to the high pulley, lock your thighs under the pads and start with straight arms, palms facing each other.","ru":"Пристегните к верхнему блоку узкую параллельную (V-образную) рукоять или гриф с параллельными ручками, зафиксируйте бёдра валиками и начните с прямых рук, ладони смотрят друг на друга."},"cues":{"en":["Lean back slightly with the chest up and keep that angle.","Draw the shoulder blades down, then drive the elbows down close to your ribs.","Bring the handle to the upper chest, just below the collarbones.","Exhale on the pull and squeeze the lats briefly at the bottom.","Return over 2–3 s until the arms are straight and the lats stretch."],"ru":["Слегка отклонитесь назад, грудь вперёд, и сохраняйте этот угол.","Опустите лопатки, затем ведите локти вниз вдоль рёбер.","Доводите рукоять до верха груди, чуть ниже ключиц.","Выдох на тяге; внизу коротко напрягите широчайшие.","Возвращайте 2–3 секунды до прямых рук и растяжения широчайших."]},"mistakes":{"en":["Leaning back so far that the pulldown becomes a row.","Rounding the upper back and pushing the head forward to meet the handle.","Shrugging at the top or the bottom of the rep.","Jerking the stack with a hip swing."],"ru":["Отклоняться так сильно, что тяга превращается в горизонтальную.","Сутулиться и тянуть голову навстречу рукояти.","Поднимать плечи к ушам в верхней или нижней точке.","Сдёргивать стек рывком корпуса."]},"startLoad":{"kg":30,"source":"Strength Level close-grip lat pulldown, 80 kg man: Beginner 1RM 54 kg; × 0.6 ≈ 32 → 30 kg."},"tags":["owner-alt"],"images":[],"sources":["Electromyographic analysis of three different types of lat pull-down — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181b8d30a","Electromyographic analysis of muscle activation during pull-up variations — J Electromyogr Kinesiol, 2017. https://doi.org/10.1016/j.jelekin.2016.11.004","Close Grip Lat Pulldown Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/close-grip-lat-pulldown/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"assisted-pull-up","equipment_id":"assisted","name":{"en":"Assisted pull-up (machine)","ru":"Подтягивания в гравитроне"},"pattern":"vertical-pull","details":{"id":"assisted-pull-up","name":{"en":"Assisted pull-up (machine)","ru":"Подтягивания в гравитроне"},"aka":["Gravitron","Assisted chin-up machine","Assist Dip Chin (Life Fitness Insignia / Signature)","Chin/Dip Assist (Hoist)","Dip Chin Assist (Cybex Prestige VRS)"],"equipment":"assisted","pattern":"vertical-pull","class":"vertical-pull","primary":["lats","teres-major"],"secondary":["traps-lower","rhomboids","rotator-cuff","biceps","brachialis","forearm-flexors"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"assistance":true,"alternatives":["lat-pulldown","band-assisted-pull-up","neutral-grip-pulldown","vertical-traction","plate-loaded-pulldown","single-arm-cable-pulldown"],"setup":{"en":"Select the counterweight on the stack (more kg = more help). Climb the steps, take the handles about shoulder width (neutral or overhand), then place your knees or feet on the pad one at a time and lower yourself under control to straight arms.","ru":"Выберите на стеке вес противовеса (больше килограммов — больше помощи). Поднимитесь по ступенькам, возьмитесь за рукояти на ширине плеч (параллельно или сверху), поставьте колени или стопы на платформу по одному и плавно опуститесь до прямых рук."},"cues":{"en":["Hang with straight arms but active shoulders: pull them slightly down, away from the ears, before each rep.","Drive the elbows down and back until your chin clears the handles.","Keep the ribs down and the legs still: no kicking or swinging.","Exhale on the way up, inhale on the way down.","Lower over 2–3 s to straight arms; don''t drop into the bottom.","Progress by taking assistance off: 5 kg less once every set reaches the top of the rep range.","To get off, step back onto the steps before you let go of the handles."],"ru":["Висите на прямых руках, но с активными плечами: перед каждым повтором слегка опустите их от ушей.","Ведите локти вниз и назад, пока подбородок не окажется выше рукоятей.","Рёбра опущены, ноги неподвижны: без махов и раскачки.","Выдох на подъёме, вдох на опускании.","Опускайтесь 2–3 секунды до прямых рук, не проваливаясь вниз.","Прогресс — это меньше помощи: снимайте 5 кг противовеса, когда во всех подходах выполнен верх диапазона повторов.","Чтобы сойти, сначала встаньте на ступеньки и только потом отпускайте рукояти."]},"mistakes":{"en":["Stepping off the pad before standing on the steps: the platform springs up.","Dropping into the bottom and hanging on relaxed, shrugged shoulders.","Half reps: not straightening the arms or not getting the chin over the handles.","Kicking or swinging to finish the rep.","Reading the stack backwards: adding kg makes it easier, not harder."],"ru":["Сходить с платформы, не встав на ступеньки: она резко подпрыгивает вверх.","Проваливаться вниз и висеть на расслабленных, поднятых к ушам плечах.","Неполные повторы: руки не выпрямляются или подбородок не поднимается выше рукоятей.","Помогать себе махом ног или раскачкой.","Путать направление: больше килограммов противовеса — легче, а не тяжелее."]},"startLoad":{"kg":45,"source":"Assistance, not load: research 04 §3.9 seeds 35–50 kg of assistance for 6–8 reps (≈ a 30–45 kg pulldown) for an 80 kg man; Strength Level puts an 80 kg Beginner at 1 strict pull-up."},"tags":["owner-primary"],"images":[],"sources":["Insignia Series Assist Dip Chin — Life Fitness, 2026. https://www.lifefitness.com/en-us/catalog/strength-training/selectorized/insignia-series-assist-dip-chin","Surface electromyographic activation patterns and elbow joint motion during a pull-up, chin-up, or Perfect-Pullup rotational exercise — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181f1598c","Pull Ups Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/pull-ups"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"single-arm-cable-pulldown","equipment_id":"cable","name":{"en":"Single-arm cable pulldown","ru":"Тяга верхнего блока одной рукой"},"pattern":"vertical-pull","details":{"id":"single-arm-cable-pulldown","name":{"en":"Single-arm cable pulldown","ru":"Тяга верхнего блока одной рукой"},"aka":["One-arm lat pulldown","Kneeling single-arm pulldown","Single-arm high cable pull","Unilateral cable pulldown"],"equipment":"cable","pattern":"vertical-pull","class":"vertical-pull","primary":["lats","teres-major"],"secondary":["traps-lower","rhomboids","biceps","brachialis","obliques"],"difficulty":2,"unilateral":true,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[8,12],"alternatives":["vertical-traction","plate-loaded-pulldown","lat-pulldown","neutral-grip-pulldown","assisted-pull-up","band-assisted-pull-up","pull-up","chin-up"],"setup":{"en":"Clip a single D-handle to a high pulley. Sit at a pulldown station with the thighs under the pads (or half-kneel facing a cable column) and start with the working arm straight overhead.","ru":"Пристегните одиночную D-рукоять к верхнему блоку. Сядьте в тренажёр для тяги сверху, зафиксировав бёдра валиками (или встаньте на одно колено лицом к кроссоверу), и начните с прямой рабочей руки над головой."},"cues":{"en":["Let the working shoulder rise into a stretch at the top, then pull it down first.","Drive the elbow down toward your hip, palm facing forward or inward.","Keep the torso square: don''t twist or lean toward the working side.","Exhale as you pull and pause with the hand at shoulder height.","Return over 2–3 s to a full stretch; finish all reps on one side, then switch."],"ru":["Вверху позвольте рабочему плечу подняться в растяжение, а затем первым делом опустите его.","Ведите локоть вниз к тазу; ладонь смотрит вперёд или внутрь.","Держите корпус ровно: не скручивайтесь и не заваливайтесь в рабочую сторону.","Выдох на тяге, пауза, когда кисть на уровне плеча.","Возвращайте 2–3 секунды до полного растяжения; сделайте все повторы одной рукой, затем другой."]},"mistakes":{"en":["Rotating the trunk to pull with the body instead of the lat.","Shrugging the working shoulder at the bottom.","Bending the wrist and pulling with the forearm.","Doing more reps or load on the stronger side: match both arms."],"ru":["Скручивать корпус, чтобы тянуть телом, а не широчайшей.","Поднимать рабочее плечо к уху в нижней точке.","Сгибать запястье и тянуть предплечьем.","Делать сильной рукой больше, чем слабой: повторы и вес на обеих руках одинаковые."]},"startLoad":{"kg":12.5,"source":"Per arm: about half of the 30 kg two-arm pulldown start (Strength Level lat pulldown Beginner 1RM 47 kg × 0.6), rounded down."},"tags":["owner-alt"],"images":[],"sources":["Voluntary increase in latissimus dorsi muscle activity during the lat pull-down following expert instruction — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181bb7213","Electromyographic analysis of latissimus dorsi activation during common resistance training exercises: a narrative review — J Funct Morphol Kinesiol, 2026. https://doi.org/10.3390/jfmk11030315","Lat Pulldown Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/lat-pulldown/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"band-assisted-pull-up","equipment_id":"band","name":{"en":"Band-assisted pull-up","ru":"Подтягивания с резиновой петлёй"},"pattern":"vertical-pull","details":{"id":"band-assisted-pull-up","name":{"en":"Band-assisted pull-up","ru":"Подтягивания с резиновой петлёй"},"aka":["Banded pull-up","Band-assisted chin-up","Resistance-band pull-up"],"equipment":"band","pattern":"vertical-pull","class":"vertical-pull","primary":["lats","teres-major"],"secondary":["traps-lower","rhomboids","rotator-cuff","biceps","brachialis","forearm-flexors"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[5,10],"alternatives":["assisted-pull-up","lat-pulldown","neutral-grip-pulldown","vertical-traction","plate-loaded-pulldown","chin-up","pull-up"],"setup":{"en":"Loop a strong resistance band around the pull-up bar, step into it with one knee or both feet (stand on a bench to reach) and grip the bar overhand about shoulder width.","ru":"Закрепите плотную резиновую петлю на перекладине, вставьте в неё колено или обе стопы (встаньте на скамью, чтобы дотянуться) и возьмитесь за перекладину хватом сверху на ширине плеч."},"cues":{"en":["Start from straight arms with the shoulders drawn slightly down.","Pull your chest toward the bar until the chin is over it.","Keep the legs together and the body still; the band helps most at the bottom and least at the top.","Lower over 2–3 s; don''t let the band fling you up or snap you down.","Move to a thinner band once every set reaches the top of the rep range."],"ru":["Начинайте с прямых рук, плечи слегка опущены.","Тяните грудь к перекладине, пока подбородок не окажется над ней.","Ноги вместе, тело неподвижно; резина сильнее всего помогает внизу и слабее всего — вверху.","Опускайтесь 2–3 секунды; не позволяйте резине подбрасывать вас или дёргать вниз.","Переходите на более тонкую петлю, когда во всех подходах выполнен верх диапазона повторов."]},"mistakes":{"en":["Stepping into the band carelessly: it can slip off the foot and whip back.","Bouncing out of the bottom on the band''s recoil.","Half reps with the chin below the bar.","Staying on the same band for months instead of progressing."],"ru":["Неаккуратно вставать в петлю: она может соскользнуть со стопы и хлестнуть.","Отскакивать из нижней точки за счёт отдачи резины.","Неполные повторы: подбородок не доходит до перекладины.","Месяцами работать с одной и той же петлёй вместо прогрессии."]},"tags":["owner-alt"],"images":[],"sources":["Surface electromyographic activation patterns and elbow joint motion during a pull-up, chin-up, or Perfect-Pullup rotational exercise — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181f1598c","Electromyographic analysis of muscle activation during pull-up variations — J Electromyogr Kinesiol, 2017. https://doi.org/10.1016/j.jelekin.2016.11.004","Pull Ups Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/pull-ups"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"pull-up","equipment_id":"bodyweight","name":{"en":"Pull-up","ru":"Подтягивания прямым хватом"},"pattern":"vertical-pull","details":{"id":"pull-up","name":{"en":"Pull-up","ru":"Подтягивания прямым хватом"},"aka":["Overhand pull-up","Pronated-grip pull-up","Bodyweight pull-up","Strict pull-up"],"equipment":"bodyweight","pattern":"vertical-pull","class":"vertical-pull","primary":["lats","teres-major"],"secondary":["traps-lower","rotator-cuff","rhomboids","biceps","brachialis","forearm-flexors"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[3,8],"alternatives":["chin-up","band-assisted-pull-up","assisted-pull-up","lat-pulldown","vertical-traction","plate-loaded-pulldown","neutral-grip-pulldown","single-arm-cable-pulldown"],"setup":{"en":"Grip the bar overhand slightly wider than shoulder width and hang with straight arms, legs together or crossed at the ankles.","ru":"Возьмитесь за перекладину хватом сверху чуть шире плеч и повисните на прямых руках, ноги вместе или скрещены в лодыжках."},"cues":{"en":["Before each rep pull the shoulders down, away from the ears (active hang).","Drive the elbows down to your ribs and pull your chest toward the bar.","Finish with the chin over the bar without craning the neck.","Hold a slight hollow: ribs down, glutes tight, no swing.","Exhale on the way up; lower over 2–3 s to straight arms.","If you cannot do 3 clean reps, use the assisted machine or a band instead."],"ru":["Перед каждым повтором опустите плечи от ушей (активный вис).","Ведите локти к рёбрам и тяните грудь к перекладине.","Заканчивайте с подбородком над перекладиной, не вытягивая шею.","Корпус слегка собран: рёбра опущены, ягодицы напряжены, без раскачки.","Выдох на подъёме; опускайтесь 2–3 секунды до прямых рук.","Если не получается 3 чистых повтора — работайте в гравитроне или с резиновой петлёй."]},"mistakes":{"en":["Kipping or swinging the legs to get over the bar.","Half reps that never reach straight arms at the bottom.","Reaching the chin up to the bar instead of pulling the body up.","Dropping into the bottom on relaxed shoulders, which jolts the joint.","Adding weight before you can do 8 strict reps."],"ru":["Киппинг или раскачка ногами, чтобы перебраться через перекладину.","Неполные повторы без выпрямления рук внизу.","Тянуться подбородком к перекладине вместо подъёма всего тела.","Падать в нижнюю точку на расслабленных плечах — это рывок для сустава.","Вешать дополнительный вес раньше, чем получается 8 строгих повторов."]},"startLoad":{"kg":0,"source":"Bodyweight: Strength Level pull-ups, 80 kg man: Beginner 1 rep, Novice 7 reps; add load only after 8 strict reps."},"tags":["owner-alt"],"images":[],"sources":["Surface electromyographic activation patterns and elbow joint motion during a pull-up, chin-up, or Perfect-Pullup rotational exercise — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181f1598c","ACE-sponsored research: what is the best back exercise? — American Council on Exercise, 2018. https://www.acefitness.org/continuing-education/certified/april-2018/6959/ace-sponsored-research-what-is-the-best-back-exercise/","Electromyographic analysis of muscle activation during pull-up variations — J Electromyogr Kinesiol, 2017. https://doi.org/10.1016/j.jelekin.2016.11.004","Pull Ups Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/pull-ups"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"chin-up","equipment_id":"bodyweight","name":{"en":"Chin-up","ru":"Подтягивания обратным хватом"},"pattern":"vertical-pull","details":{"id":"chin-up","name":{"en":"Chin-up","ru":"Подтягивания обратным хватом"},"aka":["Underhand pull-up","Supinated-grip pull-up","Reverse-grip pull-up"],"equipment":"bodyweight","pattern":"vertical-pull","class":"vertical-pull","primary":["lats","teres-major"],"secondary":["biceps","brachialis","pec-sternal","traps-lower","rhomboids","forearm-flexors"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[3,8],"alternatives":["pull-up","band-assisted-pull-up","assisted-pull-up","neutral-grip-pulldown","lat-pulldown","vertical-traction","plate-loaded-pulldown","single-arm-cable-pulldown"],"setup":{"en":"Grip the bar underhand (palms toward you) about shoulder width and hang with straight arms.","ru":"Возьмитесь за перекладину хватом снизу (ладони к себе) на ширине плеч и повисните на прямых руках."},"cues":{"en":["Set the shoulders down before the first rep.","Pull the elbows down to your sides and your chest to the bar.","Finish with the chin over the bar, neck neutral.","Ribs down, legs still: no swing.","Exhale on the way up; lower over 2–3 s until the elbows are fully straight."],"ru":["Перед первым повтором опустите плечи.","Ведите локти вниз к бокам, а грудь — к перекладине.","Заканчивайте с подбородком над перекладиной, шея нейтрально.","Рёбра опущены, ноги неподвижны: без раскачки.","Выдох на подъёме; опускайтесь 2–3 секунды до полностью прямых локтей."]},"mistakes":{"en":["Stopping short of straight elbows at the bottom.","Swinging or kipping.","Gripping so narrow that the wrists and elbows ache.","Dropping fast and jolting the elbows at the bottom."],"ru":["Не выпрямлять локти в нижней точке.","Раскачиваться или делать киппинг.","Брать хват настолько узкий, что болят запястья и локти.","Резко падать вниз с рывком в локтях."]},"startLoad":{"kg":0,"source":"Bodyweight: Strength Level chin-ups, 80 kg man: Beginner 1 rep, Novice 7 reps."},"tags":["owner-alt"],"images":[],"sources":["Surface electromyographic activation patterns and elbow joint motion during a pull-up, chin-up, or Perfect-Pullup rotational exercise — J Strength Cond Res, 2010. https://doi.org/10.1519/JSC.0b013e3181f1598c","Kinematic and electromyographic comparisons between chin-ups and lat-pull down exercises — Sports Biomech, 2013. https://doi.org/10.1080/14763141.2012.760204","Chin Ups Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/chin-ups"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-pullover","equipment_id":"selectorized","name":{"en":"Machine pullover","ru":"Пуловер в тренажёре"},"pattern":"pullover","details":{"id":"machine-pullover","name":{"en":"Machine pullover","ru":"Пуловер в тренажёре"},"aka":["Nautilus Pullover","Nautilus Inspiration Pull Over","Hammer Strength Pullover","Technogym Pure Strength Pullover","Lever pullover"],"equipment":"selectorized","pattern":"pullover","class":"lat-isolation","primary":["lats","teres-major"],"secondary":["pec-sternal","triceps-long","serratus-anterior","rectus-abdominis"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":5,"repRange":[8,15],"alternatives":["straight-arm-pulldown","dumbbell-pullover","lat-pulldown","single-arm-cable-pulldown"],"setup":{"en":"Set the seat so your shoulder joint lines up with the machine''s pivot (usually marked) and fasten the belt. Press the foot bar to bring the pads forward, rest the backs of your upper arms on the elbow pads and keep the hands open on the bar.","ru":"Отрегулируйте сиденье так, чтобы плечевой сустав был на одной линии с осью вращения тренажёра (обычно она отмечена), и застегните ремень. Нажмите на педаль, чтобы подвести упоры вперёд, положите на них заднюю поверхность плеч, кисти держите открытыми на перекладине."},"cues":{"en":["Release the foot bar slowly and let the arms travel back overhead into a stretch.","Drive with the elbows, not the hands: push the pads down in an arc to your sides.","Keep your back against the pad and the ribs down; don''t arch to finish.","Exhale as you drive the pads down and pause briefly at the bottom.","Return over 2–3 s to the deepest stretch you can control without shoulder pain.","At the end of the set take the weight with the foot bar before you get out."],"ru":["Медленно отпустите педаль и дайте рукам уйти назад за голову в растяжение.","Работайте локтями, а не кистями: ведите упоры по дуге вниз к бокам.","Спина прижата к спинке, рёбра опущены; не прогибайтесь, чтобы дожать.","Выдох, когда ведёте упоры вниз; короткая пауза внизу.","Возвращайте 2–3 секунды до самого глубокого растяжения, которое контролируете без боли в плече.","В конце подхода примите вес на педаль и только потом выходите из тренажёра."]},"mistakes":{"en":["Seat at the wrong height, so the shoulder does not rotate around the machine''s axis.","Gripping hard and pulling with the forearms instead of pressing with the elbows.","Arching the lower back to gain range.","Forcing the stretch past what the shoulder tolerates.","Letting the weight snap the arms back overhead."],"ru":["Неправильная высота сиденья: плечо вращается не вокруг оси тренажёра.","Крепко сжимать перекладину и тянуть предплечьями вместо давления локтями.","Прогибать поясницу ради амплитуды.","Форсировать растяжение сверх того, что терпит плечо.","Позволять весу рывком утаскивать руки за голову."]},"startLoad":{"kg":15,"source":"Estimate: no crowd standard for this machine; between 0.6 × Strength Level straight-arm pulldown (Beginner 20 kg) and lat pulldown (47 kg) for an 80 kg man; cams differ by brand."},"tags":[],"images":[],"sources":["Inspiration Pull Over product sheet — Nautilus (Core Health & Fitness), 2026. https://www.corehandf.com/cdn/shop/files/Product_Pull_Over_Inspiration_Nautilus_Product_Sheet.pdf","Differences between pullover and pulldown exercises on maximal isometric force and myoelectric activity in recreationally-trained men — Int J Exerc Sci, 2022. https://pmc.ncbi.nlm.nih.gov/articles/PMC9362894/","Straight Arm Pulldown Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/straight-arm-pulldown/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"straight-arm-pulldown","equipment_id":"cable","name":{"en":"Straight-arm pulldown","ru":"Тяга прямыми руками на верхнем блоке"},"pattern":"pullover","details":{"id":"straight-arm-pulldown","name":{"en":"Straight-arm pulldown","ru":"Тяга прямыми руками на верхнем блоке"},"aka":["Straight-arm lat pulldown","Standing cable pullover","Stiff-arm pulldown","Rope pullover (cable)"],"equipment":"cable","pattern":"pullover","class":"lat-isolation","primary":["lats","teres-major"],"secondary":["triceps-long","pec-costal","delt-rear","traps-lower"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[10,15],"alternatives":["machine-pullover","dumbbell-pullover","single-arm-cable-pulldown","lat-pulldown"],"setup":{"en":"Clip a straight bar or rope to a high pulley and step back until the cable is taut with your arms extended in front at about head height. Soften the knees and hinge forward slightly with a neutral spine.","ru":"Пристегните прямую рукоять или канат к верхнему блоку и отойдите назад, чтобы трос был натянут, а руки вытянуты вперёд примерно на уровне головы. Колени слегка согнуты, корпус немного наклонён вперёд, спина ровная."},"cues":{"en":["Lock a slight bend in the elbows and keep it: the elbows neither open nor close.","Draw the shoulder blades down, then sweep the bar in an arc down to your thighs.","Keep the torso still; the movement happens only at the shoulders.","Exhale on the way down and squeeze the lats at the thighs.","Return over 2–3 s until the arms reach about head height and you feel a stretch under the armpits."],"ru":["Зафиксируйте небольшой сгиб в локтях и не меняйте его.","Опустите лопатки и ведите рукоять по дуге вниз к бёдрам.","Корпус неподвижен, движение только в плечевых суставах.","Выдох при движении вниз; у бёдер напрягите широчайшие.","Возвращайте 2–3 секунды, пока руки не поднимутся примерно до уровня головы и не почувствуется растяжение под мышками."]},"mistakes":{"en":["Bending the elbows and turning it into a triceps pushdown.","Bobbing the torso up and down to move the weight.","Shrugging as the bar comes up.","Loading it like a compound lift: the exercise is light by nature and fails as soon as form breaks."],"ru":["Сгибать локти — получается разгибание рук на трицепс.","Качать корпусом вверх-вниз, чтобы сдвинуть вес.","Поднимать плечи к ушам, когда рукоять идёт вверх.","Грузить его как базовое упражнение: оно по природе лёгкое и теряет смысл, как только ломается техника."]},"startLoad":{"kg":12.5,"source":"Strength Level straight-arm pulldown, 80 kg man: Beginner 1RM 20 kg; × 0.6 = 12 → 12.5 kg."},"tags":[],"images":[],"sources":["Straight Arm Pulldown Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/straight-arm-pulldown/kg","Differences between pullover and pulldown exercises on maximal isometric force and myoelectric activity in recreationally-trained men — Int J Exerc Sci, 2022. https://pmc.ncbi.nlm.nih.gov/articles/PMC9362894/","Electromyographic analysis of latissimus dorsi activation during common resistance training exercises: a narrative review — J Funct Morphol Kinesiol, 2026. https://doi.org/10.3390/jfmk11030315"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dumbbell-pullover","equipment_id":"dumbbell","name":{"en":"Dumbbell pullover","ru":"Пуловер с гантелью лёжа"},"pattern":"pullover","details":{"id":"dumbbell-pullover","name":{"en":"Dumbbell pullover","ru":"Пуловер с гантелью лёжа"},"aka":["Lying dumbbell pullover","Bench pullover","Cross-bench pullover"],"equipment":"dumbbell","pattern":"pullover","class":"lat-isolation","primary":["lats","pec-sternal"],"secondary":["teres-major","pec-costal","triceps-long","serratus-anterior"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":2,"repRange":[8,15],"alternatives":["machine-pullover","straight-arm-pulldown","lat-pulldown","single-arm-cable-pulldown"],"setup":{"en":"Lie on a flat bench with your head and upper back supported and the feet flat. Hold one dumbbell with both palms cupped under the top plate, arms over the chest, elbows slightly bent.","ru":"Лягте на горизонтальную скамью так, чтобы голова и верх спины были на опоре, стопы на полу. Держите одну гантель обеими ладонями под верхним диском, руки над грудью, локти слегка согнуты."},"cues":{"en":["Brace: ribs down and the lower back lightly in contact with the bench.","Lower the dumbbell behind your head in an arc, keeping the elbow bend fixed.","Stop when the upper arms are in line with your torso or at a comfortable stretch.","Inhale on the way down, exhale as you pull it back.","Bring it back only to above the forehead so the lats and chest stay loaded."],"ru":["Напрягите пресс: рёбра опущены, поясница слегка касается скамьи.","Опускайте гантель по дуге за голову, не меняя сгиб в локтях.","Остановитесь, когда плечи окажутся на одной линии с корпусом или в комфортном растяжении.","Вдох при опускании, выдох при подъёме.","Возвращайте гантель только до положения над лбом, чтобы широчайшие и грудь оставались под нагрузкой."]},"mistakes":{"en":["Arching the lower back as the weight goes behind the head.","Bending and straightening the elbows, which turns it into a triceps extension.","Lowering past a comfortable shoulder stretch or with a heavy, uncontrolled weight.","A loose grip on the handle instead of cupping the top plate (the dumbbell is over your face)."],"ru":["Прогибать поясницу, когда гантель уходит за голову.","Сгибать и разгибать локти — так получается разгибание на трицепс.","Опускать глубже комфортного растяжения плеча или с тяжёлым неконтролируемым весом.","Держать гантель за ручку некрепко вместо обхвата верхнего диска (гантель над лицом)."]},"startLoad":{"kg":10,"source":"Strength Level dumbbell pullover, 80 kg man: Beginner 1RM 15 kg (one dumbbell); × 0.6 = 9 → 10 kg."},"tags":[],"images":[],"sources":["Effects of the pullover exercise on the pectoralis major and latissimus dorsi muscles as evaluated by EMG — J Appl Biomech, 2011. https://doi.org/10.1123/jab.27.4.380","Electromyographic analysis of latissimus dorsi activation during common resistance training exercises: a narrative review — J Funct Morphol Kinesiol, 2026. https://doi.org/10.3390/jfmk11030315","Dumbbell Pullover Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-pullover/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-row","equipment_id":"selectorized","name":{"en":"Chest-supported machine row","ru":"Горизонтальная тяга в тренажёре с упором в грудь"},"pattern":"horizontal-pull","details":{"id":"machine-row","name":{"en":"Chest-supported machine row","ru":"Горизонтальная тяга в тренажёре с упором в грудь"},"aka":["Low Row (Technogym Selection)","Row (Life Fitness Insignia)","Row (Cybex Eagle NX)","Row (Nautilus One)","Vertical Row (Nautilus Inspiration)","Seated row machine"],"equipment":"selectorized","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["delt-rear","teres-major","traps-lower","biceps","brachialis"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[6,12],"alternatives":["plate-loaded-row","t-bar-row","high-row-machine","chest-supported-dumbbell-row","seated-cable-row","single-arm-dumbbell-row","inverted-row","single-arm-cable-row"],"setup":{"en":"Set the seat so the handles are at lower-chest height and the chest pad so you can just reach them with straight arms and the shoulder blades drawn forward. Sit tall, chest on the pad, feet flat.","ru":"Отрегулируйте сиденье так, чтобы рукояти были на уровне низа груди, а упор — так, чтобы вы доставали до них прямыми руками с выведенными вперёд лопатками. Сядьте ровно, грудь на упоре, стопы на полу."},"cues":{"en":["Keep the chest on the pad from the first rep to the last.","Start each rep by pulling the shoulder blades back, then drive the elbows back past your torso.","Pick the grip for the goal: neutral handles with the elbows close work the lats more; a wide overhand grip with the elbows out works the upper back and rear delts.","Pause for a moment with the elbows behind you and the shoulders down.","Exhale as you pull, inhale on the way back.","Return over 2–3 s until the arms are straight and the shoulder blades spread forward.","Keep the neck long and the chin slightly tucked; look straight ahead."],"ru":["Держите грудь на упоре от первого до последнего повтора.","Каждый повтор начинайте со сведения лопаток, затем ведите локти назад за линию корпуса.","Хват — под цель: параллельные рукояти и локти у корпуса сильнее нагружают широчайшие, широкий хват сверху с локтями в стороны — верх спины и задние дельты.","Коротко задержитесь, когда локти позади корпуса, а плечи опущены.","Выдох на тяге, вдох на возврате.","Возвращайте 2–3 секунды до прямых рук и разведённых вперёд лопаток.","Шея длинная, подбородок слегка втянут, взгляд вперёд."]},"mistakes":{"en":["Lifting the chest off the pad and leaning back to finish the rep.","Shrugging the shoulders up as you pull.","Jerking the handles and letting the stack slam between reps.","Short reps: the arms never straighten, so the upper back never stretches.","Ego loading: if you cannot pause at the end of the pull, the weight is too heavy."],"ru":["Отрывать грудь от упора и отклоняться назад, чтобы дотянуть повтор.","Поднимать плечи к ушам на тяге.","Дёргать рукояти и бросать стек между повторами.","Короткие повторы: руки не выпрямляются, и верх спины не растягивается.","Гнаться за весом: если не удаётся задержаться в конце тяги, вес слишком большой."]},"startLoad":{"kg":30,"source":"Strength Level machine row, 80 kg man: Beginner 1RM 47 kg; × 0.6 ≈ 28 → 30 kg at about 3 reps in reserve (research 04 §3.9)."},"tags":["owner-primary"],"images":[],"sources":["Selection 700 Low Row — Technogym, 2026. https://www.technogym.com/en-SG/product/selection-700-low-row_MNHC.html","Variations in muscle activation levels during traditional latissimus dorsi weight training exercises — Dyn Med, 2004. https://doi.org/10.1186/1476-5918-3-4","Electromyographic analysis of latissimus dorsi activation during common resistance training exercises: a narrative review — J Funct Morphol Kinesiol, 2026. https://doi.org/10.3390/jfmk11030315","Machine Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-row/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"plate-loaded-row","equipment_id":"plate-loaded","name":{"en":"Plate-loaded row (iso-lateral)","ru":"Горизонтальная тяга в рычажном тренажёре с дисками"},"pattern":"horizontal-pull","details":{"id":"plate-loaded-row","name":{"en":"Plate-loaded row (iso-lateral)","ru":"Горизонтальная тяга в рычажном тренажёре с дисками"},"aka":["Hammer Strength Iso-Lateral Row","Hammer Strength Iso-Lateral Low Row","Technogym Pure Strength Row","Technogym Pure Strength Low Row","Iso-lateral row"],"equipment":"plate-loaded","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["delt-rear","teres-major","traps-lower","biceps","brachialis"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["machine-row","t-bar-row","high-row-machine","chest-supported-dumbbell-row","seated-cable-row","single-arm-dumbbell-row","inverted-row","single-arm-cable-row"],"setup":{"en":"Adjust the seat so the handles are at mid-to-lower chest height with your chest on the pad. Load equal plates on both arms and log the total plate weight.","ru":"Отрегулируйте сиденье так, чтобы рукояти были на уровне середины или низа груди, а грудь лежала на упоре. Навесьте одинаковые диски на оба рычага и записывайте общий вес дисков."},"cues":{"en":["Chest stays on the pad, feet planted.","Pull the shoulder blades back first, then row the elbows past your ribs.","Follow the levers'' converging arc and keep the wrists straight.","Exhale on the pull and pause briefly at the end.","Lower over 2–3 s to straight arms and a full upper-back stretch.","The arms move independently: keep them level, or row one arm at a time if one side lags."],"ru":["Грудь на упоре, стопы упираются в пол.","Сначала сведите лопатки, затем ведите локти назад мимо рёбер.","Следуйте сходящейся дуге рычагов, запястья прямые.","Выдох на тяге, короткая пауза в конце.","Опускайте 2–3 секунды до прямых рук и полного растяжения верха спины.","Рычаги независимы: держите их на одной высоте или тяните по одной руке, если одна сторона отстаёт."]},"mistakes":{"en":["Different plates on each side.","Peeling the chest off the pad and swinging the torso.","Shrugging toward the ears.","Dropping the levers so they bang at the bottom."],"ru":["Разный вес дисков на сторонах.","Отрывать грудь от упора и раскачивать корпус.","Поднимать плечи к ушам.","Бросать рычаги, чтобы они ударялись внизу."]},"startLoad":{"kg":20,"source":"Estimate: 10 kg of plates per side (≈ 0.6–0.7 × the 30 kg machine-row start; Strength Level machine row Beginner 1RM 47 kg); the Hammer Strength arms already add about 5 kg each before plates."},"tags":["owner-alt"],"images":[],"sources":["Plate Loaded Iso-Lateral Row — Hammer Strength (Life Fitness), 2026. https://www.lifefitness.com/en-eu/catalog/strength-training/plate-loaded/plate-loaded-iso-lateral-row","Comparison of different rowing exercises: trunk muscle activation and lumbar spine motion, load, and stiffness — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181942019","Machine Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-row/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"t-bar-row","equipment_id":"plate-loaded","name":{"en":"Chest-supported T-bar row","ru":"Тяга Т-грифа с упором в грудь"},"pattern":"horizontal-pull","details":{"id":"t-bar-row","name":{"en":"Chest-supported T-bar row","ru":"Тяга Т-грифа с упором в грудь"},"aka":["Hammer Strength Iso-Lateral T-Bar Row","Lying T-bar row","Incline lever row","Chest-supported lever row"],"equipment":"plate-loaded","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["delt-rear","teres-major","traps-lower","biceps","brachialis","forearm-flexors"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["plate-loaded-row","machine-row","chest-supported-dumbbell-row","high-row-machine","seated-cable-row","single-arm-dumbbell-row","inverted-row"],"setup":{"en":"Stand on the foot platform (or the floor, braced against the foot bar) and lean your chest onto the inclined pad so you can reach the handles with straight arms. Load plates on the lever and log their total weight.","ru":"Встаньте на подставку (или на пол, упершись стопами в упор для ног) и лягте грудью на наклонный упор так, чтобы доставать до рукоятей прямыми руками. Навесьте диски на рычаг и записывайте их общий вес."},"cues":{"en":["Keep the chest and stomach on the pad; knees soft, feet planted.","Lift the lever off its rest, pull the shoulder blades back, then row the elbows toward your hips.","Use the neutral handles with the elbows about 45° from your sides.","Exhale as you pull and pause with the handles near the chest.","Lower over 2–3 s to straight arms."],"ru":["Грудь и живот на упоре, колени мягкие, стопы надёжно упираются.","Снимите рычаг с упоров, сведите лопатки и ведите локти к тазу.","Используйте параллельные рукояти, локти примерно под 45° к корпусу.","Выдох на тяге, пауза, когда рукояти у груди.","Опускайте 2–3 секунды до прямых рук."]},"mistakes":{"en":["Using a T-bar without a chest pad and a rounded back: that is a bent-over row with a high lower-back load.","Lifting the chest off the pad to heave the weight up.","Craning the head up to look forward.","Letting the plates crash onto the rests."],"ru":["Делать тягу Т-грифа без упора с круглой спиной: это уже тяга в наклоне с большой нагрузкой на поясницу.","Отрывать грудь от упора, чтобы рывком поднять вес.","Задирать голову, чтобы смотреть вперёд.","Ронять диски на упоры."]},"startLoad":{"kg":20,"source":"Strength Level T-bar row, 80 kg man: Beginner 1RM 38 kg; × 0.6 ≈ 23 kg, rounded down to 20 kg of plates because lever weight differs by model."},"tags":["owner-alt"],"images":[],"sources":["Plate-Loaded Iso-Lateral T-Bar Row — Hammer Strength (Life Fitness), 2026. https://www.lifefitness.com/en-us/catalog/strength-training/plate-loaded/iso-lateral-t-bar-row","Comparison of different rowing exercises: trunk muscle activation and lumbar spine motion, load, and stiffness — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181942019","T Bar Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/t-bar-row/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"chest-supported-dumbbell-row","equipment_id":"dumbbell","name":{"en":"Chest-supported dumbbell row","ru":"Тяга гантелей лёжа на наклонной скамье"},"pattern":"horizontal-pull","details":{"id":"chest-supported-dumbbell-row","name":{"en":"Chest-supported dumbbell row","ru":"Тяга гантелей лёжа на наклонной скамье"},"aka":["Incline dumbbell row","Prone incline row","Seal row (dumbbells)","Chest-supported row (dumbbells)"],"equipment":"dumbbell","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["delt-rear","teres-major","traps-lower","biceps","brachialis","forearm-flexors"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2,"repRange":[6,12],"alternatives":["single-arm-dumbbell-row","t-bar-row","machine-row","plate-loaded-row","seated-cable-row","inverted-row","high-row-machine"],"setup":{"en":"Set a bench to about 30–45°, lie face down with the top of your chest at the upper edge and your feet on the floor, and let a dumbbell hang in each hand with straight arms.","ru":"Установите скамью под углом 30–45°, лягте на неё лицом вниз так, чтобы верх груди был у края, стопы на полу; гантели висят в прямых руках."},"cues":{"en":["Keep the chest on the bench, chin tucked, neck neutral.","Pull the shoulder blades back, then row the dumbbells toward your lower ribs.","Elbows about 30–45° from your sides, palms facing each other.","Exhale on the pull and pause at the top.","Lower over 2–3 s until the arms are straight and the shoulder blades spread."],"ru":["Грудь на скамье, подбородок слегка втянут, шея нейтрально.","Сведите лопатки и тяните гантели к низу рёбер.","Локти под 30–45° к корпусу, ладони смотрят друг на друга.","Выдох на тяге, пауза вверху.","Опускайте 2–3 секунды до прямых рук и разведения лопаток."]},"mistakes":{"en":["Lifting the chest off the bench and arching the back to finish.","Shrugging the dumbbells up instead of rowing them back.","Craning the neck to look forward.","Swinging the dumbbells up with momentum."],"ru":["Отрывать грудь от скамьи и прогибаться, чтобы дотянуть.","Поднимать гантели плечами вверх вместо тяги назад.","Задирать голову, чтобы смотреть вперёд.","Забрасывать гантели вверх рывком."]},"startLoad":{"kg":8,"source":"Per dumbbell: Strength Level chest-supported dumbbell row, 80 kg man: Beginner 1RM 14 kg; × 0.6 ≈ 8 kg."},"tags":["owner-alt"],"images":[],"sources":["Chest Supported Dumbbell Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/chest-supported-dumbbell-row/kg","Comparison of different rowing exercises: trunk muscle activation and lumbar spine motion, load, and stiffness — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181942019","Electromyographic analysis of latissimus dorsi activation during common resistance training exercises: a narrative review — J Funct Morphol Kinesiol, 2026. https://doi.org/10.3390/jfmk11030315"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"high-row-machine","equipment_id":"plate-loaded","name":{"en":"High row machine","ru":"Тяга под углом сверху в рычажном тренажёре"},"pattern":"horizontal-pull","details":{"id":"high-row-machine","name":{"en":"High row machine","ru":"Тяга под углом сверху в рычажном тренажёре"},"aka":["Hammer Strength Iso-Lateral High Row","Hammer Strength MTS Iso-Lateral High Row","Plate-loaded high row","Iso-lateral high row"],"equipment":"plate-loaded","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["teres-major","traps-lower","delt-rear","biceps","brachialis"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["plate-loaded-row","machine-row","t-bar-row","chest-supported-dumbbell-row","seated-cable-row","single-arm-dumbbell-row","inverted-row"],"setup":{"en":"Set the seat so you reach the high handles with the arms fully straight and lock your thighs under the pad. Load equal plates on both arms and log the total plate weight.","ru":"Отрегулируйте сиденье так, чтобы доставать до верхних рукоятей полностью прямыми руками, и зафиксируйте бёдра валиком. Навесьте одинаковые диски на оба рычага и записывайте общий вес дисков."},"cues":{"en":["Sit tall with the chest up.","Draw the shoulder blades down and back, then drive the elbows down and back.","Finish with the hands near the shoulders and the elbows behind your torso.","Exhale on the pull; return over 2–3 s to a full stretch.","Keep both arms level; work one arm at a time (free hand on the thigh-pad handle) if a side lags."],"ru":["Сядьте ровно, грудь вперёд.","Опустите и сведите лопатки, затем ведите локти вниз и назад.","Заканчивайте, когда кисти у плеч, а локти позади корпуса.","Выдох на тяге; возвращайте 2–3 секунды до полного растяжения.","Держите рычаги на одной высоте; если одна сторона отстаёт, работайте по одной руке, держась свободной рукой за ручку у валика."]},"mistakes":{"en":["Pulling with the traps (shrugging) instead of driving the elbows.","Leaning back to use body weight.","Letting the levers yank the shoulders up at the top.","Unequal plates on the two arms."],"ru":["Тянуть трапециями (поднимая плечи) вместо движения локтями.","Отклоняться назад, помогая весом тела.","Позволять рычагам рывком тянуть плечи вверх.","Неравный вес дисков на рычагах."]},"startLoad":{"kg":20,"source":"Estimate: 10 kg of plates per side, the same ≈ 0.6–0.7 × cable-equivalent rule used for other lever pulls (research 04 §3.8); lever ratios vary, so log it per machine."},"tags":["owner-alt"],"images":[],"sources":["Plate Loaded Iso-Lateral High Row — Hammer Strength (Life Fitness), 2026. https://www.lifefitness.com/en-us/catalog/strength-training/plate-loaded/plate-loaded-iso-lateral-high-row","Electromyographic analysis of latissimus dorsi activation during common resistance training exercises: a narrative review — J Funct Morphol Kinesiol, 2026. https://doi.org/10.3390/jfmk11030315","Machine Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-row/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"seated-cable-row","equipment_id":"cable","name":{"en":"Seated cable row","ru":"Тяга нижнего блока сидя"},"pattern":"horizontal-pull","details":{"id":"seated-cable-row","name":{"en":"Seated cable row","ru":"Тяга нижнего блока сидя"},"aka":["Low cable row","Seated low-pulley row","Pulley row (Technogym Selection Pulley)","Pulldown/Seated Row (Precor Vitality)","V-handle row"],"equipment":"cable","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["delt-rear","teres-major","biceps","brachialis","erectors"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":5,"repRange":[6,12],"alternatives":["machine-row","plate-loaded-row","single-arm-cable-row","t-bar-row","chest-supported-dumbbell-row","high-row-machine","single-arm-dumbbell-row","inverted-row"],"setup":{"en":"Clip a close neutral (V) handle to the low pulley, sit with the feet on the platform and the knees slightly bent. Take the handle with straight arms and sit upright with a neutral lower back.","ru":"Пристегните к нижнему блоку узкую параллельную (V-образную) рукоять, сядьте, поставив стопы на платформу, колени слегка согнуты. Возьмите рукоять прямыми руками и сядьте прямо, поясница в нейтральном положении."},"cues":{"en":["Sit tall: chest up, lower back neutral; the torso stays upright for the whole set.","Start each rep by pulling the shoulder blades back, then drive the elbows back close to your sides.","Pull the handle to your upper abdomen, just under the ribs.","Pause for a moment with the elbows behind you and the shoulders down.","Exhale on the pull, inhale on the return.","Return over 2–3 s until the arms are straight and the shoulder blades glide forward; the torso does not follow.","Keep the knees soft: the legs only brace, they never push."],"ru":["Сидите ровно: грудь вперёд, поясница нейтрально; корпус вертикален весь подход.","Каждый повтор начинайте со сведения лопаток, затем ведите локти назад вдоль корпуса.","Тяните рукоять к верху живота, чуть ниже рёбер.","Коротко задержитесь: локти позади корпуса, плечи опущены.","Выдох на тяге, вдох на возврате.","Возвращайте 2–3 секунды до прямых рук: лопатки уходят вперёд, а корпус остаётся на месте.","Колени мягкие: ноги только упираются, но не толкают."]},"mistakes":{"en":["Rocking the torso back and forth to move the weight.","Rounding the lower back as the handle goes forward (lumbar flexion under load).","Leaning back past vertical to finish the rep.","Shrugging the shoulders toward the ears.","Yanking the handle from a dead stop and letting the stack crash.","Ego loading: a weight you cannot hold for a one-second pause."],"ru":["Раскачиваться корпусом вперёд-назад, чтобы сдвинуть вес.","Округлять поясницу, когда рукоять уходит вперёд (сгибание поясницы под нагрузкой).","Отклоняться назад за вертикаль, чтобы дотянуть повтор.","Поднимать плечи к ушам.","Дёргать рукоять с места и бросать стек.","Гнаться за весом: вес, с которым не получается секундная пауза в конце тяги."]},"startLoad":{"kg":30,"source":"Strength Level seated cable row, 80 kg man: Beginner 1RM 47 kg; first working load ≈ 0.6 × 47 ≈ 28 → 30 kg (research 04 §3.9)."},"tags":["owner-primary"],"images":[],"sources":["Variations in muscle activation levels during traditional latissimus dorsi weight training exercises — Dyn Med, 2004. https://doi.org/10.1186/1476-5918-3-4","High-density surface electromyography excitation of prime movers across scapular positions in the seated row — J Funct Morphol Kinesiol, 2025. https://doi.org/10.3390/jfmk11010006","ACE-sponsored research: what is the best back exercise? — American Council on Exercise, 2018. https://www.acefitness.org/continuing-education/certified/april-2018/6959/ace-sponsored-research-what-is-the-best-back-exercise/","Seated Cable Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/seated-cable-row/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"inverted-row","equipment_id":"bodyweight","name":{"en":"Inverted row","ru":"Горизонтальные подтягивания (австралийские)"},"pattern":"horizontal-pull","details":{"id":"inverted-row","name":{"en":"Inverted row","ru":"Горизонтальные подтягивания (австралийские)"},"aka":["Australian pull-up","Body row","Smith-machine inverted row","Supine row","Ring or suspension row"],"equipment":"bodyweight","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["delt-rear","traps-lower","biceps","brachialis","glute-max"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[6,12],"alternatives":["machine-row","chest-supported-dumbbell-row","plate-loaded-row","t-bar-row","seated-cable-row","single-arm-dumbbell-row","high-row-machine","single-arm-cable-row"],"setup":{"en":"Fix a bar in a Smith machine or a rack at about waist height, lie underneath it, grip it slightly wider than shoulder width and hang with straight arms, body straight from heels to head.","ru":"Закрепите гриф в машине Смита или в раме примерно на уровне пояса, лягте под него, возьмитесь чуть шире плеч и повисните на прямых руках; тело — прямая линия от пяток до головы."},"cues":{"en":["Squeeze the glutes and brace the abs: the body moves as one plank.","Pull your chest to the bar, elbows at about 45°.","Pause with the shoulder blades squeezed together.","Exhale on the way up; lower over 2–3 s to straight arms.","Make it harder by lowering the bar or walking the feet forward; easier by bending the knees or raising the bar."],"ru":["Напрягите ягодицы и пресс: тело движется как единая планка.","Тяните грудь к грифу, локти примерно под 45°.","Пауза со сведёнными лопатками.","Выдох на подъёме; опускайтесь 2–3 секунды до прямых рук.","Сложнее — опустите гриф или выдвиньте стопы вперёд; легче — согните колени или поднимите гриф."]},"mistakes":{"en":["Sagging hips or an arched lower back.","Reaching the chin to the bar instead of bringing the chest.","Half reps that never reach straight arms.","A bar that is not locked: a loose barbell can roll off the hooks."],"ru":["Провисать тазом или прогибаться в пояснице.","Тянуться к грифу подбородком вместо груди.","Неполные повторы без выпрямления рук внизу.","Незафиксированный гриф: свободная штанга может скатиться с крюков."]},"startLoad":{"kg":0,"source":"Bodyweight: Strength Level inverted row, 80 kg man: Novice about 9 reps; set the bar height so 6–12 reps are possible."},"tags":["owner-alt"],"images":[],"sources":["Comparison of different rowing exercises: trunk muscle activation and lumbar spine motion, load, and stiffness — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181942019","ACE-sponsored research: what is the best back exercise? — American Council on Exercise, 2018. https://www.acefitness.org/continuing-education/certified/april-2018/6959/ace-sponsored-research-what-is-the-best-back-exercise/","Inverted Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/inverted-row"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"single-arm-cable-row","equipment_id":"cable","name":{"en":"Single-arm cable row (standing)","ru":"Тяга блока одной рукой стоя"},"pattern":"horizontal-pull","details":{"id":"single-arm-cable-row","name":{"en":"Single-arm cable row (standing)","ru":"Тяга блока одной рукой стоя"},"aka":["One-arm standing cable row","Split-stance cable row","Single-arm low cable row","Anti-rotation row"],"equipment":"cable","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["obliques","transverse-abdominis","delt-rear","biceps","brachialis"],"difficulty":2,"unilateral":true,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2.5,"repRange":[8,12],"alternatives":["seated-cable-row","single-arm-dumbbell-row","plate-loaded-row","machine-row","chest-supported-dumbbell-row","inverted-row","pallof-press"],"setup":{"en":"Set a D-handle at about chest height or lower and stand facing the cable in a split stance, the leg opposite the working arm in front. Hold the handle with a straight arm, hips and shoulders square to the cable.","ru":"Установите D-рукоять примерно на уровне груди или ниже и встаньте лицом к блоку в разножку: впереди нога, противоположная рабочей руке. Держите рукоять прямой рукой, таз и плечи развёрнуты прямо к тросу."},"cues":{"en":["Brace the trunk: the hips and shoulders must not rotate toward the cable.","Pull the shoulder blade back, then row the elbow past your ribs.","Exhale on the pull and pause with the hand at the lower ribs.","Return over 2–3 s; let the shoulder blade reach forward without the torso twisting.","Start with the weaker side, then match the reps on the stronger side."],"ru":["Напрягите корпус: таз и плечи не должны разворачиваться к блоку.","Сведите лопатку, затем ведите локоть назад мимо рёбер.","Выдох на тяге, пауза, когда кисть у нижних рёбер.","Возвращайте 2–3 секунды: лопатка уходит вперёд, корпус не скручивается.","Начинайте со слабой стороны и повторите на сильной столько же."]},"mistakes":{"en":["Twisting the torso to pull with the body.","Leaning back or sideways to finish the rep.","Shrugging the working shoulder.","Choosing a load you cannot hold square for the whole set."],"ru":["Скручивать корпус, чтобы тянуть всем телом.","Отклоняться назад или вбок, чтобы дотянуть повтор.","Поднимать рабочее плечо к уху.","Брать вес, при котором не удаётся держать корпус ровно весь подход."]},"startLoad":{"kg":12.5,"source":"Per arm: about half of the 30 kg seated-row start (Strength Level seated cable row Beginner 1RM 47 kg × 0.6), rounded down for the standing anti-rotation demand."},"tags":["owner-alt","core"],"images":[],"sources":["Comparison of different rowing exercises: trunk muscle activation and lumbar spine motion, load, and stiffness — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181942019","Seated Cable Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/seated-cable-row/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"single-arm-dumbbell-row","equipment_id":"dumbbell","name":{"en":"Single-arm dumbbell row","ru":"Тяга гантели одной рукой с упором в скамью"},"pattern":"horizontal-pull","details":{"id":"single-arm-dumbbell-row","name":{"en":"Single-arm dumbbell row","ru":"Тяга гантели одной рукой с упором в скамью"},"aka":["One-arm dumbbell row","Bench-supported dumbbell row","Single-arm DB row"],"equipment":"dumbbell","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["delt-rear","teres-major","biceps","brachialis","forearm-flexors"],"difficulty":2,"unilateral":true,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2,"repRange":[6,12],"alternatives":["chest-supported-dumbbell-row","plate-loaded-row","machine-row","single-arm-cable-row","t-bar-row","seated-cable-row","inverted-row"],"setup":{"en":"Put one knee and the same-side hand on a flat bench and the other foot on the floor. Hold a dumbbell in the free hand with the arm hanging straight and the back flat, roughly parallel to the floor.","ru":"Поставьте колено и ладонь одной стороны на горизонтальную скамью, другую стопу — на пол. Гантель в свободной руке, рука висит прямо, спина ровная, примерно параллельна полу."},"cues":{"en":["Brace the trunk: spine neutral, shoulders level.","Pull the shoulder blade back, then row the dumbbell toward your hip.","Keep the elbow close to your side; finish with it just past your torso.","Exhale on the pull; lower over 2–3 s to a full stretch.","Don''t rotate the torso to lift: the chest keeps facing the bench."],"ru":["Напрягите корпус: позвоночник нейтрален, плечи на одном уровне.","Сведите лопатку, затем тяните гантель к тазу.","Локоть близко к корпусу; в конце он чуть за линией спины.","Выдох на тяге; опускайте 2–3 секунды до полного растяжения.","Не разворачивайте корпус, чтобы поднять гантель: грудь смотрит в скамью."]},"mistakes":{"en":["Rounding the back or letting it sag.","Twisting the torso to heave the dumbbell up.","Shrugging the dumbbell toward the ear.","Dropping the dumbbell at the bottom and jerking it up again."],"ru":["Округлять спину или давать ей провисать.","Скручивать корпус, чтобы закинуть гантель.","Тянуть гантель к уху, поднимая плечо.","Бросать гантель вниз и снова дёргать вверх."]},"startLoad":{"kg":12,"source":"Strength Level dumbbell row, 80 kg man: Beginner 1RM 19 kg; × 0.6 ≈ 11 → 12 kg."},"tags":["owner-alt"],"images":[],"sources":["Dumbbell Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-row/kg","Comparison of different rowing exercises: trunk muscle activation and lumbar spine motion, load, and stiffness — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181942019","Electromyographic analysis of latissimus dorsi activation during common resistance training exercises: a narrative review — J Funct Morphol Kinesiol, 2026. https://doi.org/10.3390/jfmk11030315"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"barbell-row","equipment_id":"barbell","name":{"en":"Bent-over barbell row","ru":"Тяга штанги в наклоне"},"pattern":"horizontal-pull","details":{"id":"barbell-row","name":{"en":"Bent-over barbell row","ru":"Тяга штанги в наклоне"},"aka":["Barbell row","Bent-over row","Pendlay row (strict variant)"],"equipment":"barbell","pattern":"horizontal-pull","class":"horizontal-pull","primary":["lats","traps-mid","rhomboids"],"secondary":["erectors","delt-rear","traps-lower","biceps","brachialis","hamstrings"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"high","lengthenedBias":false,"increment":2.5,"repRange":[4,8],"alternatives":["t-bar-row","plate-loaded-row","machine-row","chest-supported-dumbbell-row","single-arm-dumbbell-row","seated-cable-row","inverted-row"],"setup":{"en":"Stand with the feet hip-width, grip the bar overhand just outside the knees, then hinge at the hips until the torso is about 45° or lower with a flat back and slightly bent knees, the bar hanging at arm''s length.","ru":"Встаньте, стопы на ширине таза, возьмите гриф хватом сверху чуть шире коленей и наклонитесь, сгибаясь в тазобедренных суставах, до угла корпуса около 45° или ниже: спина ровная, колени слегка согнуты, гриф висит на прямых руках."},"cues":{"en":["Before each rep take a breath and brace the abs; keep the spine neutral.","Hold the torso angle still: only the arms and shoulder blades move.","Row the bar to the lower chest or upper abdomen, elbows about 45° from your sides.","Lower under control for about 2 s; breathe out once the bar is down.","Keep the bar close to the thighs and your weight over mid-foot.","Leave 1–3 reps in reserve and end the set as soon as the back starts to round."],"ru":["Перед каждым повтором вдохните и напрягите пресс; позвоночник нейтрален.","Угол наклона неизменен: двигаются только руки и лопатки.","Тяните гриф к низу груди или верху живота, локти под 45° к корпусу.","Опускайте подконтрольно около 2 секунд; выдох, когда гриф внизу.","Гриф близко к бёдрам, вес на середине стопы.","Оставляйте 1–3 повтора в запасе и заканчивайте подход, как только спина начинает округляться."]},"mistakes":{"en":["Rounding the lower back under the bar.","Heaving with the hips and torso, so the torso rises a little more with every rep.","Standing almost upright, which turns it into a shrug.","Ego loading on a lift with a high lower-back load: leave reps in reserve.","Jerking the bar up without bracing first."],"ru":["Округлять поясницу под штангой.","Читинг тазом и корпусом: с каждым повтором корпус поднимается всё выше.","Стоять почти вертикально — получается шраг.","Гнаться за весом в упражнении с высокой нагрузкой на поясницу: оставляйте запас.","Дёргать штангу, не напрягая корпус."]},"startLoad":{"kg":30,"source":"Strength Level bent-over row, 80 kg man: Beginner 1RM 48 kg; × 0.6 ≈ 29 → 30 kg including the 20 kg bar."},"tags":["owner-alt"],"images":[],"sources":["Comparison of different rowing exercises: trunk muscle activation and lumbar spine motion, load, and stiffness — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181942019","ACE-sponsored research: what is the best back exercise? — American Council on Exercise, 2018. https://www.acefitness.org/continuing-education/certified/april-2018/6959/ace-sponsored-research-what-is-the-best-back-exercise/","Bent Over Row Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/bent-over-row/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"lower-back-machine","equipment_id":"selectorized","name":{"en":"Lower back machine (lumbar extension)","ru":"Разгибание спины сидя в тренажёре"},"pattern":"spinal-extension","details":{"id":"lower-back-machine","name":{"en":"Lower back machine (lumbar extension)","ru":"Разгибание спины сидя в тренажёре"},"aka":["Lower Back (Technogym Selection / Element)","Back Extension (Life Fitness Insignia)","Back Extension (Cybex Eagle NX)","Low Back (Nautilus One)","MedX Lumbar Extension","Abdominal/Back Extension (Precor Vitality)"],"equipment":"selectorized","pattern":"spinal-extension","class":"spinal-extension","primary":["erectors"],"secondary":["quadratus-lumborum","glute-max","hamstrings"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":5,"repRange":[8,15],"alternatives":["back-extension-45","reverse-hyperextension","bird-dog"],"setup":{"en":"Sit with your hips back against the seat so the pelvis lines up with the machine''s pivot, put your feet on the footrest step that fits your leg length and tighten the thigh or hip restraint if there is one; the back pad sits across your shoulder blades. Set the start-position lever to a range you can move through without pain.","ru":"Сядьте, прижав таз к спинке сиденья, чтобы он был на одной линии с осью тренажёра; поставьте стопы на ту ступень подставки, что подходит по длине ног, и затяните фиксатор бёдер или таза, если он есть; спинка упирается в область лопаток. Рычагом стартовой позиции выставьте амплитуду, которую проходите без боли."},"cues":{"en":["Lock the pelvis: press the feet into the footrest and the thighs into the pads so the lower back, not the hips, does the work.","Cross your arms on your chest or hold the handles lightly; don''t pull with them.","Extend the trunk back smoothly until you are upright or just past it, no further.","Move slowly: about 2 s back and 3–4 s forward, with no bounce at either end.","Exhale as you push back, inhale as you return.","Keep the chin neutral; the head moves with the trunk.","Start light: for the first weeks stop 2–3 reps short of failure. Muscle effort is fine; sharp or leg-radiating pain means stop."],"ru":["Зафиксируйте таз: упритесь стопами в подставку, а бёдрами — в валики, чтобы работала поясница, а не тазобедренные суставы.","Скрестите руки на груди или слегка держитесь за рукояти, не тяните ими.","Плавно отводите корпус назад до вертикали или чуть дальше — не больше.","Медленно: около 2 секунд назад и 3–4 секунды вперёд, без пружинящих движений в крайних точках.","Выдох при отклонении назад, вдох при возврате.","Голова в нейтральном положении и движется вместе с корпусом.","Начинайте с малого веса: первые недели оставляйте 2–3 повтора в запасе. Мышечное усилие — нормально, острая или отдающая в ногу боль — стоп."]},"mistakes":{"en":["Throwing the trunk back with momentum and slamming into the end of the range.","Arching hard at the end: finish upright, not hyperextended.","A loose restraint or feet off the footrest, so the pelvis tilts and the hips do the work.","Pushing through sharp, burning or leg-radiating pain.","Ego loading: a stack you can only move with a jerk.","Throwing the head back or jutting the chin forward during the rep."],"ru":["Забрасывать корпус назад рывком и ударяться в крайнюю точку.","Сильно прогибаться в конце: заканчивайте в вертикали, а не в переразгибании.","Ослабленный фиксатор или стопы не на подставке: таз наклоняется, и работают тазобедренные суставы.","Терпеть острую, жгучую или отдающую в ногу боль.","Гнаться за весом: стек, который сдвигается только рывком.","Запрокидывать голову или тянуть подбородок вперёд во время повтора."]},"startLoad":{"kg":25,"source":"Strength Level machine back extension, 80 kg man: Beginner 1RM 45 kg; × 0.6 = 27 → 25 kg; lumbar work starts light and is progressed slowly."},"tags":["owner-primary","longevity"],"images":[],"sources":["A review of the clinical value of isolated lumbar extension resistance training for chronic low back pain — PM R, 2015. https://doi.org/10.1016/j.pmrj.2014.10.009","The effect of lumbar extension training with and without pelvic stabilization on lumbar strength and low back pain — J Back Musculoskelet Rehabil, 2011. https://doi.org/10.3233/BMR-2011-0301","Effect of training frequency and specificity on isometric lumbar extension strength — Spine, 1990. https://doi.org/10.1097/00007632-199006000-00014","Machine Back Extension Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-back-extension/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"back-extension-45","equipment_id":"bodyweight","name":{"en":"45° back extension","ru":"Гиперэкстензия 45°"},"pattern":"spinal-extension","details":{"id":"back-extension-45","name":{"en":"45° back extension","ru":"Гиперэкстензия 45°"},"aka":["45-degree hyperextension","Roman chair back extension","45° Back Hyperextension (Technogym Pure Strength)","Hyperextension bench","Back raise"],"equipment":"bodyweight","pattern":"spinal-extension","class":"spinal-extension","primary":["erectors","glute-max","hamstrings"],"secondary":["quadratus-lumborum"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":0,"repRange":[8,15],"alternatives":["lower-back-machine","reverse-hyperextension","cable-pull-through","bird-dog"],"setup":{"en":"Set the hip pad so its top edge sits just below the crease of your hips (the pelvis must be free to tilt), hook your heels under the ankle rollers and start with the body in a straight line.","ru":"Отрегулируйте упор так, чтобы его верхний край был чуть ниже паховой складки (таз должен свободно наклоняться), зацепите пятки за валики и начните из положения, где тело — прямая линия."},"cues":{"en":["Cross your arms on your chest; once 15 reps are easy, hold a plate there.","Hinge at the hips and lower the torso over 2–3 s with a neutral back.","Go down only as far as you can without the lower back rounding.","Squeeze the glutes and rise until the body is a straight line, not arched.","Exhale on the way up and keep the chin slightly tucked.","Turn the toes slightly in to bias the lower-back muscles (about 18% more activity than with the toes turned out)."],"ru":["Скрестите руки на груди; когда 15 повторов даются легко, держите у груди диск.","Наклоняйтесь в тазобедренных суставах и опускайте корпус 2–3 секунды, спина ровная.","Опускайтесь только до тех пор, пока поясница не начинает округляться.","Напрягите ягодицы и поднимайтесь до прямой линии тела, без прогиба.","Выдох на подъёме, подбородок слегка втянут.","Чуть разверните носки внутрь, чтобы сильнее нагрузить разгибатели спины (активность примерно на 18 % выше, чем с носками наружу)."]},"mistakes":{"en":["Hyperextending at the top, arching past a straight line.","Pad set too high, so the hips cannot bend and the lower back bends instead.","Bouncing out of the bottom or swinging up with momentum.","Rounding the lower back under load at the bottom.","Holding a plate behind the head, which strains the neck."],"ru":["Переразгибаться вверху, прогибаясь за прямую линию.","Слишком высоко выставленный упор: таз не сгибается, и вместо него гнётся поясница.","Пружинить из нижней точки или подниматься махом.","Округлять поясницу под нагрузкой внизу.","Держать диск за головой — это перегружает шею."]},"startLoad":{"kg":0,"source":"Bodyweight: Strength Level back extension, 80 kg man: Beginner 5 reps, Novice 15 reps; add a plate at the chest after 15."},"tags":["owner-alt","longevity"],"images":[],"sources":["Electromyographic activity of the trunk extensor muscles: effect of varying hip position and lumbar posture during Roman chair exercise — Arch Phys Med Rehabil, 2002. https://doi.org/10.1053/apmr.2002.35103","Back extension endurance and strength: the effect of variable-angle Roman chair exercise training — Spine, 2002. https://doi.org/10.1097/00007632-200208150-00016","Effect of Roman chair exercise training on the development of lumbar extension strength — J Strength Cond Res, 2003. https://pubmed.ncbi.nlm.nih.gov/12741878/","Back Extension Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/back-extension"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"reverse-hyperextension","equipment_id":"bodyweight","name":{"en":"Reverse hyperextension","ru":"Обратная гиперэкстензия"},"pattern":"hip-extension","details":{"id":"reverse-hyperextension","name":{"en":"Reverse hyperextension","ru":"Обратная гиперэкстензия"},"aka":["Reverse hyper","Hammer Strength Glute Ham / Reverse Hyper","Bench reverse hyperextension","Prone leg raise"],"equipment":"bodyweight","pattern":"hip-extension","class":"spinal-extension","primary":["erectors","glute-max","hamstrings"],"secondary":["quadratus-lumborum"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":0,"repRange":[10,15],"alternatives":["back-extension-45","lower-back-machine","machine-hip-thrust","glute-kickback-machine"],"setup":{"en":"Lie face down on a reverse-hyper machine, or with your hips at the edge of a high, stable bench or glute-ham developer, so the legs hang freely; hold the handles or the bench firmly.","ru":"Лягте на живот на тренажёр для обратной гиперэкстензии или так, чтобы таз был на краю высокой устойчивой скамьи либо станка для ягодично-бицепсового подъёма (GHD); ноги свободно свисают, крепко держитесь за рукояти или скамью."},"cues":{"en":["Brace the trunk on the pad; the upper body stays still.","Squeeze the glutes and lift straight legs until they are in line with your torso.","Pause for a moment at the top without arching any further.","Lower over 2–3 s; don''t let the legs or the pendulum swing.","Exhale on the lift; legs together or slightly apart."],"ru":["Корпус прижат к упору и неподвижен.","Напрягите ягодицы и поднимайте прямые ноги до линии корпуса.","Короткая пауза вверху без дополнительного прогиба.","Опускайте 2–3 секунды; не давайте ногам или маятнику раскачиваться.","Выдох на подъёме; ноги вместе или чуть врозь."]},"mistakes":{"en":["Swinging the legs, or a loaded pendulum, with momentum.","Kicking the legs above the torso line and cranking the lower back into extension.","Using a bench that is unstable or can tip.","Loading the machine before you can do 15 controlled reps without weight."],"ru":["Раскачивать ноги или нагруженный маятник по инерции.","Забрасывать ноги выше линии корпуса, переразгибая поясницу.","Использовать неустойчивую или опрокидывающуюся скамью.","Нагружать тренажёр, пока не получается 15 подконтрольных повторов без веса."]},"startLoad":{"kg":0,"source":"Bodyweight first: Strength Level reverse hyperextension, 80 kg man: Novice 14 reps; external load increases hip and trunk flexion (Lawrence 2022), so add it only after 15 controlled reps."},"tags":["owner-alt"],"images":[],"sources":["Biomechanical comparison of the reverse hyperextension machine and the hyperextension exercise — J Strength Cond Res, 2019. https://doi.org/10.1519/JSC.0000000000003146","Electromyographical differences between the hyperextension and reverse-hyperextension — J Strength Cond Res, 2021. https://doi.org/10.1519/JSC.0000000000004049","Effect of load on muscle activity, kinematics, and force production during the reverse hyperextension exercise — J Appl Biomech, 2022. https://doi.org/10.1123/jab.2022-0046","Reverse Hyperextension Standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/reverse-hyperextension"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"four-way-neck-machine","equipment_id":"plate-loaded","name":{"en":"4-way neck machine","ru":"Тренажёр для шеи на 4 направления"},"pattern":"neck","details":{"id":"four-way-neck-machine","name":{"en":"4-way neck machine","ru":"Тренажёр для шеи на 4 направления"},"aka":["Hammer Strength Plate Loaded 4-Way Neck","Nautilus One 4-Way Neck","Multi-neck machine","Neck machine"],"equipment":"plate-loaded","pattern":"neck","class":"neck","primary":["neck-extensors","neck-flexors"],"secondary":["traps-upper"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":1.25,"repRange":[10,20],"alternatives":["neck-extension","neck-flexion","neck-isometrics"],"setup":{"en":"Adjust the seat so the head pad sits on the forehead (flexion), the back of the head (extension) or just above the ear (side bending). Sit tall, hold the handles and start with the neck in neutral.","ru":"Отрегулируйте сиденье так, чтобы упор приходился на лоб (сгибание), затылок (разгибание) или чуть выше уха (наклоны в сторону). Сядьте ровно, возьмитесь за рукояти и начните с нейтрального положения шеи."},"cues":{"en":["Move only the head and neck; the torso stays fixed against the seat.","Go slowly: about 2 s out, a short pause, 3 s back to neutral.","Stay in a pain-free middle range; don''t push to the end of your neck''s range.","Breathe normally; never hold your breath.","Train all four directions; flexion usually needs clearly less load than extension, side bends a little less.","Stop 2–3 reps short of failure."],"ru":["Двигаются только голова и шея, корпус неподвижно прижат к сиденью.","Медленно: около 2 секунд в одну сторону, короткая пауза, 3 секунды обратно в нейтраль.","Работайте в безболезненной средней амплитуде, не доводите шею до крайних положений.","Дышите ровно, не задерживайте дыхание.","Тренируйте все четыре направления; для сгибания обычно нужен заметно меньший вес, чем для разгибания, для наклонов в стороны — немного меньший.","Останавливайтесь за 2–3 повтора до отказа."]},"mistakes":{"en":["Jerking the head or using momentum.","Loading the neck like a big muscle group, with heavy weight and grinding reps.","Pushing into the end of range or carrying on through pain, dizziness, tingling or numbness.","Moving the torso to help the neck."],"ru":["Двигать головой рывками, по инерции.","Нагружать шею как крупную мышечную группу — большим весом и дожиманием.","Уходить в крайние положения или продолжать при боли, головокружении, покалывании или онемении.","Помогать шее движением корпуса."]},"startLoad":{"kg":5,"source":"Conley 1997: untrained controls'' head-extension 3 × 10RM was about 10 kg; start at about half, and lighter for flexion."},"tags":["longevity"],"images":[],"sources":["Plate Loaded 4-Way Neck — Hammer Strength (Life Fitness), 2026. https://www.lifefitness.com/en-eu/catalog/strength-training/plate-loaded/4-way-neck","Specificity of resistance training responses in neck muscle size and strength — Eur J Appl Physiol, 1997. https://doi.org/10.1007/s004210050186","Effects of neck strength training on isometric neck strength in rugby union players — Clin J Sport Med, 2014. https://doi.org/10.1097/JSM.0000000000000071"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"neck-extension","equipment_id":"plate-loaded","name":{"en":"Prone neck extension (plate)","ru":"Разгибание шеи лёжа с диском"},"pattern":"neck","details":{"id":"neck-extension","name":{"en":"Prone neck extension (plate)","ru":"Разгибание шеи лёжа с диском"},"aka":["Plate neck extension","Lying neck extension","Head harness extension","Neck harness extension"],"equipment":"plate-loaded","pattern":"neck","class":"neck","primary":["neck-extensors"],"secondary":["traps-upper"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":1.25,"repRange":[10,20],"alternatives":["four-way-neck-machine","neck-isometrics","neck-flexion"],"setup":{"en":"Lie face down on a flat bench with the shoulders at the end and the head off the edge. Put a folded towel on the back of your head and hold a light plate on it with both hands, or use a head harness.","ru":"Лягте на живот на горизонтальную скамью так, чтобы плечи были у края, а голова — за краем. Положите на затылок сложенное полотенце и придерживайте на нём лёгкий диск обеими руками или используйте упряжь для головы."},"cues":{"en":["Start with the head in line with the spine.","Lower the chin toward the chest slowly, over about 3 s, in a comfortable range.","Lift the head back to neutral, eyes on the floor ahead of you, and no higher.","Keep the plate pinned so it cannot slide; breathe normally.","Stop 2–3 reps short of failure and progress in 1.25 kg steps."],"ru":["Начните с головы на одной линии с позвоночником.","Медленно, около 3 секунд, опускайте подбородок к груди в комфортной амплитуде.","Поднимайте голову до нейтрали — взгляд в пол перед собой, не выше.","Надёжно прижимайте диск, чтобы он не соскользнул; дышите ровно.","Останавливайтесь за 2–3 повтора до отказа и добавляйте по 1,25 кг."]},"mistakes":{"en":["Throwing the head back hard into full extension.","Going heavy too soon: the neck adapts more slowly than the big muscles.","Letting the plate slide or holding it with one hand.","Carrying on through pain, dizziness, tingling or numbness."],"ru":["Резко запрокидывать голову в полное разгибание.","Слишком рано брать тяжёлый диск: шея адаптируется медленнее крупных мышц.","Позволять диску соскальзывать или держать его одной рукой.","Продолжать при боли, головокружении, покалывании или онемении."]},"startLoad":{"kg":5,"source":"Conley 1997: untrained controls'' head-extension 3 × 10RM was about 10 kg (the training group rose from 17.9 to 23.9 kg in 12 weeks); start at about half."},"tags":["longevity"],"images":[],"sources":["Specificity of resistance training responses in neck muscle size and strength — Eur J Appl Physiol, 1997. https://doi.org/10.1007/s004210050186","Resistance training and human cervical muscle recruitment plasticity — J Appl Physiol, 1997. https://doi.org/10.1152/jappl.1997.83.6.2105","Active neck muscle training in the treatment of chronic neck pain in women: a randomized controlled trial — JAMA, 2003. https://doi.org/10.1001/jama.289.19.2509"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"neck-flexion","equipment_id":"plate-loaded","name":{"en":"Supine neck flexion (plate)","ru":"Сгибание шеи лёжа с диском"},"pattern":"neck","details":{"id":"neck-flexion","name":{"en":"Supine neck flexion (plate)","ru":"Сгибание шеи лёжа с диском"},"aka":["Plate neck curl","Lying neck curl","Supine neck curl","Neck flexion with plate"],"equipment":"plate-loaded","pattern":"neck","class":"neck","primary":["neck-flexors"],"secondary":[],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":1.25,"repRange":[10,20],"alternatives":["four-way-neck-machine","neck-isometrics","neck-extension"],"setup":{"en":"Lie on your back on a flat bench with the head off the end. Put a folded towel on your forehead and hold a light plate on it with both hands.","ru":"Лягте на спину на горизонтальную скамью, голова за краем. Положите на лоб сложенное полотенце и придерживайте на нём лёгкий диск обеими руками."},"cues":{"en":["Start with the head level with the bench, not hanging back.","Tuck the chin first, then curl the head toward the chest.","Lower over about 3 s back to neutral; don''t let the head drop into extension.","Breathe normally and keep the shoulders on the bench.","If the plate is too much, start with head weight only; add 1.25 kg at a time."],"ru":["Начните с головы на уровне скамьи, а не свисающей назад.","Сначала втяните подбородок, затем подкручивайте голову к груди.","Опускайте около 3 секунд обратно до нейтрали; не давайте голове проваливаться назад.","Дышите ровно, плечи остаются на скамье.","Если с диском тяжело, начните без него; добавляйте по 1,25 кг."]},"mistakes":{"en":["Jutting the chin forward instead of tucking it.","Letting the head drop back into extension at the bottom.","Jerking the head up.","Holding the breath and straining."],"ru":["Выдвигать подбородок вперёд вместо того, чтобы втягивать его.","Ронять голову назад в разгибание в нижней точке.","Поднимать голову рывком.","Задерживать дыхание и натуживаться."]},"startLoad":{"kg":2.5,"source":"Neck flexors are weaker than extensors (about 55% in Geary 2014); about a quarter of the ≈10 kg untrained head-extension 3 × 10RM (Conley 1997) → 2.5 kg, or head weight only for the first session."},"tags":["longevity"],"images":[],"sources":["Active neck muscle training in the treatment of chronic neck pain in women: a randomized controlled trial — JAMA, 2003. https://doi.org/10.1001/jama.289.19.2509","Effects of neck strength training on isometric neck strength in rugby union players — Clin J Sport Med, 2014. https://doi.org/10.1097/JSM.0000000000000071","Specificity of resistance training responses in neck muscle size and strength — Eur J Appl Physiol, 1997. https://doi.org/10.1007/s004210050186"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"neck-isometrics","equipment_id":"bodyweight","name":{"en":"Neck isometrics (4-way)","ru":"Изометрия для шеи в 4 направлениях"},"pattern":"neck","details":{"id":"neck-isometrics","name":{"en":"Neck isometrics (4-way)","ru":"Изометрия для шеи в 4 направлениях"},"aka":["Manual neck isometrics","Hand-resisted neck holds","4-way neck isometric holds","Self-resisted neck isometrics"],"equipment":"bodyweight","pattern":"neck","class":"neck","primary":["neck-extensors","neck-flexors"],"secondary":["traps-upper"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[10,20],"repUnit":"seconds","alternatives":["four-way-neck-machine","neck-extension","neck-flexion"],"setup":{"en":"Sit or stand tall with the head in neutral. Press a palm, or both hands, against your forehead, the back of your head or the side of your head and resist with the neck so the head does not move.","ru":"Сядьте или встаньте прямо, голова в нейтральном положении. Давите ладонью или обеими руками на лоб, затылок или висок и сопротивляйтесь шеей так, чтобы голова не двигалась."},"cues":{"en":["Build the pressure up over 2–3 s; never start with a jolt.","Work at moderate effort, about 50–70%, holding 10–20 s per direction.","Cover all four directions: front, back, left and right.","Keep breathing during the hold.","Keep the chin slightly tucked and the head level."],"ru":["Наращивайте давление 2–3 секунды и никогда не начинайте рывком.","Усилие умеренное, около 50–70 %, удержание 10–20 секунд в каждом направлении.","Выполняйте все четыре направления: вперёд, назад, влево и вправо.","Продолжайте дышать во время удержания.","Подбородок слегка втянут, голова ровно."]},"mistakes":{"en":["Pushing suddenly or at maximal effort.","Holding the breath.","Letting the head tilt or turn under the pressure.","Carrying on through pain, dizziness or tingling."],"ru":["Давить резко или с максимальным усилием.","Задерживать дыхание.","Позволять голове наклоняться или поворачиваться под давлением.","Продолжать при боли, головокружении или покалывании."]},"tags":["longevity"],"images":[],"sources":["Active neck muscle training in the treatment of chronic neck pain in women: a randomized controlled trial — JAMA, 2003. https://doi.org/10.1001/jama.289.19.2509","Effects of neck muscle training in women with chronic neck pain: one-year follow-up study — J Strength Cond Res, 2006. https://doi.org/10.1519/R-17274.1","Effects of neck strength training on isometric neck strength in rugby union players — Clin J Sport Med, 2014. https://doi.org/10.1097/JSM.0000000000000071"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-preacher-curl","equipment_id":"selectorized","name":{"en":"Machine preacher curl","ru":"Сгибания рук в тренажёре Скотта"},"pattern":"elbow-flexion","details":{"id":"machine-preacher-curl","class":"biceps-curl","pattern":"elbow-flexion","name":{"en":"Machine preacher curl","ru":"Сгибания рук в тренажёре Скотта"},"aka":["Preacher curl machine","Biceps curl machine","Arm Curl (Technogym Selection, Cybex Eagle NX)","Biceps Curl (Life Fitness Insignia, Nautilus Inspiration, Precor Vitality)","Seated Biceps (Hammer Strength, plate-loaded)"],"equipment":"selectorized","primary":["biceps"],"secondary":["brachialis","brachioradialis"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["cable-curl","bayesian-cable-curl","incline-dumbbell-curl","dumbbell-curl","ez-bar-preacher-curl","barbell-curl","hammer-curl","reverse-curl"],"setup":{"en":"Set the seat so your armpits sit snugly over the top of the arm pad and your elbows line up with the machine''s pivot; take the handles palms up with your arms almost straight.","ru":"Отрегулируйте сиденье так, чтобы подмышки плотно лежали на верхнем краю подушки для рук, а локти совпадали с осью вращения тренажёра; возьмитесь за рукояти хватом снизу, руки почти прямые."},"cues":{"en":["Line your elbows up with the machine''s pivot and keep the backs of your upper arms flat on the pad.","Chest against the pad, shoulders down and away from your ears.","Keep your wrists straight, the handle deep in your palm.","Curl up in 1–2 s and squeeze for a moment at the top without lifting your elbows.","Lower in 2–3 s until your arms are almost straight: the stretched bottom half matters most, so don''t cut it short.","Breathe out as you curl, in as you lower."],"ru":["Совместите локти с осью вращения тренажёра; руки выше локтя всё время плотно лежат на подушке.","Грудь прижата к упору, плечи опущены, подальше от ушей.","Запястья прямые, рукоять лежит глубоко в ладони.","Сгибайте руки за 1–2 секунды и на мгновение задержитесь вверху, не отрывая локтей.","Опускайте за 2–3 секунды почти до прямых рук: нижняя, растянутая половина амплитуды важнее всего, не сокращайте её.","Выдох — на подъёме, вдох — на опускании."]},"mistakes":{"en":["Letting the weight drop into a straight, locked elbow: a sudden load that forces the elbow straight is the typical way the biceps tendon tears at the elbow.","Lifting the elbows off the pad or shrugging to finish the rep.","Leaning back or rocking the torso to swing the weight up.","Seat at the wrong height, so the elbow and the pivot don''t line up and the elbow is strained.","Ego loading: a stack so heavy that you only manage half reps."],"ru":["Бросать вес вниз до прямого «запертого» локтя: резкая нагрузка, выпрямляющая согнутый локоть, — типичный механизм отрыва сухожилия бицепса.","Отрывать локти от подушки или дотягивать повтор, поднимая плечи.","Отклоняться назад и раскачивать корпус, чтобы закинуть вес.","Неправильная высота сиденья: локоть не совпадает с осью, и сустав перегружается.","Погоня за весом: такой груз, что получаются только полуповторы."]},"startLoad":{"kg":15,"source":"≈0.6 × Strength Level Beginner 1RM (25 kg at 80 kg body weight)"},"tags":["owner-primary"],"images":[],"sources":["Machine Bicep Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-bicep-curl/kg","Pedrosa et al. Training in the initial range of motion promotes greater muscle adaptations than at final in the arm curl — Sports (Basel), 2023. https://www.mdpi.com/2075-4663/11/2/39","Biceps tendon tear at the elbow — OrthoInfo (AAOS), accessed 2026. https://www.orthoinfo.org/en/diseases--conditions/biceps-tendon-tear-at-the-elbow/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"incline-dumbbell-curl","equipment_id":"dumbbell","name":{"en":"Incline dumbbell curl","ru":"Сгибания рук с гантелями сидя на наклонной скамье"},"pattern":"elbow-flexion","details":{"id":"incline-dumbbell-curl","class":"biceps-curl","pattern":"elbow-flexion","name":{"en":"Incline dumbbell curl","ru":"Сгибания рук с гантелями сидя на наклонной скамье"},"aka":["Incline curl","Seated incline dumbbell curl","Incline bench biceps curl"],"equipment":"dumbbell","primary":["biceps"],"secondary":["brachialis","brachioradialis"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":2,"repRange":[8,15],"alternatives":["dumbbell-curl","machine-preacher-curl","bayesian-cable-curl","cable-curl","ez-bar-preacher-curl","barbell-curl","hammer-curl"],"setup":{"en":"Set an adjustable bench to about 45–60°, sit back with your head and shoulder blades on the pad, and let the dumbbells hang straight down from your shoulders, palms facing forward.","ru":"Установите регулируемую скамью под углом 45–60°, сядьте, прижав голову и лопатки к спинке, и опустите гантели прямо вниз от плеч, ладони вперёд."},"cues":{"en":["Head and shoulder blades stay on the pad; your upper arms hang straight down.","Curl without letting the elbows drift forward: the upper arm stays vertical.","Palms face up the whole way; squeeze briefly at the top.","Lower in about 3 s to a fully straight arm and feel the stretch at the front of the arm.","Breathe out as you curl, in as you lower.","If the front of your shoulder aches, raise the backrest a notch closer to upright."],"ru":["Голова и лопатки остаются на спинке, руки свободно висят вертикально вниз.","Сгибайте руки, не выводя локти вперёд: рука выше локтя остаётся вертикальной.","Ладони всё время смотрят вверх; вверху коротко напрягите бицепс.","Опускайте примерно 3 секунды до полностью прямой руки и почувствуйте растяжение передней поверхности руки.","Выдох — на подъёме, вдох — на опускании.","Если ноет передняя часть плеча, поднимите спинку на одно деление ближе к вертикали."]},"mistakes":{"en":["Swinging the elbows forward, which turns the curl into a front raise.","Lifting your head and shoulders off the pad to heave the weight up.","Setting the bench too low (flatter than about 45°) or going too heavy, which strains the front of the shoulder.","Dropping into the bottom and bouncing out of the stretch."],"ru":["Выводить локти вперёд — сгибание превращается в подъём перед собой.","Отрывать голову и плечи от спинки, чтобы закинуть вес.","Слишком низкая спинка (положе 45°) или слишком тяжёлые гантели — перегрузка передней части плеча.","Падать вниз и «отбивать» вес из растянутого положения."]},"startLoad":{"kg":6,"source":"Per dumbbell: ≈0.6 × Strength Level Beginner 1RM (10 kg at 80 kg body weight)"},"tags":["owner-alt"],"images":[],"sources":["Incline Dumbbell Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/incline-dumbbell-curl/kg","Zabaleta-Korta et al. Regional hypertrophy: exercises at long and short muscle lengths (incline vs preacher curl) — J Hum Kinet, 2023. https://pmc.ncbi.nlm.nih.gov/articles/PMC10407320/","Attarieh et al. Shoulder flexed vs extended elbow flexion training: preacher versus Bayesian cable curls — Eur J Sport Sci, 2025. https://doi.org/10.1002/ejsc.12279"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"bayesian-cable-curl","equipment_id":"cable","name":{"en":"Bayesian cable curl","ru":"Байесовское сгибание руки на блоке (спиной к тренажёру)"},"pattern":"elbow-flexion","details":{"id":"bayesian-cable-curl","class":"biceps-curl","pattern":"elbow-flexion","name":{"en":"Bayesian cable curl","ru":"Байесовское сгибание руки на блоке (спиной к тренажёру)"},"aka":["Bayesian curl","Behind-the-body cable curl","Face-away cable curl","Single-arm low-pulley curl, facing away"],"equipment":"cable","primary":["biceps"],"secondary":["brachialis","brachioradialis"],"difficulty":2,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[8,15],"alternatives":["cable-curl","machine-preacher-curl","incline-dumbbell-curl","dumbbell-curl","ez-bar-preacher-curl","barbell-curl","hammer-curl"],"setup":{"en":"Set a single pulley low (about knee height) with a D-handle, face away from it, take the handle palm forward and step into a staggered stance until the cable draws your arm slightly behind your body.","ru":"Установите блок низко (примерно на уровне колена) с одиночной рукоятью, встаньте спиной к тренажёру, возьмите рукоять ладонью вперёд и шагните в разножку, пока трос не отведёт руку немного за корпус."},"cues":{"en":["Staggered stance, abs braced, chest up: your torso does not move.","Let the cable draw the arm back until you feel a stretch at the front of the arm and shoulder.","Curl by bending only the elbow; the upper arm stays behind your body.","Squeeze for a moment at the top, palm facing up.","Lower in 2–3 s back into the stretch; don''t let the cable yank your arm back.","Finish all reps with one arm, then switch; start with your weaker arm."],"ru":["Стойка в разножку, пресс напряжён, грудь раскрыта — корпус неподвижен.","Позвольте тросу отвести руку назад до ощущения растяжения в передней части руки и плеча.","Сгибайте только в локте: рука выше локтя всё время остаётся позади корпуса.","Вверху на мгновение задержитесь, ладонь смотрит вверх.","Опускайте за 2–3 секунды обратно в растяжение — не давайте тросу рвать руку назад.","Сделайте все повторы одной рукой, потом смените руку; начинайте с более слабой."]},"mistakes":{"en":["Letting the cable snap the arm back at the bottom: a sudden stretch under load strains the front of the shoulder and the biceps tendon.","Swinging the elbow forward, which turns it into a front raise and removes the stretch.","Twisting or leaning the torso to finish the rep.","Standing too close to the pulley, so the cable hangs straight down and there is no stretch at the bottom.","Shrugging the working shoulder up toward your ear."],"ru":["Позволять тросу резко дёргать руку назад внизу: внезапное растяжение под нагрузкой перегружает переднюю часть плеча и сухожилие бицепса.","Выводить локоть вперёд — упражнение превращается в подъём перед собой, и растяжение пропадает.","Скручивать или наклонять корпус, чтобы дожать повтор.","Стоять слишком близко к блоку: трос висит вертикально, и внизу нет растяжения.","Поднимать рабочее плечо к уху."]},"startLoad":{"kg":5,"source":"Per arm: about half the two-arm cable-curl start (12.5 kg), rounded down; preacher and behind-the-body cable curls have similar 1RMs (Attarieh 2025)"},"tags":["owner-alt"],"images":[],"sources":["Attarieh et al. Shoulder flexed vs extended elbow flexion training: preacher versus Bayesian cable curls — Eur J Sport Sci, 2025. https://doi.org/10.1002/ejsc.12279","Cable Bicep Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-bicep-curl/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"ez-bar-preacher-curl","equipment_id":"barbell","name":{"en":"EZ-bar preacher curl","ru":"Сгибания рук с EZ-грифом на скамье Скотта"},"pattern":"elbow-flexion","details":{"id":"ez-bar-preacher-curl","class":"biceps-curl","pattern":"elbow-flexion","name":{"en":"EZ-bar preacher curl","ru":"Сгибания рук с EZ-грифом на скамье Скотта"},"aka":["Preacher curl","Scott curl","Scott bench curl","EZ-bar Scott curl"],"equipment":"barbell","primary":["biceps"],"secondary":["brachialis","brachioradialis"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[8,15],"alternatives":["barbell-curl","machine-preacher-curl","bayesian-cable-curl","cable-curl","incline-dumbbell-curl","dumbbell-curl","reverse-curl","hammer-curl"],"setup":{"en":"Set the seat so your armpits rest snugly over the top of the pad with the backs of your upper arms flat on it, and take an EZ bar on the angled grips, palms up, about shoulder-width apart.","ru":"Отрегулируйте сиденье так, чтобы подмышки плотно лежали на верхнем краю подушки, а руки выше локтя — на самой подушке; возьмите EZ-гриф за изгибы хватом снизу примерно на ширине плеч."},"cues":{"en":["Armpits snug over the pad, upper arms flat on it for the whole set.","Hold the angled part of the bar so your wrists stay straight and relaxed.","Curl until your forearms are just short of vertical: above that the tension fades.","Lower in 2–3 s until your elbows are almost straight; the bottom half matters most.","Pause for a moment near the bottom, then curl without bouncing.","Breathe out as you curl, in as you lower."],"ru":["Подмышки плотно на краю подушки, руки выше локтя лежат на ней весь подход.","Держите гриф за изогнутые участки, чтобы запястья оставались прямыми и расслабленными.","Сгибайте, пока предплечья почти не станут вертикальными: выше нагрузка с бицепса уходит.","Опускайте за 2–3 секунды почти до прямых локтей: нижняя половина амплитуды важнее всего.","Внизу задержитесь на мгновение и поднимайте без отбива.","Выдох — на подъёме, вдох — на опускании."]},"mistakes":{"en":["Letting the bar drop into a locked, straight elbow: a sudden load that forces the elbow straight is the classic way the distal biceps tendon tears.","Lifting your elbows or hips off the pad to heave the bar up.","Bending the wrists back or curling them in to move the weight.","Seat set too low, so your armpits sit below the top of the pad and your shoulders roll forward.","Ego loading: a bar so heavy that you can''t control the bottom half."],"ru":["Ронять гриф до «запертого» прямого локтя: резкая нагрузка, выпрямляющая локоть, — классический механизм отрыва сухожилия бицепса.","Отрывать локти или таз от подушки, чтобы закинуть гриф.","Отгибать или подкручивать запястья, помогая поднять вес.","Слишком низкое сиденье: подмышки ниже края подушки, плечи заваливаются вперёд.","Погоня за весом: гриф так тяжёл, что нижнюю половину не удаётся контролировать."]},"startLoad":{"kg":12.5,"source":"Bar included: ≈0.6 × Strength Level Beginner 1RM (20 kg at 80 kg body weight)"},"tags":["owner-alt"],"images":[],"sources":["Preacher Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/preacher-curl/kg","Pedrosa et al. Training in the initial range of motion promotes greater muscle adaptations than at final in the arm curl — Sports (Basel), 2023. https://www.mdpi.com/2075-4663/11/2/39","Biceps tendon tear at the elbow — OrthoInfo (AAOS), accessed 2026. https://www.orthoinfo.org/en/diseases--conditions/biceps-tendon-tear-at-the-elbow/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"cable-curl","equipment_id":"cable","name":{"en":"Cable curl","ru":"Сгибания рук на нижнем блоке стоя"},"pattern":"elbow-flexion","details":{"id":"cable-curl","class":"biceps-curl","pattern":"elbow-flexion","name":{"en":"Cable curl","ru":"Сгибания рук на нижнем блоке стоя"},"aka":["Standing cable curl","Low-pulley curl","Cable biceps curl","Straight-bar or EZ-bar cable curl"],"equipment":"cable","primary":["biceps"],"secondary":["brachialis","brachioradialis"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["bayesian-cable-curl","machine-preacher-curl","incline-dumbbell-curl","dumbbell-curl","ez-bar-preacher-curl","barbell-curl","hammer-curl","reverse-curl"],"setup":{"en":"Attach a straight or EZ bar to the low pulley, stand tall close to the stack with feet hip-width, and hold the bar palms up with your elbows at your sides.","ru":"Прикрепите прямую или EZ-рукоять к нижнему блоку, встаньте прямо вплотную к тренажёру, стопы на ширине таза, возьмите рукоять хватом снизу, локти у корпуса."},"cues":{"en":["Stand tall, abs braced, knees soft.","Pin your elbows to your sides; only the forearms move.","Curl the bar to upper-chest height in 1–2 s without bringing the elbows forward.","Lower in 2–3 s to straight arms, keeping tension on the cable.","Wrists straight, the bar deep in your palms.","Breathe out as you curl, in as you lower."],"ru":["Стойте прямо, пресс напряжён, колени чуть согнуты.","Прижмите локти к бокам: двигаются только предплечья.","Сгибайте до уровня верха груди за 1–2 секунды, не выводя локти вперёд.","Опускайте за 2–3 секунды до прямых рук, сохраняя натяжение троса.","Запястья прямые, рукоять лежит глубоко в ладонях.","Выдох — на подъёме, вдох — на опускании."]},"mistakes":{"en":["Leaning back and rocking the hips to swing the weight up, which shifts the load onto your lower back.","Elbows drifting forward and up, turning it into a front raise.","Shrugging your shoulders toward your ears.","Letting the stack crash down between reps."],"ru":["Отклоняться назад и раскачивать таз, чтобы закинуть вес, — нагрузка уходит на поясницу.","Выводить локти вперёд и вверх — получается подъём перед собой.","Поднимать плечи к ушам.","Бросать вес между повторами так, что плиты бьются друг о друга."]},"startLoad":{"kg":12.5,"source":"≈0.6 × Strength Level Beginner 1RM (20 kg at 80 kg body weight)"},"tags":["owner-alt"],"images":[],"sources":["Cable Bicep Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-bicep-curl/kg","Pedrosa et al. Training in the initial range of motion promotes greater muscle adaptations than at final in the arm curl — Sports (Basel), 2023. https://www.mdpi.com/2075-4663/11/2/39"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dumbbell-curl","equipment_id":"dumbbell","name":{"en":"Dumbbell curl","ru":"Сгибания рук с гантелями стоя"},"pattern":"elbow-flexion","details":{"id":"dumbbell-curl","class":"biceps-curl","pattern":"elbow-flexion","name":{"en":"Dumbbell curl","ru":"Сгибания рук с гантелями стоя"},"aka":["Standing dumbbell curl","Dumbbell biceps curl","Alternating dumbbell curl","Supinating dumbbell curl"],"equipment":"dumbbell","primary":["biceps"],"secondary":["brachialis","brachioradialis"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":2,"repRange":[8,15],"alternatives":["incline-dumbbell-curl","machine-preacher-curl","cable-curl","bayesian-cable-curl","ez-bar-preacher-curl","barbell-curl","hammer-curl","reverse-curl"],"setup":{"en":"Stand tall with feet hip-width, a dumbbell in each hand, arms straight at your sides and palms facing forward.","ru":"Встаньте прямо, стопы на ширине таза, в каждой руке гантель, руки прямые вдоль корпуса, ладони смотрят вперёд."},"cues":{"en":["Stand tall, abs braced, knees soft; your torso stays still.","Elbows stay by your sides; bend only at the elbow.","Keep your palms facing up as you curl; squeeze briefly at the top.","Lower in 2–3 s all the way to straight arms.","Curl both arms together, or alternate and finish each rep before the other arm starts.","Breathe out as you curl, in as you lower."],"ru":["Стойте прямо, пресс напряжён, колени чуть согнуты — корпус неподвижен.","Локти остаются у боков, сгибайте руку только в локте.","Ладони смотрят вверх по ходу движения; вверху коротко напрягите бицепс.","Опускайте за 2–3 секунды до полностью прямых рук.","Сгибайте обе руки вместе или поочерёдно, заканчивая повтор одной рукой до начала другой.","Выдох — на подъёме, вдох — на опускании."]},"mistakes":{"en":["Swinging the dumbbells up with your hips and lower back.","Letting the elbows travel forward so the shoulders do the lifting.","Bending the wrists to curl the dumbbell.","Cutting reps short at the bottom because the weight is too heavy."],"ru":["Закидывать гантели рывком тазом и поясницей.","Выводить локти вперёд, так что работают плечи.","Сгибать запястья, подтягивая гантель кистью.","Не опускать руки до конца, потому что вес слишком тяжёлый."]},"startLoad":{"kg":5,"source":"Per dumbbell: ≈0.6 × Strength Level Beginner 1RM (8 kg at 80 kg body weight)"},"tags":["owner-alt"],"images":[],"sources":["Dumbbell Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-curl/kg","Pedrosa et al. Training in the initial range of motion promotes greater muscle adaptations than at final in the arm curl — Sports (Basel), 2023. https://www.mdpi.com/2075-4663/11/2/39"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"barbell-curl","equipment_id":"barbell","name":{"en":"Barbell curl","ru":"Подъём штанги на бицепс стоя"},"pattern":"elbow-flexion","details":{"id":"barbell-curl","class":"biceps-curl","pattern":"elbow-flexion","name":{"en":"Barbell curl","ru":"Подъём штанги на бицепс стоя"},"aka":["Standing barbell curl","Straight-bar curl","EZ-bar curl","Barbell biceps curl"],"equipment":"barbell","primary":["biceps"],"secondary":["brachialis","brachioradialis"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["ez-bar-preacher-curl","machine-preacher-curl","cable-curl","bayesian-cable-curl","incline-dumbbell-curl","dumbbell-curl","reverse-curl","hammer-curl"],"setup":{"en":"Stand tall with feet hip-width and hold a straight bar (or an EZ bar if your wrists complain) palms up at about shoulder width, arms straight and elbows at your sides.","ru":"Встаньте прямо, стопы на ширине таза; возьмите прямой гриф (или EZ-гриф, если беспокоят запястья) хватом снизу на ширине плеч, руки прямые, локти у корпуса."},"cues":{"en":["Brace your abs and squeeze your glutes so your lower back stays still.","Elbows stay at your sides; curl the bar in an arc to upper-chest height.","Wrists straight, the bar in the heels of your palms.","Lower in 2–3 s to straight arms without bouncing.","Breathe out as you curl, in as you lower."],"ru":["Напрягите пресс и ягодицы, чтобы поясница оставалась неподвижной.","Локти у боков; поднимайте гриф по дуге до уровня верха груди.","Запястья прямые, гриф лежит в основании ладоней.","Опускайте за 2–3 секунды до прямых рук, без отбива.","Выдох — на подъёме, вдох — на опускании."]},"mistakes":{"en":["Leaning back and swinging the bar up with your lower back: the classic back-straining cheat.","Elbows drifting forward so the front delts take over.","Loading more than you can curl without body English.","Forcing a straight bar when your wrists or elbows ache: switch to an EZ bar."],"ru":["Отклоняться назад и закидывать гриф поясницей — классический читинг, перегружающий спину.","Выводить локти вперёд, перекладывая работу на передние дельты.","Брать вес, который не поднять без раскачки.","Упрямо работать с прямым грифом при боли в запястьях или локтях — возьмите EZ-гриф."]},"startLoad":{"kg":12.5,"source":"Bar included: ≈0.6 × Strength Level Beginner 1RM (22 kg at 80 kg body weight); use a fixed or EZ bar, since an Olympic bar alone is 20 kg"},"tags":["owner-alt"],"images":[],"sources":["Barbell Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/barbell-curl/kg","Pedrosa et al. Training in the initial range of motion promotes greater muscle adaptations than at final in the arm curl — Sports (Basel), 2023. https://www.mdpi.com/2075-4663/11/2/39"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"hammer-curl","equipment_id":"dumbbell","name":{"en":"Hammer curl","ru":"Сгибания рук с гантелями хватом «молот»"},"pattern":"elbow-flexion","details":{"id":"hammer-curl","class":"brachialis-curl","pattern":"elbow-flexion","name":{"en":"Hammer curl","ru":"Сгибания рук с гантелями хватом «молот»"},"aka":["Dumbbell hammer curl","Neutral-grip curl","Hammer curls","Rope hammer curl (cable version)"],"equipment":"dumbbell","primary":["brachialis","brachioradialis"],"secondary":["biceps"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":2,"repRange":[8,15],"alternatives":["reverse-curl","dumbbell-curl","machine-preacher-curl","cable-curl","ez-bar-preacher-curl","barbell-curl"],"setup":{"en":"Stand tall (or sit upright on a bench with back support) with a dumbbell in each hand at your sides, palms facing your thighs and thumbs forward.","ru":"Встаньте прямо (или сядьте на скамью с вертикальной спинкой), гантели в опущенных руках, ладони смотрят на бёдра, большие пальцы — вперёд."},"cues":{"en":["Palms face each other, thumbs up, for the whole rep, like holding a hammer.","Stand tall, abs braced, knees soft; your torso doesn''t move.","Elbows stay pinned to your sides; only the forearms move.","Curl in 1–2 s until your thumb is close to your shoulder, then squeeze briefly.","Lower in 2–3 s all the way to a straight arm.","Breathe out as you curl, in as you lower."],"ru":["Ладони смотрят друг на друга, большие пальцы вверх весь повтор — как будто держите молоток.","Стойте прямо, пресс напряжён, колени чуть согнуты — корпус не двигается.","Локти прижаты к бокам, двигаются только предплечья.","Сгибайте за 1–2 секунды, пока большой палец не окажется у плеча, и коротко задержитесь.","Опускайте за 2–3 секунды до полностью прямой руки.","Выдох — на подъёме, вдох — на опускании."]},"mistakes":{"en":["Swinging the dumbbells up with your hips and lower back.","Elbows drifting forward so the front delts do the lifting.","Turning the palms up mid-rep, which turns it into a regular curl.","Cocking the wrists to flick the dumbbell up.","Going so heavy that you only cover half the range."],"ru":["Раскачивать гантели тазом и поясницей.","Выводить локти вперёд, так что поднимают передние дельты.","Разворачивать ладони вверх по ходу повтора — получается обычное сгибание.","Подбрасывать гантель движением кисти.","Брать такой вес, что проходится только половина амплитуды."]},"startLoad":{"kg":6,"source":"Per dumbbell: ≈0.6 × Strength Level Beginner 1RM (11 kg at 80 kg body weight), rounded down"},"tags":["owner-primary"],"images":[],"sources":["Hammer Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/hammer-curl/kg","Kleiber et al. Muscular coordination of biceps brachii and brachioradialis in elbow flexion with respect to hand position — Front Physiol, 2015. https://doi.org/10.3389/fphys.2015.00215","Pedrosa et al. Training in the initial range of motion promotes greater muscle adaptations than at final in the arm curl — Sports (Basel), 2023. https://www.mdpi.com/2075-4663/11/2/39"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"reverse-curl","equipment_id":"barbell","name":{"en":"Reverse-grip curl","ru":"Сгибания рук со штангой обратным хватом"},"pattern":"elbow-flexion","details":{"id":"reverse-curl","class":"brachialis-curl","pattern":"elbow-flexion","name":{"en":"Reverse-grip curl","ru":"Сгибания рук со штангой обратным хватом"},"aka":["Reverse curl","Overhand curl","Pronated-grip curl","EZ-bar reverse curl"],"equipment":"barbell","primary":["brachialis","brachioradialis"],"secondary":["biceps","forearm-extensors"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[10,15],"alternatives":["hammer-curl","ez-bar-preacher-curl","barbell-curl","machine-preacher-curl","cable-curl","dumbbell-curl"],"setup":{"en":"Stand tall holding an EZ bar (or a straight bar) with an overhand grip, palms down, at shoulder width, arms straight in front of your thighs.","ru":"Встаньте прямо, возьмите EZ-гриф (или прямой гриф) хватом сверху, ладонями вниз, на ширине плеч, руки прямые перед бёдрами."},"cues":{"en":["Overhand grip, thumbs wrapped, wrists straight in line with your forearms.","Elbows at your sides; curl the bar up to chest height.","Keep your knuckles pointing forward and up; don''t let the wrists droop.","Lower in 2–3 s to straight arms.","Start at about two-thirds of your normal curl weight: palms down, the biceps is at a mechanical disadvantage and the brachioradialis takes a bigger share of the work.","Breathe out as you curl, in as you lower."],"ru":["Хват сверху, большие пальцы обхватывают гриф, запястья прямые, на одной линии с предплечьями.","Локти у боков; поднимайте гриф до уровня груди.","Костяшки смотрят вперёд и вверх — не давайте запястьям провисать.","Опускайте за 2–3 секунды до прямых рук.","Начинайте примерно с двух третей обычного веса для сгибаний: при хвате сверху бицепс в невыгодном положении, и плечелучевая мышца берёт на себя заметную часть работы.","Выдох — на подъёме, вдох — на опускании."]},"mistakes":{"en":["Letting the wrists bend down or roll back, which strains the forearm tendons.","Swinging the bar up with your hips.","Pushing through pain on the outside of the elbow (the tennis-elbow spot) instead of lightening the load.","Elbows drifting forward."],"ru":["Позволять запястьям сгибаться вниз или заваливаться назад — перегрузка сухожилий предплечья.","Закидывать гриф раскачкой таза.","Терпеть боль с наружной стороны локтя (зона «локтя теннисиста») вместо того, чтобы снизить вес.","Выводить локти вперёд."]},"startLoad":{"kg":10,"source":"Bar included: ≈0.6 × Strength Level Beginner 1RM (15 kg at 80 kg body weight)"},"tags":["owner-alt"],"images":[],"sources":["Reverse Barbell Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/reverse-barbell-curl/kg","Kleiber et al. Muscular coordination of biceps brachii and brachioradialis in elbow flexion with respect to hand position — Front Physiol, 2015. https://doi.org/10.3389/fphys.2015.00215"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"overhead-cable-triceps-extension","equipment_id":"cable","name":{"en":"Overhead cable triceps extension","ru":"Разгибание рук из-за головы на блоке"},"pattern":"elbow-extension","details":{"id":"overhead-cable-triceps-extension","class":"triceps-extension","pattern":"elbow-extension","name":{"en":"Overhead cable triceps extension","ru":"Разгибание рук из-за головы на блоке"},"aka":["Cable overhead triceps extension","Rope overhead extension","Cable French press","Overhead cable extension"],"equipment":"cable","primary":["triceps-long","triceps-lateral"],"secondary":[],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[8,15],"alternatives":["dumbbell-overhead-triceps-extension","skull-crusher","cable-pushdown","machine-triceps-extension"],"setup":{"en":"Attach a rope to a pulley at about head height, face away from the stack in a split stance, lean slightly forward from the hips and hold the rope behind your head with your elbows pointing forward.","ru":"Закрепите канат на блоке примерно на уровне головы, встаньте спиной к тренажёру в разножку, слегка наклонитесь вперёд в тазобедренных суставах и держите канат за головой, локти направлены вперёд."},"cues":{"en":["Split stance, abs braced, ribs down: don''t arch your lower back.","Elbows point forward, close to your head, and stay put.","Straighten your elbows fully, finishing with your hands in front of your forehead.","Return in 2–3 s until your hands are behind your head and the back of your arm is stretched.","Start about a third lighter than your pushdown: the overhead position is weaker but grows the triceps more.","Breathe out as you extend, in as you return."],"ru":["Стойка в разножку, пресс напряжён, рёбра опущены — не прогибайтесь в пояснице.","Локти смотрят вперёд, близко к голове, и не двигаются.","Полностью разгибайте локти, заканчивая с кистями перед лбом.","Возвращайтесь за 2–3 секунды, пока кисти не окажутся за головой, а задняя поверхность руки не растянется.","Начинайте с веса примерно на треть меньше, чем в разгибаниях на верхнем блоке: над головой рука слабее, зато трицепс растёт сильнее.","Выдох — на разгибании, вдох — на возврате."]},"mistakes":{"en":["Arching the lower back and flaring the ribs to get your arms overhead.","Elbows flaring wide, turning it into a press.","Moving the upper arms to pull with your back and shoulders instead of bending only at the elbow.","Letting the cable yank your hands back into the stretch instead of lowering under control.","Using your pushdown weight: the stretched position can''t handle it."],"ru":["Прогибаться в пояснице и раскрывать рёбра, чтобы завести руки за голову.","Разводить локти в стороны — получается жим.","Двигать руками в плечевых суставах, подключая спину и дельты, вместо работы только в локтях.","Позволять тросу рывком утягивать кисти назад вместо подконтрольного опускания.","Брать вес из разгибаний на верхнем блоке — в растянутом положении с ним не справиться."]},"startLoad":{"kg":7.5,"source":"≈0.6 × Strength Level Beginner 1RM (14 kg at 80 kg body weight); overhead loads run 34–39% below pushdowns (Maeo 2023)"},"tags":["owner-alt"],"images":[],"sources":["Maeo et al. Triceps brachii hypertrophy is substantially greater after elbow extension training performed in the overhead versus neutral arm position — Eur J Sport Sci, 2023. https://pubmed.ncbi.nlm.nih.gov/35819335/","Cable Overhead Tricep Extension strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-overhead-tricep-extension/kg"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-triceps-extension","equipment_id":"selectorized","name":{"en":"Machine triceps extension","ru":"Разгибание рук в тренажёре на трицепс"},"pattern":"elbow-extension","details":{"id":"machine-triceps-extension","class":"triceps-extension","pattern":"elbow-extension","name":{"en":"Machine triceps extension","ru":"Разгибание рук в тренажёре на трицепс"},"aka":["Triceps extension machine","Arm Extension (Technogym Selection, Cybex Eagle NX)","Triceps Extension (Life Fitness Insignia)","Biceps Curl/Triceps Extension combo (Precor Vitality)","Seated triceps extension machine"],"equipment":"selectorized","primary":["triceps-lateral","triceps-long"],"secondary":[],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["cable-pushdown","overhead-cable-triceps-extension","dumbbell-overhead-triceps-extension","skull-crusher"],"setup":{"en":"Adjust the seat so your elbows line up with the machine''s pivot and the backs of your upper arms rest flat on the pad, then sit tall against the backrest and take the handles.","ru":"Отрегулируйте сиденье так, чтобы локти совпадали с осью вращения тренажёра, а руки выше локтя лежали на подушке; сядьте прямо, прижавшись к спинке, и возьмитесь за рукояти."},"cues":{"en":["Elbows on the pad, lined up with the pivot; your upper arms never move.","Back against the pad, shoulders down.","Press to fully straight elbows in 1–2 s and squeeze briefly.","Return in 2–3 s until your elbows are well bent, without letting the stack touch down.","Breathe out as you press, in as you return."],"ru":["Локти на подушке, на одной линии с осью; руки выше локтя не двигаются.","Спина прижата к спинке, плечи опущены.","Разгибайте до полностью прямых локтей за 1–2 секунды и коротко задержитесь.","Возвращайтесь за 2–3 секунды до глубокого сгибания в локтях, не давая плитам лечь на стопку.","Выдох — на разгибании, вдох — на возврате."]},"mistakes":{"en":["Seat at the wrong height, so your elbows and the pivot don''t line up and the elbows ache.","Lifting the elbows off the pad or leaning forward to push with your shoulders.","Snapping into lockout or letting the weight crash back.","Shrugging your shoulders up toward your ears."],"ru":["Неправильная высота сиденья: локти не совпадают с осью, и суставы ноют.","Отрывать локти от подушки или наклоняться вперёд, дожимая плечами.","Резко «выстреливать» в выпрямление или бросать вес назад.","Поднимать плечи к ушам."]},"startLoad":{"kg":17.5,"source":"≈0.6 × Strength Level Beginner 1RM (31 kg at 80 kg body weight), rounded down"},"tags":["owner-alt"],"images":[],"sources":["Machine Tricep Extension strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-tricep-extension/kg","Maeo et al. Triceps brachii hypertrophy is substantially greater after elbow extension training performed in the overhead versus neutral arm position — Eur J Sport Sci, 2023. https://pubmed.ncbi.nlm.nih.gov/35819335/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dumbbell-overhead-triceps-extension","equipment_id":"dumbbell","name":{"en":"Seated dumbbell overhead triceps extension","ru":"Французский жим с гантелью сидя"},"pattern":"elbow-extension","details":{"id":"dumbbell-overhead-triceps-extension","class":"triceps-extension","pattern":"elbow-extension","name":{"en":"Seated dumbbell overhead triceps extension","ru":"Французский жим с гантелью сидя"},"aka":["Seated dumbbell French press","Two-hand overhead dumbbell extension","Overhead dumbbell triceps extension","Seated triceps extension"],"equipment":"dumbbell","primary":["triceps-long","triceps-lateral"],"secondary":[],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":2,"repRange":[8,15],"alternatives":["overhead-cable-triceps-extension","skull-crusher","machine-triceps-extension","cable-pushdown"],"setup":{"en":"Sit on a bench with an upright back support and hold one dumbbell overhead with both hands, palms cupping the upper plate and thumbs around the handle, arms straight.","ru":"Сядьте на скамью с вертикальной спинкой и держите одну гантель над головой двумя руками: ладони обхватывают верхний диск, большие пальцы — гриф, руки прямые."},"cues":{"en":["Back against the pad, ribs down, abs braced: don''t arch.","Elbows point forward and stay close to your head; only your forearms move.","Lower the dumbbell behind your head in 2–3 s until your elbows are fully bent and the back of the arm stretches.","Press back up to straight arms without letting the elbows flare.","Breathe out as you press, in as you lower."],"ru":["Спина прижата к спинке, рёбра опущены, пресс напряжён — не прогибайтесь.","Локти смотрят вперёд и остаются у головы; двигаются только предплечья.","Опускайте гантель за голову за 2–3 секунды до полного сгибания в локтях и растяжения задней поверхности руки.","Выжимайте обратно до прямых рук, не разводя локти.","Выдох — на подъёме, вдох — на опускании."]},"mistakes":{"en":["Arching your lower back off the pad to get the weight overhead.","Elbows flaring out wide.","Dropping fast into the bottom and bouncing out of the stretch, which strains the elbow.","A loose grip on the dumbbell: it is over your head, so cup the plate firmly.","Starting too heavy: the stretched bottom is the weak point."],"ru":["Отрывать поясницу от спинки, чтобы выжать вес.","Широко разводить локти.","Быстро ронять гантель вниз и отбивать её из растяжения — перегрузка локтя.","Слабый хват: гантель над головой, плотно обхватывайте диск.","Слишком тяжёлый старт: растянутое нижнее положение — самое слабое место."]},"startLoad":{"kg":8,"source":"One dumbbell: ≈0.63 × the pushdown start (12.5 kg), since overhead loads run 34–39% lighter (Maeo 2023)"},"tags":["owner-alt"],"images":[],"sources":["Maeo et al. Triceps brachii hypertrophy is substantially greater after elbow extension training performed in the overhead versus neutral arm position — Eur J Sport Sci, 2023. https://pubmed.ncbi.nlm.nih.gov/35819335/","Boehler, Porcari et al. ACE-sponsored research: best triceps exercises — ACE Certified News, 2011. https://www.acefitness.org/certifiednewsarticle/1562/ace-study-identifies-best-triceps-exercises/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"skull-crusher","equipment_id":"barbell","name":{"en":"Skull crusher","ru":"Французский жим лёжа с EZ-грифом"},"pattern":"elbow-extension","details":{"id":"skull-crusher","class":"triceps-extension","pattern":"elbow-extension","name":{"en":"Skull crusher","ru":"Французский жим лёжа с EZ-грифом"},"aka":["Lying triceps extension","EZ-bar skull crusher","Lying French press","Nose breaker"],"equipment":"barbell","primary":["triceps-long","triceps-lateral"],"secondary":[],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[8,15],"alternatives":["overhead-cable-triceps-extension","dumbbell-overhead-triceps-extension","machine-triceps-extension","cable-pushdown"],"setup":{"en":"Lie on a flat bench with your feet flat and hold an EZ bar on the angled grips, thumbs wrapped, arms straight over your shoulders; then tilt your arms slightly back toward your head.","ru":"Лягте на горизонтальную скамью, стопы на полу; возьмите EZ-гриф за изгибы, обхватив его большими пальцами, руки прямые над плечами, затем слегка наклоните их назад к голове."},"cues":{"en":["Upper arms tilted slightly back toward your head; keep them still.","Bend only at the elbows and lower the bar in 2–3 s to just behind the top of your head.","Elbows stay about shoulder-width apart, pointing up.","Extend to straight arms, keeping tension on the triceps at the top.","Shoulder blades and back stay on the bench, feet planted.","Breathe in as you lower, out as you extend."],"ru":["Руки выше локтя слегка наклонены назад, к голове, и неподвижны.","Сгибайте только локти и опускайте гриф за 2–3 секунды чуть за макушку.","Локти примерно на ширине плеч, смотрят вверх.","Разгибайте до прямых рук, сохраняя напряжение трицепса вверху.","Лопатки и спина прижаты к скамье, стопы упираются в пол.","Вдох — на опускании, выдох — на разгибании."]},"mistakes":{"en":["Elbows flaring wide.","Swinging the upper arms so it becomes a pullover or a press.","Lowering fast toward your face: control every rep.","A thumbless grip: the bar is over your face, so wrap your thumbs.","Pushing through elbow pain with heavy loads: lighten it or switch to a cable or machine."],"ru":["Разводить локти в стороны.","Двигать руками в плечевых суставах — упражнение превращается в пуловер или жим.","Быстро опускать гриф к лицу — контролируйте каждый повтор.","Хват без больших пальцев: гриф над лицом, обхватывайте его.","Работать через боль в локтях с большим весом — снизьте его или перейдите на блок или тренажёр."]},"startLoad":{"kg":12.5,"source":"Bar included: ≈0.6 × Strength Level Beginner 1RM for the lying triceps extension (20 kg at 80 kg body weight)"},"tags":["owner-alt"],"images":[],"sources":["Lying Tricep Extension strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/lying-tricep-extension/kg","Boehler, Porcari et al. ACE-sponsored research: best triceps exercises — ACE Certified News, 2011. https://www.acefitness.org/certifiednewsarticle/1562/ace-study-identifies-best-triceps-exercises/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"cable-pushdown","equipment_id":"cable","name":{"en":"Cable triceps pushdown","ru":"Разгибание рук на верхнем блоке"},"pattern":"elbow-extension","details":{"id":"cable-pushdown","class":"triceps-extension","pattern":"elbow-extension","name":{"en":"Cable triceps pushdown","ru":"Разгибание рук на верхнем блоке"},"aka":["Triceps pushdown","Rope pushdown","Straight-bar pushdown","V-bar pushdown","Cable press-down"],"equipment":"cable","primary":["triceps-lateral","triceps-long"],"secondary":[],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["machine-triceps-extension","overhead-cable-triceps-extension","dumbbell-overhead-triceps-extension","skull-crusher"],"setup":{"en":"Set the pulley at the top with a rope, straight bar or V-bar, stand tall facing the stack with feet hip-width or staggered, and grip the attachment with your thumbs wrapped, elbows bent and tucked at your sides.","ru":"Установите блок в верхнее положение с канатом, прямой или V-образной рукоятью, встаньте прямо лицом к тренажёру, стопы на ширине таза или в разножку, возьмитесь за рукоять, обхватив её большими пальцами, локти согнуты и прижаты к бокам."},"cues":{"en":["Stand tall, abs braced, with the natural arch in your lower back.","Pull your shoulders back and down and hold them there for the whole set.","Elbows stay pinned to your sides; only the forearms move.","Press down until your elbows are straight without slamming into lockout; with a rope, spread the ends at the bottom.","Pause for a moment at the bottom with the triceps squeezed.","Let your hands rise in 2–3 s to about upper-chest height, stopping before the elbows start to drift forward.","Breathe out as you press, in as you return."],"ru":["Стойте прямо, пресс напряжён, естественный прогиб в пояснице сохранён.","Отведите плечи назад и вниз и держите их так весь подход.","Локти прижаты к бокам, двигаются только предплечья.","Разгибайте руки вниз до прямых локтей, не «вбивая» их в замок; с канатом разводите концы внизу.","Внизу на мгновение задержитесь, напрягая трицепс.","Поднимайте кисти за 2–3 секунды примерно до уровня верха груди — пока локти не начали уходить вперёд.","Выдох — на разгибании, вдох — на возврате."]},"mistakes":{"en":["Leaning over the attachment to push with your bodyweight and shoulders: a sign the weight is too heavy.","Elbows drifting forward, which hands the work to the lats and shoulders.","Shrugging your shoulders up toward your ears.","Letting the attachment fly up past chest height, which lifts the elbows off your sides.","Bending the wrists to push: keep them in line with your forearms."],"ru":["Наваливаться на рукоять, дожимая весом тела и плечами, — признак того, что вес слишком велик.","Уводить локти вперёд — работа переходит на широчайшие и плечи.","Поднимать плечи к ушам.","Отпускать рукоять выше груди, так что локти отрываются от боков.","Сгибать запястья, дожимая кистями, — держите их на одной линии с предплечьями."]},"startLoad":{"kg":12.5,"source":"≈0.6 × Strength Level Beginner 1RM (22 kg at 80 kg body weight), rounded down"},"tags":["owner-primary"],"images":[],"sources":["Triceps pushdowns — ACE Exercise Library, accessed 2026. https://www.acefitness.org/resources/everyone/exercise-library/185/triceps-pushdowns/","Tricep Pushdown strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/tricep-pushdown/kg","Maeo et al. Triceps brachii hypertrophy is substantially greater after elbow extension training performed in the overhead versus neutral arm position — Eur J Sport Sci, 2023. https://pubmed.ncbi.nlm.nih.gov/35819335/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"close-grip-bench-press","equipment_id":"barbell","name":{"en":"Close-grip bench press","ru":"Жим штанги лёжа узким хватом"},"pattern":"horizontal-push","details":{"id":"close-grip-bench-press","class":"triceps-press","pattern":"horizontal-push","name":{"en":"Close-grip bench press","ru":"Жим штанги лёжа узким хватом"},"aka":["Narrow-grip bench press","CGBP","Triceps bench press","Close-grip barbell bench"],"equipment":"barbell","primary":["triceps-lateral","triceps-long"],"secondary":["pec-sternal","pec-clavicular","delt-front"],"difficulty":3,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,10],"alternatives":["triceps-press-machine","assisted-dip","diamond-push-up","dip","smith-bench-press"],"setup":{"en":"In a rack with the safety arms set just below chest height, lie on a flat bench with your eyes under the bar, grip it about shoulder-width (hands just outside your torso), pull your shoulder blades back and down and plant your feet.","ru":"В силовой раме с упорами чуть ниже уровня груди лягте на скамью так, чтобы глаза были под грифом; возьмите гриф примерно на ширине плеч (кисти чуть шире корпуса), сведите и опустите лопатки, твёрдо поставьте стопы."},"cues":{"en":["Hands about shoulder-width: that already shifts work to the triceps, and going narrower mostly strains the wrists.","Shoulder blades pulled back and down, feet planted, glutes on the bench.","Lower the bar in 2–3 s to your lower chest with your elbows tucked at about 30–45° from your sides.","Touch lightly, with no bounce, then press up and slightly back over your shoulders.","Wrists stacked over your elbows, the bar in the heels of your palms.","Take a breath and brace before each rep; breathe out past the hardest part."],"ru":["Хват примерно на ширине плеч: этого уже достаточно, чтобы сместить нагрузку на трицепс, а более узкий хват в основном перегружает запястья.","Лопатки сведены и опущены, стопы упираются в пол, ягодицы на скамье.","Опускайте гриф за 2–3 секунды к низу груди, локти прижаты под углом 30–45° к корпусу.","Касайтесь груди мягко, без отбива, затем выжимайте вверх и слегка назад, к линии плеч.","Запястья над локтями, гриф лежит в основании ладоней.","Перед каждым повтором вдохните и напрягите корпус; выдыхайте после самой тяжёлой точки."]},"mistakes":{"en":["Training alone without safety arms or a spotter: never take this lift close to failure unprotected.","Hands touching or very close, which bends and strains the wrists.","Elbows flaring past about 75° from your torso, which loads the front of the shoulder.","Bouncing the bar off your chest.","Lifting your hips off the bench or overarching your lower back.","Ego loading: using your regular bench-press weight."],"ru":["Работать в одиночку без страховочных упоров или партнёра: никогда не подходите к отказу без страховки.","Ставить кисти вплотную или почти вплотную — запястья заламываются и перегружаются.","Разводить локти больше чем примерно на 75° от корпуса — перегрузка передней части плеча.","Отбивать гриф от груди.","Отрывать таз от скамьи или чрезмерно прогибать поясницу.","Погоня за весом: брать свой обычный вес из жима лёжа."]},"startLoad":{"kg":30,"source":"Bar included: ≈0.55 × Strength Level Beginner 1RM (55 kg at 80 kg body weight) = empty bar plus two 5 kg plates"},"tags":["owner-alt"],"images":[],"sources":["Close Grip Bench Press strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/close-grip-bench-press/kg","Lehman. The influence of grip width and forearm pronation/supination on upper-body myoelectric activity during the flat bench press — J Strength Cond Res, 2005. https://pubmed.ncbi.nlm.nih.gov/16095407/","Boehler, Porcari et al. ACE-sponsored research: best triceps exercises — ACE Certified News, 2011. https://www.acefitness.org/certifiednewsarticle/1562/ace-study-identifies-best-triceps-exercises/"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"diamond-push-up","equipment_id":"bodyweight","name":{"en":"Diamond push-up","ru":"Алмазные отжимания (узкая постановка рук)"},"pattern":"horizontal-push","details":{"id":"diamond-push-up","class":"triceps-press","pattern":"horizontal-push","name":{"en":"Diamond push-up","ru":"Алмазные отжимания (узкая постановка рук)"},"aka":["Triangle push-up","Close-hand push-up","Narrow push-up","Diamond press-up"],"equipment":"bodyweight","primary":["triceps-lateral","triceps-long"],"secondary":["pec-sternal","delt-front","serratus-anterior","rectus-abdominis"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[6,15],"alternatives":["dip","triceps-press-machine","assisted-dip","close-grip-bench-press","push-up"],"setup":{"en":"Place your hands under your chest with thumbs and index fingers touching to form a diamond, and set a straight plank from head to heels (knees down or hands on a bench to make it easier).","ru":"Поставьте руки под грудью так, чтобы большие и указательные пальцы соприкасались и образовывали ромб, и примите упор лёжа: тело прямое от головы до пяток (для облегчения — с колен или руками на скамье)."},"cues":{"en":["One straight line from head to heels: squeeze your glutes and abs.","Elbows travel back along your ribs, not out to the sides.","Lower in about 2 s until your chest nearly touches your hands.","Push the floor away to straight arms; keep your shoulders away from your ears.","Breathe in on the way down, out on the way up.","If you can''t do 6, put your hands on a bench or box: the higher, the easier."],"ru":["Тело — одна прямая линия от головы до пяток: напрягите ягодицы и пресс.","Локти уходят назад вдоль рёбер, а не в стороны.","Опускайтесь примерно 2 секунды, пока грудь почти не коснётся кистей.","Отталкивайте пол до прямых рук, плечи подальше от ушей.","Вдох — при опускании, выдох — при подъёме.","Если не получается 6 раз, поставьте руки на скамью или тумбу: чем выше опора, тем легче."]},"mistakes":{"en":["Hips sagging and the lower back arching.","Elbows flaring straight out to the sides, which loads the shoulders.","Half reps that stop well short of your hands.","Forcing the diamond when your wrists or elbows hurt: move the hands to just inside shoulder-width instead."],"ru":["Провисание таза и прогиб в пояснице.","Разведение локтей в стороны — нагрузка уходит на плечи.","Полуповторы, далеко не доходящие до кистей.","Упорствовать с «ромбом» при боли в запястьях или локтях — лучше поставьте руки чуть уже плеч."]},"startLoad":{"kg":0,"source":"Body weight; the Strength Level Beginner standard at 80 kg is 2–3 reps, so most beginners start with their hands on a bench"},"tags":["owner-alt"],"images":[],"sources":["Boehler, Porcari et al. ACE-sponsored research: best triceps exercises — ACE Certified News, 2011. https://www.acefitness.org/certifiednewsarticle/1562/ace-study-identifies-best-triceps-exercises/","Diamond Push Ups strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/diamond-push-ups"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"wrist-curl","equipment_id":"dumbbell","name":{"en":"Dumbbell wrist curl","ru":"Сгибания кистей с гантелями сидя"},"pattern":"forearm-flexion","details":{"id":"wrist-curl","class":"wrist","pattern":"forearm-flexion","name":{"en":"Dumbbell wrist curl","ru":"Сгибания кистей с гантелями сидя"},"aka":["Wrist curl","Seated dumbbell wrist curl","Palms-up wrist curl","Barbell wrist curl"],"equipment":"dumbbell","primary":["forearm-flexors"],"secondary":[],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":1,"repRange":[10,20],"alternatives":["gripper","dead-hang","plate-pinch","farmers-carry","reverse-wrist-curl"],"setup":{"en":"Sit on a bench with your forearms resting on your thighs, palms up, wrists just past your knees, and a dumbbell in each hand.","ru":"Сядьте на скамью, положите предплечья на бёдра ладонями вверх так, чтобы запястья выступали за колени, в каждой руке гантель."},"cues":{"en":["Forearms stay glued to your thighs; only the wrists move.","Let the wrist bend back under control; you can let the dumbbell roll toward your fingertips.","Close your fingers and curl the wrist up as high as it goes.","Move slowly: 1–2 s up, 2 s down, no bouncing.","Breathe steadily throughout the set."],"ru":["Предплечья неподвижно лежат на бёдрах, двигаются только кисти.","Подконтрольно опускайте кисть назад; можно дать гантели скатиться к кончикам пальцев.","Сожмите пальцы и согните кисть вверх как можно выше.","Двигайтесь медленно: 1–2 секунды вверх, 2 секунды вниз, без рывков.","Дышите ровно на протяжении всего подхода."]},"mistakes":{"en":["Lifting the forearms off your thighs to swing the weight.","Heavy, jerky, short reps.","Letting the dumbbell drop at the bottom, which jolts the wrist."],"ru":["Отрывать предплечья от бёдер, раскачивая вес.","Тяжёлые, рваные, короткие повторы.","Ронять гантель в нижней точке — это бьёт по запястью."]},"startLoad":{"kg":4,"source":"Per dumbbell: ≈0.6 × Strength Level Beginner 1RM (7 kg at 80 kg body weight)"},"tags":[],"images":[],"sources":["Dumbbell Wrist Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-wrist-curl/kg","Delp, Grierson, Buchanan. Maximum isometric moments generated by the wrist muscles in flexion-extension and radial-ulnar deviation — J Biomech, 1996. https://doi.org/10.1016/0021-9290(96)00029-2"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"reverse-wrist-curl","equipment_id":"dumbbell","name":{"en":"Dumbbell reverse wrist curl","ru":"Разгибания кистей с гантелями сидя"},"pattern":"forearm-extension","details":{"id":"reverse-wrist-curl","class":"wrist","pattern":"forearm-extension","name":{"en":"Dumbbell reverse wrist curl","ru":"Разгибания кистей с гантелями сидя"},"aka":["Reverse wrist curl","Wrist extension","Palms-down wrist curl","Barbell reverse wrist curl"],"equipment":"dumbbell","primary":["forearm-extensors"],"secondary":[],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":1,"repRange":[12,20],"alternatives":["reverse-curl","wrist-curl","plate-pinch"],"setup":{"en":"Sit on a bench with your forearms resting on your thighs, palms down, wrists just past your knees, and a light dumbbell in each hand.","ru":"Сядьте на скамью, положите предплечья на бёдра ладонями вниз так, чтобы запястья выступали за колени, в каждой руке лёгкая гантель."},"cues":{"en":["Forearms stay on your thighs; only your hands move.","Lift the back of your hand as high as it goes, fingers relaxed around the handle.","Lower slowly, over about 3 s: slow lowering is the core of tennis-elbow rehab.","Use about half of your wrist-curl weight: the wrist extensors are much weaker.","Smooth tempo, no jerks."],"ru":["Предплечья лежат на бёдрах, двигаются только кисти.","Поднимайте тыльную сторону кисти как можно выше, пальцы спокойно обхватывают гриф.","Опускайте медленно, около 3 секунд: медленное опускание — основа реабилитации «локтя теннисиста».","Берите примерно половину веса из сгибаний кистей: разгибатели запястья заметно слабее.","Плавный темп, без рывков."]},"mistakes":{"en":["Adding weight before reps: the extensors are small, so reach 20 clean reps first.","Swinging the weight or lifting the forearms.","Twisting the wrist sideways to help the weight up.","Training through sharp pain on the outside of the elbow instead of lightening the load."],"ru":["Добавлять вес раньше повторов: разгибатели небольшие, сначала добейтесь 20 чистых повторов.","Раскачивать вес или отрывать предплечья.","Выворачивать кисть в сторону, помогая поднять вес.","Терпеть острую боль с наружной стороны локтя вместо того, чтобы снизить вес."]},"startLoad":{"kg":2,"source":"Per dumbbell: about half the wrist-curl start, since the wrist extensors produce ≈60% of the flexors'' torque (Delp 1996)"},"tags":[],"images":[],"sources":["Dumbbell Reverse Wrist Curl strength standards — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-reverse-wrist-curl/kg","Delp, Grierson, Buchanan. Maximum isometric moments generated by the wrist muscles in flexion-extension and radial-ulnar deviation — J Biomech, 1996. https://doi.org/10.1016/0021-9290(96)00029-2","Peterson et al. Eccentric vs concentric graded exercise in chronic tennis elbow: a randomized controlled trial — Clin Rehabil, 2014. https://pubmed.ncbi.nlm.nih.gov/24634444/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"farmers-carry","equipment_id":"dumbbell","name":{"en":"Farmer''s carry","ru":"Прогулка фермера"},"pattern":"carry","details":{"id":"farmers-carry","class":"grip","pattern":"carry","name":{"en":"Farmer''s carry","ru":"Прогулка фермера"},"aka":["Farmer''s walk","Farmers walk","Loaded carry","Dumbbell farmer''s carry","Trap-bar or handle farmer''s walk"],"equipment":"dumbbell","primary":["forearm-flexors","traps-upper"],"secondary":["erectors","quadratus-lumborum","obliques","glute-med"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2,"repRange":[20,40],"repUnit":"meters","alternatives":["suitcase-carry","plate-pinch","dead-hang","gripper"],"setup":{"en":"Stand between two equal dumbbells (or kettlebells, or farmer''s handles), pick them up like a deadlift — hips back, flat back, chest up — and stand tall with them at your sides, facing a clear, straight 20–40 m lane.","ru":"Встаньте между двумя одинаковыми гантелями (гирями или рукоятями для прогулки фермера), поднимите их как в становой тяге — таз назад, спина ровная, грудь раскрыта — и выпрямитесь с ними в опущенных руках лицом к свободной прямой дорожке длиной 20–40 м."},"cues":{"en":["Grip the middle of the handles hard; arms straight and relaxed at your sides.","Stand tall: chest up, shoulders down and slightly back, head level, eyes forward.","Brace your abs as if about to be poked, and breathe in short breaths behind the brace.","Walk with short, quick, controlled steps; keep the weights from swinging.","Keep your hips and shoulders level: no leaning or twisting.","Turn around with small steps, or put the weights down and pick them up again.","Set the weights down the way you picked them up — hips back, flat back — before your grip gives out."],"ru":["Крепко держите рукояти посередине, руки прямые и расслабленные вдоль корпуса.","Стойте ровно: грудь раскрыта, плечи опущены и слегка отведены назад, голова прямо, взгляд вперёд.","Напрягите пресс, как перед лёгким толчком в живот, и дышите короткими вдохами, не теряя напряжения.","Идите короткими, частыми, подконтрольными шагами, не давая весу раскачиваться.","Таз и плечи держите ровно — без наклонов и скручиваний.","Разворачивайтесь мелкими шагами или поставьте вес и поднимите его снова.","Ставьте вес так же, как поднимали, — таз назад, спина ровная, — до того как хват откажет."]},"mistakes":{"en":["Rounding your back to pick the weights up or put them down.","Leaning to one side, slouching, or letting your shoulders roll forward.","Shrugging your shoulders up to your ears.","Long, bouncing strides that set the weights swinging.","Holding your breath for the whole walk.","Walking until your grip fails and the weights drop."],"ru":["Округлять спину, поднимая или ставя вес.","Заваливаться в сторону, сутулиться или сводить плечи вперёд.","Поднимать плечи к ушам.","Длинные, прыгающие шаги, раскачивающие вес.","Задерживать дыхание на всю дистанцию.","Идти до отказа хвата, пока вес не выпадет из рук."]},"startLoad":{"kg":20,"source":"Per hand: 25% of body weight (50% in total), the NSCA Coach ''rehabilitation'' benchmark for a 30 s bilateral carry"},"tags":["owner-primary","longevity"],"images":[],"sources":["Taylor, Reed. Increase hip and trunk stability with loaded carries — NSCA Coach 7.3, 2020. https://www.nsca.com/contentassets/927868f8d4bb45f2ac4429631d558d83/coach-7.3.6-increase-hip-and-trunk-stability-with-loaded-carries-for-injury-prevention-rehabilitation-and-performance.pdf","McGill, McDermott, Fenwick. Comparison of different strongman events: trunk muscle activation and lumbar spine motion, load, and stiffness — J Strength Cond Res, 2009. https://pubmed.ncbi.nlm.nih.gov/19528856/","McGill, Marshall, Andersen. Low back loads while walking and carrying: comparing the load carried in one hand or in both hands — Ergonomics, 2013. https://doi.org/10.1080/00140139.2012.752528","Leong et al. Prognostic value of grip strength: findings from the PURE study — Lancet, 2015. https://doi.org/10.1016/S0140-6736(14)62000-6"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dead-hang","equipment_id":"bodyweight","name":{"en":"Dead hang","ru":"Вис на перекладине"},"pattern":"grip","details":{"id":"dead-hang","class":"grip","pattern":"grip","name":{"en":"Dead hang","ru":"Вис на перекладине"},"aka":["Bar hang","Passive hang","Active hang","Hang from a pull-up bar"],"equipment":"bodyweight","primary":["forearm-flexors"],"secondary":["lats","traps-lower","rotator-cuff"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[20,60],"repUnit":"seconds","alternatives":["plate-pinch","gripper","farmers-carry","suitcase-carry"],"setup":{"en":"Stand on a box or step under a pull-up bar, take an overhand grip just outside shoulder-width with your thumbs wrapped around the bar, then lift your feet and hang with straight arms.","ru":"Встаньте на тумбу или ступень под перекладиной, возьмитесь хватом сверху чуть шире плеч, обхватив перекладину большими пальцами, затем поднимите ноги и повисните на прямых руках."},"cues":{"en":["Full grip: thumbs wrapped around the bar.","Arms straight, shoulders gently pulled down away from your ears (an active hang).","Ribs down, legs still and slightly in front of you; don''t swing.","Breathe slowly and steadily for the whole hold.","Finish by stepping back onto the box instead of dropping.","Build time first: 60 s is a good target before making it harder."],"ru":["Полный хват: большие пальцы обхватывают перекладину.","Руки прямые, плечи мягко опущены от ушей (активный вис).","Рёбра опущены, ноги неподвижны и чуть впереди — не раскачивайтесь.","Дышите медленно и ровно всё время виса.","Заканчивайте, вставая обратно на тумбу, а не спрыгивая.","Сначала наращивайте время: 60 секунд — хорошая цель, прежде чем усложнять."]},"mistakes":{"en":["Dropping off the bar instead of stepping down, which jars the shoulders and ankles.","Hanging through pain at the front or top of the shoulder: set the shoulders down or stop.","Kipping or swinging the body.","Holding your breath."],"ru":["Спрыгивать с перекладины вместо того, чтобы встать на опору, — удар по плечам и голеностопам.","Висеть через боль в передней или верхней части плеча — опустите плечи или прекратите.","Раскачиваться или делать киппинг.","Задерживать дыхание."]},"tags":["owner-alt","longevity"],"images":[],"sources":["Leong et al. Prognostic value of grip strength: findings from the PURE study — Lancet, 2015. https://doi.org/10.1016/S0140-6736(14)62000-6","Dodds et al. Grip strength across the life course: normative data from twelve British studies — PLoS One, 2014. https://doi.org/10.1371/journal.pone.0113637"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"gripper","equipment_id":"band","name":{"en":"Hand gripper","ru":"Кистевой эспандер"},"pattern":"grip","details":{"id":"gripper","class":"grip","pattern":"grip","name":{"en":"Hand gripper","ru":"Кистевой эспандер"},"aka":["Gripper","Grip trainer","Torsion-spring gripper (e.g. Captains of Crush)","Adjustable hand gripper","Gripper (Hammer Strength, plate-loaded machine)"],"equipment":"band","primary":["forearm-flexors"],"secondary":[],"difficulty":1,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[10,20],"alternatives":["plate-pinch","dead-hang","farmers-carry","suitcase-carry","wrist-curl"],"setup":{"en":"Sit or stand tall and hold the gripper in one hand with the spring above your thumb and index finger, one handle across your palm and the other across the middle of your fingers.","ru":"Сядьте или встаньте прямо и возьмите эспандер в одну руку пружиной вверх, над большим и указательным пальцами: одна рукоять лежит поперёк ладони, другая — поперёк середины пальцев."},"cues":{"en":["Pick a gripper you can close fully 10–20 times.","Squeeze until the handles touch, hold for a second, then open slowly.","Keep your wrist straight.","Train both hands with the same reps, weaker hand first.","Breathe steadily; don''t hold your breath."],"ru":["Выберите эспандер, который можете полностью сжать 10–20 раз.","Сжимайте до касания рукоятей, задержитесь на секунду и медленно разжимайте.","Держите запястье прямым.","Работайте обеими руками с одинаковым числом повторов, начиная со слабой.","Дышите ровно, не задерживайте дыхание."]},"mistakes":{"en":["Using a gripper too strong to close, so every rep is a partial squeeze.","Letting the gripper snap open.","Bending the wrist to help the squeeze.","Squeezing to failure every day: give the fingers a rest day between hard sessions."],"ru":["Слишком тугой эспандер: ни одного полного сжатия, только частичные.","Позволять эспандеру резко разжиматься.","Сгибать запястье, помогая сжатию.","Сжимать до отказа каждый день — давайте пальцам день отдыха между тяжёлыми тренировками."]},"tags":["owner-alt","longevity"],"images":[],"sources":["Leong et al. Prognostic value of grip strength: findings from the PURE study — Lancet, 2015. https://doi.org/10.1016/S0140-6736(14)62000-6","Dodds et al. Grip strength across the life course: normative data from twelve British studies — PLoS One, 2014. https://doi.org/10.1371/journal.pone.0113637"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"plate-pinch","equipment_id":"barbell","name":{"en":"Plate pinch hold","ru":"Удержание блинов щипковым хватом"},"pattern":"grip","details":{"id":"plate-pinch","class":"grip","pattern":"grip","name":{"en":"Plate pinch hold","ru":"Удержание блинов щипковым хватом"},"aka":["Plate pinch","Pinch grip hold","Two-plate pinch","Plate pinch carry (walking version)"],"equipment":"barbell","primary":["forearm-flexors"],"secondary":["forearm-extensors"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[20,40],"repUnit":"seconds","alternatives":["dead-hang","gripper","farmers-carry","suitcase-carry"],"setup":{"en":"Stand two smooth-faced plates of the same size together, smooth sides out, on a bench or the floor; pinch them along the top rim, fingers on one side and thumb on the other, one pair in each hand, and stand up tall with a flat back.","ru":"Поставьте вместе два одинаковых блина гладкими сторонами наружу на скамью или пол; зажмите их за верхний край — пальцы с одной стороны, большой палец с другой, по паре в каждой руке — и выпрямитесь с ровной спиной."},"cues":{"en":["Smooth sides out; fingers straight and together on one side, thumb flat on the other.","Squeeze the thumb hard toward the fingers so the plates can''t swivel.","Stand tall, shoulders down, arms straight, plates beside your legs.","Hold for the target time, breathing steadily.","Set the plates down with a hip hinge before your grip gives out.","Progress by time first, then by a third plate or bigger plates."],"ru":["Гладкие стороны наружу; пальцы прямые и сомкнуты с одной стороны, большой палец плашмя — с другой.","С силой прижимайте большой палец к остальным, чтобы блины не проворачивались.","Стойте прямо, плечи опущены, руки прямые, блины сбоку от ног.","Удерживайте заданное время, дыша ровно.","Ставьте блины, наклоняясь в тазобедренных суставах, до того как хват откажет.","Прогрессируйте сначала временем, затем третьим блином или более крупными блинами."]},"mistakes":{"en":["Holding the plates over your feet or training in open shoes: a slipped plate lands on your toes.","Curling the fingers over the rim, which turns the pinch into an ordinary grip.","Leaning or shrugging to cope with the load.","Holding on until the plates slip out of your hands."],"ru":["Держать блины над стопами или тренироваться в открытой обуви: сорвавшийся блин падает на пальцы ног.","Загибать пальцы за край блина — щипковый хват превращается в обычный.","Наклоняться или поднимать плечи, чтобы справиться с весом.","Держать, пока блины не выскользнут из рук."]},"startLoad":{"kg":10,"source":"Per hand: two 5 kg plates, a conservative coaching start; progress by hold time first"},"tags":["owner-alt","longevity"],"images":[],"sources":["Leong et al. Prognostic value of grip strength: findings from the PURE study — Lancet, 2015. https://doi.org/10.1016/S0140-6736(14)62000-6","Dodds et al. Grip strength across the life course: normative data from twelve British studies — PLoS One, 2014. https://doi.org/10.1371/journal.pone.0113637"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"suitcase-carry","equipment_id":"dumbbell","name":{"en":"Suitcase carry","ru":"Прогулка с гантелью в одной руке («чемодан»)"},"pattern":"carry","details":{"id":"suitcase-carry","class":"grip","pattern":"carry","name":{"en":"Suitcase carry","ru":"Прогулка с гантелью в одной руке («чемодан»)"},"aka":["One-arm farmer''s carry","Single-arm farmer''s walk","Unilateral carry","Suitcase walk"],"equipment":"dumbbell","primary":["forearm-flexors","obliques","quadratus-lumborum"],"secondary":["glute-med","erectors","traps-upper"],"difficulty":2,"unilateral":true,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2,"repRange":[20,40],"repUnit":"meters","alternatives":["farmers-carry","side-plank","plate-pinch","dead-hang","gripper"],"setup":{"en":"Pick up one dumbbell or kettlebell from a rack, or from the floor with a hip hinge, and stand tall with it at your side, free arm relaxed or slightly out; walk 20–40 m, then switch hands.","ru":"Возьмите одну гантель или гирю со стойки или с пола, наклонившись в тазобедренных суставах, и выпрямитесь, держа её сбоку, свободная рука расслаблена или чуть отведена; пройдите 20–40 м и смените руку."},"cues":{"en":["Stand perfectly upright: lean neither toward nor away from the weight.","Brace your abs and tense the side opposite the weight, as if resisting a push from the side.","Keep your shoulders level: the loaded shoulder neither drops nor shrugs up.","Take short, controlled steps; keep the weight from bumping your leg.","Breathe in short breaths behind the brace.","Walk the same distance with each hand and log the distance per side."],"ru":["Держитесь строго вертикально — не наклоняйтесь ни к весу, ни от него.","Напрягите пресс и сторону, противоположную весу, как будто сопротивляетесь толчку сбоку.","Плечи на одном уровне: нагруженное плечо не опускается и не поднимается.","Делайте короткие подконтрольные шаги, не давая весу биться о ногу.","Дышите короткими вдохами, сохраняя напряжение корпуса.","Пройдите одинаковую дистанцию каждой рукой и записывайте её для каждой стороны."]},"mistakes":{"en":["Leaning away from the weight (or toward it).","Twisting the torso or letting the hips swing.","Picking the weight up or setting it down with a rounded, twisted back.","Going heavier than you can carry perfectly upright."],"ru":["Отклоняться от веса (или наклоняться к нему).","Скручивать корпус или раскачивать таз.","Поднимать или ставить вес с округлённой, скрученной спиной.","Брать вес больше, чем можете пронести строго вертикально."]},"startLoad":{"kg":16,"source":"One hand: ≈20% of body weight, lighter than the farmer''s carry per hand because one-hand carrying loads the spine more (McGill 2013)"},"tags":["owner-alt","core","longevity"],"images":[],"sources":["McGill, Marshall, Andersen. Low back loads while walking and carrying: comparing the load carried in one hand or in both hands — Ergonomics, 2013. https://doi.org/10.1080/00140139.2012.752528","McGill, McDermott, Fenwick. Comparison of different strongman events: trunk muscle activation and lumbar spine motion, load, and stiffness — J Strength Cond Res, 2009. https://pubmed.ncbi.nlm.nih.gov/19528856/","Taylor, Reed. Increase hip and trunk stability with loaded carries — NSCA Coach 7.3, 2020. https://www.nsca.com/contentassets/927868f8d4bb45f2ac4429631d558d83/coach-7.3.6-increase-hip-and-trunk-stability-with-loaded-carries-for-injury-prevention-rehabilitation-and-performance.pdf"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"bird-dog","equipment_id":"bodyweight","name":{"en":"Bird dog","ru":"Птица-собака"},"pattern":"anti-rotation","details":{"id":"bird-dog","class":"spine-stability","pattern":"anti-rotation","name":{"en":"Bird dog","ru":"Птица-собака"},"aka":["Birddog (McGill ''big 3'')","Quadruped opposite arm and leg raise","Подъём руки и ноги на четвереньках"],"equipment":"bodyweight","primary":["erectors"],"secondary":["glute-max","obliques","transverse-abdominis"],"difficulty":1,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[5,10],"alternatives":["dead-bug","side-plank","plank","pallof-press"],"setup":{"en":"Start on hands and knees: hands under the shoulders, knees under the hips, spine neutral. Brace the abs lightly, as if someone were about to poke your belly.","ru":"Встаньте на четвереньки: ладони под плечами, колени под тазобедренными суставами, спина в нейтральном положении. Слегка напрягите пресс, как будто вас сейчас ткнут в живот."},"cues":{"en":["Slowly reach one arm forward and the opposite leg back until both are level with your back — no higher.","Push the heel back and reach long with the fingertips: the body gets longer, not higher.","Keep hips and shoulders square and still, as if a glass of water stood on your lower back.","Hold 5–10 s at full reach and keep breathing.","Bring the hand and knee back under you without sagging, then switch sides; reps are counted per side.","Progress: draw small squares with the hand and foot while the spine stays completely still."],"ru":["Медленно вытяните одну руку вперёд, а противоположную ногу назад до уровня спины — не выше.","Тянитесь пяткой назад, а кончиками пальцев вперёд: тело удлиняется, а не поднимается.","Таз и плечи неподвижны и параллельны полу, как будто на пояснице стоит стакан воды.","Задержитесь в вытянутом положении на 5–10 секунд, продолжая дышать.","Верните руку и колено под себя, не проседая в пояснице, и смените сторону; повторы считаются на каждую сторону.","Усложнение: рисуйте рукой и стопой маленькие квадраты, позвоночник при этом полностью неподвижен."]},"mistakes":{"en":["Lifting the leg above hip height and arching the lower back.","Rotating or hiking the hip on the side of the raised leg.","Swinging through fast reps instead of holding the position.","Holding the breath during the hold."],"ru":["Поднимать ногу выше таза и прогибаться в пояснице.","Разворачивать или задирать таз со стороны поднятой ноги.","Махать руками и ногами в быстром темпе вместо удержания позиции.","Задерживать дыхание во время удержания."]},"startLoad":{"kg":0,"source":"Bodyweight drill: no external load; progress the hold, then the squares variant (McGill & Karpowicz 2009)."},"tags":["owner-alt","core"],"images":[],"sources":["Exercises for spine stabilization: motion/motor patterns, stability progressions and clinical technique (McGill & Karpowicz) — Arch Phys Med Rehabil, 2009. https://pubmed.ncbi.nlm.nih.gov/19154838/","To crunch or not to crunch: spinal flexion exercises, their potential risks and program design (Contreras & Schoenfeld) — Strength Cond J, 2011. https://doi.org/10.1519/SSC.0b013e3182259d05"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dead-bug","equipment_id":"bodyweight","name":{"en":"Dead bug","ru":"Мёртвый жук"},"pattern":"anti-extension","details":{"id":"dead-bug","class":"spine-stability","pattern":"anti-extension","name":{"en":"Dead bug","ru":"Мёртвый жук"},"aka":["Dying bug","Supine opposite arm and leg lowering","Опускание руки и ноги лёжа на спине"],"equipment":"bodyweight","primary":["rectus-abdominis","transverse-abdominis"],"secondary":["obliques","hip-flexors"],"difficulty":1,"unilateral":true,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[6,12],"alternatives":["plank","ab-wheel-rollout","bird-dog","side-plank","mcgill-curl-up"],"setup":{"en":"Lie on your back with hips and knees bent to 90° and arms pointing at the ceiling. At first, slide one hand under your lower back to feel that it does not move, and work the other arm with the opposite leg.","ru":"Лягте на спину, согните бёдра и колени под 90°, руки направьте в потолок. На первых подходах подложите одну ладонь под поясницу, чтобы чувствовать, что она не двигается, и работайте другой рукой в паре с противоположной ногой."},"cues":{"en":["Brace first: ribs down toward the pelvis, lower back still.","Exhale and lower one arm overhead and the opposite leg toward the floor over 3 s.","Stop just above the floor, or earlier if your lower back starts to lift off your hand.","Pause, bring both limbs back and switch sides; reps are counted per side.","Keep the head and shoulders relaxed on the floor.","Progress: straighter legs, then a light dumbbell in the hands."],"ru":["Сначала напрягите пресс: рёбра опущены к тазу, поясница неподвижна.","На выдохе за 3 секунды опустите одну руку за голову, а противоположную ногу — к полу.","Остановитесь чуть выше пола или раньше, если поясница начинает отрываться от ладони.","Задержитесь, верните руку и ногу в исходное положение и смените сторону; повторы считаются на каждую сторону.","Голова и плечи спокойно лежат на полу.","Усложнение: более прямые ноги, затем лёгкая гантель в руках."]},"mistakes":{"en":["Lower back arching off the floor as the leg goes down — the range is too big.","Rushing and swinging the arms and legs.","Holding the breath instead of exhaling as the limbs extend.","Lifting the head and straining the neck."],"ru":["Поясница отрывается от пола, когда нога опускается, — амплитуда слишком большая.","Спешить и махать руками и ногами.","Задерживать дыхание вместо выдоха при выпрямлении рук и ног.","Поднимать голову и напрягать шею."]},"startLoad":{"kg":0,"source":"Bodyweight drill: progress the lever length (straighter legs) before adding a light dumbbell."},"tags":["core"],"images":[],"sources":["Exercises for spine stabilization: motion/motor patterns, stability progressions and clinical technique (McGill & Karpowicz) — Arch Phys Med Rehabil, 2009. https://pubmed.ncbi.nlm.nih.gov/19154838/","Exercise technique: the dead bug (Mullane, Turner & Bishop) — Strength Cond J, 2019. https://doi.org/10.1519/SSC.0000000000000455"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"plank","equipment_id":"bodyweight","name":{"en":"Plank","ru":"Планка"},"pattern":"anti-extension","details":{"id":"plank","class":"spine-stability","pattern":"anti-extension","name":{"en":"Plank","ru":"Планка"},"aka":["Front plank","Front bridge","Hover","Планка на локтях"],"equipment":"bodyweight","primary":["rectus-abdominis","transverse-abdominis"],"secondary":["obliques","serratus-anterior","delt-front","glute-max"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[20,60],"repUnit":"seconds","alternatives":["dead-bug","ab-wheel-rollout","side-plank","bird-dog"],"setup":{"en":"Forearms on the floor with elbows under the shoulders, legs straight, feet hip-width apart. Lift the body into one straight line from head to heels.","ru":"Упор на предплечья, локти под плечами, ноги прямые, стопы на ширине таза. Поднимите тело в одну прямую линию от головы до пяток."},"cues":{"en":["Squeeze the glutes hard and draw the pubic bone slightly toward the belly button so the lower back doesn''t sag.","Brace the abs as if for a punch and keep the ribs down.","Push the floor away with the forearms; shoulders stay away from the ears.","Neck long, eyes on the floor just ahead of the hands.","Breathe in short, controlled breaths without letting the brace go.","When 60 s is easy, make it harder, not longer: elbows about 15 cm apart at nose level, feet together, glutes squeezed (long-lever plank)."],"ru":["Сильно сожмите ягодицы и слегка подтяните лобковую кость к пупку, чтобы поясница не проваливалась.","Напрягите пресс, как перед ударом, рёбра опущены.","Отталкивайте пол предплечьями, плечи подальше от ушей.","Шея длинная, взгляд в пол чуть впереди кистей.","Дышите короткими контролируемыми вдохами, не отпуская напряжения пресса.","Когда 60 секунд даются легко, усложняйте, а не удлиняйте: локти примерно в 15 см друг от друга на уровне носа, стопы вместе, ягодицы сжаты (планка с длинным рычагом)."]},"mistakes":{"en":["Hips sagging toward the floor so the lower back hangs into an arch.","Hips piked high to take the load off the abs.","Head hanging or craned up; shoulders shrugged.","Chasing multi-minute holds with sloppy form instead of moving to a harder variation.","Holding the breath."],"ru":["Таз проседает к полу, и поясница прогибается.","Таз задран вверх, чтобы снять нагрузку с пресса.","Голова свисает или задрана, плечи подняты.","Стоять по несколько минут с плохой техникой вместо перехода к более трудному варианту.","Задерживать дыхание."]},"tags":["core"],"images":[],"sources":["Exercise technique: the long-lever posterior-tilt plank (Schoenfeld & Contreras) — Strength Cond J, 2013. https://doi.org/10.1519/SSC.0b013e31828226d5","EMG comparison of the long-lever posterior-tilt plank and the traditional plank (Schoenfeld et al.) — Sports Biomech, 2014. https://pubmed.ncbi.nlm.nih.gov/25325773/","New study puts the crunch on ineffective ab exercises (ACE-commissioned EMG study, San Diego State University) — ACE FitnessMatters, 2001. https://www.acefitness.org/getfit/studies/BestWorstAbExercises.pdf"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"side-plank","equipment_id":"bodyweight","name":{"en":"Side plank","ru":"Боковая планка"},"pattern":"lateral-flexion","details":{"id":"side-plank","class":"spine-stability","pattern":"lateral-flexion","name":{"en":"Side plank","ru":"Боковая планка"},"aka":["Side bridge (McGill ''big 3'')","Side support","Боковой мост"],"equipment":"bodyweight","primary":["obliques","quadratus-lumborum"],"secondary":["transverse-abdominis","glute-med","rectus-abdominis"],"difficulty":1,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[20,45],"repUnit":"seconds","alternatives":["suitcase-carry","plank","bird-dog","dead-bug","pallof-press"],"setup":{"en":"Lie on your side with the elbow directly under the shoulder, legs straight, top foot in front of the bottom one. Beginners start from the knees, knees bent to 90°.","ru":"Лягте на бок, локоть точно под плечом, ноги прямые, стопа верхней ноги стоит перед нижней. Новичкам — начинать с упора на колени, согнутые под 90°."},"cues":{"en":["Lift the hips until the body is a straight line from head to feet.","Lock the ribcage to the pelvis: don''t roll the chest forward or the hips back.","Push the floor away with the elbow so the shoulder doesn''t sink toward the ear.","Rest the top hand on the opposite shoulder, later on the hip.","Breathe steadily through the whole hold; give both sides the same time.","Progress: knees → feet → a slow roll through a plank to the other side."],"ru":["Поднимите таз, чтобы тело вытянулось в прямую линию от головы до стоп.","Зафиксируйте рёбра относительно таза: не заваливайте ни грудь вперёд, ни таз назад.","Отталкивайте пол локтем, чтобы плечо не проваливалось к уху.","Верхнюю руку положите на противоположное плечо, позже — на бедро.","Ровно дышите всё удержание; на обе стороны держите одинаковое время.","Усложнение: колени → стопы → медленный перекат через планку на другой бок."]},"mistakes":{"en":["Hips sagging toward the floor.","Twisting: the chest rolls toward the floor or the hips drift back.","Elbow placed away from the shoulder, so the shoulder joint takes the load.","Holding the breath."],"ru":["Таз проседает к полу.","Скручиваться: грудь заваливается к полу или таз уходит назад.","Локоть стоит не под плечом, и нагрузку берёт на себя плечевой сустав.","Задерживать дыхание."]},"tags":["core"],"images":[],"sources":["Exercises for spine stabilization: motion/motor patterns, stability progressions and clinical technique (McGill & Karpowicz) — Arch Phys Med Rehabil, 2009. https://pubmed.ncbi.nlm.nih.gov/19154838/","Intramuscular activity of psoas and the abdominal wall during a wide variety of tasks (Juker et al.) — Med Sci Sports Exerc, 1998. https://pubmed.ncbi.nlm.nih.gov/9502361/","Endurance times for low back stabilization exercises: a normal database (McGill, Childs & Liebenson) — Arch Phys Med Rehabil, 1999. https://pubmed.ncbi.nlm.nih.gov/10453772/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-crunch","equipment_id":"selectorized","name":{"en":"Seated machine crunch","ru":"Скручивания в тренажёре сидя"},"pattern":"trunk-flexion","details":{"id":"machine-crunch","class":"trunk-flexion","pattern":"trunk-flexion","name":{"en":"Seated machine crunch","ru":"Скручивания в тренажёре сидя"},"aka":["Ab crunch machine","Technogym Selection/Element Abdominal Crunch","Life Fitness Insignia Abdominal","Matrix Ultra Abdominal Crunch","Nautilus Inspiration Abdominal Crunch","Тренажёр для пресса"],"equipment":"selectorized","primary":["rectus-abdominis"],"secondary":["obliques"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["cable-crunch","bicycle-crunch","mcgill-curl-up","reverse-crunch","ab-wheel-rollout","decline-sit-up"],"setup":{"en":"Set the seat so the handles (or shoulder pads) sit just above your shoulders when you sit tall with your back to the pad. Rest the feet on the foot plate or lightly under the rollers and hold the handles with the elbows bent.","ru":"Отрегулируйте сиденье так, чтобы рукояти (или наплечники) были чуть выше плеч, когда вы сидите прямо, спиной к спинке. Стопы — на подставке или без усилия под валиками, рукояти держите согнутыми руками."},"cues":{"en":["Exhale hard and curl the ribs down toward the pelvis — round the spine like rolling up a mat; don''t fold at the hips.","The arms only hold the handles; the abs pull, not the shoulders.","Keep the hips on the seat and don''t pull with the legs — that hands the work to the hip flexors.","The head moves with the trunk: chin slightly tucked, neck still.","Squeeze for 1 s in the fully curled position.","Uncurl over 2–3 s until the plates almost touch, then start the next rep."],"ru":["На мощном выдохе скручивайтесь: рёбра тянутся к тазу, спина округляется, как сворачиваемый коврик; не сгибайтесь в тазобедренных суставах.","Руки только держат рукояти; тянет пресс, а не плечи.","Таз прижат к сиденью, ногами не тяните — иначе работу заберут сгибатели бедра.","Голова движется вместе с корпусом: подбородок слегка опущен, шея неподвижна.","В положении полного скручивания задержитесь на 1 секунду, сжимая пресс.","Разгибайтесь за 2–3 секунды, пока плиты почти не коснутся стопки, и начинайте следующий повтор."]},"mistakes":{"en":["Pulling the handles down with the arms and shoulders instead of curling with the abs.","Hinging forward at the hips with a flat back: the hip flexors move the weight and the abs barely work.","Ego loading: a stack so heavy you jerk the first few centimetres and lose control on the way back.","Letting the plates crash and yank you back into an arch.","Hard flexion work within an hour of waking or straight after long sitting, when the discs tolerate bending least."],"ru":["Тянуть рукояти вниз руками и плечами вместо скручивания прессом.","Наклоняться вперёд с прямой спиной: вес двигают сгибатели бедра, а пресс почти не работает.","Вес «на эго»: рывок в первые сантиметры и потеря контроля на обратном ходе.","Отпускать вес, позволяя плитам рывком разгибать вас назад.","Тяжёлые скручивания в первый час после сна или сразу после долгого сидения, когда диски хуже всего переносят сгибание."]},"startLoad":{"kg":15,"source":"≈0.5–0.6 × the Strength Level Beginner 1RM for the machine seated crunch (29 kg at 80 kg body weight), rounded down to a pin step."},"tags":["owner-primary","core"],"images":[],"sources":["Machine seated crunch strength standards, male by body weight — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-seated-crunch/kg","Selection 700 Abdominal Crunch: Smart Pin half-weight plate, foot supports that keep the hip flexors out — Technogym, 2026. https://www.technogym.com/en-CA/product/selection-700-abdominal-crunch_MNBC.html","To crunch or not to crunch: spinal flexion exercises, their potential risks and program design (Contreras & Schoenfeld) — Strength Cond J, 2011. https://doi.org/10.1519/SSC.0b013e3182259d05"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"cable-crunch","equipment_id":"cable","name":{"en":"Kneeling cable crunch","ru":"Скручивания на блоке стоя на коленях"},"pattern":"trunk-flexion","details":{"id":"cable-crunch","class":"trunk-flexion","pattern":"trunk-flexion","name":{"en":"Kneeling cable crunch","ru":"Скручивания на блоке стоя на коленях"},"aka":["Cable crunch","Rope crunch","High-pulley crunch","«Молитва»"],"equipment":"cable","primary":["rectus-abdominis"],"secondary":["obliques"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["machine-crunch","bicycle-crunch","mcgill-curl-up","reverse-crunch","ab-wheel-rollout","decline-sit-up"],"setup":{"en":"Attach a rope to a high pulley and kneel facing the stack, about a forearm''s length away. Hold the rope ends beside your forehead and keep the hips over the knees, not back on the heels.","ru":"Закрепите канат на верхнем блоке и встаньте на колени лицом к стойке, примерно на длину предплечья от неё. Держите концы каната у лба, таз над коленями, а не на пятках."},"cues":{"en":["Lock the hips in place: they stay over the knees for the whole set.","Exhale and curl the ribs toward the pelvis, bringing the elbows toward the middle of the thighs.","Hands stay fixed beside the head — the arms don''t pull.","Pause and squeeze for 1 s at the bottom.","Return over 2–3 s until the trunk is upright, without letting the stack pull you up and back."],"ru":["Зафиксируйте таз: весь подход он остаётся над коленями.","На выдохе скручивайтесь, подтягивая рёбра к тазу, а локти — к середине бёдер.","Кисти неподвижны у головы — руки не тянут.","Внизу задержитесь на 1 секунду, сжимая пресс.","Возвращайтесь за 2–3 секунды до вертикального корпуса, не позволяя блоку тянуть вас вверх и назад."]},"mistakes":{"en":["Sitting back on the heels and hinging at the hips, so body weight moves the stack instead of the abs.","Pulling the rope down with the arms.","Jerking the weight down and letting it snap you back up.","Ego loading: if the hips start moving, the stack is too heavy.","Twisting under load at the bottom — flexion plus twist is the classic disc-injury mechanism."],"ru":["Садиться на пятки и сгибаться в тазобедренных суставах: стопку двигает вес тела, а не пресс.","Тянуть канат руками.","Дёргать вес вниз и позволять ему рывком выпрямлять вас.","Вес «на эго»: если начинает двигаться таз, вес слишком большой.","Скручиваться с поворотом корпуса под нагрузкой — сгибание вместе с поворотом классически травмирует межпозвонковые диски."]},"startLoad":{"kg":15,"source":"≈0.6 × the Strength Level Beginner 1RM for the cable crunch (26 kg at 80 kg body weight)."},"tags":["owner-alt","core"],"images":[],"sources":["Cable crunch strength standards, male by body weight — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-crunch/kg","To crunch or not to crunch: spinal flexion exercises, their potential risks and program design (Contreras & Schoenfeld) — Strength Cond J, 2011. https://doi.org/10.1519/SSC.0b013e3182259d05","The role of axial torque in disc herniation (Marshall & McGill) — Clin Biomech, 2010. https://pubmed.ncbi.nlm.nih.gov/19815318/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"decline-sit-up","equipment_id":"bodyweight","name":{"en":"Decline sit-up","ru":"Подъём корпуса на скамье для пресса"},"pattern":"trunk-flexion","details":{"id":"decline-sit-up","class":"trunk-flexion","pattern":"trunk-flexion","name":{"en":"Decline sit-up","ru":"Подъём корпуса на скамье для пресса"},"aka":["Decline bench sit-up","Weighted decline sit-up","Подъём туловища на наклонной скамье"],"equipment":"bodyweight","primary":["rectus-abdominis"],"secondary":["hip-flexors","obliques"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"high","lengthenedBias":false,"increment":0,"repRange":[8,15],"alternatives":["bicycle-crunch","mcgill-curl-up","machine-crunch","cable-crunch","reverse-crunch","captains-chair-knee-raise"],"setup":{"en":"Set a decline ab bench to a moderate angle, hook your feet under the rollers and lie back with the knees bent. Cross your arms on your chest; to load it, hug a weight plate to the chest.","ru":"Установите скамью для пресса под умеренным углом, зацепитесь стопами за валики и лягте на спину, колени согнуты. Скрестите руки на груди; для нагрузки прижмите к груди блин."},"cues":{"en":["Start every rep with a curl: head, shoulders and ribs peel off the bench first.","Sit up until the trunk is nearly upright, then go straight back down — no resting at the top.","Exhale on the way up, inhale on the way down.","Lower over 2–3 s, uncurling the spine back onto the bench.","Make it harder with a steeper bench or a heavier plate only after 15 clean reps."],"ru":["Начинайте каждый повтор со скручивания: сначала от скамьи отрываются голова, плечи и рёбра.","Поднимайтесь почти до вертикали и сразу опускайтесь — без отдыха вверху.","Выдох — на подъёме, вдох — на опускании.","Опускайтесь за 2–3 секунды, раскручивая позвоночник обратно на скамью.","Увеличивайте наклон скамьи или вес блина, только когда 15 чистых повторов даются легко."]},"mistakes":{"en":["Yanking up with a flat back by pulling on the foot rollers — the hip flexors take over and compress the lumbar spine.","Pulling on the head with the hands.","Dropping back onto the bench.","Twisting elbow-to-knee while holding a plate: loaded flexion plus twist is the disc-injury mechanism.","Doing them with an irritable lower back — sit-ups are among the most spine-loading ab exercises; use a crunch or curl-up instead."],"ru":["Рывком поднимать прямую спину, цепляясь стопами за валики, — работу берут сгибатели бедра и сжимают поясничный отдел.","Тянуть себя руками за голову.","Падать на скамью при опускании.","Поворачиваться локтем к колену с блином в руках: нагруженное сгибание с поворотом травмирует диски.","Делать их при ноющей пояснице: подъёмы корпуса — одно из самых нагружающих позвоночник упражнений на пресс; выберите вместо них скручивания."]},"startLoad":{"kg":0,"source":"Bodyweight first; hug a 2.5–5 kg plate only after 15 clean reps."},"tags":["owner-alt","core"],"images":[],"sources":["Low back loads over a variety of abdominal exercises: searching for the safest abdominal challenge (Axler & McGill) — Med Sci Sports Exerc, 1997. https://pubmed.ncbi.nlm.nih.gov/9219209/","Intramuscular activity of psoas and the abdominal wall during a wide variety of tasks (Juker et al.) — Med Sci Sports Exerc, 1998. https://pubmed.ncbi.nlm.nih.gov/9502361/","Electromyographic analysis of traditional and nontraditional abdominal exercises (Escamilla et al.) — Physical Therapy, 2006. https://pubmed.ncbi.nlm.nih.gov/16649890/","The role of axial torque in disc herniation (Marshall & McGill) — Clin Biomech, 2010. https://pubmed.ncbi.nlm.nih.gov/19815318/"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"bicycle-crunch","equipment_id":"bodyweight","name":{"en":"Bicycle crunch","ru":"Скручивания „велосипед“"},"pattern":"trunk-flexion","details":{"id":"bicycle-crunch","class":"trunk-flexion","pattern":"trunk-flexion","name":{"en":"Bicycle crunch","ru":"Скручивания „велосипед“"},"aka":["Bicycle maneuver","Cross-body bicycle crunch","Велосипед"],"equipment":"bodyweight","primary":["rectus-abdominis","obliques"],"secondary":["hip-flexors"],"difficulty":1,"unilateral":true,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[10,20],"alternatives":["mcgill-curl-up","machine-crunch","cable-crunch","captains-chair-knee-raise","reverse-crunch","decline-sit-up"],"setup":{"en":"Lie on your back with the lower back lightly pressed to the floor and fingertips beside your head. Lift the knees to about 45° and the shoulder blades just off the floor.","ru":"Лягте на спину, поясница слегка прижата к полу, кончики пальцев у висков. Поднимите колени примерно на 45°, лопатки чуть оторвите от пола."},"cues":{"en":["Pedal slowly: one leg straightens low while the other knee comes in.","Turn the ribcage so the shoulder, not just the elbow, travels toward the opposite knee.","Keep the lower back on the floor; straighten the leg higher if it starts to arch.","About 2 s per side with even, relaxed breathing; reps are counted per side.","Hands only cradle the head; elbows stay wide."],"ru":["Крутите «педали» медленно: одна нога выпрямляется низко над полом, другое колено подтягивается.","Поворачивайте грудную клетку так, чтобы к противоположному колену шло плечо, а не только локоть.","Поясница остаётся на полу; если она начинает прогибаться, выпрямляйте ногу выше.","Около 2 секунд на сторону, дыхание ровное и спокойное; повторы считаются на каждую сторону.","Руки только поддерживают голову, локти разведены."]},"mistakes":{"en":["Yanking the head forward with the hands.","Flapping the elbows without turning the ribcage.","Racing through reps on momentum.","Lower back arching as the straight leg drops too low."],"ru":["Тянуть голову вперёд руками.","Водить локтями, не поворачивая грудную клетку.","Гнать повторы по инерции.","Прогибаться в пояснице, когда прямая нога опускается слишком низко."]},"startLoad":{"kg":0,"source":"Bodyweight exercise: progress with a slower tempo and more reps, not load."},"tags":["owner-alt","core"],"images":[],"sources":["New study puts the crunch on ineffective ab exercises (ACE-commissioned EMG study, San Diego State University) — ACE FitnessMatters, 2001. https://www.acefitness.org/getfit/studies/BestWorstAbExercises.pdf","To crunch or not to crunch: spinal flexion exercises, their potential risks and program design (Contreras & Schoenfeld) — Strength Cond J, 2011. https://doi.org/10.1519/SSC.0b013e3182259d05"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"mcgill-curl-up","equipment_id":"bodyweight","name":{"en":"McGill curl-up","ru":"Скручивание по Макгиллу"},"pattern":"trunk-flexion","details":{"id":"mcgill-curl-up","class":"trunk-flexion","pattern":"trunk-flexion","name":{"en":"McGill curl-up","ru":"Скручивание по Макгиллу"},"aka":["Modified curl-up","Curl-up (McGill ''big 3'')","Скручивание Макгилла"],"equipment":"bodyweight","primary":["rectus-abdominis"],"secondary":["obliques","transverse-abdominis"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[5,10],"alternatives":["bicycle-crunch","machine-crunch","cable-crunch","dead-bug","plank"],"setup":{"en":"Lie on your back with one knee bent and the other leg straight. Slide both hands, palms down, under the arch of your lower back to keep its natural curve.","ru":"Лягте на спину, одну ногу согните в колене, другую выпрямите. Подложите обе ладони под поясничный прогиб, чтобы сохранить его естественную форму."},"cues":{"en":["Brace the abdominal wall: stiffen it without sucking it in or pushing it out.","Lift the head and shoulders just off the floor as one unit, pivoting at the breastbone.","Keep the neck straight and the curve of the lower back unchanged — it is a small movement.","Hold 5–10 s while breathing, lower, repeat; swap the bent leg halfway through the set.","Progress: lift the elbows off the floor, then take deep breaths during the hold."],"ru":["Напрягите стенку живота: сделайте её жёсткой, не втягивая и не выпячивая.","Приподнимите голову и плечи над полом единым блоком, словно вращаясь вокруг грудины.","Шея прямая, прогиб в пояснице не меняется — движение очень маленькое.","Удерживайте 5–10 секунд, продолжая дышать, опуститесь и повторите; на середине подхода смените согнутую ногу.","Усложнение: оторвите локти от пола, затем глубоко дышите во время удержания."]},"mistakes":{"en":["Flattening the lower back into the floor instead of keeping its curve.","Cranking the chin to the chest — the neck bends instead of the trunk lifting.","Coming up too high and turning it into a sit-up.","Holding the breath."],"ru":["Прижимать поясницу к полу вместо сохранения её естественного прогиба.","Тянуть подбородок к груди — сгибается шея, а не поднимается корпус.","Подниматься слишком высоко, превращая упражнение в подъём корпуса.","Задерживать дыхание."]},"startLoad":{"kg":0,"source":"Bodyweight drill (McGill''s ''big 3''): progress the hold and the elbows-up variant, not load."},"tags":["owner-alt","core"],"images":[],"sources":["Exercises for spine stabilization: motion/motor patterns, stability progressions and clinical technique (McGill & Karpowicz) — Arch Phys Med Rehabil, 2009. https://pubmed.ncbi.nlm.nih.gov/19154838/","Low back loads over a variety of abdominal exercises: searching for the safest abdominal challenge (Axler & McGill) — Med Sci Sports Exerc, 1997. https://pubmed.ncbi.nlm.nih.gov/9219209/","Intramuscular activity of psoas and the abdominal wall during a wide variety of tasks (Juker et al.) — Med Sci Sports Exerc, 1998. https://pubmed.ncbi.nlm.nih.gov/9502361/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"captains-chair-knee-raise","equipment_id":"bodyweight","name":{"en":"Captain''s chair knee raise","ru":"Подъём коленей в упоре на локтях"},"pattern":"hip-flexion","details":{"id":"captains-chair-knee-raise","class":"lower-ab-flexion","pattern":"hip-flexion","name":{"en":"Captain''s chair knee raise","ru":"Подъём коленей в упоре на локтях"},"aka":["Captain''s chair","Vertical knee raise (VKR)","Hammer Strength VKR","Life Fitness Dip/Leg Raise","Подъём ног в упоре на брусьях","Капитанский стул"],"equipment":"bodyweight","primary":["rectus-abdominis"],"secondary":["hip-flexors","obliques"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[8,15],"alternatives":["reverse-crunch","bicycle-crunch","machine-crunch","cable-crunch","ab-wheel-rollout"],"setup":{"en":"Back against the pad, forearms on the elbow pads, hands on the grips. Press down through the forearms so the shoulders sit low, away from the ears, and let the legs hang still.","ru":"Спина прижата к спинке, предплечья на подлокотниках, кисти на рукоятях. Давите предплечьями вниз, чтобы плечи были опущены, подальше от ушей, ноги висят неподвижно."},"cues":{"en":["Exhale and lift the knees toward the chest without swinging.","Past hip height, curl the pelvis up toward the ribs, pressing the lower back lightly into the pad — this last part is where the abs work.","Pause for 1 s at the top.","Lower over 2–3 s to a straight hang without letting the legs swing back.","Keep pressing down through the forearms for the whole set.","When every set reaches the top of your rep range with strict reps, squeeze a light (2–4 kg) dumbbell between the feet or raise straight legs."],"ru":["На выдохе поднимайте колени к груди без раскачки.","Когда колени выше таза, подкрутите таз к рёбрам, слегка прижимая поясницу к спинке, — именно здесь работает пресс.","Задержитесь вверху на 1 секунду.","Опускайте ноги за 2–3 секунды до прямого виса, не давая им раскачиваться назад.","Весь подход продолжайте давить предплечьями в подлокотники.","Когда во всех подходах выходит верх диапазона строгих повторов, зажмите между стопами лёгкую гантель (2–4 кг) или поднимайте прямые ноги."]},"mistakes":{"en":["Swinging the legs and using momentum.","Stopping at hip height: that is mostly hip flexors; the abs work in the pelvic curl.","Shoulders shrugged to the ears, hanging on the joints instead of pressing down.","Dropping the legs fast and arching the lower back off the pad at the bottom.","Holding the breath."],"ru":["Раскачивать ноги и работать по инерции.","Останавливаться на уровне таза: это в основном работа сгибателей бедра, пресс включается при подкручивании таза.","Плечи подняты к ушам, тело «висит» на суставах вместо упора предплечьями.","Бросать ноги вниз и отрывать поясницу от спинки в нижней точке.","Задерживать дыхание."]},"startLoad":{"kg":0,"source":"Bodyweight first; add a 2–4 kg dumbbell between the feet only when every set reaches the top of the rep range with strict reps."},"tags":["owner-primary","core"],"images":[],"sources":["New study puts the crunch on ineffective ab exercises (ACE-commissioned EMG study, San Diego State University) — ACE FitnessMatters, 2001. https://www.acefitness.org/getfit/studies/BestWorstAbExercises.pdf","Electromyographic analysis of traditional and nontraditional abdominal exercises (Escamilla et al.) — Physical Therapy, 2006. https://pubmed.ncbi.nlm.nih.gov/16649890/","Muscle activity and spine load during the body saw, hanging leg raise and walkout from a push-up (McGill, Andersen & Cannon) — J Sports Sci, 2015. https://pubmed.ncbi.nlm.nih.gov/25111163/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"reverse-crunch","equipment_id":"bodyweight","name":{"en":"Reverse crunch","ru":"Обратные скручивания"},"pattern":"hip-flexion","details":{"id":"reverse-crunch","class":"lower-ab-flexion","pattern":"hip-flexion","name":{"en":"Reverse crunch","ru":"Обратные скручивания"},"aka":["Lying knee-to-chest raise","Incline reverse crunch","Обратные скручивания на наклонной скамье"],"equipment":"bodyweight","primary":["rectus-abdominis"],"secondary":["obliques","hip-flexors"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[8,15],"alternatives":["captains-chair-knee-raise","bicycle-crunch","dead-bug","machine-crunch","cable-crunch"],"setup":{"en":"Lie on your back on the floor or a flat bench, arms by your sides or hands gripping the bench behind your head. Lift the legs with the knees bent at 90° and the thighs vertical.","ru":"Лягте на спину на пол или горизонтальную скамью, руки вдоль корпуса или держитесь за скамью за головой. Поднимите ноги: колени согнуты под 90°, бёдра вертикально."},"cues":{"en":["Exhale and curl the pelvis up off the floor, rolling the knees toward the chest — the hips lift, the legs don''t swing.","Think ''tailbone to the ceiling'': a small, slow curl of the lower spine.","Pause for 1 s with the hips up.","Lower the hips over 2–3 s until the tailbone touches down, knees still at 90°.","Progress on a bench inclined about 30°, head end higher, holding on behind your head."],"ru":["На выдохе подкрутите таз и оторвите его от пола, подтягивая колени к груди, — поднимается таз, ноги не раскачиваются.","Думайте «копчик к потолку»: небольшое медленное скручивание нижней части позвоночника.","Задержитесь на 1 секунду с поднятым тазом.","Опускайте таз за 2–3 секунды, пока копчик не коснётся опоры; колени по-прежнему согнуты под 90°.","Усложнение: скамья под углом около 30°, голова выше ног, держитесь за скамью за головой."]},"mistakes":{"en":["Swinging the legs to throw the hips up.","Pushing off the floor with the hands.","Letting the knees drift away from the chest, which turns it into a leg raise and arches the lower back.","Dropping the hips back down fast."],"ru":["Раскачивать ноги, чтобы забросить таз вверх.","Отталкиваться руками от пола.","Отпускать колени от груди — упражнение превращается в подъём ног, и поясница прогибается.","Резко бросать таз вниз."]},"startLoad":{"kg":0,"source":"Bodyweight; progress to a 30° incline bench before adding load."},"tags":["owner-alt","core"],"images":[],"sources":["New study puts the crunch on ineffective ab exercises (ACE-commissioned EMG study, San Diego State University) — ACE FitnessMatters, 2001. https://www.acefitness.org/getfit/studies/BestWorstAbExercises.pdf","Electromyographic analysis of traditional and nontraditional abdominal exercises (Escamilla et al.) — Physical Therapy, 2006. https://pubmed.ncbi.nlm.nih.gov/16649890/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"hanging-leg-raise","equipment_id":"bodyweight","name":{"en":"Hanging leg raise","ru":"Подъём ног в висе"},"pattern":"hip-flexion","details":{"id":"hanging-leg-raise","class":"lower-ab-flexion","pattern":"hip-flexion","name":{"en":"Hanging leg raise","ru":"Подъём ног в висе"},"aka":["Hanging straight-leg raise","Hanging knee raise (easier)","Toes-to-bar (harder)","Подъём прямых ног в висе на перекладине"],"equipment":"bodyweight","primary":["rectus-abdominis"],"secondary":["hip-flexors","obliques","forearm-flexors","lats"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":0,"repRange":[6,12],"alternatives":["captains-chair-knee-raise","reverse-crunch","ab-wheel-rollout","machine-crunch","cable-crunch"],"setup":{"en":"Hang from a pull-up bar with an overhand, shoulder-width grip; use straps or ab slings if your grip gives out first. Pull the shoulders slightly down from the ears and stop any swing before the first rep.","ru":"Повисните на перекладине прямым хватом на ширине плеч; если первым сдаёт хват — используйте лямки или петли для пресса. Слегка опустите плечи от ушей и погасите раскачку перед первым повтором."},"cues":{"en":["Brace and tilt the pelvis back slightly before the legs move.","Exhale and raise straight legs to at least horizontal, then keep curling the pelvis up toward the bar.","If straight legs aren''t possible yet, bend the knees (hanging knee raise) and straighten them gradually.","Pause for 1 s at the top.","Lower over 2–3 s and kill the swing at the bottom before the next rep."],"ru":["Напрягите пресс и слегка подкрутите таз ещё до того, как поднимать ноги.","На выдохе поднимите прямые ноги минимум до горизонтали и продолжайте подкручивать таз к перекладине.","Если прямые ноги пока не получаются, сгибайте колени (подъём коленей в висе) и выпрямляйте их постепенно.","Задержитесь вверху на 1 секунду.","Опускайте ноги за 2–3 секунды и гасите раскачку внизу перед следующим повтором."]},"mistakes":{"en":["Kipping: swinging the body to throw the legs up.","Lifting the legs only with the hip flexors while the lower back stays arched.","Hanging passively with the shoulders shrugged to the ears.","Dropping the legs and swinging back.","Training it through back pain: the straight-leg version puts about 3000 N of compression on the lumbar spine."],"ru":["Кипинг: раскачиваться всем телом, чтобы забросить ноги.","Поднимать ноги только сгибателями бедра, оставляя поясницу прогнутой.","Висеть пассивно с поднятыми к ушам плечами.","Бросать ноги вниз и раскачиваться назад.","Делать при боли в спине: при подъёме прямых ног сжимающая нагрузка на поясничный отдел — около 3000 Н."]},"startLoad":{"kg":0,"source":"Bodyweight; Strength Level puts an 80 kg beginner at about 1 strict rep and a novice at about 9, so most people start with bent knees."},"tags":["owner-alt","core"],"images":[],"sources":["Muscle activity and spine load during the body saw, hanging leg raise and walkout from a push-up (McGill, Andersen & Cannon) — J Sports Sci, 2015. https://pubmed.ncbi.nlm.nih.gov/25111163/","Electromyographic analysis of traditional and nontraditional abdominal exercises (Escamilla et al.) — Physical Therapy, 2006. https://pubmed.ncbi.nlm.nih.gov/16649890/","Hanging leg raise standards (reps), male by body weight — Strength Level, 2026. https://strengthlevel.com/strength-standards/hanging-leg-raise"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"ab-wheel-rollout","equipment_id":"bodyweight","name":{"en":"Ab wheel rollout","ru":"Раскатка ролика для пресса"},"pattern":"anti-extension","details":{"id":"ab-wheel-rollout","class":"anti-extension","pattern":"anti-extension","name":{"en":"Ab wheel rollout","ru":"Раскатка ролика для пресса"},"aka":["Ab roller rollout","Kneeling rollout","Power Wheel roll-out","Ролик для пресса"],"equipment":"bodyweight","primary":["rectus-abdominis"],"secondary":["obliques","transverse-abdominis","lats"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":true,"increment":0,"repRange":[6,12],"alternatives":["plank","dead-bug","hanging-leg-raise","captains-chair-knee-raise","reverse-crunch","cable-crunch"],"setup":{"en":"Kneel on a mat with the wheel under your shoulders and the arms straight. Before moving, brace hard and tuck the pelvis slightly so the lower back is flat.","ru":"Встаньте на колени на коврик, ролик под плечами, руки прямые. Перед движением сильно напрягите пресс и слегка подкрутите таз, чтобы поясница была ровной."},"cues":{"en":["Roll forward slowly with straight arms; hips and shoulders travel together like one plank.","Go only as far as you can keep the lower back from sagging — the range grows week by week.","Keep the glutes squeezed and the ribs down throughout.","Exhale and pull back by driving the hands toward the knees with the abs and lats.","Progress: longer range → roll out to a wall as a stopper → standing rollouts much later."],"ru":["Медленно катите ролик вперёд на прямых руках; таз и плечи движутся вместе, как одна планка.","Уходите вперёд лишь настолько, насколько поясница не проваливается, — амплитуда растёт от недели к неделе.","Ягодицы сжаты, рёбра опущены весь подход.","На выдохе возвращайтесь, подтягивая руки к коленям усилием пресса и широчайших.","Прогрессия: больше амплитуда → выкат до стены как ограничителя → раскатка стоя — гораздо позже."]},"mistakes":{"en":["Lower back sagging into an arch at the far end — the main injury risk.","Returning hips-first by piking while the abs switch off.","Bending the elbows.","Going for full range in the first sessions."],"ru":["Поясница проваливается в дальней точке — главный риск травмы.","Возвращаться, отводя таз назад «углом» при выключенном прессе.","Сгибать руки в локтях.","Сразу выкатываться на полную амплитуду в первые тренировки."]},"startLoad":{"kg":0,"source":"Bodyweight; Strength Level puts an 80 kg beginner at under one full rollout and a novice at about 8, so start with a short range."},"tags":["core"],"images":[],"sources":["Electromyographic analysis of traditional and nontraditional abdominal exercises (Escamilla et al.) — Physical Therapy, 2006. https://pubmed.ncbi.nlm.nih.gov/16649890/","Core muscle activation during Swiss ball and traditional abdominal exercises (Escamilla et al.) — J Orthop Sports Phys Ther, 2010. https://pubmed.ncbi.nlm.nih.gov/20436242/","Ab wheel rollout standards (reps), male by body weight — Strength Level, 2026. https://strengthlevel.com/strength-standards/ab-wheel-rollout"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"pallof-press","equipment_id":"cable","name":{"en":"Pallof press","ru":"Жим Паллофа"},"pattern":"anti-rotation","details":{"id":"pallof-press","class":"anti-rotation","pattern":"anti-rotation","name":{"en":"Pallof press","ru":"Жим Паллофа"},"aka":["Cable anti-rotation press","Half-kneeling Pallof press","Band Pallof press","Антиротационный жим"],"equipment":"cable","primary":["obliques"],"secondary":["transverse-abdominis","rectus-abdominis","glute-med"],"difficulty":1,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[8,12],"alternatives":["single-arm-cable-row","bird-dog","cable-woodchop","side-plank","suitcase-carry"],"setup":{"en":"Set a D-handle at chest height, stand side-on to the cable and step out until the plates lift off the stack. Feet shoulder-width, knees soft, both hands holding the handle against the breastbone.","ru":"Установите рукоять на уровне груди, встаньте к блоку боком и отойдите, пока плиты не оторвутся от стопки. Стопы на ширине плеч, колени слегка согнуты, обе руки держат рукоять у грудины."},"cues":{"en":["Brace and keep the hips and shoulders square to the front — they must not turn toward the stack.","Exhale and press the handle straight out from the breastbone until the arms are straight.","Hold 2–3 s with the arms straight — that is where the twisting pull on your trunk is greatest.","Bring the hands back to the chest slowly, staying square.","Do all reps facing one way, then turn around; reps are counted per side.","Progress: more weight, a step further from the stack, then a narrower stance or one foot in front of the other."],"ru":["Напрягите пресс, таз и плечи развёрнуты прямо вперёд — они не должны поворачиваться к блоку.","На выдохе выжмите рукоять от грудины строго вперёд до прямых рук.","Задержитесь на прямых руках 2–3 секунды — здесь трос сильнее всего разворачивает корпус.","Медленно верните руки к груди, не разворачиваясь.","Сделайте все повторы в одну сторону, затем развернитесь; повторы считаются на каждую сторону.","Прогрессия: больше вес, шаг дальше от блока, затем более узкая стойка или стопы на одной линии, одна перед другой."]},"mistakes":{"en":["Letting the torso or hips rotate toward the stack.","Pressing diagonally toward the cable instead of straight ahead.","Leaning away from the cable or arching the lower back to fight the load.","Shrugging and pushing with the arms only.","Going too heavy too soon: if you can''t stay square, the weight is too heavy."],"ru":["Позволять корпусу или тазу поворачиваться к блоку.","Выжимать по диагонали в сторону троса, а не строго вперёд.","Отклоняться от блока или прогибать поясницу, чтобы удержать вес.","Поднимать плечи и толкать одними руками.","Слишком большой вес слишком рано: если не удаётся стоять ровно, вес велик."]},"startLoad":{"kg":5,"source":"No published strength standard; ≈7.5% of fat-free mass (the lightest load in a Pallof press EMG methods study) ≈ 5 kg for an 80 kg man on a 1:1 cable."},"tags":["owner-primary","core"],"images":[],"sources":["The Pallof press: technique, coaching points and progressions (Mullane, Turner & Bishop) — Strength Cond J, 2021. https://doi.org/10.1519/SSC.0000000000000596","Anti-rotational and rotational abdominal exercises and concurrent muscle activation: a methodology study (Stephens et al.) — Int J Exerc Sci Conf Proc, 2021. https://digitalcommons.wku.edu/ijesab/vol8/iss9/12","Comparison of different rowing exercises: trunk muscle activation and lumbar spine load (Fenwick, Brown & McGill) — J Strength Cond Res, 2009. https://pubmed.ncbi.nlm.nih.gov/19197209/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"cable-woodchop","equipment_id":"cable","name":{"en":"Cable woodchop","ru":"Дровосек на блоке"},"pattern":"rotation","details":{"id":"cable-woodchop","class":"rotation","pattern":"rotation","name":{"en":"Cable woodchop","ru":"Дровосек на блоке"},"aka":["Cable woodchopper","High-to-low cable chop","Cable chop","Рубка дров на блоке"],"equipment":"cable","primary":["obliques"],"secondary":["rectus-abdominis","transverse-abdominis","glute-max","lats"],"difficulty":2,"unilateral":true,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2.5,"repRange":[8,12],"alternatives":["pallof-press","suitcase-carry","side-plank","bicycle-crunch","rotary-torso-machine"],"setup":{"en":"Set the pulley at the top and stand side-on to it, feet wider than the shoulders, a step away from the stack. Hold the handle with both hands above the near shoulder, arms long.","ru":"Установите блок вверху и встаньте к нему боком, стопы шире плеч, на шаг от стойки. Держите рукоять обеими руками над ближним плечом, руки длинные."},"cues":{"en":["Brace first: the ribcage and pelvis turn together; the lower back does not twist on its own.","Exhale and pull the handle diagonally down across the body to the outside of the far knee, arms staying long.","Turn through the hips and upper back; let the heel nearer the machine lift and pivot so the hips can rotate.","Keep the chest up at the bottom — bend the knees a little rather than rounding forward.","Return slowly along the same diagonal, resisting the cable.","Do all reps to one side, then switch; reps are counted per side."],"ru":["Сначала напрягите пресс: грудная клетка и таз поворачиваются вместе, поясница отдельно не скручивается.","На выдохе ведите рукоять по диагонали вниз через корпус к внешней стороне дальнего колена; руки остаются длинными.","Поворачивайтесь за счёт таза и грудного отдела; пятка ноги, ближней к блоку, отрывается и разворачивается, чтобы таз мог повернуться.","Внизу держите грудь раскрытой — лучше чуть согнуть колени, чем округлить спину.","Медленно возвращайтесь по той же диагонали, сопротивляясь тросу.","Сделайте все повторы в одну сторону, затем смените сторону; повторы считаются на каждую сторону."]},"mistakes":{"en":["Twisting from the lower back with the feet and hips locked.","Rounding forward and twisting at the same time at the bottom — flexion plus twist is the disc-injury mechanism.","Bending the elbows and turning it into an arm pull.","Yanking with momentum and letting the stack snap you back.","Ego loading: the weight must allow a smooth, controlled return."],"ru":["Скручиваться поясницей при неподвижных стопах и тазе.","Внизу одновременно округлять спину и скручиваться — сгибание с поворотом травмирует межпозвонковые диски.","Сгибать локти и превращать упражнение в тягу руками.","Дёргать по инерции и позволять стопке рывком возвращать вас.","Вес «на эго»: нагрузка должна позволять плавно и подконтрольно вернуться."]},"startLoad":{"kg":5,"source":"≈0.6 × the Strength Level Beginner 1RM for the cable woodchopper (8 kg at 80 kg body weight)."},"tags":["core"],"images":[],"sources":["Standing wood chop — ACE Exercise Library, 2026. https://www.acefitness.org/resources/everyone/exercise-library/108","Cable woodchopper strength standards, male by body weight — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-woodchopper/kg","The role of axial torque in disc herniation (Marshall & McGill) — Clin Biomech, 2010. https://pubmed.ncbi.nlm.nih.gov/19815318/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"rotary-torso-machine","equipment_id":"selectorized","name":{"en":"Rotary torso machine","ru":"Повороты корпуса в тренажёре"},"pattern":"rotation","details":{"id":"rotary-torso-machine","class":"rotation","pattern":"rotation","name":{"en":"Rotary torso machine","ru":"Повороты корпуса в тренажёре"},"aka":["Torso rotation machine","Technogym Selection Rotary Torso","Life Fitness Insignia Torso Rotation","Cybex Eagle NX Torso Rotation","Nautilus One Rotary Torso","Тренажёр для косых мышц живота"],"equipment":"selectorized","primary":["obliques"],"secondary":["transverse-abdominis","rectus-abdominis"],"difficulty":1,"unilateral":true,"supported":false,"lowerBackLoad":"high","lengthenedBias":false,"increment":2.5,"repRange":[10,15],"alternatives":["cable-woodchop","pallof-press","bicycle-crunch","side-plank"],"setup":{"en":"Choose a small start angle so you begin only slightly turned. Sit tall with your back to the pad, knees or thighs locked in the pads and hands on the handles (chest against the pad if the machine has one).","ru":"Выберите небольшой стартовый угол, чтобы начинать лишь слегка повернувшись. Сядьте прямо спиной к спинке, колени или бёдра зафиксированы валиками, руки на рукоятях (грудью — к упору, если он есть)."},"cues":{"en":["Sit tall and stay tall: no slumping while you rotate.","Exhale and turn slowly from the ribcage through a short, pain-free range.","Stop well short of your end range: each lumbar joint rotates only about 2°, so most of the turn should come from the upper back.","Pause briefly, then return over 2–3 s without letting the stack swing you back.","Light loads only — this is an optional accessory, not a strength lift.","Finish one side, reset the start angle and do the other; reps are counted per side."],"ru":["Сядьте прямо и сохраняйте это положение: не сутультесь во время поворота.","На выдохе медленно поворачивайтесь от грудной клетки в небольшой безболезненной амплитуде.","Не доходите до крайней точки: каждый поясничный сегмент поворачивается лишь примерно на 2°, поэтому основной поворот должен идти из грудного отдела.","Короткая пауза, затем возвращайтесь за 2–3 секунды, не давая стопке развернуть вас обратно.","Только лёгкий вес — это необязательное вспомогательное упражнение, а не силовое.","Закончите одну сторону, смените стартовый угол и сделайте другую; повторы считаются на каждую сторону."]},"mistakes":{"en":["Slumping forward while twisting — flexion plus twist is the disc-injury mechanism.","Heavy loads and fast reps that bounce at the end range.","Pulling with the arms instead of turning the trunk.","Training it through back pain."],"ru":["Сутулиться во время поворота — сгибание вместе с поворотом травмирует межпозвонковые диски.","Большие веса и быстрые повторы с отбивом в крайней точке.","Тянуть руками вместо поворота корпуса.","Делать упражнение через боль в спине."]},"startLoad":{"kg":10,"source":"No published standard; loaded seated twisting is kept light and optional (porcine disc studies), so start with 1–2 plates (≈10 kg) and 3+ reps in reserve."},"tags":["core"],"images":[],"sources":["The role of axial torque in disc herniation (Marshall & McGill) — Clin Biomech, 2010. https://pubmed.ncbi.nlm.nih.gov/19815318/","Static axial torque in combined loading and intervertebral joint failure, porcine model (Drake et al.) — Clin Biomech, 2005. https://pubmed.ncbi.nlm.nih.gov/16098646/","Axial rotation and lateral bending in the normal lumbar spine measured by 3D radiography (Pearcy & Tibrewal) — Spine, 1984. https://pubmed.ncbi.nlm.nih.gov/6495028/","Selection 900 Rotary Torso: pelvis held by back and knee pads, labelled start angles — Technogym, 2026. https://www.technogym.com/en-SG/product/selection-900-rotary-torso_MNYP.html"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"leg-press-45","equipment_id":"plate-loaded","name":{"en":"45° leg press","ru":"Жим ногами под углом 45°"},"pattern":"squat","details":{"id":"leg-press-45","name":{"en":"45° leg press","ru":"Жим ногами под углом 45°"},"aka":["Sled leg press","Incline leg press","Hammer Strength Plate-Loaded Linear Leg Press","Technogym Pure Strength Linear Leg Press"],"equipment":"plate-loaded","pattern":"squat","class":"squat","primary":["quads","glute-max"],"secondary":["adductors"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[6,12],"alternatives":["seated-leg-press","hack-squat","belt-squat","v-squat","goblet-squat","bulgarian-split-squat","smith-squat"],"setup":{"en":"Sit with your lower back and hips flat on the pad and your feet hip- to shoulder-width in the middle of the platform, toes turned slightly out. Press the sled up and turn the safety handles out before the first rep; if the machine has bottom stops, set them just below your deepest position.","ru":"Сядьте так, чтобы поясница и таз плотно лежали на спинке; стопы на ширине таза–плеч в середине платформы, носки чуть врозь. Выжмите платформу и откройте страховочные рукоятки перед первым повторением; если есть нижние ограничители, выставьте их чуть ниже вашей самой глубокой точки."},"cues":{"en":["Lower the sled under control (2–3 s) as deep as you can while your hips and lower back stay on the pad — for most people a little past 90° at the knee.","Keep your knees in line with your second toe; never let them cave inward.","Push through the whole foot with heels down; feet low on the platform shift work to the quads, feet high to the glutes.","Breathe in and brace before you lower; breathe out as you drive through the hardest part.","Stop just short of locking the knees at the top, then start the next rep.","Turn the safety handles back in before you move your feet or get out."],"ru":["Опускайте платформу подконтрольно (2–3 с), пока таз и поясница остаются прижатыми к спинке, — обычно это чуть глубже 90° в коленях.","Ведите колени по линии второго пальца стопы, не сводите их внутрь.","Давите всей стопой, пятки не отрывайте; стопы ниже на платформе — больше работы квадрицепсам, выше — ягодицам.","Перед опусканием вдохните и напрягите корпус; выдыхайте, проходя самую тяжёлую часть подъёма.","Вверху не выпрямляйте колени до блокировки — остановитесь чуть раньше и начинайте следующее повторение.","Прежде чем переставить ноги или встать, закройте страховочные рукоятки."]},"mistakes":{"en":["Going so deep that the pelvis rolls off the pad and the lower back rounds under load.","Snapping the knees into a hard lockout with a heavy sled.","Knees collapsing inward as you push.","Bouncing off the bottom, or quarter-depth reps with a mountain of plates (ego loading).","Pushing on your knees with your hands or lifting the heels."],"ru":["Слишком глубокое опускание: таз подкручивается и отрывается от спинки, поясница округляется под весом.","Резкое выпрямление коленей до блокировки с тяжёлой платформой.","Колени заваливаются внутрь при выжиме.","Отбив от нижней точки или четверть амплитуды с горой блинов — погоня за весом.","Помощь руками на коленях или отрыв пяток от платформы."]},"startLoad":{"kg":65,"source":"≈0.6 × Strength Level Beginner 1RM (109 kg at 80 kg body weight); count plates only, not the sled"},"tags":["legs","longevity"],"images":[],"sources":["Sled Leg Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/sled-leg-press/kg","Analysis of muscle activation during different leg press exercises at submaximum effort levels — J Strength Cond Res, 2008. https://doi.org/10.1519/JSC.0b013e3181739445","Effects of technique variations on knee biomechanics during the squat and leg press — Med Sci Sports Exerc, 2001. https://doi.org/10.1097/00005768-200109000-00020","Exercise Technique Manual for Resistance Training, 4th ed. — NSCA / Human Kinetics, 2021. https://us.humankinetics.com/products/exercise-technique-manual-for-resistance-training-4th-edition-with-hkpropel-online-video"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"seated-leg-press","equipment_id":"selectorized","name":{"en":"Seated leg press","ru":"Горизонтальный жим ногами сидя"},"pattern":"squat","details":{"id":"seated-leg-press","name":{"en":"Seated leg press","ru":"Горизонтальный жим ногами сидя"},"aka":["Horizontal leg press","Selectorized leg press","Technogym Selection Leg Press","Cybex Eagle NX Leg Press","Nautilus One Leg Press"],"equipment":"selectorized","pattern":"squat","class":"squat","primary":["quads","glute-max"],"secondary":["adductors"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":5,"repRange":[6,12],"alternatives":["leg-press-45","hack-squat","belt-squat","v-squat","goblet-squat","bulgarian-split-squat","smith-squat"],"setup":{"en":"Adjust the seat or backrest so your knees start bent to about 90° with the heels flat on the footplate, feet hip-width. Sit with your hips and lower back against the pad and hold the side handles.","ru":"Отрегулируйте сиденье или спинку так, чтобы в исходной позиции колени были согнуты примерно на 90°, а пятки стояли на платформе; стопы на ширине таза. Таз и поясница прижаты к спинке, руки на боковых рукоятках."},"cues":{"en":["Brace and breathe out as you press the plate away through your heels and midfoot.","Keep the knees tracking over the toes the whole way.","Finish with the knees soft, not locked; the hips stay on the seat.","Return slowly (2–3 s) to the start and let the plates almost touch the stack without resting.","A deeper start trains the quads and glutes through a longer range — only as long as your lower back stays on the pad."],"ru":["Напрягите корпус и на выдохе отталкивайте платформу пятками и серединой стопы.","Колени всё время идут по линии носков.","Вверху колени остаются слегка согнутыми, без блокировки; таз не отрывается от сиденья.","Возвращайтесь медленно (2–3 с): грузы почти касаются стопки, но не ложатся на неё.","Более глубокая исходная позиция нагружает квадрицепсы и ягодицы в большей амплитуде — но только пока поясница прижата к спинке."]},"mistakes":{"en":["Starting so deep that the thighs press into the ribs and the lower back peels off the pad.","Locking the knees out hard at the top.","Knees collapsing inward or heels lifting off the plate.","Letting the stack crash down between reps."],"ru":["Слишком глубокая исходная позиция: бёдра упираются в рёбра, поясница отрывается от спинки.","Резкое выпрямление коленей до блокировки в верхней точке.","Колени заваливаются внутрь или пятки отрываются от платформы.","Грузы с грохотом падают на стопку между повторениями."]},"startLoad":{"kg":45,"source":"≈0.6 × Strength Level Beginner 1RM for the horizontal leg press (76 kg at 80 kg body weight)"},"tags":["legs"],"images":[],"sources":["Horizontal Leg Press Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/horizontal-leg-press/kg","Seated Leg Press — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/154/seated-leg-press/","Analysis of muscle activation during different leg press exercises at submaximum effort levels — J Strength Cond Res, 2008. https://doi.org/10.1519/JSC.0b013e3181739445"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"hack-squat","equipment_id":"plate-loaded","name":{"en":"Hack squat","ru":"Гакк-приседания в тренажёре"},"pattern":"squat","details":{"id":"hack-squat","name":{"en":"Hack squat","ru":"Гакк-приседания в тренажёре"},"aka":["Machine hack squat","Sled hack squat","Hammer Strength Plate-Loaded Hack Squat","Hammer Strength Plate-Loaded Linear Hack Squat"],"equipment":"plate-loaded","pattern":"squat","class":"squat","primary":["quads","glute-max"],"secondary":["adductors"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"moderate","lengthenedBias":true,"increment":2.5,"repRange":[6,12],"alternatives":["v-squat","leg-press-45","seated-leg-press","belt-squat","goblet-squat","bulgarian-split-squat","smith-squat"],"setup":{"en":"Stand on the platform with your back and hips flat against the pad and your shoulders under the pads; feet shoulder-width, slightly ahead of your hips, toes turned out a little. Straighten up and release the safety handles.","ru":"Встаньте на платформу, прижав спину и таз к спинке, плечи — под валиками; стопы на ширине плеч, немного впереди таза, носки чуть врозь. Выпрямитесь и откройте страховочные рукоятки."},"cues":{"en":["Brace, then sit down between your heels under control (2–3 s) to at least thighs parallel to the platform.","Let the knees travel forward over the toes along the line of the second toe; keep the heels down.","Keep your back, hips and head on the pad for the whole rep.","Drive up through the whole foot and breathe out past the hardest point.","Stop just short of locking the knees and go straight into the next rep.","Lock the safety handles before you step off."],"ru":["Напрягите корпус и подконтрольно (2–3 с) опускайтесь между пятками — минимум до параллели бёдер с платформой.","Колени могут выходить вперёд за носки — главное, чтобы шли по линии второго пальца; пятки на платформе.","Спина, таз и голова всё повторение прижаты к спинке.","Вставайте, давя всей стопой, и выдыхайте после самой тяжёлой точки.","Вверху не выпрямляйте колени до блокировки — сразу начинайте следующее повторение.","Закройте страховочные рукоятки, прежде чем сойти с платформы."]},"mistakes":{"en":["Feet so low that the heels lift, or so high that the knees barely bend.","Hips sliding off the pad at the bottom and the lower back rounding.","Knees caving inward on the way up.","Half reps with a heavy load and bouncing out of the bottom."],"ru":["Стопы стоят так низко, что отрываются пятки, или так высоко, что колени почти не сгибаются.","Таз сползает со спинки внизу, поясница округляется.","Колени заваливаются внутрь при подъёме.","Полуповторения с большим весом и отбив из нижней точки."]},"startLoad":{"kg":35,"source":"≈0.55 × Strength Level Beginner 1RM (63 kg at 80 kg body weight); count plates only, not the sled"},"tags":["legs","longevity"],"images":[],"sources":["Hack Squat Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/hack-squat/kg","Trunk muscle activation in the back and hack squat at the same relative loads — J Strength Cond Res, 2019. https://doi.org/10.1519/JSC.0000000000002144","Effect of knee position on hip and knee torques during the barbell squat — J Strength Cond Res, 2003. https://pubmed.ncbi.nlm.nih.gov/14636100/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"v-squat","equipment_id":"plate-loaded","name":{"en":"V-squat machine","ru":"Приседания в рычажном тренажёре (V-squat)"},"pattern":"squat","details":{"id":"v-squat","name":{"en":"V-squat machine","ru":"Приседания в рычажном тренажёре (V-squat)"},"aka":["V-squat","Hammer Strength Plate-Loaded V-Squat","Hammer Strength Pendulum-X Squat","Pendulum squat"],"equipment":"plate-loaded","pattern":"squat","class":"squat","primary":["quads","glute-max"],"secondary":["adductors"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"moderate","lengthenedBias":true,"increment":2.5,"repRange":[6,12],"alternatives":["hack-squat","leg-press-45","seated-leg-press","belt-squat","goblet-squat","bulgarian-split-squat","smith-squat"],"setup":{"en":"Step onto the platform with your back against the back pad and your shoulders under the pads; feet about shoulder-width in the middle of the platform. Stand up and release the racking lever.","ru":"Встаньте на платформу спиной к опорной подушке, плечи под валиками; стопы примерно на ширине плеч в середине платформы. Выпрямитесь и снимите рычаг с фиксатора."},"cues":{"en":["Brace and sit down along the machine''s arc under control (2–3 s) to at least thighs parallel.","Keep the knees in line with the toes and the heels down.","Keep your back on the pad — the curved path already shares the work with the hips.","Drive up through the whole foot, breathing out past the sticking point; stop short of locking the knees.","Re-rack with the lever before you step off."],"ru":["Напрягите корпус и подконтрольно (2–3 с) опускайтесь по дуге тренажёра — минимум до параллели бёдер.","Колени по линии носков, пятки прижаты.","Спина остаётся на подушке: изогнутая траектория уже распределяет работу между коленями и тазом.","Вставайте, давя всей стопой, с выдохом после самой тяжёлой точки; колени до блокировки не выпрямляйте.","Прежде чем сойти, поставьте рычаг на фиксатор."]},"mistakes":{"en":["Rounding the lower back at the bottom as the hips tuck under.","Knees caving in or heels lifting.","Bouncing out of the bottom or cutting depth to move more plates."],"ru":["Округление поясницы внизу, когда таз подкручивается.","Колени заваливаются внутрь или отрываются пятки.","Отбив из нижней точки или неполная глубина ради большего веса."]},"startLoad":{"kg":30,"source":"Estimate: no published standard; ≈0.5 × Strength Level hack-squat Beginner 1RM (63 kg at 80 kg). The Hammer Strength lever adds about 25 kg of starting resistance"},"tags":["legs"],"images":[],"sources":["Hammer Strength Plate-Loaded V-Squat — Life Fitness, n.d. https://www.lifefitness.com/en-eu/catalog/strength-training/plate-loaded/plate-loaded-v-squat","Hack Squat Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/hack-squat/kg","Effects of squat training with different depths on lower limb muscle volumes — Eur J Appl Physiol, 2019. https://doi.org/10.1007/s00421-019-04181-y"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"belt-squat","equipment_id":"plate-loaded","name":{"en":"Belt squat","ru":"Приседания с поясом (белт-сквот)"},"pattern":"squat","details":{"id":"belt-squat","name":{"en":"Belt squat","ru":"Приседания с поясом (белт-сквот)"},"aka":["Belt squat machine","Hip belt squat","Hammer Strength Plate-Loaded Belt Squat","Pit Shark belt squat"],"equipment":"plate-loaded","pattern":"squat","class":"squat","primary":["quads","glute-max"],"secondary":["adductors"],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[6,12],"alternatives":["leg-press-45","seated-leg-press","hack-squat","v-squat","goblet-squat","bulgarian-split-squat","smith-squat"],"setup":{"en":"Fasten the belt low around your hips (on the pelvis, not the waist) and clip it to the lever or chain; stand on the platform with feet shoulder-width, toes slightly out, hands on the handles. Stand tall to lift the weight off the stops.","ru":"Застегните пояс низко на тазу (на тазовых костях, а не на талии) и пристегните к рычагу или цепи; встаньте на платформу, стопы на ширине плеч, носки чуть врозь, руки на рукоятках. Выпрямитесь, чтобы снять вес с упоров."},"cues":{"en":["Stay tall: the load hangs from your hips, so the torso stays upright and the spine is unloaded.","Sit straight down (2–3 s) until the thighs are at least parallel, knees tracking over the toes.","Use the handles for balance only, not to pull yourself up.","Drive the floor away and finish by squeezing the glutes; breathe out on the way up.","Set the strap length so the weight clears the stops at the top and you can reach full depth."],"ru":["Держите корпус вертикально: вес висит на тазу, позвоночник разгружен.","Опускайтесь прямо вниз (2–3 с) минимум до параллели бёдер, колени по линии носков.","Рукоятки — только для равновесия, не подтягивайтесь за них.","Отталкивайте пол и вверху напрягите ягодицы; выдох на подъёме.","Подберите длину ремня так, чтобы вверху вес отрывался от упоров, а внизу хватало глубины."]},"mistakes":{"en":["Wearing the belt at the waist, where it rides up and pulls you forward.","Pulling on the handles to stand up.","Knees caving in or cutting depth.","Leaning far forward, which turns it into a hinge and loses the back-friendly set-up."],"ru":["Пояс на талии: он уезжает вверх и тянет корпус вперёд.","Вставание за счёт рук на рукоятках.","Колени заваливаются внутрь или неполная глубина.","Сильный наклон вперёд: упражнение превращается в наклон и теряет щадящую для спины механику."]},"startLoad":{"kg":45,"source":"≈0.6 × Strength Level Beginner 1RM (75 kg at 80 kg body weight)"},"tags":["legs"],"images":[],"sources":["Belt Squat Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/belt-squat/kg","Activity of trunk and lower extremity musculature: comparison between parallel back squats and belt squats — J Hum Kinet, 2020. https://doi.org/10.2478/hukin-2019-0126","Hammer Strength Plate-Loaded Belt Squat — Life Fitness, n.d. https://www.lifefitness.com/en-eu/catalog/strength-training/plate-loaded/hammer-strength-plate-loaded-belt-squat"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"goblet-squat","equipment_id":"dumbbell","name":{"en":"Goblet squat","ru":"Гоблет-приседания с гантелью"},"pattern":"squat","details":{"id":"goblet-squat","name":{"en":"Goblet squat","ru":"Гоблет-приседания с гантелью"},"aka":["Dumbbell goblet squat","Kettlebell goblet squat","Cup squat"],"equipment":"dumbbell","pattern":"squat","class":"squat","primary":["quads","glute-max"],"secondary":["adductors","erectors"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":true,"increment":2,"repRange":[6,12],"alternatives":["bulgarian-split-squat","leg-press-45","hack-squat","belt-squat","seated-leg-press","smith-squat","barbell-back-squat"],"setup":{"en":"Hold one dumbbell vertically against your chest, both hands cupping the top end, elbows tucked under it. Stand with feet shoulder-width or slightly wider, toes turned out 15–30°.","ru":"Держите гантель вертикально у груди, обхватив ладонями верхний диск, локти под гантелью. Стопы на ширине плеч или чуть шире, носки развёрнуты на 15–30°."},"cues":{"en":["Breathe in, brace and sit straight down between your heels.","Keep the dumbbell touching your chest and the chest up — the weight in front lets you stay upright.","Push the knees out over the toes; at the bottom your elbows can brush the inside of the knees.","Go as deep as you can with a neutral back (hips at least level with the knees) and pause briefly — no bounce.","Drive up through the whole foot and breathe out near the top."],"ru":["Вдохните, напрягите корпус и садитесь прямо вниз между пятками.","Гантель прижата к груди, грудь раскрыта: вес спереди помогает держать корпус вертикально.","Разводите колени по линии носков; внизу локти могут касаться внутренней стороны коленей.","Опускайтесь так глубоко, как позволяет ровная спина (таз минимум на уровне коленей), и сделайте короткую паузу без отбива.","Вставайте, давя всей стопой, выдох ближе к верхней точке."]},"mistakes":{"en":["Letting the dumbbell drift away from the chest, which pulls you forward and rounds the upper back.","Heels lifting or knees caving in.","Rounding the lower back to chase depth (the pelvis tucking under at the bottom).","Choosing a dumbbell so heavy that your arms give out before your legs."],"ru":["Гантель отходит от груди: корпус заваливается вперёд, верх спины округляется.","Отрыв пяток или колени внутрь.","Округление поясницы ради глубины (таз подкручивается внизу).","Гантель настолько тяжёлая, что руки устают раньше ног."]},"startLoad":{"kg":10,"source":"≈0.6 × Strength Level Beginner 1RM for the goblet squat (15 kg, one dumbbell, at 80 kg body weight)"},"tags":["legs","longevity"],"images":[],"sources":["Goblet Squat Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/goblet-squat/kg","Goblet Squat — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/362/goblet-squat/","Effects of squat training with different depths on lower limb muscle volumes — Eur J Appl Physiol, 2019. https://doi.org/10.1007/s00421-019-04181-y"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"bulgarian-split-squat","equipment_id":"dumbbell","name":{"en":"Bulgarian split squat","ru":"Болгарские выпады (сплит-приседания)"},"pattern":"lunge","details":{"id":"bulgarian-split-squat","name":{"en":"Bulgarian split squat","ru":"Болгарские выпады (сплит-приседания)"},"aka":["Rear-foot-elevated split squat","RFESS","Dumbbell Bulgarian split squat"],"equipment":"dumbbell","pattern":"lunge","class":"squat","primary":["quads","glute-max"],"secondary":["adductors","glute-med"],"difficulty":2,"unilateral":true,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":true,"increment":2,"repRange":[6,12],"alternatives":["goblet-squat","leg-press-45","hack-squat","belt-squat","seated-leg-press","smith-squat","barbell-back-squat"],"setup":{"en":"Rest the top of your back foot on a knee-height bench and place the front foot far enough forward that, at the bottom, the front shin is about vertical or slightly forward. Hold a dumbbell in each hand at your sides (or one at the chest).","ru":"Положите подъём задней стопы на скамью высотой примерно до колена, переднюю ногу выставьте так далеко, чтобы внизу голень была почти вертикальной или чуть наклонена вперёд. Гантели в опущенных руках по бокам (или одна у груди)."},"cues":{"en":["Lower straight down (2–3 s) until the back knee nearly touches the floor; the front leg does the work.","Keep the front knee over the middle toes and the whole front foot planted.","Lean the torso slightly forward for more glutes; stay upright for more quads.","Keep the hips square — don''t let the pelvis twist or drop to one side.","Push up through the front heel and midfoot; breathe out on the way up.","Start with your weaker leg and match its reps on the other side."],"ru":["Опускайтесь прямо вниз (2–3 с), пока заднее колено почти не коснётся пола; работает передняя нога.","Переднее колено над средними пальцами стопы, вся передняя стопа прижата к полу.","Небольшой наклон корпуса вперёд — больше работы ягодицам, вертикальный корпус — квадрицепсам.","Таз держите ровно: не разворачивайте и не проваливайте его в сторону.","Поднимайтесь, давя пяткой и серединой передней стопы; выдох на подъёме.","Начинайте со слабой ноги и сделайте столько же повторений другой."]},"mistakes":{"en":["Front foot too close, so the heel lifts and the knee is driven far forward.","Pushing off the back foot instead of the front leg.","Front knee caving inward.","A bench so high that the rear hip and thigh are over-stretched."],"ru":["Передняя стопа слишком близко: пятка отрывается, колено уходит далеко вперёд.","Толчок задней ногой вместо работы передней.","Переднее колено заваливается внутрь.","Слишком высокая скамья: передняя поверхность бедра и сгибатели бедра задней ноги перерастянуты."]},"startLoad":{"kg":8,"source":"≈0.6 × Strength Level Beginner 1RM (13 kg per dumbbell at 80 kg body weight); per hand"},"tags":["legs"],"images":[],"sources":["Dumbbell Bulgarian Split Squat Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-bulgarian-split-squat/kg","Bulgarian Split Squat — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/366/bulgarian-split-squat/","Targeted muscle activation in Bulgarian split squat variations: effects of trunk position and suspension-based execution — BMC Sports Sci Med Rehabil, 2025. https://doi.org/10.1186/s13102-025-01306-z","Gluteus maximus activation during common strength and hypertrophy exercises: a systematic review — J Sports Sci Med, 2020. https://pmc.ncbi.nlm.nih.gov/articles/PMC7039033/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"smith-squat","equipment_id":"smith","name":{"en":"Smith machine squat","ru":"Приседания в машине Смита"},"pattern":"squat","details":{"id":"smith-squat","name":{"en":"Smith machine squat","ru":"Приседания в машине Смита"},"aka":["Smith squat","Technogym Multipower squat","Guided-bar squat"],"equipment":"smith","pattern":"squat","class":"squat","primary":["quads","glute-max"],"secondary":["adductors","erectors"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"high","lengthenedBias":true,"increment":2.5,"repRange":[6,12],"alternatives":["hack-squat","v-squat","leg-press-45","belt-squat","goblet-squat","bulgarian-split-squat","barbell-back-squat"],"setup":{"en":"Set the safety stops just below the lowest point of your squat. Bar across your upper back (not the neck), hands just outside the shoulders; feet shoulder-width and 10–20 cm in front of the bar line.","ru":"Выставьте страховочные упоры чуть ниже нижней точки вашего приседа. Гриф на верхней части спины (не на шее), хват чуть шире плеч; стопы на ширине плеч и на 10–20 см впереди линии грифа."},"cues":{"en":["Unhook the bar by twisting it off the hooks, then brace before the first rep.","Sit down under control (2–3 s) to at least thighs parallel, knees tracking over the toes.","Keep the whole foot planted and the chest up; the bar path is fixed, so your foot position sets the balance.","Drive up and breathe out past the hardest part; stop short of locking the knees.","Rack the bar by twisting it onto the nearest hooks."],"ru":["Снимите гриф с крюков поворотом и напрягите корпус перед первым повторением.","Подконтрольно (2–3 с) опускайтесь минимум до параллели бёдер, колени по линии носков.","Вся стопа на полу, грудь раскрыта: траектория грифа фиксирована, поэтому баланс задаёт постановка стоп.","Поднимайтесь, выдыхая после самой тяжёлой точки; колени до блокировки не выпрямляйте.","Возвращайте гриф поворотом на ближайшие крюки."]},"mistakes":{"en":["Training without the safety stops set.","Feet right under the bar (knees forced far forward, heels up) or far in front (the lower back rounds at the bottom).","Resting the bar on the neck.","Bouncing out of the bottom or cutting depth."],"ru":["Работа без выставленных страховочных упоров.","Стопы прямо под грифом (колени уходят далеко вперёд, пятки отрываются) или слишком далеко впереди (поясница округляется внизу).","Гриф лежит на шее.","Отбив снизу или неполная глубина."]},"startLoad":{"kg":35,"source":"≈0.6 × Strength Level Beginner 1RM (57 kg at 80 kg body weight), bar included; Smith bars weigh 7–25 kg, so check yours"},"tags":["legs"],"images":[],"sources":["Smith Machine Squat Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/smith-machine-squat/kg","A comparison of free weight squat to Smith machine squat using electromyography — J Strength Cond Res, 2009. https://doi.org/10.1519/JSC.0b013e3181b1b181","Effects of squat training with different depths on lower limb muscle volumes — Eur J Appl Physiol, 2019. https://doi.org/10.1007/s00421-019-04181-y"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"barbell-back-squat","equipment_id":"barbell","name":{"en":"Barbell back squat","ru":"Приседания со штангой на спине"},"pattern":"squat","details":{"id":"barbell-back-squat","name":{"en":"Barbell back squat","ru":"Приседания со штангой на спине"},"aka":["Back squat","High-bar squat","Low-bar squat","Barbell squat"],"equipment":"barbell","pattern":"squat","class":"squat","primary":["quads","glute-max"],"secondary":["adductors","erectors"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"high","lengthenedBias":true,"increment":2.5,"repRange":[4,8],"alternatives":["hack-squat","smith-squat","belt-squat","leg-press-45","v-squat","goblet-squat","bulgarian-split-squat"],"setup":{"en":"In a power rack, set the J-hooks at mid-chest height and the safety arms just below your bottom position. Bar on the upper back (on the traps, not the neck), hands just outside the shoulders; unrack, take two or three steps back and set the feet shoulder-width, toes out 15–30°.","ru":"В силовой раме поставьте крюки на уровне середины груди, а страховочные упоры — чуть ниже нижней точки приседа. Гриф на трапециях (не на шее), хват чуть шире плеч; снимите штангу, сделайте 2–3 шага назад, стопы на ширине плеч, носки развёрнуты на 15–30°."},"cues":{"en":["Breathe into your belly and brace before every rep; keep the upper back tight and pull the bar into your back.","Sit down between your heels (2–3 s) until the thighs are at least parallel, keeping a neutral spine.","Let the knees travel forward over the toes along the line of the second toe; keep the whole foot planted.","Drive up so the chest and hips rise together; breathe out near the top.","First weeks: learn the pattern with the empty bar and add load only while every rep looks the same.","Training alone: squat only inside the rack with the safety arms set — if a rep fails, sit down and let the bar rest on them."],"ru":["Перед каждым повторением наберите воздух в живот и напрягите корпус; верх спины собран, гриф прижат к спине.","Садитесь вниз между пятками (2–3 с), пока бёдра не станут хотя бы параллельны полу; спина ровная.","Колени могут выходить вперёд за носки по линии второго пальца; вся стопа на полу.","Поднимайтесь так, чтобы грудь и таз шли вверх одновременно; выдох ближе к верхней точке.","Первые недели отрабатывайте технику с пустым грифом и добавляйте вес, только пока все повторения одинаково чистые.","В одиночку приседайте только в раме с выставленными упорами: если повторение не идёт, опуститесь и положите штангу на упоры."]},"mistakes":{"en":["Squatting outside a rack, or without safety arms, when training alone.","Lower back rounding at the bottom (pelvis tucking under) or over-arching at the top.","Hips shooting up first so the squat turns into a good-morning.","Knees caving inward on the way up.","Bar on the neck, or adding weight faster than your technique allows."],"ru":["Приседания вне рамы или без страховочных упоров, когда тренируетесь один.","Округление поясницы внизу (таз подкручивается) или переразгибание вверху.","Таз уходит вверх первым, и присед превращается в «гуд-морнинг».","Колени заваливаются внутрь на подъёме.","Гриф на шее или прибавка веса быстрее, чем позволяет техника."]},"startLoad":{"kg":45,"source":"≈0.6 × Strength Level Beginner 1RM (75 kg at 80 kg body weight), 20 kg bar included"},"tags":["legs","longevity"],"images":[],"sources":["Squat Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/squat/kg","Effect of knee position on hip and knee torques during the barbell squat — J Strength Cond Res, 2003. https://pubmed.ncbi.nlm.nih.gov/14636100/","Effects of squat training with different depths on lower limb muscle volumes — Eur J Appl Physiol, 2019. https://doi.org/10.1007/s00421-019-04181-y","A comparison of bone-targeted exercise strategies to reduce fracture risk in middle-aged and older men with osteopenia and osteoporosis (LIFTMOR-M) — J Bone Miner Res, 2020. https://doi.org/10.1002/jbmr.4008"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"leg-extension","equipment_id":"selectorized","name":{"en":"Leg extension","ru":"Разгибание ног сидя в тренажёре"},"pattern":"knee-extension","details":{"id":"leg-extension","name":{"en":"Leg extension","ru":"Разгибание ног сидя в тренажёре"},"aka":["Knee extension machine","Technogym Selection Leg Extension","Life Fitness Insignia Leg Extension","Cybex Eagle NX Leg Extension","Nautilus One Leg Extension","Hammer Strength Leg Extension"],"equipment":"selectorized","pattern":"knee-extension","class":"knee-extension","primary":["quads"],"secondary":[],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":5,"repRange":[8,15],"alternatives":["leg-press-45","seated-leg-press","hack-squat","belt-squat","v-squat","goblet-squat","bulgarian-split-squat"],"setup":{"en":"Line up your knee joint with the machine''s pivot (often marked with a coloured dot), set the shin pad on the lower shin just above the ankle, and adjust the backrest so your knees start bent to at least 90°. Hold the side handles.","ru":"Совместите коленный сустав с осью вращения тренажёра (часто отмечена цветной точкой), валик — на нижней части голени чуть выше голеностопа; спинку настройте так, чтобы в исходной позиции колени были согнуты не меньше чем на 90°. Держитесь за боковые рукоятки."},"cues":{"en":["Keep your hips down on the seat and your back on the pad; pull on the handles to stay put.","Extend the knees smoothly until straight and squeeze the quads for a one-second pause.","Lower slowly (2–3 s) all the way back to the deep-knee start — the stretched bottom range builds the most muscle.","If the backrest reclines, lean it back: a more open hip stretches the rectus femoris, which then grows more.","Breathe out as you extend, in as you lower."],"ru":["Таз прижат к сиденью, спина к спинке — удерживайте себя руками за рукоятки.","Плавно выпрямите колени и задержитесь на секунду, напрягая квадрицепсы.","Опускайте медленно (2–3 с) до глубокого сгибания в исходной точке: нижняя, растянутая часть амплитуды даёт больше всего роста.","Если спинка отклоняется, отклоните её: при более открытом тазобедренном суставе прямая мышца бедра растягивается и растёт сильнее.","Выдох на разгибании, вдох на опускании."]},"mistakes":{"en":["Knee not lined up with the pivot, so the pad slides along the shin and loads the knee awkwardly.","Swinging the weight up and letting the stack drop.","Lifting the hips off the seat to finish the rep.","Working only the top half of the range."],"ru":["Колено не совмещено с осью: валик ездит по голени, и колено нагружается неправильно.","Забрасывание веса рывком и бросок стопки вниз.","Отрыв таза от сиденья, чтобы дожать повторение.","Работа только в верхней половине амплитуды."]},"startLoad":{"kg":30,"source":"≈0.6 × Strength Level Beginner 1RM (48 kg at 80 kg body weight)"},"tags":["legs","longevity"],"images":[],"sources":["Leg Extension Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/leg-extension/kg","Partial range of motion training elicits favorable improvements in muscular adaptations when carried out at long muscle lengths — Eur J Sport Sci, 2022. https://doi.org/10.1080/17461391.2021.1927199","The effects of hip flexion angle on quadriceps femoris muscle hypertrophy in the leg extension exercise — J Sports Sci, 2025. https://doi.org/10.1080/02640414.2024.2444713","Muscular strength as a predictor of all-cause mortality in an apparently healthy population: a systematic review and meta-analysis of data from approximately 2 million men and women — Arch Phys Med Rehabil, 2018. https://doi.org/10.1016/j.apmr.2018.01.008"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"seated-leg-curl","equipment_id":"selectorized","name":{"en":"Seated leg curl","ru":"Сгибание ног сидя в тренажёре"},"pattern":"knee-flexion","details":{"id":"seated-leg-curl","name":{"en":"Seated leg curl","ru":"Сгибание ног сидя в тренажёре"},"aka":["Seated hamstring curl","Technogym Selection Leg Curl","Life Fitness Insignia Seated Leg Curl","Nautilus One Seated Leg Curl"],"equipment":"selectorized","pattern":"knee-flexion","class":"knee-flexion","primary":["hamstrings"],"secondary":["gastrocnemius"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":5,"repRange":[8,15],"alternatives":["lying-leg-curl","dumbbell-rdl","back-extension-45","cable-pull-through"],"setup":{"en":"Line up your knee joint with the pivot, put the lower-leg pad on the back of your lower calves (above the Achilles tendon) and clamp the thigh pad snugly just above the knees. Sit back against the pad and hold the handles.","ru":"Совместите колено с осью вращения, валик для голеней — под нижней частью икр (выше ахиллова сухожилия), бедренный валик плотно прижмите чуть выше коленей. Сядьте вплотную к спинке и возьмитесь за рукоятки."},"cues":{"en":["Sit tall or lean slightly forward: the bent hip stretches the hamstrings, which is why seated curls grow them more than lying curls.","Curl the pad down and back as far as you can (well past 90°) and pause for a second.","Return slowly (2–3 s) to an almost straight knee without letting the stack rest.","Keep the thighs pinned under the pad; don''t lift the hips.","Breathe out as you curl, in on the way back."],"ru":["Сидите прямо или чуть наклонитесь вперёд: согнутый тазобедренный сустав растягивает заднюю поверхность бедра — поэтому сгибания сидя растят её лучше, чем лёжа.","Сгибайте ноги вниз и назад как можно дальше (заметно больше 90°) с паузой в секунду.","Возвращайте медленно (2–3 с) почти до прямого колена, не опуская грузы на стопку.","Бёдра прижаты валиком, таз не отрывайте.","Выдох на сгибании, вдох на возврате."]},"mistakes":{"en":["Thigh pad left loose, so the hips ride up and the stretch is lost.","Pad pressing on the Achilles tendon, or the knee off the pivot.","Jerking the weight and stopping short of a full curl.","Letting the stack slam on the way back."],"ru":["Бедренный валик не прижат: таз уезжает вверх, и растяжение теряется.","Валик давит на ахиллово сухожилие или колено не совмещено с осью.","Рывки и неполное сгибание.","Грузы падают на стопку при возврате."]},"startLoad":{"kg":25,"source":"≈0.6 × Strength Level Beginner 1RM (39 kg at 80 kg body weight)"},"tags":["legs"],"images":[],"sources":["Seated Leg Curl Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/seated-leg-curl/kg","Greater hamstrings muscle hypertrophy but similar damage protection after training at long versus short muscle lengths — Med Sci Sports Exerc, 2021. https://doi.org/10.1249/MSS.0000000000002523"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"lying-leg-curl","equipment_id":"selectorized","name":{"en":"Lying leg curl","ru":"Сгибание ног лёжа в тренажёре"},"pattern":"knee-flexion","details":{"id":"lying-leg-curl","name":{"en":"Lying leg curl","ru":"Сгибание ног лёжа в тренажёре"},"aka":["Prone leg curl","Lying hamstring curl","Technogym Selection Prone Leg Curl","Life Fitness Insignia Leg Curl"],"equipment":"selectorized","pattern":"knee-flexion","class":"knee-flexion","primary":["hamstrings"],"secondary":["gastrocnemius"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[8,15],"alternatives":["seated-leg-curl","dumbbell-rdl","back-extension-45","cable-pull-through"],"setup":{"en":"Lie face down with your knees just off the end of the pad and in line with the pivot; place the roller on the lower third of your calves, above the heels. Hold the handles.","ru":"Лягте лицом вниз так, чтобы колени были чуть за краем скамьи и на одной линии с осью вращения; валик — на нижней трети голеней, выше пяток. Возьмитесь за рукоятки."},"cues":{"en":["Press your hips into the pad and brace your abs so the lower back doesn''t arch.","Curl your heels toward your glutes until the knees are bent past 90°, then pause for a second.","Lower under control (2–3 s) to almost straight, keeping tension at the bottom.","Breathe out as you curl, in as you lower."],"ru":["Прижмите таз к скамье и напрягите пресс, чтобы поясница не прогибалась.","Сгибайте ноги, подводя пятки к ягодицам, пока колени не согнутся больше чем на 90°, затем секундная пауза.","Опускайте подконтрольно (2–3 с) почти до прямых ног, не теряя напряжения внизу.","Выдох на сгибании, вдох на опускании."]},"mistakes":{"en":["Hips lifting off the pad and the lower back arching to finish reps.","Roller on the Achilles or heels, or knees out of line with the pivot.","Swinging the weight up and dropping it."],"ru":["Таз отрывается от скамьи, поясница прогибается, чтобы дожать повторение.","Валик на ахиллах или пятках либо колени не совмещены с осью.","Забрасывание веса и бросок вниз."]},"startLoad":{"kg":20,"source":"≈0.6 × Strength Level Beginner 1RM (30 kg at 80 kg body weight)"},"tags":["legs"],"images":[],"sources":["Lying Leg Curl Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/lying-leg-curl/kg","Lying Hamstrings Curl — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/153/lying-hamstrings-curl/","Greater hamstrings muscle hypertrophy but similar damage protection after training at long versus short muscle lengths — Med Sci Sports Exerc, 2021. https://doi.org/10.1249/MSS.0000000000002523"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"nordic-hamstring-curl","equipment_id":"bodyweight","name":{"en":"Nordic hamstring curl","ru":"Нордические сгибания ног"},"pattern":"knee-flexion","details":{"id":"nordic-hamstring-curl","name":{"en":"Nordic hamstring curl","ru":"Нордические сгибания ног"},"aka":["Nordic curl","Nordic hamstring exercise (NHE)","Russian hamstring curl","Hammer Strength Plate-Loaded Assisted Nordic Ham"],"equipment":"bodyweight","pattern":"knee-flexion","class":"knee-flexion","primary":["hamstrings"],"secondary":["gastrocnemius","glute-max"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":0,"repRange":[3,8],"alternatives":["seated-leg-curl","lying-leg-curl","dumbbell-rdl","back-extension-45","barbell-rdl"],"setup":{"en":"Kneel on a soft pad with your heels locked under a padded bar, a machine roller or a partner''s hands. Keep your body straight from knees to head, hands ready in front of your chest.","ru":"Встаньте на колени на мягкий коврик, зафиксировав пятки под валиком, перекладиной или руками партнёра. Тело прямое от коленей до головы, руки перед грудью наготове."},"cues":{"en":["Squeeze your glutes and keep the hips straight — the movement happens only at the knees.","Lean forward as slowly as you can (3–5 s), braking with your hamstrings.","When you can no longer hold it, catch yourself with your hands as in a push-up and push lightly back up.","Progress by controlling a longer range, then add reps; at first get help from a band anchored behind you around your chest, or from plates on an assisted Nordic machine.","Breathe out slowly as you lower."],"ru":["Напрягите ягодицы и держите таз выпрямленным: движение происходит только в коленях.","Наклоняйтесь вперёд как можно медленнее (3–5 с), тормозя задней поверхностью бедра.","Когда удерживать уже не получается, поймайте себя руками, как в отжимании, и слегка оттолкнитесь обратно.","Прогрессируйте: сначала больше подконтрольной амплитуды, потом повторений; на старте помогут резинка, закреплённая сзади вокруг груди, или диски на тренажёре с поддержкой.","Медленно выдыхайте на опускании."]},"mistakes":{"en":["Bending at the hips (bottom sticking out), which shortens the lever and takes the hamstrings out of it.","Dropping through the last part of the range instead of controlling it.","Doing many hard sets in the first weeks; start with 1–2 sets of 3–5 once a week, because the soreness is severe at first.","Kneeling on a hard floor with no padding."],"ru":["Сгибание в тазобедренном суставе (таз уходит назад): рычаг укорачивается, и задняя поверхность бедра выключается.","Падение в конце амплитуды вместо контроля.","Много тяжёлых подходов в первые недели: начните с 1–2 подходов по 3–5 повторений раз в неделю — поначалу крепатура сильная.","Колени на жёстком полу без подкладки."]},"startLoad":{"kg":0,"source":"Body weight; start with 1–2 sets of 3–5 slow reps once a week (Petersen 2011 began with one session in week 1 and built up over 10 weeks)"},"tags":["legs"],"images":[],"sources":["Including the Nordic hamstring exercise in injury prevention programmes halves the rate of hamstring injuries — Br J Sports Med, 2019. https://doi.org/10.1136/bjsports-2018-100045","Preventive effect of eccentric training on acute hamstring injuries in men''s soccer: a cluster-randomized controlled trial — Am J Sports Med, 2011. https://doi.org/10.1177/0363546511419277"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"trap-bar-deadlift","equipment_id":"barbell","name":{"en":"Trap-bar deadlift","ru":"Становая тяга с трэп-грифом"},"pattern":"hip-hinge","details":{"id":"trap-bar-deadlift","name":{"en":"Trap-bar deadlift","ru":"Становая тяга с трэп-грифом"},"aka":["Hex bar deadlift","Hexagonal bar deadlift","Trap bar lift"],"equipment":"barbell","pattern":"hip-hinge","class":"hip-hinge","primary":["glute-max","quads"],"secondary":["hamstrings","erectors","adductors","forearm-flexors"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"high","lengthenedBias":false,"increment":2.5,"repRange":[4,8],"alternatives":["conventional-deadlift","cable-pull-through","kettlebell-swing","barbell-rdl","dumbbell-rdl","back-extension-45"],"setup":{"en":"Step into the centre of the bar with feet hip-width and the handles in line with the middle of your feet. Use the raised handles while you learn — they shorten the pull.","ru":"Встаньте в центр грифа, стопы на ширине таза, рукоятки на одной линии с серединой стоп. Пока осваиваете движение, берите высокие рукоятки — амплитуда короче."},"cues":{"en":["Push your hips back and bend your knees to grip the middle of the handles; back flat, chest up, arms long.","Breathe into your belly, brace, and pull the slack out of the bar before it leaves the floor.","Push the floor away with your legs; hips and shoulders rise together.","Finish standing tall with the glutes squeezed — don''t lean back.","Lower by pushing the hips back first, then bending the knees; set the bar down, don''t drop it.","Re-brace before every rep and end the set as soon as your back position changes."],"ru":["Отведите таз назад и согните колени, чтобы взяться за середину рукояток; спина ровная, грудь раскрыта, руки прямые.","Наберите воздух в живот, напрягите корпус и выберите люфт грифа, прежде чем оторвать его от пола.","Отталкивайте пол ногами; таз и плечи поднимаются одновременно.","Вверху встаньте прямо, напрягая ягодицы, — без отклонения назад.","Опускайте, сначала отводя таз назад, затем сгибая колени; ставьте гриф, а не бросайте.","Перед каждым повторением заново напрягайте корпус и заканчивайте подход, как только меняется положение спины."]},"mistakes":{"en":["Rounding the lower back to reach the handles.","Jerking the bar off the floor instead of building tension first.","Hips shooting up first, turning the lift into a stiff-legged pull.","Leaning back or shrugging hard at the top.","Standing off-centre so the bar tilts or hits your legs."],"ru":["Округление поясницы, чтобы дотянуться до рукояток.","Рывок грифа с пола без предварительного напряжения.","Таз уходит вверх первым — тяга превращается в тягу на прямых ногах.","Отклонение назад или сильное пожимание плечами вверху.","Стойка не по центру: гриф перекашивается или бьёт по ногам."]},"startLoad":{"kg":60,"source":"≈0.6 × Strength Level Beginner 1RM (99 kg at 80 kg body weight), bar included — trap bars weigh 20–30 kg"},"tags":["legs","longevity"],"images":[],"sources":["Hex Bar Deadlift Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/trap-bar-deadlift/kg","A biomechanical analysis of straight and hexagonal barbell deadlifts using submaximal loads — J Strength Cond Res, 2011. https://doi.org/10.1519/JSC.0b013e3181e73f87","An examination of muscle activation and power characteristics while performing the deadlift exercise with straight and hexagonal barbells — J Strength Cond Res, 2016. https://doi.org/10.1519/JSC.0000000000001352","A comparison of bone-targeted exercise strategies to reduce fracture risk in middle-aged and older men with osteopenia and osteoporosis (LIFTMOR-M) — J Bone Miner Res, 2020. https://doi.org/10.1002/jbmr.4008"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"dumbbell-rdl","equipment_id":"dumbbell","name":{"en":"Dumbbell Romanian deadlift","ru":"Румынская тяга с гантелями"},"pattern":"hip-hinge","details":{"id":"dumbbell-rdl","name":{"en":"Dumbbell Romanian deadlift","ru":"Румынская тяга с гантелями"},"aka":["Dumbbell RDL","DB Romanian deadlift","Dumbbell hip hinge"],"equipment":"dumbbell","pattern":"hip-hinge","class":"hip-hinge","primary":["hamstrings","glute-max"],"secondary":["erectors","adductors","forearm-flexors"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":true,"increment":2,"repRange":[6,12],"alternatives":["barbell-rdl","cable-pull-through","back-extension-45","kettlebell-swing","trap-bar-deadlift","seated-leg-curl","lying-leg-curl"],"setup":{"en":"Stand tall with feet hip-width and a dumbbell in each hand in front of your thighs, knees unlocked (slightly bent).","ru":"Встаньте прямо, стопы на ширине таза, гантели в руках перед бёдрами, колени слегка согнуты."},"cues":{"en":["Brace, then push your hips straight back; the dumbbells slide down close to your thighs and shins.","Keep the knee bend almost fixed and your back flat from head to tailbone.","Lower (2–3 s) until you feel a strong hamstring stretch, usually around mid-shin, and stop before your back starts to round.","Drive the hips forward to stand up, squeezing the glutes; breathe out at the top.","Keep the shoulders down and back, dumbbells under the shoulders."],"ru":["Напрягите корпус и отводите таз строго назад; гантели скользят вниз вплотную к бёдрам и голеням.","Сгиб в коленях почти не меняется, спина ровная от головы до копчика.","Опускайтесь (2–3 с) до сильного растяжения задней поверхности бедра — обычно до середины голени — и остановитесь раньше, чем начнёт округляться спина.","Поднимайтесь, подавая таз вперёд и напрягая ягодицы; выдох вверху.","Плечи опущены и отведены назад, гантели под плечами."]},"mistakes":{"en":["Rounding the lower back to reach lower.","Turning it into a squat by bending the knees more on the way down.","Letting the dumbbells drift forward, away from the legs.","Over-arching the lower back at the top instead of finishing with the glutes."],"ru":["Округление поясницы ради большей глубины.","Тяга превращается в присед: колени сгибаются всё сильнее по ходу опускания.","Гантели уходят вперёд от ног.","Переразгибание поясницы вверху вместо дожима ягодицами."]},"startLoad":{"kg":12,"source":"≈0.6 × Strength Level Beginner 1RM (19 kg per dumbbell at 80 kg body weight); per hand"},"tags":["legs"],"images":[],"sources":["Dumbbell Romanian Deadlift Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/dumbbell-romanian-deadlift/kg","Muscle activation during various hamstring exercises — J Strength Cond Res, 2014. https://doi.org/10.1519/JSC.0000000000000302","Romanian Deadlift — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/317/romanian-deadlift/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"barbell-rdl","equipment_id":"barbell","name":{"en":"Barbell Romanian deadlift","ru":"Румынская тяга со штангой"},"pattern":"hip-hinge","details":{"id":"barbell-rdl","name":{"en":"Barbell Romanian deadlift","ru":"Румынская тяга со штангой"},"aka":["Romanian deadlift","RDL","Barbell RDL"],"equipment":"barbell","pattern":"hip-hinge","class":"hip-hinge","primary":["hamstrings","glute-max"],"secondary":["erectors","adductors","forearm-flexors"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"high","lengthenedBias":true,"increment":2.5,"repRange":[6,10],"alternatives":["dumbbell-rdl","conventional-deadlift","trap-bar-deadlift","cable-pull-through","back-extension-45","kettlebell-swing","seated-leg-curl","lying-leg-curl"],"setup":{"en":"Take the bar from a rack set at mid-thigh height (not off the floor) with an overhand grip just outside your thighs; stand tall, feet hip-width, knees slightly bent.","ru":"Снимите штангу со стоек на уровне середины бедра (не с пола) прямым хватом чуть шире бёдер; встаньте прямо, стопы на ширине таза, колени слегка согнуты."},"cues":{"en":["Brace and set the shoulders back; keep the bar touching your thighs as you push the hips back.","Keep the knees softly bent and the shins nearly vertical.","Lower (2–3 s) to just below the knees or mid-shin — only as far as you can keep your back flat.","Stand up by driving the hips forward with the bar close; breathe out at the top.","Keep your neck in line with your back: look at the floor a couple of metres ahead."],"ru":["Напрягите корпус, сведите лопатки; отводя таз назад, ведите гриф вплотную по бёдрам.","Колени слегка согнуты, голени почти вертикальны.","Опускайте (2–3 с) чуть ниже колен или до середины голени — только пока спина остаётся ровной.","Поднимайтесь, подавая таз вперёд, гриф у ног; выдох вверху.","Шея продолжает линию спины: смотрите в пол в паре метров впереди."]},"mistakes":{"en":["Rounding the lower back at the bottom — the main injury risk on this lift.","Bar drifting forward away from the legs, which multiplies the load on the lower back.","Bending the knees into a squat, or locking them straight.","Leaning back at the top, or adding load before the hinge is consistent."],"ru":["Округление поясницы внизу — главный риск травмы в этом упражнении.","Гриф уходит вперёд от ног — нагрузка на поясницу резко растёт.","Сгибание коленей до приседа или полностью прямые, заблокированные колени.","Отклонение назад вверху или прибавка веса раньше, чем наклон стал стабильным."]},"startLoad":{"kg":40,"source":"≈0.6 × Strength Level Beginner 1RM (65 kg at 80 kg body weight), 20 kg bar included"},"tags":["legs"],"images":[],"sources":["Romanian Deadlift Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/romanian-deadlift/kg","Romanian Deadlift — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/317/romanian-deadlift/","Muscle activation during various hamstring exercises — J Strength Cond Res, 2014. https://doi.org/10.1519/JSC.0000000000000302","Exercise Technique Manual for Resistance Training, 4th ed. — NSCA / Human Kinetics, 2021. https://us.humankinetics.com/products/exercise-technique-manual-for-resistance-training-4th-edition-with-hkpropel-online-video"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"cable-pull-through","equipment_id":"cable","name":{"en":"Cable pull-through","ru":"Тяга нижнего блока между ног (пулл-тру)"},"pattern":"hip-hinge","details":{"id":"cable-pull-through","name":{"en":"Cable pull-through","ru":"Тяга нижнего блока между ног (пулл-тру)"},"aka":["Pull-through","Rope pull-through","Cable hip hinge"],"equipment":"cable","pattern":"hip-hinge","class":"hip-hinge","primary":["glute-max","hamstrings"],"secondary":["erectors","adductors"],"difficulty":2,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":2.5,"repRange":[8,15],"alternatives":["kettlebell-swing","trap-bar-deadlift","conventional-deadlift","dumbbell-rdl","back-extension-45","barbell-rdl","machine-hip-thrust","barbell-hip-thrust"],"setup":{"en":"Attach a rope to a low pulley. Face away from the stack, straddle the cable and take the rope with both hands between your legs, then walk forward one or two steps; feet slightly wider than the hips, knees soft.","ru":"Закрепите канат на нижнем блоке. Встаньте спиной к стойке, перешагните трос и возьмите канат обеими руками между ног, затем отойдите на 1–2 шага; стопы чуть шире таза, колени слегка согнуты."},"cues":{"en":["Hinge: push the hips back and let the rope travel back between your legs, back flat, arms long.","Go down until you feel the hamstrings stretch, torso around 45° or lower — never by rounding.","Snap the hips forward to stand tall and squeeze the glutes hard for a second.","Your arms are just hooks — don''t pull with them.","Breathe out as you stand; finish upright, not leaning back."],"ru":["Наклон за счёт таза: отводите таз назад, канат уходит назад между ног; спина ровная, руки прямые.","Опускайтесь до растяжения задней поверхности бедра (корпус примерно под 45° или ниже) — только без округления спины.","Мощно подайте таз вперёд, встаньте прямо и на секунду сильно напрягите ягодицы.","Руки — просто крюки: не тяните ими.","Выдох на подъёме; вверху стойте прямо, без отклонения назад."]},"mistakes":{"en":["Squatting down instead of hinging back.","Pulling the rope with the arms.","Leaning back and arching the lower back at the top.","Standing so close to the stack that the plates rest at the bottom and the tension disappears."],"ru":["Приседание вместо наклона с отведением таза.","Тяга каната руками.","Отклонение назад с прогибом поясницы в верхней точке.","Стойка слишком близко к блоку: внизу грузы ложатся на стопку, и напряжение пропадает."]},"startLoad":{"kg":10,"source":"≈0.6 × Strength Level Beginner 1RM (15 kg at 80 kg body weight); stack weight — pulley ratios differ between gyms"},"tags":["legs"],"images":[],"sources":["Cable Pull Through Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/cable-pull-through/kg","Hip Hinge — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/33/hip-hinge/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"conventional-deadlift","equipment_id":"barbell","name":{"en":"Conventional deadlift","ru":"Классическая становая тяга"},"pattern":"hip-hinge","details":{"id":"conventional-deadlift","name":{"en":"Conventional deadlift","ru":"Классическая становая тяга"},"aka":["Deadlift","Barbell deadlift","Conventional barbell deadlift"],"equipment":"barbell","pattern":"hip-hinge","class":"hip-hinge","primary":["glute-max","hamstrings"],"secondary":["erectors","quads","adductors","forearm-flexors"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"high","lengthenedBias":false,"increment":2.5,"repRange":[4,8],"alternatives":["trap-bar-deadlift","cable-pull-through","kettlebell-swing","barbell-rdl","dumbbell-rdl","back-extension-45"],"setup":{"en":"Stand with the bar over your mid-foot (2–3 cm from the shins), feet hip-width, toes slightly out, and full-size plates so the bar starts at standard height. Grip it overhand just outside your legs; use straps or a mixed grip only when the grip, not the back, is what fails.","ru":"Встаньте так, чтобы гриф был над серединой стопы (2–3 см от голеней), стопы на ширине таза, носки чуть врозь; диски полноразмерные, чтобы гриф стоял на стандартной высоте. Хват сверху чуть шире ног; лямки или разнохват — только когда подводит хват, а не спина."},"cues":{"en":["Bend the knees until the shins touch the bar: chest up, back flat, shoulders slightly in front of the bar.","Tighten the lats (''bend the bar around your legs''), breathe into your belly and brace.","Pull the slack out, then push the floor away; the bar travels straight up, brushing your legs.","Hips and shoulders rise together; finish tall with the glutes, no lean back.","Lower by pushing the hips back until the bar passes the knees, then bend the knees; start every rep from the floor.","Training alone: end the set at the first sign of your back rounding — never grind out a rep with a rounded back."],"ru":["Согните колени, чтобы голени коснулись грифа: грудь раскрыта, спина ровная, плечи чуть впереди грифа.","Напрягите широчайшие («согните гриф вокруг ног»), наберите воздух в живот и напрягите корпус.","Выберите люфт грифа, затем отталкивайте пол: гриф идёт строго вверх, касаясь ног.","Таз и плечи поднимаются одновременно; вверху встаньте прямо за счёт ягодиц, без отклонения назад.","Опускайте, отводя таз назад, пока гриф не пройдёт колени, затем сгибайте колени; каждое повторение — с пола.","В одиночку заканчивайте подход при первом признаке округления спины — никогда не дожимайте повторение с круглой спиной."]},"mistakes":{"en":["Lifting with a rounded lower back.","Bar starting too far from the shins or swinging forward on the way up.","Jerking the bar off the floor.","Hips rising before the bar moves (stiff-legging the start).","Over-arching the lower back at lockout, or bouncing reps off the floor."],"ru":["Тяга с округлённой поясницей.","Гриф далеко от голеней на старте или уходит вперёд по ходу подъёма.","Рывок грифа с пола.","Таз поднимается раньше, чем гриф отрывается от пола (старт на прямых ногах).","Переразгибание поясницы в верхней точке или отбив повторений от пола."]},"startLoad":{"kg":50,"source":"≈0.6 × Strength Level Beginner 1RM (89 kg at 80 kg body weight), rounded down; 20 kg bar included"},"tags":["legs","longevity"],"images":[],"sources":["Deadlift Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/deadlift/kg","Deadlift — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/6/deadlift/","A biomechanical analysis of straight and hexagonal barbell deadlifts using submaximal loads — J Strength Cond Res, 2011. https://doi.org/10.1519/JSC.0b013e3181e73f87","A comparison of bone-targeted exercise strategies to reduce fracture risk in middle-aged and older men with osteopenia and osteoporosis (LIFTMOR-M) — J Bone Miner Res, 2020. https://doi.org/10.1002/jbmr.4008"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"kettlebell-swing","equipment_id":"kettlebell","name":{"en":"Kettlebell swing","ru":"Махи гирей двумя руками"},"pattern":"hip-hinge","details":{"id":"kettlebell-swing","name":{"en":"Kettlebell swing","ru":"Махи гирей двумя руками"},"aka":["Two-hand kettlebell swing","Russian kettlebell swing","Hardstyle swing"],"equipment":"kettlebell","pattern":"hip-hinge","class":"hip-hinge","primary":["glute-max","hamstrings"],"secondary":["erectors","quads","forearm-flexors"],"difficulty":3,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":false,"increment":4,"repRange":[10,20],"alternatives":["cable-pull-through","trap-bar-deadlift","conventional-deadlift","dumbbell-rdl","back-extension-45","barbell-rdl"],"setup":{"en":"Set the kettlebell about 30 cm in front of you, feet shoulder-width. Hinge back, grip the handle with both hands and tilt the bell toward you.","ru":"Поставьте гирю примерно в 30 см перед собой, стопы на ширине плеч. Наклонитесь, отводя таз назад, возьмитесь за дужку двумя руками и наклоните гирю к себе."},"cues":{"en":["Hike the bell back high between your thighs like passing a ball back between your legs: back flat, forearms against the inner thighs.","Snap the hips forward hard; the bell floats up to chest height on straight, relaxed arms.","At the top stand tall like a plank — glutes and abs tight, no lean back.","Let the bell fall, wait for it, then hinge as it passes your hips; keep it above the knees.","Breathe out sharply at the top of every rep.","End the set by hiking the bell back and parking it on the floor in front of you."],"ru":["Заведите гирю назад высоко между бёдер, будто отдаёте мяч назад между ног: спина ровная, предплечья у внутренней поверхности бёдер.","Резко подайте таз вперёд: гиря взлетает до уровня груди на прямых расслабленных руках.","Вверху стойте прямо, как в планке: ягодицы и пресс напряжены, без отклонения назад.","Дайте гире упасть, дождитесь её и наклонитесь, когда она пройдёт таз; держите её выше колен.","Резкий выдох в верхней точке каждого повторения.","Заканчивайте подход, заводя гирю назад и ставя её на пол перед собой."]},"mistakes":{"en":["Squatting the swing (knees forward, hips down) instead of hinging.","Lifting the bell with the arms and shoulders.","Rounding the lower back at the bottom or letting the bell drop below the knees.","Leaning back and over-arching at the top.","Carrying on when tired and the form breaks — swings are crisp sets of 10–20."],"ru":["Махи «приседом» (колени вперёд, таз вниз) вместо наклона с отведением таза.","Подъём гири руками и плечами.","Округление поясницы внизу или гиря проваливается ниже колен.","Отклонение назад с прогибом в верхней точке.","Продолжение подхода, когда устали и техника развалилась: махи — это чёткие подходы по 10–20."]},"startLoad":{"kg":16,"source":"Lake & Lauder 2012 used a 16 kg bell for men over 70 kg; the usual first swing bell for an average man"},"tags":["legs"],"images":[],"sources":["Kettlebell swing training improves maximal and explosive strength — J Strength Cond Res, 2012. https://doi.org/10.1519/JSC.0b013e31825c2c9b","Kettlebell swing, snatch, and bottoms-up carry: back and hip muscle activation, motion, and low back loads — J Strength Cond Res, 2012. https://doi.org/10.1519/JSC.0b013e31823a4063","Swing — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/391/swing/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"machine-hip-thrust","equipment_id":"plate-loaded","name":{"en":"Hip thrust machine","ru":"Ягодичный мост в тренажёре (хип-траст)"},"pattern":"hip-extension","details":{"id":"machine-hip-thrust","name":{"en":"Hip thrust machine","ru":"Ягодичный мост в тренажёре (хип-траст)"},"aka":["Glute drive","Glute bridge machine","Hammer Strength Plate-Loaded Glute Drive","Technogym Pure Hip Thrust","Life Fitness Insignia Glute Bridge"],"equipment":"plate-loaded","pattern":"hip-extension","class":"hip-thrust","primary":["glute-max"],"secondary":["hamstrings"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[8,12],"alternatives":["glute-kickback-machine","barbell-hip-thrust","cable-pull-through","back-extension-45","bulgarian-split-squat","leg-press-45"],"setup":{"en":"Sit with your upper back (just below the shoulder blades) against the back pad and the padded lever or belt across your hips, just below the hip bones. Feet flat and hip-width, placed so your shins are vertical at the top.","ru":"Сядьте так, чтобы верх спины (чуть ниже лопаток) упирался в подушку, а валик или ремень лежал поперёк таза чуть ниже тазовых костей. Стопы на ширине таза, поставьте их так, чтобы вверху голени были вертикальны."},"cues":{"en":["Keep the chin slightly tucked and the ribs down; your gaze follows your torso.","Drive through the heels and midfoot until the hips are fully extended — torso and thighs in one line.","Squeeze the glutes for a second at the top with a slight backward tilt of the pelvis, not an arch in the lower back.","Lower under control (2 s) until the plates almost touch down.","Breathe out as you drive up."],"ru":["Подбородок слегка прижат, рёбра опущены: взгляд следует за корпусом.","Давите пятками и серединой стопы, пока таз полностью не разогнётся: корпус и бёдра на одной линии.","Вверху на секунду напрягите ягодицы, слегка подкрутив таз назад, — без прогиба в пояснице.","Опускайте подконтрольно (2 с), пока диски почти не коснутся упора.","Выдох на подъёме."]},"mistakes":{"en":["Arching the lower back to fake the top position.","Feet too far out (the hamstrings take over) or too close (the quads take over).","Pushing through the toes so the heels lift.","Throwing the head back."],"ru":["Прогиб в пояснице вместо полного разгибания таза.","Стопы слишком далеко (работает задняя поверхность бедра) или слишком близко (работают квадрицепсы).","Толчок носками с отрывом пяток.","Запрокидывание головы."]},"startLoad":{"kg":30,"source":"Estimate: no machine standard; ≈0.55 × Strength Level barbell hip-thrust Beginner 1RM (56 kg at 80 kg). Lever ratios differ, so adjust after the first set"},"tags":["legs"],"images":[],"sources":["Hip thrust and back squat training elicit similar gluteus muscle hypertrophy and transfer similarly to the deadlift — Front Physiol, 2023. https://doi.org/10.3389/fphys.2023.1279170","A comparison of gluteus maximus, biceps femoris, and vastus lateralis EMG activity in the back squat and barbell hip thrust — J Appl Biomech, 2015. https://doi.org/10.1123/jab.2014-0301","Hip Thrust Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/hip-thrust/kg"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"barbell-hip-thrust","equipment_id":"barbell","name":{"en":"Barbell hip thrust","ru":"Хип-траст со штангой (ягодичный мост от скамьи)"},"pattern":"hip-extension","details":{"id":"barbell-hip-thrust","name":{"en":"Barbell hip thrust","ru":"Хип-траст со штангой (ягодичный мост от скамьи)"},"aka":["Hip thrust","Bench hip thrust","Barbell glute bridge from a bench"],"equipment":"barbell","pattern":"hip-extension","class":"hip-thrust","primary":["glute-max"],"secondary":["hamstrings"],"difficulty":2,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[6,12],"alternatives":["machine-hip-thrust","glute-kickback-machine","cable-pull-through","back-extension-45","bulgarian-split-squat","leg-press-45"],"setup":{"en":"Sit with the lower edge of your shoulder blades against a stable bench about knee height, roll a padded bar into your hip crease and plant your feet hip-width so the shins are vertical at the top. Use full-diameter (bumper) plates so the bar clears your hips.","ru":"Сядьте, уперевшись нижним краем лопаток в устойчивую скамью высотой примерно до колена, закатите штангу с мягкой накладкой на сгиб таза, стопы на ширине таза так, чтобы вверху голени были вертикальны. Используйте полноразмерные (бамперные) диски, чтобы гриф проходил над тазом."},"cues":{"en":["Hold the bar with both hands to keep it centred; chin slightly tucked, ribs down.","Drive through the heels until the torso is parallel to the floor and the hips are fully extended.","Pause for a second at the top and squeeze the glutes — tilt the pelvis back slightly instead of arching.","Lower the hips under control until the plates nearly touch the floor.","Breathe out as you drive up; breathe in and brace before the next rep."],"ru":["Держите гриф обеими руками, чтобы он оставался по центру; подбородок слегка прижат, рёбра опущены.","Давите пятками, пока корпус не станет параллелен полу, а таз полностью не разогнётся.","Секундная пауза вверху с сильным напряжением ягодиц: таз слегка подкручен назад, без прогиба в пояснице.","Опускайте таз подконтрольно, пока диски почти не коснутся пола.","Выдох на подъёме; перед следующим повторением вдох и напряжение корпуса."]},"mistakes":{"en":["Over-arching the lower back instead of extending the hips.","A bench that slides away or is too high.","Bar rolling toward the stomach because it isn''t held or padded.","Feet too far out or too close, or pushing through the toes."],"ru":["Переразгибание поясницы вместо разгибания таза.","Скамья уезжает или стоит слишком высоко.","Гриф скатывается к животу, потому что его не придерживают и не подложили накладку.","Стопы слишком далеко или слишком близко либо толчок носками."]},"startLoad":{"kg":40,"source":"≈0.7 × Strength Level Beginner 1RM (56 kg at 80 kg body weight): the 20 kg bar plus two 10 kg bumper plates, the lightest load that clears the hips"},"tags":["legs"],"images":[],"sources":["Hip Thrust Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/hip-thrust/kg","A comparison of gluteus maximus, biceps femoris, and vastus lateralis EMG activity in the back squat and barbell hip thrust — J Appl Biomech, 2015. https://doi.org/10.1123/jab.2014-0301","Hip thrust and back squat training elicit similar gluteus muscle hypertrophy and transfer similarly to the deadlift — Front Physiol, 2023. https://doi.org/10.3389/fphys.2023.1279170","Gluteus maximus activation during common strength and hypertrophy exercises: a systematic review — J Sports Sci Med, 2020. https://pmc.ncbi.nlm.nih.gov/articles/PMC7039033/"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"glute-kickback-machine","equipment_id":"selectorized","name":{"en":"Glute kickback machine","ru":"Отведение ноги назад в тренажёре"},"pattern":"hip-extension","details":{"id":"glute-kickback-machine","name":{"en":"Glute kickback machine","ru":"Отведение ноги назад в тренажёре"},"aka":["Glute machine","Rear kick machine","Life Fitness Insignia Glute","Cybex Eagle NX Glute","Nautilus Inspiration Glute Press"],"equipment":"selectorized","pattern":"hip-extension","class":"hip-thrust","primary":["glute-max"],"secondary":["hamstrings"],"difficulty":1,"unilateral":true,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[10,15],"alternatives":["machine-hip-thrust","barbell-hip-thrust","cable-pull-through","back-extension-45","bulgarian-split-squat"],"setup":{"en":"Set the chest or elbow pad so your torso is supported and the hips stay level; put the working foot on the footplate (or the pad behind your thigh) and stand or kneel on the other leg (depending on the machine), knee soft. Hold the handles.","ru":"Отрегулируйте упор для груди или локтей так, чтобы корпус опирался на него, а таз оставался ровным; рабочую стопу поставьте на платформу (или заведите валик за бедро); опорная нога — на полу или на колене (зависит от тренажёра), колено мягкое. Возьмитесь за рукоятки."},"cues":{"en":["Brace your abs and keep the pelvis square — the movement comes only from the hip.","Push back and up until the thigh is in line with your torso, then squeeze the glute for a second.","Stop before the lower back arches: the range ends where your hip extension ends.","Return slowly (2 s) to a deep hip bend without letting the stack rest.","Do all reps on your weaker side first; breathe out as you push."],"ru":["Напрягите пресс и держите таз ровно: движение только в тазобедренном суставе.","Отводите ногу назад-вверх, пока бедро не окажется на одной линии с корпусом, и на секунду напрягите ягодицу.","Останавливайтесь до прогиба в пояснице: амплитуда заканчивается там, где заканчивается разгибание бедра.","Возвращайте медленно (2 с) до глубокого сгибания в тазобедренном суставе, не опуская грузы на стопку.","Начинайте со слабой стороны; выдох на усилии."]},"mistakes":{"en":["Arching the lower back to kick the leg higher.","Rotating the pelvis open toward the working side.","Swinging the weight with momentum.","A load so heavy that the support leg and the back do the work."],"ru":["Прогиб в пояснице, чтобы закинуть ногу выше.","Разворот таза в сторону рабочей ноги.","Махи с инерцией.","Вес настолько большой, что работают опорная нога и спина."]},"startLoad":{"kg":15,"source":"Estimate: no published standard; start light and find the working weight with 10–15 controlled reps"},"tags":["legs"],"images":[],"sources":["Glute Press — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/293/glute-press/","Quadruped Bent-knee Hip Extensions — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/270/quadruped-bent-knee-hip-extensions/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"hip-abduction-machine","equipment_id":"selectorized","name":{"en":"Hip abduction machine","ru":"Разведение ног сидя в тренажёре"},"pattern":"hip-abduction","details":{"id":"hip-abduction-machine","name":{"en":"Hip abduction machine","ru":"Разведение ног сидя в тренажёре"},"aka":["Seated hip abduction","Outer-thigh machine","Technogym Selection 700 Dual Abductor/Adductor","Life Fitness Insignia Hip Abduction/Adduction","Cybex Eagle NX Hip AB/AD","Nautilus One Hip Ab/Ad"],"equipment":"selectorized","pattern":"hip-abduction","class":"hip-abduction","primary":["glute-med"],"secondary":["glute-max"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[10,20],"alternatives":["glute-kickback-machine","side-plank","bulgarian-split-squat"],"setup":{"en":"Sit with your back against the pad and the pads on the outside of your knees; set the start position with the legs together (or only slightly apart) and the feet on the footrests.","ru":"Сядьте, прижав спину к спинке, валики — снаружи коленей; исходное положение — ноги вместе (или чуть врозь), стопы на подставках."},"cues":{"en":["Push the knees apart as far as is comfortable and pause for a second at the widest point.","Bring them back slowly (2 s) and stop just before the plates touch.","Keep the hips on the seat and the torso still — no rocking.","Breathe out as you push out."],"ru":["Разводите колени настолько широко, насколько комфортно, с паузой в секунду в крайней точке.","Сводите медленно (2 с), останавливаясь чуть раньше, чем грузы коснутся стопки.","Таз на сиденье, корпус неподвижен — без раскачки.","Выдох при разведении."]},"mistakes":{"en":["Bouncing the legs out with momentum and letting the stack crash.","Rocking the torso forward and back to move the weight.","Partial reps with too much weight."],"ru":["Резкое разведение с инерцией и бросок грузов на стопку.","Раскачивание корпуса вперёд-назад ради веса.","Неполная амплитуда со слишком большим весом."]},"startLoad":{"kg":25,"source":"≈0.6 × Strength Level Beginner 1RM (38 kg at 80 kg body weight)"},"tags":["legs"],"images":[],"sources":["Hip Abduction Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/hip-abduction/kg","An examination of the gluteal muscle activity associated with dynamic hip abduction and hip external rotation exercise: a systematic review — Int J Sports Phys Ther, 2015. https://pmc.ncbi.nlm.nih.gov/articles/PMC4595911/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"hip-adduction-machine","equipment_id":"selectorized","name":{"en":"Hip adduction machine","ru":"Сведение ног сидя в тренажёре"},"pattern":"hip-adduction","details":{"id":"hip-adduction-machine","name":{"en":"Hip adduction machine","ru":"Сведение ног сидя в тренажёре"},"aka":["Seated hip adduction","Inner-thigh machine","Technogym Selection Adductor","Technogym Selection 700 Dual Abductor/Adductor","Life Fitness Insignia Hip Adduction","Nautilus One Hip Ab/Ad"],"equipment":"selectorized","pattern":"hip-adduction","class":"hip-adduction","primary":["adductors"],"secondary":[],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":5,"repRange":[10,15],"alternatives":["copenhagen-adduction","leg-press-45","goblet-squat","bulgarian-split-squat"],"setup":{"en":"Sit with your back against the pad and the pads on the inside of your knees. Set the start width to a mild stretch only — narrower in the first sessions, then widen it gradually over weeks.","ru":"Сядьте, прижав спину к спинке, валики — с внутренней стороны коленей. Исходную ширину выставьте до лёгкого растяжения: в первые занятия — уже, затем расширяйте постепенно, неделя за неделей."},"cues":{"en":["Squeeze the knees together smoothly and pause for a second.","Open back slowly (2–3 s) to the set width — never let the weight yank your legs apart.","Keep the hips back on the seat and the torso tall.","Breathe out as you squeeze in."],"ru":["Плавно сводите колени и задержитесь на секунду.","Разводите медленно (2–3 с) до выставленной ширины — не позволяйте грузу рывком растаскивать ноги.","Таз прижат к спинке, корпус ровный.","Выдох при сведении."]},"mistakes":{"en":["Setting the start too wide in the first sessions — a common way to strain the groin.","Jerking the first rep out of the stretched position.","Letting the stack crash between reps."],"ru":["Слишком широкая исходная позиция в первые занятия — частая причина растяжения паховых мышц.","Рывок на первом повторении из растянутого положения.","Грузы падают на стопку между повторениями."]},"startLoad":{"kg":25,"source":"≈0.6 × Strength Level Beginner 1RM (41 kg at 80 kg body weight)"},"tags":["legs"],"images":[],"sources":["Hip Adduction Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/hip-adduction/kg","The Adductor Strengthening Programme prevents groin problems among male football players: a cluster-randomised controlled trial — Br J Sports Med, 2019. https://doi.org/10.1136/bjsports-2017-098937"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"copenhagen-adduction","equipment_id":"bodyweight","name":{"en":"Copenhagen adduction","ru":"Копенгагенское приведение (копенгагенская планка)"},"pattern":"hip-adduction","details":{"id":"copenhagen-adduction","name":{"en":"Copenhagen adduction","ru":"Копенгагенское приведение (копенгагенская планка)"},"aka":["Copenhagen plank","Copenhagen adductor exercise","Side-lying bench adduction"],"equipment":"bodyweight","pattern":"hip-adduction","class":"hip-adduction","primary":["adductors"],"secondary":["obliques","quadratus-lumborum"],"difficulty":2,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":false,"increment":0,"repRange":[6,15],"alternatives":["hip-adduction-machine","side-plank","goblet-squat","bulgarian-split-squat"],"setup":{"en":"Lie on your side next to a flat bench, propped on the forearm under your shoulder. Rest the inside of your top knee on the bench (easier) or the inside of your ankle (harder, long lever); the bottom leg starts under the bench.","ru":"Лягте на бок рядом с горизонтальной скамьёй, опираясь на предплечье под плечом. Положите на скамью внутреннюю сторону колена верхней ноги (легче) или внутреннюю сторону голеностопа (тяжелее, длинный рычаг); нижняя нога в начале под скамьёй."},"cues":{"en":["Press the top leg down into the bench to lift your hips until your body is one straight line.","Bring the bottom leg up to meet the bench, then lower hips and leg together under control (2–3 s).","Keep the hips stacked and the body in one plane — don''t roll forward or let the hips sag.","Progress through three levels: side-lying leg lifts on the floor, then the knee on the bench, then the ankle on the bench.","Breathe steadily, and stop at any sharp groin pain."],"ru":["Давите верхней ногой в скамью и поднимайте таз, пока тело не вытянется в одну прямую линию.","Подтяните нижнюю ногу к скамье, затем подконтрольно (2–3 с) опустите таз и ногу вместе.","Таз «стопкой», тело в одной плоскости — не заваливайтесь вперёд и не проваливайте таз.","Прогрессия в три ступени: подъёмы ноги лёжа на боку на полу, затем опора коленом на скамью, затем опора голеностопом.","Дышите ровно; при острой боли в паху остановитесь."]},"mistakes":{"en":["Starting straight on the long-lever (ankle) version — groin soreness is common in the first weeks.","Hips sagging or rotating forward.","Dropping down fast: the slow lowering phase is what built eccentric adductor strength in the trials."],"ru":["Старт сразу с длинного рычага (опора голеностопом): в первые недели пах часто болит.","Таз проваливается или разворачивается вперёд.","Быстрое опускание: именно медленная уступающая фаза развивала эксцентрическую силу приводящих мышц в исследованиях."]},"startLoad":{"kg":0,"source":"Body weight; start around 2 × 6 per side on the knee version and add reps — Ishøi 2016 built up to 3 sets of 15 per side over 8 weeks"},"tags":["legs"],"images":[],"sources":["The Adductor Strengthening Programme prevents groin problems among male football players: a cluster-randomised controlled trial — Br J Sports Med, 2019. https://doi.org/10.1136/bjsports-2017-098937","Large eccentric strength increase using the Copenhagen Adduction exercise in football: a randomized controlled trial — Scand J Med Sci Sports, 2016. https://doi.org/10.1111/sms.12585","The neuromuscular effects of the Copenhagen adductor exercise: a systematic review — Int J Sports Phys Ther, 2021. https://doi.org/10.26603/001c.27975"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"standing-calf-raise-machine","equipment_id":"selectorized","name":{"en":"Standing calf raise machine","ru":"Подъём на носки стоя в тренажёре"},"pattern":"calf-raise","details":{"id":"standing-calf-raise-machine","name":{"en":"Standing calf raise machine","ru":"Подъём на носки стоя в тренажёре"},"aka":["Standing calf machine","Machine calf raise","Hammer Strength Select Standing Calf"],"equipment":"selectorized","pattern":"calf-raise","class":"calf-straight","primary":["gastrocnemius","soleus"],"secondary":[],"difficulty":1,"unilateral":false,"supported":false,"lowerBackLoad":"moderate","lengthenedBias":true,"increment":5,"repRange":[10,20],"alternatives":["leg-press-calf-raise","single-leg-dumbbell-calf-raise","seated-calf-raise-machine"],"setup":{"en":"Set the shoulder pads so you have to bend your knees slightly to get under them; stand with the balls of your feet on the edge of the step, heels free, feet hip-width.","ru":"Выставьте плечевые валики так, чтобы под них приходилось заходить с чуть согнутыми коленями; встаньте подушечками стоп на край ступени, пятки свободно свисают, стопы на ширине таза."},"cues":{"en":["Stand tall with the knees straight but not locked — a straight knee keeps the gastrocnemius on stretch.","Lower the heels slowly (2–3 s) into a deep stretch and pause 1–2 s at the bottom — no bounce.","Rise as high as you can onto the big toe and pause for a second.","Keep the body still; don''t bend the knees or hips to push the weight.","Breathe out on the way up."],"ru":["Стойте прямо, колени выпрямлены, но не заблокированы: прямое колено держит икроножную мышцу в растяжении.","Медленно (2–3 с) опускайте пятки до глубокого растяжения и задержитесь внизу на 1–2 с — без пружинки.","Поднимайтесь как можно выше на большой палец стопы и задержитесь на секунду.","Корпус неподвижен: не помогайте коленями и тазом.","Выдох на подъёме."]},"mistakes":{"en":["Bouncing at the bottom so the Achilles tendon, not the muscle, does the work.","Short, fast half reps with the whole stack (ego loading).","Bending the knees to push the weight up.","Rolling onto the outer edge of the foot."],"ru":["Пружинящие движения внизу: работу делает ахиллово сухожилие, а не мышца.","Короткие быстрые полуповторения со всей стопкой — погоня за весом.","Сгибание коленей, чтобы вытолкнуть вес.","Заваливание стопы на внешний край."]},"startLoad":{"kg":30,"source":"≈0.6 × Strength Level Beginner 1RM for the machine calf raise (49 kg at 80 kg body weight)"},"tags":["legs","longevity"],"images":[],"sources":["Machine Calf Raise Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/machine-calf-raise/kg","Triceps surae muscle hypertrophy is greater after standing versus seated calf-raise training — Front Physiol, 2023. https://doi.org/10.3389/fphys.2023.1272106","Calf Raises — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/51/calf-raises/"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

insert into public.fitness_exercises (catalog_version, id, equipment_id, name, pattern, details)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","id":"leg-press-calf-raise","equipment_id":"plate-loaded","name":{"en":"Leg press calf raise","ru":"Подъём на носки в тренажёре для жима ногами"},"pattern":"calf-raise","details":{"id":"leg-press-calf-raise","name":{"en":"Leg press calf raise","ru":"Подъём на носки в тренажёре для жима ногами"},"aka":["Calf press","Sled calf press","Toe press","Life Fitness Insignia Calf Extension"],"equipment":"plate-loaded","pattern":"calf-raise","class":"calf-straight","primary":["gastrocnemius","soleus"],"secondary":[],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":true,"increment":2.5,"repRange":[10,20],"alternatives":["standing-calf-raise-machine","single-leg-dumbbell-calf-raise","seated-calf-raise-machine"],"setup":{"en":"Sit in the leg press with your back flat on the pad and only the balls of your feet on the bottom edge of the platform, feet hip-width. Press the platform up with straight (not locked) knees and keep a hand near the safety handles.","ru":"Сядьте в тренажёр для жима ногами, спина на спинке; на нижний край платформы поставьте только подушечки стоп на ширине таза. Выжмите платформу прямыми, но не заблокированными ногами и держите руку рядом со страховочными рукоятками."},"cues":{"en":["Keep the knees straight and still — only the ankles move.","Let the platform come down slowly (2–3 s) into a deep calf stretch and pause 1–2 s.","Press through the big toe as far as you can and pause for a second.","Use a moderate load and shoes with grip: your feet must never slip off the edge.","Turn the safety handles back in before you move your feet."],"ru":["Колени прямые и неподвижные — работают только голеностопы.","Медленно (2–3 с) опускайте платформу до глубокого растяжения икр и задержитесь на 1–2 с.","Выжимайте платформу через большой палец стопы как можно дальше и задержитесь на секунду.","Умеренный вес и нескользкая обувь: стопы ни в коем случае не должны соскользнуть с края.","Прежде чем переставить ноги, закройте страховочные рукоятки."]},"mistakes":{"en":["Bending the knees, which turns it into a mini leg press.","Feet so low on the edge that they can slip off under a loaded sled.","Bouncing short reps."],"ru":["Сгибание коленей: упражнение превращается в мини-жим ногами.","Стопы так низко на краю, что могут соскользнуть с платформы под весом.","Короткие пружинящие повторения."]},"startLoad":{"kg":50,"source":"≈0.6 × Strength Level Beginner 1RM for the sled calf press (84 kg at 80 kg body weight); count plates only, not the sled"},"tags":["legs"],"images":[],"sources":["Sled Press Calf Raise Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/sled-press-calf-raise/kg","Calf Raise (machine) — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/294/calf-raise/","Triceps surae muscle hypertrophy is greater after standing versus seated calf-raise training — Front Physiol, 2023. https://doi.org/10.3389/fphys.2023.1272106"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"single-leg-dumbbell-calf-raise","equipment_id":"dumbbell","name":{"en":"Single-leg dumbbell calf raise","ru":"Подъём на носок одной ноги с гантелью"},"pattern":"calf-raise","details":{"id":"single-leg-dumbbell-calf-raise","name":{"en":"Single-leg dumbbell calf raise","ru":"Подъём на носок одной ноги с гантелью"},"aka":["One-leg calf raise","Single-leg standing calf raise","Step calf raise"],"equipment":"dumbbell","pattern":"calf-raise","class":"calf-straight","primary":["gastrocnemius","soleus"],"secondary":[],"difficulty":2,"unilateral":true,"supported":false,"lowerBackLoad":"low","lengthenedBias":true,"increment":2,"repRange":[10,20],"alternatives":["leg-press-calf-raise","standing-calf-raise-machine","seated-calf-raise-machine"],"setup":{"en":"Stand on the ball of one foot on a step or a plate with the heel hanging off; hold a dumbbell in the same-side hand and a rail or rack with the other hand for balance.","ru":"Встаньте подушечкой одной стопы на ступеньку или диск, пятка свисает; гантель в руке со стороны рабочей ноги, другой рукой держитесь за поручень или стойку для равновесия."},"cues":{"en":["Keep the working knee straight but soft — that keeps the gastrocnemius long.","Lower the heel slowly (2–3 s) into a deep stretch and pause 1–2 s.","Rise as high as you can onto the big toe and pause for a second.","Use the support hand for balance only, not to pull yourself up.","Train the weaker calf first and match the reps on the other side."],"ru":["Колено рабочей ноги прямое, но не заблокированное: так икроножная мышца остаётся растянутой.","Медленно (2–3 с) опускайте пятку до глубокого растяжения, пауза 1–2 с.","Поднимайтесь как можно выше на большой палец стопы и задержитесь на секунду.","Опорная рука — только для равновесия, не подтягивайтесь ею.","Начинайте со слабой икры и повторите то же число повторений другой ногой."]},"mistakes":{"en":["Bouncing out of the bottom.","Bending the knee to help the rep.","Pulling on the rail to lift yourself."],"ru":["Пружинящий отбив из нижней точки.","Сгибание колена, чтобы помочь себе.","Подтягивание рукой за поручень."]},"startLoad":{"kg":0,"source":"Start with body weight only — one leg already carries the whole body; add a dumbbell once 20 slow full-range reps are easy"},"tags":["legs"],"images":[],"sources":["Triceps surae muscle hypertrophy is greater after standing versus seated calf-raise training — Front Physiol, 2023. https://doi.org/10.3389/fphys.2023.1272106","Calf Raises — ACE Exercise Library, n.d. https://www.acefitness.org/resources/everyone/exercise-library/51/calf-raises/"]}},{"catalog_version":"fitness-v2-915b27fc7429a034","id":"seated-calf-raise-machine","equipment_id":"plate-loaded","name":{"en":"Seated calf raise machine","ru":"Подъём на носки сидя в тренажёре"},"pattern":"calf-raise","details":{"id":"seated-calf-raise-machine","name":{"en":"Seated calf raise machine","ru":"Подъём на носки сидя в тренажёре"},"aka":["Seated calf machine","Hammer Strength Plate-Loaded Seated Calf Raise","Soleus raise"],"equipment":"plate-loaded","pattern":"calf-raise","class":"calf-bent","primary":["soleus"],"secondary":["gastrocnemius"],"difficulty":1,"unilateral":false,"supported":true,"lowerBackLoad":"low","lengthenedBias":false,"increment":2.5,"repRange":[10,20],"alternatives":["leg-press-calf-raise","standing-calf-raise-machine","single-leg-dumbbell-calf-raise"],"setup":{"en":"Sit with the balls of your feet on the footplate, heels free, and the knee pad snug on your lower thighs just above the knees. Lift your heels slightly and release the safety lever.","ru":"Сядьте, поставив подушечки стоп на подставку (пятки свободны), валик плотно на нижней части бёдер чуть выше коленей. Слегка поднимите пятки и откиньте стопорный рычаг."},"cues":{"en":["Lower the heels slowly (2–3 s) into a deep stretch and pause 1–2 s at the bottom.","Rise as high as you can and pause for a second at the top.","With the knees bent this trains mainly the soleus; pair it with a straight-knee calf raise for the gastrocnemius.","Keep the torso still and don''t push the pad with your hands.","Lock the safety lever before you take your feet off."],"ru":["Медленно (2–3 с) опускайте пятки до глубокого растяжения и задержитесь внизу на 1–2 с.","Поднимайтесь как можно выше с паузой в секунду вверху.","С согнутыми коленями работает в основном камбаловидная мышца — для икроножной добавляйте подъёмы на носки с прямыми ногами.","Корпус неподвижен, не помогайте себе руками, давя на валик.","Прежде чем убрать ноги, закройте стопорный рычаг."]},"mistakes":{"en":["Bouncing quick half reps.","Pushing the pad up with the hands or rocking the torso.","Forgetting the safety lever when getting out."],"ru":["Быстрые пружинящие полуповторения.","Помощь руками или раскачивание корпусом.","Забыть закрыть стопорный рычаг, выходя из тренажёра."]},"startLoad":{"kg":17.5,"source":"≈0.6 × Strength Level Beginner 1RM (31 kg at 80 kg body weight)"},"tags":["legs"],"images":[],"sources":["Seated Calf Raise Standards (kg) — Strength Level, 2026. https://strengthlevel.com/strength-standards/seated-calf-raise/kg","Triceps surae muscle hypertrophy is greater after standing versus seated calf-raise training — Front Physiol, 2023. https://doi.org/10.3389/fphys.2023.1272106","Hammer Strength Plate-Loaded Seated Calf Raise — Life Fitness, n.d. https://www.lifefitness.com/en-be/catalog/strength-training/plate-loaded/plate-loaded-seated-calf-raise"]}}]'::jsonb) as x(catalog_version text, id text, equipment_id text, name jsonb, pattern text, details jsonb)
on conflict do nothing;

