insert into public.fitness_exercise_machines (catalog_version, exercise_id, machine_id, configuration)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"assisted-dip","machine_id":"assisted-dip-chin-station","configuration":{"geometry":"an assisted dip and chin-up machine: a tall frame with chin-up handles on top, parallel dip handles at hip height on both sides, and a padded knee platform on a lever linked to a weight stack that pushes up to help","setup":"kneeling on the assistance pad, hands on the parallel dip handles, torso leaning slightly forward","start":"elbows bent about 90 degrees, shoulders just above elbow height, torso leaning slightly forward","end":"arms pressed straight, body raised between the handles, shoulders down away from the ears"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"assisted-pull-up","machine_id":"assisted-dip-chin-station","configuration":{"geometry":"an assisted pull-up and dip machine: a tall frame with wide overhand handles and parallel handles on top, dip handles lower at the sides, a padded knee platform on a lever linked to a weight stack that pushes up to help, steps to climb on","setup":"kneeling with both knees on the assistance pad, hands on the top handles a little wider than the shoulders, overhand grip","start":"hanging with straight arms overhead, body upright, knees on the pad, shoulders reaching up","end":"body pulled up until the chin is level with the handles, elbows bent sharply and down beside the ribs, chest toward the handles, knees still on the pad"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"back-extension-45","machine_id":"back-extension-45","configuration":{"geometry":"a 45-degree back extension bench (hyperextension): an angled frame with a padded thigh support and two ankle rollers on a foot plate, no weights","setup":"on the 45-degree bench with the thighs on the pad, its top edge just below the hip crease, ankles locked under the rollers, arms crossed on the chest","start":"torso hanging down toward the floor, hips bent, back flat","end":"torso raised until the body forms one straight line from head to heels, not beyond"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"bayesian-cable-curl","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set LOW, at about knee height, and a single stirrup handle","setup":"standing facing away from the column in a split stance, the working arm extended down and behind the body holding the handle, palm forward","start":"working arm extended down and slightly behind the torso, a stretch in the biceps","end":"handle curled up toward the shoulder, the upper arm still behind the torso line"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"belt-squat","machine_id":"belt-squat","configuration":{"geometry":"a plate-loaded belt squat machine: a raised standing platform, a hip belt hanging from a chain on a lever arm loaded with plates, handrails in front","setup":"standing on the platform with the belt around the hips, hands on the front rails","start":"hips and knees bent, thighs about parallel to the floor, torso upright","end":"standing up tall, legs straight"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"cable-crunch","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set at the TOP and a rope attachment","setup":"kneeling facing the column about an arm''s length away, hips high over the knees, holding the rope ends beside the forehead","start":"torso tall and slightly arched, hips over the knees, rope by the head","end":"torso curled down so the elbows reach toward the thighs, spine rounded, hips still over the knees rather than sitting back"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"cable-curl","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage at the LOWEST position and a short straight bar attachment","setup":"standing facing the pulley, feet hip-width, underhand grip on the bar at shoulder width, elbows at the sides","start":"arms straight down, bar at the thighs","end":"bar curled up to the shoulders, elbows still at the sides"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"cable-external-rotation","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set at elbow height and a single stirrup handle","setup":"standing side-on to the column with the working arm farthest from it; elbow bent 90 degrees and pinned to the side with a small rolled towel between elbow and ribs; the handle held across the belly","start":"forearm across the belly, elbow bent 90 degrees at the side","end":"forearm rotated outward away from the body as far as is comfortable, elbow still pinned to the side"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"cable-fly","machine_id":"dual-cable-crossover","configuration":{"geometry":"a dual-pulley cable crossover station: two tall columns, each with a weight stack and a pulley carriage set at shoulder height, a single stirrup handle on each cable","setup":"standing centred between the columns in a short split stance, a slight forward lean, a handle in each hand, elbows softly bent","start":"arms out to the sides at chest height, elbows softly bent, hands slightly behind the chest line, a stretch across the chest","end":"hands brought together in front of the chest at chest height, elbow bend unchanged"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"cable-lateral-raise","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set at the LOWEST position and a single stirrup handle","setup":"standing side-on to the low pulley, holding the handle in the far hand so the cable crosses in front of the body; the near hand on the column","start":"working arm hanging across the front of the hips, elbow softly bent","end":"working arm raised out to the side to shoulder height, elbow slightly bent and level with the hand"}}]'::jsonb) as x(catalog_version text, exercise_id text, machine_id text, configuration jsonb)
on conflict do nothing;

insert into public.fitness_exercise_machines (catalog_version, exercise_id, machine_id, configuration)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"cable-pull-through","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage at the LOWEST position and a rope attachment","setup":"standing facing away from the column, straddling the cable, holding the rope between the legs with both hands, two steps forward","start":"hips hinged back, torso forward about 45 degrees, rope pulled back between the legs, back flat","end":"hips driven forward to standing tall, arms straight, glutes squeezed"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"cable-pushdown","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set at the TOP and a short straight bar attachment","setup":"standing tall facing the pulley, close to the cable, feet hip-width, a slight forward lean, elbows pinned to the sides; overhand grip on the bar with the hands about 20 to 30 centimetres apart","start":"elbows bent a little more than 90 degrees, forearms about level with the floor, bar at lower-chest height, upper arms vertical at the sides","end":"arms pushed straight down, bar at the thighs, elbows still at the sides"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"cable-rear-delt-fly","machine_id":"dual-cable-crossover","configuration":{"geometry":"a dual-pulley cable crossover station with both pulley carriages at shoulder height and no handles, the cable ends held directly","setup":"standing centred, holding the left cable in the right hand and the right cable in the left hand, the cables crossed in front of the chest","start":"arms crossed in front of the chest at shoulder height","end":"arms swept out and back to a T at shoulder height, elbows softly bent"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"cable-woodchop","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set at the TOP and a single stirrup handle","setup":"standing side-on to the column, feet wider than the shoulders, both hands on the handle up by the shoulder nearest the pulley","start":"arms extended up toward the high pulley, torso turned toward the column","end":"arms pulled diagonally down and across the body to the outside of the far knee, torso rotated away, pivoting on the back foot"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"captains-chair-knee-raise","machine_id":"captains-chair-knee-raise","configuration":{"geometry":"a captain''s chair (vertical knee raise station): a tall upright frame with a vertical back pad, two horizontal padded forearm rests with grip handles at elbow height, and a step at the bottom, no weights","setup":"back against the pad, forearms on the arm rests, hands on the handles, feet off the step, legs hanging","start":"legs hanging straight down, back against the pad","end":"knees raised to hip height or higher with the pelvis tucked under, lower back curling slightly off the pad"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"converging-chest-press","machine_id":"converging-chest-press","configuration":{"geometry":"a seated pin-loaded converging chest press: an upright back pad, an adjustable seat, two independent handle arms that swing forward and inward on angled pivots so the hands meet in front of the chest, a weight stack beside the seat","setup":"seat set so the handles are level with the middle of the chest; feet flat; back and head against the pad","start":"hands on the handles beside the chest, elbows bent about 90 degrees and slightly below shoulder height","end":"arms extended forward and inward, hands almost meeting in front of the breastbone, elbows nearly straight"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"decline-chest-press-machine","machine_id":"decline-chest-press-machine","configuration":{"geometry":"A plate-loaded seated decline press with adjustable upright seat/back pad, two independent lever arms carrying low handles that move forward and downward, plate horns on the arms and a stable base. No selector stack.","setup":"seat set so the handles start level with the lower chest; feet flat; back on the pad","start":"hands on the handles beside the lower chest, elbows bent about 90 degrees","end":"arms extended forward and slightly downward, elbows almost straight"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"face-pull","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set at about forehead height and a rope attachment with two knotted ends","setup":"standing tall facing the pulley in a slight split stance, a step back so the cable is taut and the arms are straight; an overhand grip on the two rope ends, palms down, one end in each hand","start":"arms extended forward toward the pulley at face height","end":"rope pulled to the face, the two ends split apart beside the ears, elbows high and level with the shoulders, forearms pointing up, upper arms rotated back"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"four-way-neck-machine","machine_id":"four-way-neck-machine","configuration":{"geometry":"A generic plate-loaded four-way neck station with adjustable seat, torso support, side handles and one padded head-contact plate on a lever at head height, loaded by a plate horn. No selector stack or forced neck rotation.","setup":"seated facing away from the head pad so the back of the head rests on it, torso upright, hands on the side handles","start":"head tilted slightly forward, chin toward the chest, back of the head against the pad","end":"head pushed back to neutral and slightly beyond against the pad, torso still"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"glute-kickback-machine","machine_id":"glute-kickback-machine","configuration":{"geometry":"a glute kickback machine: a standing frame with a chest pad and handles, a padded foot plate on a lever behind the working leg, a weight stack","setup":"standing with the chest on the pad, holding the handles, the working foot on the foot plate","start":"working hip and knee bent, the thigh forward under the hip","end":"working leg pushed back and up until the hip is straight"}}]'::jsonb) as x(catalog_version text, exercise_id text, machine_id text, configuration jsonb)
on conflict do nothing;

insert into public.fitness_exercise_machines (catalog_version, exercise_id, machine_id, configuration)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"hack-squat","machine_id":"hack-squat","configuration":{"geometry":"a plate-loaded hack squat: an angled sled with shoulder pads and a back pad running on rails at about 45 degrees, a large angled foot platform at the bottom, weight plates on horns on the sled","setup":"back flat against the pad, shoulders under the shoulder pads, feet about shoulder width on the platform","start":"knees bent deeply, thighs about parallel to the platform, back flat on the pad","end":"legs extended, standing up along the rails, knees not locked"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"high-row-machine","machine_id":"high-row-machine","configuration":{"geometry":"a plate-loaded high row: a seat with a thigh pad and a chest pad, two independent lever arms with handles high in front that pull down and back in an arc, weight plates on horns on the levers","setup":"thighs under the pad, chest against the pad; arms reaching up and forward to the handles","start":"arms extended up and forward holding the handles","end":"handles pulled down and back to the shoulders, elbows behind the torso"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"high-to-low-cable-fly","machine_id":"dual-cable-crossover","configuration":{"geometry":"a dual-pulley cable crossover station with both pulley carriages set HIGH, a single stirrup handle on each cable","setup":"standing in the middle in a short split stance, leaning slightly forward, a stirrup handle in each hand","start":"arms up and out to the sides above shoulder height, elbows softly bent, a stretch across the chest","end":"hands swept down and together in front of the lower chest, elbow bend unchanged"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"hip-abduction-machine","machine_id":"hip-abduction-machine","configuration":{"geometry":"a seated pin-loaded hip abduction machine: a reclined seat with a back pad, two padded leg pads on levers on the outside of the knees, foot rests, a weight stack","setup":"seated with the back against the pad, feet on the foot rests, the outside of the knees against the pads","start":"knees together","end":"knees pushed wide apart against the pads"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"hip-adduction-machine","machine_id":"hip-adduction-machine","configuration":{"geometry":"a seated pin-loaded hip adduction machine: a reclined seat with a back pad, two padded leg pads on levers on the inside of the knees, foot rests, a weight stack","setup":"seated with the back against the pad, feet on the foot rests, the inside of the knees against the pads","start":"knees spread wide apart","end":"knees squeezed together"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"lat-pulldown","machine_id":"seated-lat-pulldown","configuration":{"geometry":"a lat pulldown station: a tall frame whose weight stack column stands in front of the seated mannequin (on the right in a profile view), a top beam reaching back from the column to a pulley just above and in front of the mannequin''s head, the cable running from that pulley straight down to the middle of a long straight bar with slightly bent ends, and a seat with padded knee rollers on a short post at the front end of the seat, resting on top of the thighs just behind the knees (in a profile view: a round pad seen end-on, sitting on top of the thigh near the knee, never behind the hips)","setup":"seated facing the weight stack column, thighs locked under the knee rollers, feet flat; overhand grip on the bar about one and a half times shoulder width (in this profile view the bar is seen end-on, as a short stub held in the hands)","start":"arms fully extended overhead holding the bar above and slightly in front of the head, torso upright with a slight lean back of about 10 to 15 degrees, shoulders reaching up; the cable is long and straight from the pulley to the bar","end":"bar pulled down IN FRONT of the face to the top of the chest at collarbone height (never behind the neck), elbows pointing down and slightly back beside the ribs, forearms vertical under the bar, chest lifted toward the bar; the torso keeps the same slight lean and the thighs stay under the rollers"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"leg-extension","machine_id":"leg-extension","configuration":{"geometry":"a seated pin-loaded leg extension machine: a seat with an adjustable back pad, a padded roller on a lever arm in front of the shins with the pivot level with the knees, side handles, a weight stack","setup":"back pad set so the knee joint lines up with the machine''s pivot; the roller on the shins just above the ankles; hands on the side handles","start":"knees bent about 90 degrees, feet under the front edge of the seat","end":"knees straightened, legs level with the floor, toes up"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"leg-press-45","machine_id":"sled-leg-press-45","configuration":{"geometry":"a 45-degree plate-loaded sled leg press: a reclined padded seat and back pad, a large foot platform on a sled that slides up and down 45-degree rails, weight plates on horns on the sled, safety stop handles at the sides","setup":"lying back in the seat, feet on the platform about shoulder width apart in its middle, hands on the side handles, safety stops released","start":"knees bent about 90 degrees, thighs toward the chest, hips and lower back still flat on the pad","end":"legs pressed out to almost straight, knees not locked, the sled pushed up the rails"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"leg-press-calf-raise","machine_id":"sled-leg-press-45","configuration":{"geometry":"a 45-degree plate-loaded sled leg press: a reclined seat, a foot platform on a sled on 45-degree rails, weight plates on horns, safety handles","setup":"seated in the leg press with the legs straight but the knees not locked, only the balls of the feet on the bottom edge of the platform","start":"ankles flexed, toes pulled back toward the shins, heels below the platform edge","end":"ankles pointed, pushing the platform up with the balls of the feet"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"low-to-high-cable-fly","machine_id":"dual-cable-crossover","configuration":{"geometry":"a dual-pulley cable crossover station: two tall columns, each with a weight stack and an adjustable pulley carriage set at the LOWEST position, a single stirrup handle on each cable","setup":"standing in the middle between the two low pulleys in a short split stance, a stirrup handle in each hand, palms facing forward and up","start":"arms down and out to the sides below hip height, elbows softly bent, a stretch across the chest","end":"hands swept up and together in front of the upper chest at about chin height, elbow bend unchanged"}}]'::jsonb) as x(catalog_version text, exercise_id text, machine_id text, configuration jsonb)
on conflict do nothing;

insert into public.fitness_exercise_machines (catalog_version, exercise_id, machine_id, configuration)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"lower-back-machine","machine_id":"lower-back-machine","configuration":{"geometry":"a seated pin-loaded lower back machine: a seat with a foot platform, thigh and hip pads that lock the pelvis, a padded roller across the upper back on a lever arm pivoting at the level of the lower back, a weight stack","setup":"seat set so the machine''s pivot lines up with the lower back at navel height; feet on the platform, thigh pads locked; upper back against the roller, arms crossed on the chest","start":"torso leaning forward about 30 to 40 degrees, the back gently rounded forward against the roller","end":"torso pushed back to upright, spine extended to neutral, hips still locked"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"lying-leg-curl","machine_id":"lying-leg-curl","configuration":{"geometry":"a lying (prone) pin-loaded leg curl: an angled bench to lie face down on, handles at the front, a padded roller on a lever behind the ankles with the pivot level with the knees, a weight stack","setup":"lying face down, knees just off the end of the pad and in line with the pivot, roller on the back of the ankles, hands on the handles","start":"legs straight, roller on the back of the ankles","end":"knees bent, heels curled toward the glutes, hips pressed into the pad"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-chest-press","machine_id":"machine-chest-press","configuration":{"geometry":"a seated pin-loaded chest press: an upright padded back rest, an adjustable seat, two lever arms (one on each side of the seat, pivoting high on the frame behind the shoulders) that each end in a horizontal handle beside the chest and swing forward with the hands, and a weight stack with a selector pin standing behind the seat; nothing crosses in front of the chest","setup":"seat height set so the handles are level with the middle of the chest; feet flat on the floor; hips, upper back and head against the back pad; a full grip on the horizontal handles with straight wrists","start":"hands on the handles beside the chest, elbows bent about 90 degrees and slightly below shoulder height, upper arms about 45 degrees out from the torso, chest up, shoulder blades back against the pad","end":"arms extended straight forward, handles pushed away to arm''s length at mid-chest height, elbows almost straight but not locked, shoulder blades and head still on the pad"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-crunch","machine_id":"machine-crunch","configuration":{"geometry":"a seated pin-loaded abdominal crunch machine: a seat with a back pad, two handles above the shoulders on a lever that pivots forward and down, padded foot rollers, a weight stack","setup":"seat set so the handles sit just above the shoulders; feet hooked under the rollers; hands holding the handles beside the head","start":"torso upright against the back pad, hands at the handles beside the head","end":"torso curled forward and down, ribs pulled toward the pelvis, chin tucked, the lever brought down by the trunk rather than the arms"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-hip-thrust","machine_id":"machine-hip-thrust","configuration":{"geometry":"a plate-loaded hip thrust machine: a padded back rest for the upper back, a padded lever pad across the hips, a foot platform, weight plates on horns","setup":"upper back on the back rest, the hip pad across the hip crease, feet flat about hip width on the platform, knees bent","start":"hips lowered below the level of the knees","end":"hips driven up until the body is a straight line from shoulders to knees, shins vertical, chin tucked"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-incline-press","machine_id":"machine-incline-press","configuration":{"geometry":"a seated pin-loaded incline chest press: a back pad reclined about 30 to 45 degrees, an adjustable seat, two handles on lever arms that travel up and forward along the incline, a weight stack behind","setup":"seat set so the handles start level with the upper chest just below the collarbones; feet flat; back and head on the reclined pad","start":"hands on the handles beside the upper chest, elbows bent about 90 degrees and below the hands","end":"arms extended up and forward along the incline, elbows almost straight, shoulders down"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-lateral-raise","machine_id":"machine-lateral-raise","configuration":{"geometry":"a seated pin-loaded lateral raise machine: a seat facing a padded chest rest, two padded lever arms at the sides whose round pads rest against the outside of the upper arms just above the elbows, the lever pivots level with the shoulders, a weight stack in front","setup":"seat set so the shoulders line up with the lever pivots; chest against the chest rest, feet flat; the pads against the outside of the upper arms, elbows bent about 90 degrees, hands lightly on the handles","start":"upper arms down at the sides, elbows bent, pads resting on the outer upper arms","end":"upper arms raised out to the sides to shoulder height, elbows leading, shoulders down and not shrugged"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-preacher-curl","machine_id":"machine-preacher-curl","configuration":{"geometry":"a seated pin-loaded preacher curl (arm curl) machine: a seat, an angled arm pad in front sloping down away from the body, two handles on a lever whose pivot sits level with the elbows, a weight stack","setup":"seat set so the armpits sit snugly at the top of the arm pad and the elbows line up with the machine''s pivot; upper arms flat on the pad; underhand grip on the handles","start":"arms almost straight along the pad, elbows slightly bent, handles low","end":"elbows fully bent, handles raised toward the shoulders, upper arms still flat on the pad"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-pullover","machine_id":"machine-pullover","configuration":{"geometry":"a seated pin-loaded pullover machine: a seat with a back pad and a hip belt, a curved bar above the head joined to padded elbow plates on a lever that rotates around the shoulders, a weight stack","setup":"seat set so the shoulders line up with the lever''s pivot; belt across the hips; elbows against the pads, hands resting lightly on the bar","start":"arms raised overhead and slightly behind the head, elbows on the pads, a stretch along the sides of the back","end":"arms rotated forward and down in a big arc until the bar touches the belly"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-row","machine_id":"machine-row","configuration":{"geometry":"a seated pin-loaded row machine: a seat, an upright padded chest rest in front, two handles on lever arms reaching forward with horizontal and vertical grips, a weight stack","setup":"seat set so the handles are level with the lower chest; chest rest set so the arms are fully stretched at the handles; chest against the pad, feet flat","start":"arms extended forward holding the handles, shoulder blades spread forward, chest on the pad","end":"handles pulled back to the sides of the lower ribs, elbows driven back past the torso, shoulder blades squeezed together, chest still on the pad"}}]'::jsonb) as x(catalog_version text, exercise_id text, machine_id text, configuration jsonb)
on conflict do nothing;

insert into public.fitness_exercise_machines (catalog_version, exercise_id, machine_id, configuration)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-shoulder-press","machine_id":"machine-shoulder-press","configuration":{"geometry":"a seated pin-loaded shoulder press: an upright back pad, an adjustable seat, two handles at shoulder height on lever arms that travel straight up, a weight stack behind","setup":"seat set so the handles start level with the top of the shoulders; feet flat; back and head against the pad; palms facing forward on the handles","start":"hands at shoulder height beside the head, elbows bent below the hands and slightly in front of the torso","end":"arms pressed straight overhead, elbows almost straight, ribs down, back still on the pad"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-shrug","machine_id":"machine-shrug","configuration":{"geometry":"a plate-loaded standing shrug machine: a platform to stand on between two handles at hip height at the ends of a lever arm, weight plates on horns at the lever ends","setup":"standing tall on the platform between the handles, arms straight down holding the handles","start":"shoulders relaxed and low, arms straight","end":"shoulders raised straight up toward the ears, arms still straight"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"machine-triceps-extension","machine_id":"machine-triceps-extension","configuration":{"geometry":"a seated pin-loaded triceps extension machine: a seat, an angled arm pad in front, two handles on a lever whose pivot sits level with the elbows, a weight stack","setup":"seat set so the elbows line up with the machine''s pivot, upper arms flat on the pad, hands on the handles","start":"elbows bent about 90 degrees or more, hands near the shoulders","end":"arms extended straight along the pad, upper arms unmoved"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"neutral-grip-pulldown","machine_id":"seated-lat-pulldown","configuration":{"geometry":"a lat pulldown station with a parallel-grip handle (two handles with the palms facing each other, about shoulder width apart) on the high pulley, the weight stack column in front of the seated mannequin, and a seat with padded knee rollers on a short post at the front end of the seat, resting on top of the thighs just behind the knees (in a profile view: a round pad seen end-on, sitting on top of the thigh near the knee, never behind the hips)","setup":"seated facing the weight stack column, thighs locked under the knee rollers, feet flat; palms facing each other on the parallel handles","start":"arms fully extended overhead, torso upright with a slight lean back","end":"handle pulled down to the upper chest, elbows down beside the ribs, chest up"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"overhead-cable-triceps-extension","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set at about head height and a rope attachment","setup":"standing in a split stance facing away from the column, leaning slightly forward, holding the rope behind the head with both hands, upper arms beside the head pointing forward and up","start":"elbows bent fully, hands behind the head, a stretch along the back of the upper arms","end":"arms extended forward and up in line with the upper arms, elbows straight, upper arms unmoved"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"pallof-press","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set at chest height and a single stirrup handle","setup":"standing side-on to the column with the column at the mannequin''s RIGHT side, feet shoulder-width, knees soft, a step away so the cable is taut; both hands hold the single handle against the breastbone","start":"hands holding the handle against the breastbone, elbows bent and tucked in, the cable running sideways from the column to the hands; chest, hips and feet square to the front, the direction the mannequin faces (toward the lower left of the picture)","end":"arms pressed straight out in FRONT of the chest, in the direction the chest faces (toward the lower left of the picture), at a right angle to the cable: the cable and the straight arms form an L at the hands; the hands do NOT move toward or away from the column; chest and hips still square to the front, never turned toward the column"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"pec-deck","machine_id":"reversible-pec-rear-delt","configuration":{"geometry":"a seated pin-loaded pec deck (butterfly) machine: an upright back pad, an adjustable seat, two long swinging arms with vertical handles that swing together in front of the chest, a weight stack behind the seat","setup":"seat set so the handles are at mid-chest height and the shoulders level with the arms'' pivots; back and head against the pad; hands on the vertical handles, elbows softly bent","start":"arms open wide to the sides at chest height, elbows softly bent and level with the back pad, a stretch across the chest","end":"arms swept forward together so the handles nearly touch in front of the chest, elbow bend unchanged, back still on the pad"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"plate-loaded-chest-press","machine_id":"plate-loaded-chest-press","configuration":{"geometry":"a plate-loaded iso-lateral chest press: a heavy steel frame with a slightly reclined back pad and a seat, two independent lever arms with vertical handles that pivot from above and behind, round weight plates on a horn on each lever arm, no weight stack","setup":"seat set so the handles are level with the middle of the chest; feet flat; back and head on the pad; neutral grip on the vertical handles","start":"hands on the handles beside the chest, elbows bent about 90 degrees","end":"both arms pressed forward to almost straight, the lever arms swung forward"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"plate-loaded-incline-press","machine_id":"plate-loaded-incline-press","configuration":{"geometry":"a plate-loaded iso-lateral incline press: a back pad reclined about 30 to 45 degrees, a seat, two independent lever arms with handles that press up and forward, weight plates on a horn on each lever arm","setup":"seat set so the handles start at the upper chest; feet flat; back on the pad","start":"hands on the handles beside the upper chest, elbows bent about 90 degrees","end":"arms pressed up and forward to almost straight"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"plate-loaded-pulldown","machine_id":"plate-loaded-pulldown","configuration":{"geometry":"a plate-loaded front lat pulldown: a seat with padded knee rollers on a short post at the front end of the seat, resting on top of the thighs just behind the knees (in a profile view: a round pad seen end-on, sitting on top of the thigh near the knee, never behind the hips), two independent lever arms with handles overhead that pull down and back in an arc, weight plates on horns at the back of the levers","setup":"thighs locked under the pads, feet flat; hands on the overhead handles","start":"arms extended up holding the handles, shoulders reaching up","end":"handles pulled down to the upper chest, elbows down and back beside the ribs, chest up"}}]'::jsonb) as x(catalog_version text, exercise_id text, machine_id text, configuration jsonb)
