insert into public.fitness_exercise_machines (catalog_version, exercise_id, machine_id, configuration)
select * from jsonb_to_recordset('[{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"smith-bench-press","machine_id":"smith-vertical-rack","configuration":{"geometry":"a Smith machine: a barbell fixed on two vertical steel guide rails inside a tall frame, with rack hooks and adjustable safety stops, and a flat bench placed inside it so the bar comes down over the middle of the chest","setup":"lying on the flat bench inside the Smith machine, eyes under the bar, feet flat on the floor, shoulder blades pulled back; hands on the bar a little wider than the shoulders","start":"bar lowered to touch the middle of the chest, forearms vertical, elbows about 45 to 60 degrees out from the torso","end":"bar pressed straight up along the rails to arm''s length above the chest, elbows almost straight"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"smith-incline-press","machine_id":"smith-vertical-rack","configuration":{"geometry":"a Smith machine with an adjustable bench set to about 30 degrees incline inside it, so the bar comes down to the upper chest","setup":"lying back on the 30-degree incline bench, feet flat, shoulder blades back; hands a little wider than the shoulders","start":"bar lowered to the upper chest just below the collarbones, forearms vertical","end":"bar pressed straight up along the rails to arm''s length"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"smith-shoulder-press","machine_id":"smith-vertical-rack","configuration":{"geometry":"a Smith machine with an upright bench (back rest almost vertical) inside it, placed so the bar passes just in front of the face","setup":"seated on the upright bench, back against the pad, feet flat; hands on the bar a little wider than the shoulders","start":"bar at chin height just in front of the face, forearms vertical, elbows under the bar","end":"bar pressed straight up along the rails to arm''s length overhead"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"smith-squat","machine_id":"smith-vertical-rack","configuration":{"geometry":"a Smith machine: a barbell fixed on two vertical steel guide rails with rack hooks and safety stops, the bar set at upper-chest height","setup":"bar across the upper back, feet about shoulder width and slightly in front of the bar","start":"squatted down, thighs about parallel to the floor, back straight","end":"standing tall, legs straight"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"standing-calf-raise-machine","machine_id":"standing-calf-raise-machine","configuration":{"geometry":"a standing pin-loaded calf raise machine: padded shoulder yokes on a lever, a raised foot step block beneath, side handles, a weight stack","setup":"shoulders under the pads, balls of the feet on the edge of the step, knees straight but not locked, body upright","start":"heels lowered below the step, a deep stretch in the calves","end":"heels raised as high as possible onto the balls of the feet"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"straight-arm-pulldown","machine_id":"single-cable-tower","configuration":{"geometry":"a single cable column with the pulley carriage set at the TOP and a straight bar attachment","setup":"standing a step back from the high pulley, feet hip-width, hips hinged slightly forward with a flat back, arms straight holding the bar at shoulder width","start":"arms straight up in front at about head height, a stretch along the sides of the back","end":"bar swept down in an arc to the thighs, arms still straight"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"t-bar-row","machine_id":"t-bar-row","configuration":{"geometry":"a chest-supported T-bar row: a foot platform, an inclined chest pad, a long lever arm under the pad with wide and narrow handles, weight plates on a horn at the end of the lever","setup":"standing on the foot platform with the chest on the inclined pad, arms hanging straight down holding the handles","start":"arms straight down holding the handles, shoulder blades spread","end":"handles pulled up to the lower chest, elbows back past the torso, shoulder blades squeezed"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"triceps-press-machine","machine_id":"triceps-press-machine","configuration":{"geometry":"a seated pin-loaded dip machine (triceps press): an upright back pad, a seat with a padded thigh hold-down, two handles beside the hips on lever arms that are pushed downward, a weight stack behind","setup":"seat set so the handles start level with the lower chest; back against the pad, thighs under the pad; neutral grip on the handles at the sides","start":"elbows bent about 90 degrees and pointing back, hands beside the lower ribs, shoulders down","end":"arms pressed straight down, hands beside the hips, elbows almost straight, torso upright against the pad"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"v-squat","machine_id":"v-squat","configuration":{"geometry":"a plate-loaded V-squat: an angled foot platform, padded shoulder yokes on a long lever arm that pivots behind, weight plates on a horn on the lever","setup":"standing on the platform under the shoulder pads, feet about shoulder width","start":"knees and hips bent, thighs about parallel to the platform","end":"standing up with the legs straight, knees not locked"}},{"catalog_version":"fitness-v2-915b27fc7429a034","exercise_id":"vertical-traction","machine_id":"vertical-traction","configuration":{"geometry":"a seated pin-loaded vertical traction machine: a seat with padded knee rollers on a short post at the front end of the seat, resting on top of the thighs just behind the knees (in a profile view: a round pad seen end-on, sitting on top of the thigh near the knee, never behind the hips), two independent handle arms above the head that pull down in an arc (no bar and no cable at the hands), a weight stack","setup":"seat set so the thighs fit snugly under the pads and the handles are just reachable with straight arms; feet flat","start":"arms extended up gripping the handles, shoulders reaching up, torso upright","end":"handles pulled down to the shoulders, elbows down beside the ribs and slightly back, chest up"}}]'::jsonb) as x(catalog_version text, exercise_id text, machine_id text, configuration jsonb)
